                    nam       c.comp
                    ttl       program module

* Annotated 2026-07-13 (Claude Code):
*   - renamed disassembled labels (code, data and the static storage block) to meaningful names
*   - added inline comments describing the compiler's flow
*   - re-disassembled the "**** STACK OVERFLOW ****" message text (was decoded as code)
*   - verified byte-identical to the original assembly (module CRC $8FDC90)

                    use       defsfile

tylg                set       Prgrm+Objct
atrv                set       ReEnt+rev
rev                 set       1
edition             set       5

                    mod       eom,name,tylg,atrv,_start,size

                    * ------------------------------------------------------------------
                    * Data area (named rmb fields).  rmb reserves RAM without emitting
                    * bytes; OS-9 allocates <size> at load, cstart inits from WorkBlockImage.
                    * Names for ,y-referenced fields are derived from the code comments.
                    * ------------------------------------------------------------------
                    rmb       1
GlbVar0001          rmb       1
Destination         rmb       1
GlbVar0003          rmb       2
GlbVar0005          rmb       2
GlbVar0007          rmb       2
CacheUserId         rmb       2
GlbVar000B          rmb       2
GlbVar000D          rmb       2
GlbVar000F          rmb       2
GlbVar0011          rmb       2
GlbVar0013          rmb       2
GlbVar0015          rmb       2
GlbVar0017          rmb       2
GlbVar0019          rmb       2
GlbVar001B          rmb       2
                    rmb       6
GlbVar0023          rmb       2
                    rmb       2
IdentifierField     rmb       2
NodeBuilderBase     rmb       2
XAddressGlobal      rmb       2
GlbVar002D          rmb       2
GlbVar002F          rmb       2
GlbVar0031          rmb       2
GlbVar0033          rmb       2
GlbVar0035          rmb       2
GlbVar0037          rmb       2
GlbVar0039          rmb       2
F003bYLink          rmb       2
GlbVar003D          rmb       2
GlbVar003F          rmb       2
GlbVar0041          rmb       2
GlbVar0043          rmb       2
GlbVar0045          rmb       2
                    rmb       3
F004aYFirst         rmb       1
GlbVar004B          rmb       2
                    rmb       5
GlbVar0052          rmb       2
                    rmb       6
GlbVar005A          rmb       2
                    rmb       2
GlbVar005E          rmb       2
GlbVar0060          rmb       2
GlbVar0062          rmb       2
GlbVar0064          rmb       2
GlbVar0066          rmb       2
GlbVar0068          rmb       2
                    rmb       4
GlbVar006E          rmb       2
                    rmb       2
GlbVar0072          rmb       2
GlbVar0074          rmb       2
GlbVar0076          rmb       2
ErrorTypeTemplate   rmb       28
DFlagsValue         rmb       2
StringListVariable  rmb       11
NameBuf             rmb       11
BufferLimit         rmb       2
RegNameTab          rmb       2
StackPointerRegister rmb       2
PendingMnemonicString rmb       2
BaseRegisterName    rmb       2
RegisterNameString  rmb       2
GlobalMessageField  rmb       2
CtypeTab            rmb       128
AttributeTable      rmb       128
PowerTenTable       rmb       104
TableBase           rmb       28
Pow10               rmb       8
XOutputFile         rmb       13
XStderrStruct       rmb       13
XStderrStream       rmb       182
TableEndAddress     rmb       64
DBreakPointer       rmb       2
ScratchType         rmb       2
ResultLowWord       rmb       2
Scratch             rmb       4
ArenaTop            rmb       2
ArenaLimit          rmb       2
Errno           rmb       2
XNameBuffer         rmb       30
GlobalSymbolHash    rmb       256
LocalSymbolHash     rmb       256
LineBuffer          rmb       256
SecondSourceBuffer  rmb       256
DefaultLabel        rmb       2
LoopContextLow      rmb       2
LoopContextHigh     rmb       2
OutputBuffer        rmb       256
XNumberBuffer       rmb       10
UScratchBuffer      rmb       10
DivideSignFlag      rmb       1
DivideRoutinePointer rmb       2
FreeBytes           rmb       2
HandlerPointer      rmb       2
HeapStart           rmb       2176     remaining data, bss and heap
size                equ       .

name                equ       *
                    fcs       /c.comp/
                    fcb       edition

GlbSrcLine          equ       $001F     current source line/file info
GlbNestDepth        equ       $0021     declarator nesting / scope depth
GlbFreeList         equ       $0025     node free-list head
GlbMemLow           equ       $0046     memory low watermark
GlbMemHigh          equ       $0048     memory high watermark
GlbStrList          equ       $004C     string list / string file handle
GlbPassMode         equ       $0056     pass / init mode flag
GlbFirstCall        equ       $0058     first-call primed flag
GlbFrameLbl         equ       $005C     frame-size label number
GlbNodePtr          equ       $006A     current node / list pointer
GlbListTail         equ       $006C     list tail pointer
GlbOutPtr           equ       $0070     output buffer / destination pointer
* --- shared C runtime startup (see lib/cstart.asm) ---
RTBASE              equ       TableEndAddress runtime-globals block base in the data area
DATAEND             equ       HeapStart end of static data / heap start / stack limit
HDRADV              equ       ErrorTypeTemplate advance to where the non-DP data starts
                    use       lib/cstart.asm

main                pshs      u         save u
                    leax      FlushStringPool,pcr x = init routine pointer
                    pshs      x         push argument
                    lbsr      SetupIntercept register startup routine
                    leas      2,s        drop argument
                    leax      StringListVariable,y   x = work area
                    pshs      x         push argument
                    lbsr      SubstXPlaceholder initialize subsystem
                    leas      2,s        drop argument
                    leax      StrDummy,pcr x = dummy symbol name
                    pshs      x         push name
                    ldd       DFlagsValue,y   d = flags value
                    pshs      d         push value
                    lbsr      StrCpy    create dummy symbol
                    leas      4,s        drop arguments
                    lbsr      InstallKeywords initialize tables
                    leax      XOutputFile,y   x = output file struct
                    stx       GlbVar0003 store output file pointer
                    leax      XStderrStruct,y   x = stderr struct
                    stx       GlbVar0005 store error file pointer
                    lbra      ArgLoopNext enter argument loop

ArgLoop             ldx       6,s       x = argv pointer
                    leax      2,x       advance to next arg
                    stx       6,s       save argv pointer
                    ldu       ,x        u = current argument string
                    ldb       ,u        b = first char
                    cmpb      #'-      is it a dash
                    lbne      InputFile no, treat as filename
                    lbra      NextOptChar yes, scan option chars

OptCharLoad         ldb       ,u        b = option char
                    sex                 sign-extend to d
                    tfr       d,x       x = option char
                    lbra      OptDispatch dispatch on option letter

OptS                ldd       #1        d = 1
                    std       GlbVar0015 set -s flag
                    lbra      NextOptChar next option char

OptN                ldd       GlbVar0019 d = -n counter
                    addd      #1        increment counter
                    std       GlbVar0019 store counter
                    lbra      NextOptChar next option char

OptO                leau      1,u       skip the o letter
                    ldb       ,u        b = next char
                    cmpb      #'=      is it an equals
                    bne       OptODone  no, malformed option
                    leax      StrModeW,pcr x = write-mode string
                    pshs      x         push mode
                    leau      1,u       skip the equals
                    pshs      u         push filename
                    lbsr      BuildOperand2 fopen output file
                    leas      4,s        drop arguments
                    std       GlbVar0005 store output file pointer
                    bne       OptODone  opened, continue
                    pshs      u         push filename
                    leax      MsgCantOpen,pcr x = can't-open format
                    pshs      x         push format
                    leax      XStderrStream,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      fprintf   print open error
                    leas      6,s        drop arguments
                    lbsr      ExitErr   exit with failure
OptODone            leax      ,s        x = stack pointer
                    bra       OptORestore resume argument loop

OptP                ldd       #1        d = 1
                    std       GlbVar0017 set -p flag
                    bra       NextOptChar next option char

UnknownFlag         ldb       ,u        b = unknown flag char
                    sex                 sign-extend to d
                    pshs      d         push char
                    leax      MsgUnknownFlag,pcr x = unknown-flag format
                    pshs      x         push format
                    leax      XStderrStream,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      fprintf   print warning
                    leas      6,s        drop arguments
                    lbsr      ExitErr   exit with failure
                    bra       NextOptChar next option char

OptDispatch         cmpx      #'s       is option letter s
                    lbeq      OptS      handle -s
                    cmpx      #'n       is option letter n
                    lbeq      OptN      handle -n
                    cmpx      #'o       is option letter o
                    lbeq      OptO      handle -o
                    cmpx      #'p       is option letter p
                    beq       OptP      handle -p
                    bra       UnknownFlag unknown flag

NextOptChar         leau      1,u       advance in option string
                    ldb       ,u        b = next char
                    lbne      OptCharLoad more option chars
                    bra       ArgLoopNext done, go to next arg

OptORestore         leas      ,x        restore stack pointer
                    bra       ArgLoopNext next argument

InputFile           ldd       GlbVar0052 d = input-open flag
                    bne       ArgLoopNext already have input, skip
                    ldd       GlbVar0052 d = input-open flag
                    addd      #1        set flag to one
                    std       GlbVar0052 mark input opened
                    leax      XOutputFile,y   x = input file struct
                    pshs      x         push struct
                    leax      StrModeR,pcr x = read-mode string
                    pshs      x         push mode
                    ldd       [10,s]    d = filename pointer
                    pshs      d         push filename
                    lbsr      BuildOperandEval fopen input file
                    leas      6,s        drop arguments
                    std       GlbVar0003 store input file pointer
                    bne       ArgLoopNext opened, next arg
                    leax      MsgCantOpenIn,pcr x = can't-open input message
                    pshs      x         push message
                    lbsr      PrintMsg  print error
                    leas      2,s        drop argument
ArgLoopNext         ldd       4,s       d = argc counter
                    addd      #$FFFF    decrement counter
                    std       4,s       store counter
                    lbgt      ArgLoop   more args to process
                    lbsr      ResetInputBuf run parser and compile
                    lbsr      ParseStatement2 generate output code
                    bra       EmitCheck enter emit-check loop

EmitItem            lbsr      ParseUnaryExpr emit one output item
EmitCheck           ldd       GlbVar003F d = work queue head
                    cmpd      #$FFFF    queue empty
                    bne       EmitItem  more items to emit
                    lbsr      EmitProgramEnd finalize output
                    ldx       GlbVar0005 x = error file struct
                    ldd       6,x       d = file status flags
                    clra                clear high byte
                    andb      #$20      test write-error bit
                    beq       FlushErr  no write error
                    leax      MsgWriteErr,pcr x = write-error message
                    pshs      x         push message
                    lbsr      PrintMsg  print error
                    leas      2,s        drop argument
FlushErr            leax      XStderrStruct,y   x = stderr struct
                    pshs      x         push stream
                    lbsr      CheckWritable flush and close stream
                    leas      2,s        drop argument
                    ldd       CacheUserId d = compilation error count
                    beq       MainDone  none, done
                    ldd       CacheUserId d = error count
                    pshs      d         push count
                    leax      MsgErrCount,pcr x = error-count format
                    pshs      x         push format
                    leax      XStderrStream,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      fprintf   print error summary
                    leas      6,s        drop arguments
                    bsr       ExitErr   exit with failure
MainDone            puls      pc,u      return from main

ExitErr             pshs      u         save u
                    ldd       #1        exit code = 1
                    pshs      d         push exit code
                    lbsr      exit      exit with failure
                    leas      2,s        drop exit code
                    puls      pc,u      return (unreached)

StrDummy            fcc       /_dummy_/
                    fcb       C$NULL
StrModeW            fcb       $77
                    fcb       C$NULL
MsgCantOpen         fcc       /can't open %s/
                    fcb       C$CR,C$NULL
MsgUnknownFlag      fcc       /unknown flag : -%c/
                    fcb       C$CR,C$NULL
StrModeR            fcb       $72
                    fcb       C$NULL
MsgCantOpenIn       fcc       /can't open input file/
                    fcb       C$NULL
MsgWriteErr         fcc       /error writing assembly code file/
                    fcb       C$NULL
MsgErrCount         fcc       /errors in compilation : %d/
                    fcb       C$CR,C$NULL
AllocBlk            pshs      u         save u
                    ldu       4,s       u = argument pointer
                    leas      -6,s       allocate locals
                    ldd       GlbVar0023 d = free-list head
                    std       2,s       save head pointer
                    beq       AllocNew  list empty, allocate new
                    ldx       2,s       x = free block
                    ldd       16,x      d = next-block link
                    std       GlbVar0023 pop block from free list
                    bra       AllocInit initialize the block

AllocNew            ldd       #18       size = 18 bytes
                    pshs      d         push size
                    lbsr      AllocMem  malloc a block
                    leas      2,s        drop size
                    std       2,s       save block pointer
AllocInit           ldd       #18       length = 18 bytes
                    pshs      d         push length
                    ldd       4,s       d = source pointer
                    pshs      d         push source
                    stu       8,s       save u as dest
                    pshs      u         push dest
                    bsr       CopyMem   copy 18 bytes into block
                    leas      6,s        drop arguments
                    ldd       #9        count = 9 words
                    std       ,s        set counter
                    bra       AllocZeroChk enter zero loop

AllocZeroLoop       clra                a = 0
                    clrb                b = 0
                    std       ,u++      zero one word
AllocZeroChk        ldd       ,s        d = word counter
                    addd      #$FFFF    decrement counter
                    std       ,s        store counter
                    subd      #$FFFF    test counter for zero
                    bne       AllocZeroLoop zero more words
                    ldd       2,s       d = block pointer
                    ldx       4,s       x = destination struct
                    std       14,x      store block pointer in field
                    lbra      CleanupRet6 return the block

FreeBlk             pshs      u         save u
                    ldu       4,s       u = block to free
                    leas      -2,s       allocate local
                    ldd       14,u      d = block-pointer field
                    std       ,s        save it
                    ldd       #18       length = 18 bytes
                    pshs      d         push length
                    pshs      u         push block argument
                    ldd       4,s       d = source pointer
                    pshs      d         push source
                    bsr       CopyMem   copy 18 bytes out
                    leas      6,s        drop arguments
                    ldd       GlbVar0023 d = free-list head
                    ldx       ,s        x = freed block
                    std       16,x      link old head into block
                    ldd       ,s        d = freed block
                    std       GlbVar0023 push block onto free list
                    lbra      DropArgReturn return

CopyMem             pshs      u         save u
                    ldu       4,s       u = source pointer
                    bra       CopyMemChk enter copy loop

CopyMemLoop         ldb       ,u+       load source byte
                    ldx       6,s       x = destination pointer
                    leax      1,x       advance destination
                    stx       6,s       save destination pointer
                    stb       -1,x      store byte
CopyMemChk          ldd       8,s       d = byte count
                    addd      #$FFFF    decrement count
                    std       8,s       store count
                    subd      #$FFFF    test count for zero
                    bne       CopyMemLoop copy next byte
                    puls      pc,u      return

PrintNamePfx        pshs      u         save u
                    leax      XNameBuffer,y   x = name buffer
                    pshs      x         push name
                    leax      FmtNameColon,pcr x = name-prefix format
                    pshs      x         push format
                    lbsr      ErrPrintf print to stderr
                    lbra      PutCharDone return

PrintMsg            pshs      u         save u
                    ldd       4,s       d = message pointer
                    pshs      d         push message
                    bsr       BuildMsgBuf format into buffer
                    leas      2,s        drop argument
                    leax      XStderrStream,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      CheckWritable write buffer to stderr
                    lbra      AbortTail return

ErrMultiDef         pshs      u         save u
                    leax      MsgMultiDef,pcr x = multiple-definition message
                    pshs      x         push message
                    bsr       BuildMsgBuf format into buffer
                    lbra      DropArgReturn return

BuildMsgBuf         pshs      u         save u
                    ldd       GlbSrcLine d = buffer state global
                    pshs      d         push it
                    ldd       6,s       d = message pointer
                    pshs      d         push message
                    leax      LineBuffer,y   x = work buffer
                    pshs      x         push buffer
                    ldd       GlbVar0043 d = current position
                    bra       ComputeCaretCol build the message

InternalErr         pshs      u         save u
                    leas      -50,s      allocate 50-byte buffer
                    leax      MsgCompilerErr,pcr x = compiler-error message
                    pshs      x         push message
                    leax      2,s       point X at local arguments
                    pshs      x         push argument pointer
                    lbsr      StrCpy    call formatting helper
                    leas      4,s        drop two arguments
                    ldd       56,s      load caller value
                    pshs      d         push it
                    leax      2,s       point X at locals
                    pshs      x         push pointer argument
                    lbsr      strcat    call formatting helper
                    leas      4,s        drop arguments
                    leax      ,s        point X at stack top
                    pshs      x         push pointer argument
                    ldd       56,s      reload caller value
                    pshs      d         push as argument
                    bsr       ReportErrorAt report error at this location
                    leas      4,s        drop arguments
                    leas      50,s       release local frame
                    puls      pc,u      restore and return

ReportErrorAt       pshs      u         save U
                    ldu       4,s       U = error record pointer
                    ldd       14,u      load base column field
                    pshs      d         push it
                    ldd       8,s       load line-position argument
                    pshs      d         push it
                    leax      LineBuffer,y   point at source line buffer
                    pshs      x         push buffer pointer
                    ldd       16,u      load error column field
ComputeCaretCol     subd      ,s++      column = errcol minus base
                    pshs      d         push caret column
                    bsr       FormatErrorLine format and print error line
                    lbra      CleanupRet6 clean up and return

FormatErrorLine     pshs      u         save U
                    ldu       4,s       U = source line buffer
                    lbsr      PrintNamePfx prepare output line
                    ldd       8,s       load line number
                    pshs      d         push it
                    leax      FmtLineNum,pcr line number format string
                    pshs      x         push format pointer
                    lbsr      ErrPrintf fprintf the line number
                    leas      4,s        drop arguments
                    ldd       6,s       source buffer pointer
                    pshs      d         push it
                    leax      FmtStars,pcr starred source-line format
                    pshs      x         push format pointer
                    lbsr      ErrPrintf fprintf the source line
                    leas      4,s        drop arguments
                    ldd       8,s       load caret column
                    cmpd      GlbVar0007 compare to marker base
                    bne       CaretFromBuf2 differs, use second buffer
                    leax      LineBuffer,y   first source buffer
                    pshs      x         push buffer pointer
                    lbsr      PutErrString print the string
                    leas      2,s        drop argument
                    leax      ,s        X = stack pointer
                    bra       SetCaretPtr set caret pointer

CaretFromBuf2       ldd       GlbVar0007 load marker base
                    addd      #$FFFF    subtract one
                    cmpd      8,s       compare caret column
                    bne       BumpErrorCount no caret, skip to count
                    leax      SecondSourceBuffer,y   second source buffer
                    pshs      x         push buffer pointer
                    lbsr      PutErrString print the string
                    leas      2,s        drop argument
                    bra       SpaceLoopTest enter space loop

SetCaretPtr         leas      ,x        restore stack to X
                    bra       SpaceLoopTest enter space loop

EmitSpaceLoop       ldd       #'        space character
                    pshs      d         push it
                    lbsr      PutErrChar output a space
                    leas      2,s        drop argument
                    leau      -1,u      decrement column count
SpaceLoopTest       cmpu      #0        any columns left
                    bgt       EmitSpaceLoop keep emitting spaces
                    leax      CharCaret,pcr caret marker string
                    pshs      x         push pointer
                    bsr       PutErrString print the caret
                    leas      2,s        drop argument
BumpErrorCount      ldd       CacheUserId load error count
                    addd      #1        increment it
                    std       CacheUserId store back
                    cmpd      #30       reached 30 errors
                    ble       ErrLineDone under limit, done
                    leax      XStderrStream,y   error stream pointer
                    pshs      x         push it
                    lbsr      CheckWritable flush the stream
                    leas      2,s        drop argument
                    leax      MsgTooManyErr,pcr too many errors message
                    pshs      x         push pointer
                    bsr       PutErrString print abort message
AbortTail           leas      2,s        drop argument
                    lbsr      FlushStringPool exit the compiler
ErrLineDone         puls      pc,u      restore and return

ErrPrintf           pshs      u         save U
                    ldd       8,s       first varargs value
                    pshs      d         push it
                    ldd       8,s       second value
                    pshs      d         push it
                    ldd       8,s       format string pointer
                    pshs      d         push it
                    leax      XStderrStream,y   error stream pointer
                    pshs      x         push it
                    lbsr      fprintf   formatted output
                    leas      8,s        drop arguments
                    puls      pc,u      restore and return

PutErrString        pshs      u         save U
                    leax      XStderrStream,y   error stream pointer
                    pshs      x         push it
                    ldd       6,s       string pointer argument
                    pshs      d         push it
                    lbsr      CopyStringToBuf write the string
                    leas      4,s        drop arguments
                    ldd       #13       carriage return character
                    pshs      d         push it
                    bsr       PutErrChar output the newline
                    bra       DropArgReturn clean up and return

PutErrChar          pshs      u         save U
                    leax      XStderrStream,y   error stream pointer
                    pshs      x         push it
                    ldb       7,s       load char argument
                    sex                 sign-extend to D
                    pshs      d         push it
                    lbsr      PutByte   putc to the stream
PutCharDone         leas      4,s        drop arguments
                    puls      pc,u      restore and return

FreeExprTree        pshs      u         save U
                    ldu       4,s       U = tree node
                    stu       -2,s      test node pointer
                    beq       ReturnU   null, return
                    ldd       10,u      left child
                    pshs      d         push it
                    bsr       FreeExprTree recurse left subtree
                    leas      2,s        drop argument
                    ldd       12,u      right child
                    pshs      d         push it
                    lbsr      FreeExprTree recurse right subtree
                    leas      2,s        drop argument
                    pshs      u         push this node
                    bsr       LinkFreeNode link node onto free list
DropArgReturn       leas      2,s        drop argument
ReturnU             puls      pc,u      restore and return

LinkFreeNode        pshs      u         save U
                    ldu       4,s       U = node to free
                    stu       -2,s      test pointer
                    beq       LinkNodeDone null, skip
                    ldd       GlbVar000D current free-list head
                    std       10,u      chain into node
                    stu       GlbVar000D node becomes new head
LinkNodeDone        puls      pc,u      restore and return

ReportDiag22        pshs      u         save U
                    ldd       #22       diagnostic code 22
                    pshs      d         push it
                    ldd       8,s       first argument
                    pshs      d         push it
                    ldd       8,s       second argument
                    pshs      d         push it
                    lbsr      CopyMem   report the diagnostic
CleanupRet6         leas      6,s        drop arguments
                    puls      pc,u      restore and return

IsTypeSpecifier     pshs      u         save U
                    ldd       GlbVar003F current token type
                    cmpd      #51       is it type 51
                    bne       CheckType52Tok no, check type 52
                    ldx       GlbVar0041 token value
                    cmpx      #1        value 1
                    lbeq      ReturnOne yes, return true
                    cmpx      #2        value 2
                    lbeq      ReturnOne yes, return true
                    cmpx      #7        value 7
                    lbeq      ReturnOne yes, return true
                    cmpx      #10       value 10
                    lbeq      ReturnOne yes, return true
                    cmpx      #8        value 8
                    lbeq      ReturnOne yes, return true
                    cmpx      #4        value 4
                    lbeq      ReturnOne yes, return true
                    cmpx      #3        value 3
                    lbeq      ReturnOne yes, return true
                    cmpx      #6        value 6
                    lbeq      ReturnOne yes, return true
                    cmpx      #5        value 5
                    lbeq      ReturnOne yes, return true
                    lbra      ReturnZero not a specifier, false

CheckType52Tok      ldd       GlbVar003F current token type
                    cmpd      #52       is it type 52
                    lbne      ReturnZero no, return false
                    ldx       GlbVar0041 token value
                    ldd       8,x       node type field
                    cmpd      #30       compare to 30
                    bra       TokenMatchTail test result

IsStorageKeyword    pshs      u         save U
                    ldd       GlbVar003F current token type
                    cmpd      #51       is it type 51
                    lbne      ReturnZero no, return false
                    ldx       GlbVar0041 token value
                    cmpx      #14       value 14
                    lbeq      ReturnOne yes, return true
                    cmpx      #13       value 13
                    lbeq      ReturnOne yes, return true
                    cmpx      #30       value 30
                    lbeq      ReturnOne yes, return true
                    cmpx      #16       value 16
                    lbeq      ReturnOne yes, return true
                    cmpx      #15       value 15
                    lbeq      ReturnOne yes, return true
                    cmpx      #33       value 33
TokenMatchTail      lbeq      ReturnOne matched, return true
                    lbra      ReturnZero no match, return false

TypeRemoveLevel     pshs      u         save U
                    ldd       4,s       type code argument
                    asra                shift right one bit
                    rorb                rotate low byte
                    asra                shift right second bit
                    rorb                rotate low byte
                    andb      #$F0      keep derived-type bits
                    bra       MergeTypeBase merge with base type

TypeAddLevel        pshs      u         save U
                    ldd       4,s       type code argument
                    andb      #$F0      isolate derived bits
                    aslb                shift left one bit
                    rola                rotate high byte
                    aslb                shift left second bit
                    rola                rotate high byte
                    addd      #16       add one indirection level
MergeTypeBase       pshs      d         push derived bits
                    ldd       6,s       base type argument
                    clra                clear high byte
                    andb      #$0f      keep base-type nibble
                    addd      ,s++      combine with derived bits
                    puls      pc,u      restore and return

IsTypeCodeInRange   pshs      u         save U
                    ldu       4,s       token code argument
                    cmpu      #76       below range start
                    blt       ReturnZero out of range, false
                    cmpu      #99       above range end
                    bgt       ReturnZero out of range, false
                    ldd       #1        in range, true
                    bra       ReturnD   return result

GetNodeType         pshs      u         save U
                    ldu       4,s       node pointer argument
                    stu       -2,s      test pointer
                    beq       ReturnZero null, return zero
                    ldd       2,u       node type field
                    bra       ReturnD   return it

ExpectToken         pshs      u         save U
                    ldd       GlbVar003F current token type
                    cmpd      4,s       matches expected token
                    bne       LookupTokenName no, report error
                    lbsr      ParseStatement2 consume the token
ReturnZero          clra                clear A
                    clrb                return zero on success
ReturnD             puls      pc,u      restore and return

LookupTokenName     ldu       #0        table index zero
                    bra       NameSearchTest enter search loop

NameSearchLoop      tfr       u,d       index to D
                    leax      CtypeTab,y token-name table
                    leax      d,x       index into table
                    ldb       ,x        table byte
                    sex                 sign-extend
                    cmpd      4,s       matches expected token
                    beq       FoundTokenName found it
                    leau      1,u       next table index
NameSearchTest      cmpu      #128      end of table
                    blt       NameSearchLoop keep searching
FoundTokenName      tfr       u,d       index to D
                    stb       NameBuf,y store found name char
                    leax      NameBuf,y point at name
                    pshs      x         push it
                    lbsr      BuildMsgBuf print expected error
                    leas      2,s        drop argument
ReturnOne           ldd       #1        return true
                    puls      pc,u      restore and return

SkipToRecover       pshs      u         save U
                    bra       SkipTokTest test current token

SkipTokLoop         lbsr      ParseStatement2 advance token
SkipTokTest         ldd       GlbVar003F current token type
                    cmpd      #'(       is it semicolon
                    beq       SkipDone  yes, stop skipping
                    ldd       GlbVar003F current token type
                    cmpd      #'*       is it close brace
                    beq       SkipDone  yes, stop skipping
                    ldd       GlbVar003F current token type
                    cmpd      #$FFFF    end of input
                    bne       SkipTokLoop none yet, keep skipping
SkipDone            puls      pc,u      restore and return

FmtNameColon        fcc       /%s : /
                    fcb       C$NULL
MsgMultiDef         fcc       /multiple definition/
                    fcb       C$NULL
MsgCompilerErr      fcc       /compiler error - /
                    fcb       C$NULL
FmtLineNum          fcc       /line %d  /
                    fcb       C$NULL
FmtStars            fcc       /****  %s  ****/
                    fcb       C$CR,C$NULL
CharCaret           fcb       $5E
                    fcb       C$NULL
MsgTooManyErr       fcc       /too many errors - ABORT/
                    fcb       C$NULL
ParseBinaryExpr     pshs      u         save U
                    ldd       #$FFA2    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -14,s      allocate locals
                    lbsr      ParsePrimaryExpr parse left operand
                    std       12,s      save operand node
                    lbne      ContinueParse non-null, parse operators
                    clra                clear A
                    clrb                null result
                    lbra      ParseExprExit return null

                    lbra      ContinueParse unreached

ParseBinOpLoop      ldd       GlbVar003F save operator token type
                    std       10,s      into local
                    ldd       GlbVar0041 operator value
                    std       8,s       save it
                    std       ,s        also at frame base
                    ldd       GlbSrcLine source line
                    std       4,s       save it
                    ldd       GlbVar0043 source column
                    std       2,s       save it
                    lbsr      ParseStatement2 advance past operator
                    ldx       10,s      X = operator token type
                    bra       ClassifyOperator classify operator

CheckOperatorRange  ldd       10,s      operator token type
                    cmpd      #160      below operator range
                    blt       AdjustOperatorCode outside, count operand
                    ldd       10,s      operator token type
                    cmpd      #169      within operator range
                    ble       ParseRightOperand valid operator
AdjustOperatorCode  ldd       8,s       operator value
                    addd      #1        increment it
                    std       ,s        save adjusted code
                    bra       ParseRightOperand parse right operand

ClassifyOperator    cmpx      #100      special token 100
                    beq       ParseRightOperand yes, parse right operand
                    cmpx      #120      special token 120
                    beq       ParseRightOperand yes, parse right operand
                    bra       CheckOperatorRange check precedence range

ParseRightOperand   ldd       ,s        operator code
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse right operand recursively
                    leas      2,s        drop argument
                    tfr       d,u       U = right node
                    stu       -2,s      test result
                    lbeq      EmitOperandErr null, syntax error
                    ldd       10,s      operator token type
                    cmpd      #100      special token 100
                    lbne      BuildBinNode no, build binary node
                    ldd       #47       node kind 47
                    pshs      d         push it
                    lbsr      ExpectToken expect matching token
                    std       ,s++      save result and pop
                    bne       FreeAndReturn mismatch, free and return
                    ldd       GlbVar0043 source column
                    std       2,s       save it
                    ldd       GlbSrcLine source line
                    std       4,s       save it
                    ldd       #3        operand count
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse third operand
                    leas      2,s        drop argument
                    std       6,s       save node
                    beq       EmitTernaryErr null, error
                    ldd       2,s       source column
                    pshs      d         push it
                    ldd       6,s       operand node
                    pshs      d         push it
                    ldd       #3        node kind 3
                    pshs      d         push it
                    ldd       12,s      left operand
                    pshs      d         push it
                    pshs      u         push right operand
                    ldd       #47       node kind 47
                    pshs      d         push it
                    lbsr      AllocExprNode build expression node
                    leas      12,s       drop arguments
                    tfr       d,u       U = new node
                    bra       BuildBinNode continue building

EmitTernaryErr      leax      MsgThirdExprMissing,pcr error message text
                    pshs      x         push pointer
                    lbsr      BuildMsgBuf print the error
                    leas      2,s        drop argument
FreeAndReturn       pshs      u         push right node
                    lbsr      FreeExprTree free expression tree
                    leas      2,s        drop argument
                    leax      14,s      restore frame pointer
                    bra       RestoreFrame restore and return

BuildBinNode        ldd       2,s       source column
                    pshs      d         push it
                    ldd       6,s       source line
                    pshs      d         push it
                    ldd       12,s      left operand node
                    pshs      d         push it
                    pshs      u         push right operand node
                    ldd       20,s      operator value
                    pshs      d         push it
                    ldd       20,s      operator token type
                    pshs      d         push it
                    lbsr      AllocExprNode build binary expression node
                    leas      12,s       drop arguments
                    std       12,s      save as new left operand
                    bra       ContinueParse look for next operator

EmitOperandErr      leax      MsgOperandExpected,pcr error message text
                    pshs      x         push pointer
                    lbsr      BuildMsgBuf print the error
                    leas      2,s        drop argument
ContinueParse       lbsr      ParseConditional get operator precedence
                    std       -2,s      test and save precedence
                    beq       ParseExprRet none, return operand
                    ldd       18,s      saved precedence
                    cmpd      GlbVar0041 compare token value
                    lble      ParseBinOpLoop higher precedence, keep parsing
                    bra       ParseExprRet done, return operand

RestoreFrame        leas      -14,x     adjust stack pointer
ParseExprRet        ldd       12,s      result operand node
ParseExprExit       leas      14,s       release locals
                    puls      pc,u      restore and return

ParsePrimaryExpr    pshs      u         save U
                    ldd       #$FFA4    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -12,s      allocate locals
                    ldu       #0        clear node pointer
                    ldx       GlbVar003F current token type
                    lbra      DispatchUnaryOp dispatch by token type

BuildLeafNode       ldd       GlbVar0043 source column
                    pshs      d         push it
                    ldd       GlbSrcLine source line
                    pshs      d         push it
                    ldd       GlbVar0041 token value
                    pshs      d         push it
                    clra                clear A
                    clrb                clear B
                    pshs      d         push null field
                    clra                clear A
                    clrb                clear B
                    pshs      d         push null field
                    ldd       GlbVar003F token type
                    pshs      d         push it
                    lbsr      AllocExprNode build token node
                    leas      12,s       drop arguments
                    tfr       d,u       built node pointer to U
                    lbsr      ParseStatement2 get the next token
                    lbra      PostfixLoop resume the postfix loop

ParseParenOrCast    lbsr      ParseStatement2 get next token after (
                    lbsr      IsTypeSpecifier check if a type name follows
                    std       -2,s      save the type result
                    beq       ParseParenExpr not a type, parse parenthesized expression
                    lbsr      ParseCast get the cast type info
                    tfr       d,u       cast type node to U
                    ldd       #46       expected closing ) token
                    pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the )
                    leas      2,s        drop the pushed token
                    bsr       ParsePrimaryExpr parse the operand being cast
                    std       10,u      store operand into the cast node
                    lbne      PostfixLoop got operand, resume postfix loop
                    pshs      u         push the cast node
                    lbsr      LinkFreeNode apply the cast conversion
                    leas      2,s        drop the pushed node
                    ldu       #0        clear the current node
                    lbra      PostfixLoop resume the postfix loop

ParseParenExpr      clra                D = 0
                    clrb                D = 0
                    pshs      d         push null type context
                    lbsr      ParseBinaryExpr parse the parenthesized expression
                    leas      2,s        drop the argument
                    tfr       d,u       expression node to U
                    stu       -2,s      save the node
                    bne       ExpectRParenDone got a node, expect )
                    bra       MakeErrNode empty, build an error node

MakeErrNodeAdj      leas      -12,x     restore the local frame
MakeErrNode         lbsr      ExprMissingErr prepare error recovery
                    ldd       GlbVar0043 current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       #54       node type = constant
                    pshs      d         push node type
                    lbsr      AllocExprNode build the placeholder constant node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
ExpectRParenDone    ldd       #46       expected closing ) token
                    pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the )
                    lbra      OperandDone finish this operand

ParsePrefixOp       ldd       GlbVar003F current token type
                    std       8,s       save the operator token
                    ldd       GlbSrcLine source file info
                    std       6,s       save it
                    ldd       GlbVar0043 current line number
                    std       4,s       save it
                    lbsr      ParseStatement2 get the next token
                    lbsr      ParsePrimaryExpr parse the unary operand
                    std       10,s      save the operand node
                    beq       PrefixOperandErr no operand, report error
                    ldd       4,s       saved line number
                    pshs      d         push line
                    ldd       8,s       saved operator token
                    pshs      d         push token
                    ldd       #14       node type = unary operator
                    pshs      d         push node type
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       18,s      the operand node
                    pshs      d         push operand
                    ldd       18,s      the operand node again
                    pshs      d         push operand
                    lbsr      AllocExprNode build the unary-operator node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
                    lbra      PostfixLoop resume the postfix loop

PrefixOperandErr    leax      MsgPrimaryExpected,pcr address of error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    lbra      OperandDone finish this operand

ParseSizeof         ldd       GlbSrcLine source file info
                    std       6,s       save it
                    ldd       GlbVar0043 current line number
                    std       4,s       save it
                    lbsr      ParseStatement2 get the next token
                    ldd       GlbVar003F current token type
                    cmpd      #45       is it (
                    bne       SizeofUnary no, sizeof a unary expression
                    lbsr      ParseStatement2 get next token after (
                    lbsr      IsTypeSpecifier check if a type name follows
                    std       -2,s      save the type result
                    beq       SizeofExpr not a type, sizeof an expression
                    lbsr      ParseCast get the type's size
                    std       10,s      save the size
                    bra       SizeofExpectRParen expect the closing )

SizeofExpr          clra                D = 0
                    clrb                D = 0
                    pshs      d         push null type context
                    lbsr      ParseBinaryExpr parse the expression
                    leas      2,s        drop the argument
                    std       10,s      save the expression node
                    bne       SizeofExpectRParen got a node, expect )
                    leax      12,s      point past the local frame
                    lbra      MakeErrNodeAdj build an error node

SizeofExpectRParen  ldd       #46       expected closing ) token
                    pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the )
                    leas      2,s        drop the pushed token
                    bra       BuildSizeofNode build the sizeof node

SizeofUnary         lbsr      ParsePrimaryExpr parse the unary operand
                    std       10,s      save the operand node
BuildSizeofNode     ldd       10,s      the operand/size node
                    std       ,s        stash it
                    ldd       4,s       saved line number
                    pshs      d         push line
                    ldd       8,s       saved token
                    pshs      d         push it
                    leax      4,s       point to the saved fields
                    pshs      x         push pointer
                    lbsr      EmitOperand compute the operand's size
                    std       ,s        store the size
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       #54       node type = constant
                    pshs      d         push node type
                    lbsr      AllocExprNode build the size constant node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
                    ldd       ,s        the operand node
                    pshs      d         push it
                    lbsr      FreeExprTree release the operand node
OperandDone         leas      2,s        drop the pushed node
                    bra       PostfixLoop resume the postfix loop

DispatchUnaryOp     cmpx      #55       token is a unary operator
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #52       token is an identifier
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #74       token type
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #75       token type
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #54       token is a constant
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #45       token is (
                    lbeq      ParseParenOrCast parse cast or parenthesized
                    cmpx      #64       prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #67       prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #68       prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #66       prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #61       prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #60       prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #65       prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #59       token is sizeof
                    lbeq      ParseSizeof parse sizeof
PostfixLoop         cmpu      #0        is the current node empty
                    bne       PostfixNext no, handle postfix operators
                    clra                return null node
                    clrb                return null node
                    lbra      UnaryDone return

PostfixNext         ldx       GlbVar003F current token type
                    lbra      DispatchPostfixOp dispatch postfix operators

ParseCall           ldd       GlbVar0043 current line number
                    std       4,s       save it
                    ldd       GlbSrcLine source file info
                    std       6,s       save it
                    lbsr      ParseStatement2 get next token after (
                    ldd       4,s       saved line number
                    pshs      d         push line
                    ldd       8,s       the function expression node
                    pshs      d         push it
                    ldd       #15       node type = call
                    pshs      d         push node type
                    lbsr      ParseArgList parse the argument list
                    pshs      d         push the arg-list node
                    pshs      u         push args
                    ldd       #101      subtype = function call
                    pshs      d         push subtype
                    lbsr      AllocExprNode build the call node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
                    ldd       #46       expected closing ) token
                    lbra      ExpectCloseThenLoop expect ) then loop

ParseSubscript      lbsr      ParseStatement2 get next token after [
                    ldd       #2        assignment precedence level
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse the index expression
                    leas      2,s        drop the argument
                    std       10,s      save the index node
                    bne       BuildSubscript got index, build subscript
                    lbsr      ExprMissingErr prepare error recovery
                    ldd       GlbVar0043 current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       #54       node type = constant
                    pshs      d         push node type
                    lbsr      AllocExprNode build placeholder index node
                    leas      12,s       drop node arguments
                    std       10,s      save the index node
BuildSubscript      ldd       GlbVar0043 current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       #12       node type = add
                    pshs      d         push node type
                    ldd       16,s      the array expression node
                    pshs      d         push it
                    pshs      u         push the index node
                    ldd       #80       subtype
                    pshs      d         push subtype
                    lbsr      AllocExprNode build the base+index node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
                    ldd       GlbVar0043 current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       #15       node type = dereference
                    pshs      d         push node type
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    pshs      u         push the address node
                    ldd       #66       subtype = indirection
                    pshs      d         push subtype
                    lbsr      AllocExprNode build the dereference node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
                    ldd       #44       expected closing ] token
ExpectCloseThenLoop pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the token
                    leas      2,s        drop the pushed token
                    lbra      PostfixNext resume the postfix loop

ParseMemberAccess   ldd       GlbVar003F current token type
                    std       8,s       save the . or -> operator
                    ldd       GlbSrcLine source file info
                    std       6,s       save it
                    ldd       GlbVar0043 current line number
                    std       4,s       save it
                    ldd       GlbNestDepth suppress-lookup depth
                    addd      #1        increment it
                    std       GlbNestDepth store it
                    lbsr      ParseStatement2 get next token, the member name
                    ldd       GlbNestDepth suppress-lookup depth
                    addd      #$FFFF    decrement it
                    std       GlbNestDepth store it
                    ldd       GlbVar003F current token type
                    cmpd      #52       is it an identifier
                    beq       BuildMemberNode yes, build the member node
                    lbsr      ErrIdentMissing report the syntax error
                    lbra      CheckPostIncDec resume the dispatch

BuildMemberNode     ldd       GlbVar0043 current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       GlbVar0041 the member name value
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       GlbVar003F the member token
                    pshs      d         push it
                    lbsr      AllocExprNode build the member-name node
                    leas      12,s       drop node arguments
                    std       10,s      save the member node
                    ldd       4,s       saved line number
                    pshs      d         push line
                    ldd       8,s       saved operator token
                    pshs      d         push it
                    ldd       #15       node type = member select
                    pshs      d         push node type
                    ldd       16,s      the struct expression node
                    pshs      d         push it
                    pshs      u         push the current node
                    ldd       18,s      the member node
                    pshs      d         push it
                    lbsr      AllocExprNode build the member-access node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
                    lbsr      ParseStatement2 get the next token
                    lbra      PostfixNext resume the postfix loop

DispatchPostfixOp   cmpx      #45       token is (
                    lbeq      ParseCall parse a function call
                    cmpx      #43       token is [
                    lbeq      ParseSubscript parse an array subscript
                    cmpx      #69       token is .
                    lbeq      ParseMemberAccess parse member access
                    cmpx      #70       token is ->
                    lbeq      ParseMemberAccess parse member access
CheckPostIncDec     ldx       GlbVar003F current token type
                    bra       DispatchPostIncDec check for ++ or --

ParsePostInc        ldd       #62       post-increment operator token
                    std       GlbVar003F set the operator token
                    leax      12,s      point past the local frame
                    bra       BuildPostIncDecAdj build the inc/dec node

ParsePostDec        ldd       #63       post-decrement operator token
                    std       GlbVar003F set the operator token
                    bra       BuildPostIncDec build the inc/dec node

BuildPostIncDecAdj  leas      -12,x     restore the local frame
BuildPostIncDec     ldd       GlbVar0043 current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       #14       node type = unary operator
                    pshs      d         push node type
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    pshs      u         push the operand node
                    ldd       GlbVar003F the operator token
                    pshs      d         push it
                    lbsr      AllocExprNode build the post inc/dec node
                    leas      12,s       drop node arguments
                    tfr       d,u       node to U
                    lbsr      ParseStatement2 get the next token
                    bra       ReturnNode return the node

DispatchPostIncDec  cmpx      #60       token is ++
                    beq       ParsePostInc parse post-increment
                    cmpx      #61       token is --
                    beq       ParsePostDec parse post-decrement
ReturnNode          tfr       u,d       move current node into D
UnaryDone           leas      12,s       drop the local frame
                    puls      pc,u      restore U and return

ParseArgList        pshs      u         save the caller node
                    ldd       #$FFAE    local frame size
                    lbsr      stkcheck  check for stack overflow
                    leas      -2,s       reserve a local
                    ldu       #0        clear the arg-list node
                    bra       ArgLoop2  enter the argument loop

ArgLoop2            ldd       GlbVar003F current token type
                    cmpd      #46       is it )
                    beq       ArgListDone end of arguments
                    ldd       #2        assignment precedence level
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse one argument expression
                    leas      2,s        drop the argument
                    std       ,s        save the argument node
                    beq       ArgCheckComma none, check for comma
                    ldx       ,s        the argument node
                    ldd       16,x      its line field
                    pshs      d         push it
                    ldx       2,s       the argument node
                    ldd       14,x      its file field
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    pshs      u         push the current arg-list
                    ldd       8,s       the argument node
                    pshs      d         push it
                    ldd       #11       node type = argument link
                    pshs      d         push node type
                    lbsr      AllocExprNode build the argument-link node
                    leas      12,s       drop node arguments
                    std       ,s        save the link node
                    ldu       ,s        link node to U
ArgCheckComma       ldd       GlbVar003F current token type
                    cmpd      #'0       is it a comma
                    bne       ArgListDone no, arguments done
                    lbsr      ParseStatement2 get the next token
                    bra       ArgLoop2  parse the next argument

ArgListDone         tfr       u,d       return the arg-list node
                    bra       ConstExprExit return

ParseConstExpr      pshs      u         save the caller node
                    ldd       #$FFB8    local frame size
                    lbsr      stkcheck  check for stack overflow
                    leas      -2,s       reserve a local
                    ldd       6,s       caller-supplied context
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse the expression
                    std       ,s        save the node
                    lbsr      CopyExprTree constant-fold the expression
                    leas      2,s        drop the argument
                    tfr       d,u       folded node to U
                    stu       -2,s      save it
                    beq       ConstExprErr nothing, report error
                    ldd       6,u       node type
                    cmpd      #54       is it a constant
                    bne       ConstExprErr no, report error
                    ldd       8,u       the constant value
                    std       ,s        save it
                    bra       ConstExprCleanup clean up and return

ConstExprErr        clra                value = 0
                    clrb                value = 0
                    std       ,s        save the zero result
                    leax      MsgConstRequired,pcr constant-required message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop the pushed pointer
ConstExprCleanup    stu       -2,s      refresh the saved node
                    beq       ConstExprResult no node, return the value
                    pshs      u         push the node
                    lbsr      FreeExprTree release the node
                    leas      2,s        drop the pushed node
ConstExprResult     ldd       ,s        the constant value
ConstExprExit       leas      2,s        drop the local
                    puls      pc,u      restore U and return

ParseConditional    pshs      u         save the caller node
                    ldd       #$FFC0    local frame size
                    lbsr      stkcheck  check for stack overflow
                    ldx       GlbVar003F current token type
                    bra       ClassifyConstType dispatch on the token

TernaryOp           ldd       #87       ternary operator token
                    std       GlbVar003F set the token
                    ldd       #8        node subtype
                    bra       StoreTypeSize build the conditional node

SetTypeLong         ldd       #82       load long type code
                    std       GlbVar003F set current type to long
                    ldd       #13       long type size
                    bra       StoreTypeSize store size and return valid

SetTypeInt          ldd       #81       load int type code
                    std       GlbVar003F set current type to int
                    ldd       #12       int type size
StoreTypeSize       std       GlbVar0041 store current type size
ConstTypeValid      ldd       #1        result equals valid
                    puls      pc,u      return to caller

CheckTypeInRange    ldd       GlbVar003F load current type code
                    cmpd      #71       below scalar range
                    blt       ReloadTypeCode try pointer range
                    ldd       GlbVar003F reload type code
                    cmpd      #95       above scalar range
                    ble       ResultValid in scalar range so valid
ReloadTypeCode      ldd       GlbVar003F reload type code
                    cmpd      #160      below pointer range
                    lblt      FoldZero  not usable return zero
                    ldd       GlbVar003F reload type code
                    cmpd      #169      above pointer range
                    lbgt      FoldZero  not usable return zero
ResultValid         ldd       #1        result equals valid
                    lbra      FoldReturn return to caller

ClassifyConstType   cmpx      #65       type code A
                    beq       TernaryOp normalize that type
                    cmpx      #66       type code B
                    beq       SetTypeLong normalize to long
                    cmpx      #67       type code C
                    beq       SetTypeInt normalize to int
                    cmpx      #48       already usable type
                    beq       ConstTypeValid accept as valid
                    cmpx      #120      already usable type
                    lbeq      ConstTypeValid accept as valid
                    cmpx      #100      already usable type
                    lbeq      ConstTypeValid accept as valid
                    cmpx      #47       void or no type
                    lbeq      FoldZero  reject return zero
                    bra       CheckTypeInRange range-check other codes

                    puls      pc,u      unreachable return

FoldConstOp         pshs      u         save the caller u register
                    ldd       #$FFB8    stack frame size
                    lbsr      stkcheck  check stack space
                    ldx       4,s       X equals operator code
                    lbra      FoldConstOpDispatch dispatch to operator handler

FoldAdd             ldd       6,s       left operand
                    addd      8,s       add right operand
                    puls      pc,u      return the sum

FoldSub             ldd       6,s       left operand
                    subd      8,s       subtract right operand
                    puls      pc,u      return the difference

FoldMul             ldd       6,s       left operand
                    pshs      d         push as argument
                    ldd       10,s      right operand
                    lbsr      MulEntry  multiply operands
                    puls      pc,u      return the product

FoldDiv             ldd       8,s       divisor operand
                    beq       FoldDivZeroErr zero divisor error
                    ldd       6,s       dividend operand
                    pshs      d         push dividend
                    ldd       10,s      divisor argument
                    lbsr      SDivEntry divide operands
                    bra       FoldDivDone return the quotient

FoldMod             ldd       8,s       divisor operand
                    beq       FoldDivZeroErr zero divisor error
                    ldd       6,s       dividend operand
                    pshs      d         push dividend
                    ldd       10,s      divisor argument
                    lbsr      SignedDivSetup compute remainder
FoldDivDone         puls      pc,u      return the result

FoldDivZeroErr      lbsr      DivByZeroErr report divide by zero
                    lbra      FoldZero  return zero

FoldBitAnd          ldd       6,s       left operand
                    anda      8,s       and high byte
                    andb      9,s       and low byte
                    puls      pc,u      return bitwise and

FoldBitOr           ldd       6,s       left operand
                    ora       8,s       or high byte
                    orb       9,s       or low byte
                    puls      pc,u      return bitwise or

FoldBitXor          ldd       6,s       left operand
                    eora      8,s       xor high byte
                    eorb      9,s       xor low byte
                    puls      pc,u      return bitwise xor

FoldShl             ldd       6,s       value to shift
                    pshs      d         push value
                    ldd       10,s      shift count
                    lbsr      AslEntry  shift left
                    puls      pc,u      return shifted value

FoldShr             ldd       6,s       value to shift
                    pshs      d         push value
                    ldd       10,s      shift count
                    lbsr      AsrEntry  shift right
                    puls      pc,u      return shifted value

FoldEq              ldd       6,s       left operand
                    cmpd      8,s       compare operands
                    lbne      FoldZero  not equal return zero
                    ldd       #1        equal so result one
                    lbra      FoldReturn return result

FoldNe              ldd       6,s       left operand
                    cmpd      8,s       compare operands
                    lbeq      FoldZero  equal return zero
                    ldd       #1        not equal so result one
                    lbra      FoldReturn return result

FoldGt              ldd       6,s       left operand
                    cmpd      8,s       compare operands
                    lble      FoldZero  not greater return zero
                    ldd       #1        greater so result one
                    lbra      FoldReturn return result

FoldLt              ldd       6,s       left operand
                    cmpd      8,s       compare operands
                    lbge      FoldZero  not less return zero
                    ldd       #1        less so result one
                    lbra      FoldReturn return result

FoldGe              ldd       6,s       left operand
                    cmpd      8,s       compare operands
                    lblt      FoldZero  less return zero
                    ldd       #1        greater-or-equal result one
                    lbra      FoldReturn return result

FoldLe              ldd       6,s       left operand
                    cmpd      8,s       compare operands
                    lbgt      FoldZero  greater return zero
                    ldd       #1        less-or-equal result one
                    lbra      FoldReturn return result

FoldNeg             ldd       6,s       operand to negate
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #0        propagate borrow
                    puls      pc,u      return negated value

FoldLogNot          ldd       6,s       operand
                    lbne      FoldZero  nonzero return zero
                    ldd       #1        zero so result one
                    lbra      FoldReturn return result

FoldBitNot          ldd       6,s       operand
                    coma                complement high byte
                    comb                complement low byte
                    puls      pc,u      return complement

FoldLogAnd          ldd       6,s       left operand
                    lbeq      FoldZero  left zero result zero
                    ldd       8,s       right operand
                    lbeq      FoldZero  right zero result zero
                    ldd       #1        both nonzero result one
                    lbra      FoldReturn return result

FoldLogOr           ldd       6,s       left operand
                    bne       FoldLogOrTrue left nonzero result one
                    ldd       8,s       right operand
                    lbeq      FoldZero  both zero result zero
FoldLogOrTrue       ldd       #1        result one
                    lbra      FoldReturn return result

FoldUnsignedCmp     leas      -4,s       make room for locals
                    ldd       12,s      right operand
                    std       2,s       save as local
                    ldd       10,s      left operand
                    std       ,s        save as local
                    ldx       8,s       X equals comparison operator
                    bra       FoldUnsignedDispatch dispatch unsigned compare

FoldUle             ldd       ,s        left operand
                    cmpd      2,s       unsigned compare
                    bhi       FoldCmpFalse if above result zero
                    ldd       #1        otherwise result one
                    bra       FoldCmpDone return result

FoldUlt             ldd       ,s        left operand
                    cmpd      2,s       unsigned compare
                    bcc       FoldCmpFalse if at-or-above result zero
                    ldd       #1        otherwise result one
                    bra       FoldCmpDone return result

FoldUge             ldd       ,s        left operand
                    cmpd      2,s       unsigned compare
                    bcs       FoldCmpFalse if below result zero
                    ldd       #1        otherwise result one
                    bra       FoldCmpDone return result

FoldUgt             ldd       ,s        left operand
                    cmpd      2,s       unsigned compare
                    bls       FoldCmpFalse if below-or-equal result zero
                    ldd       #1        otherwise result one
                    bra       FoldCmpDone return result

FoldCmpFalse        clra                result zero high
                    clrb                result zero low
FoldCmpDone         leas      4,s        drop locals
                    puls      pc,u      return result

FoldUnsignedDispatch cmpx      #96       unsigned less-or-equal operator
                    beq       FoldUle   fold that comparison
                    cmpx      #97       unsigned less-than operator
                    beq       FoldUlt   fold that comparison
                    cmpx      #98       unsigned greater-or-equal operator
                    beq       FoldUge   fold that comparison
                    bra       FoldUgt   else unsigned greater-than

                    leas      4,s        unreachable drop locals
BadConstOpErr       leax      MsgConstOperator,pcr constant operator message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop argument
FoldZero            clra                result zero high
                    clrb                result zero low
FoldReturn          puls      pc,u      return result

FoldConstOpDispatch cmpx      #80       add operator
                    lbeq      FoldAdd   fold add
                    cmpx      #81       subtract operator
                    lbeq      FoldSub   fold subtract
                    cmpx      #82       multiply operator
                    lbeq      FoldMul   fold multiply
                    cmpx      #83       divide operator
                    lbeq      FoldDiv   fold divide
                    cmpx      #84       modulo operator
                    lbeq      FoldMod   fold modulo
                    cmpx      #87       bitwise-and operator
                    lbeq      FoldBitAnd fold and
                    cmpx      #88       bitwise-or operator
                    lbeq      FoldBitOr fold or
                    cmpx      #89       bitwise-xor operator
                    lbeq      FoldBitXor fold xor
                    cmpx      #86       shift-left operator
                    lbeq      FoldShl   fold shift left
                    cmpx      #85       shift-right operator
                    lbeq      FoldShr   fold shift right
                    cmpx      #90       equality operator
                    lbeq      FoldEq    fold equal
                    cmpx      #91       inequality operator
                    lbeq      FoldNe    fold not-equal
                    cmpx      #95       greater-than operator
                    lbeq      FoldGt    fold greater-than
                    cmpx      #93       less-than operator
                    lbeq      FoldLt    fold less-than
                    cmpx      #94       greater-or-equal operator
                    lbeq      FoldGe    fold greater-or-equal
                    cmpx      #92       less-or-equal operator
                    lbeq      FoldLe    fold less-or-equal
                    cmpx      #67       unary minus operator
                    lbeq      FoldNeg   fold negate
                    cmpx      #64       logical-not operator
                    lbeq      FoldLogNot fold logical not
                    cmpx      #68       bitwise-not operator
                    lbeq      FoldBitNot fold complement
                    cmpx      #71       logical-and operator
                    lbeq      FoldLogAnd fold logical and
                    cmpx      #72       logical-or operator
                    lbeq      FoldLogOr fold logical or
                    cmpx      #96       unsigned less-or-equal operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    cmpx      #97       unsigned less-than operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    cmpx      #98       unsigned greater-or-equal operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    cmpx      #99       unsigned greater-than operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    lbra      BadConstOpErr unknown operator error

                    puls      pc,u      unreachable return

ParseCast           pshs      u         save the caller u register
                    ldd       #$FFA2    stack frame size
                    lbsr      stkcheck  check stack space
                    leas      -14,s      allocate locals
                    ldd       GlbSrcLine current source position global
                    std       4,s       save into locals
                    ldd       GlbVar0043 current type global
                    std       2,s       save into locals
                    leax      ,s        point at locals
                    pshs      x         push pointer argument
                    leax      12,s      address of arg slot
                    pshs      x         push pointer argument
                    leax      16,s      address of arg slot
                    pshs      x         push pointer argument
                    lbsr      ParseDeclSpec parse declaration specifiers
                    leas      6,s        drop arguments
                    std       8,s       save base type
                    pshs      d         push base type
                    leax      12,s      address of declarator slot
                    pshs      x         push pointer argument
                    leax      10,s      address of slot
                    pshs      x         push pointer argument
                    lbsr      ParseDeclarator parse abstract declarator
                    leas      6,s        drop arguments
                    std       8,s       save declared type
                    leax      >IdentifierField,y  point at identifier field
                    pshs      x         push pointer argument
                    lbsr      FreeLocalSymbols check for declarator name
                    leas      2,s        drop argument
                    ldd       6,s       declared name present
                    beq       CastTypeOk no name type-only cast ok
                    leax      MsgNameInCast,pcr name in a cast message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop argument
CastTypeOk          ldd       2,s       saved outer type
                    pshs      d         push type argument
                    ldd       6,s       declared type
                    pshs      d         push type argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push null field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push null field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push null field
                    ldd       #32       cast node kind
                    pshs      d         push node kind
                    bsr       AllocExprNode allocate cast node
                    leas      12,s       drop node arguments
                    std       6,s       save node pointer
                    ldd       8,s       declared type
                    std       [6,s]     store type into node
                    ldd       12,s      operand subtree
                    pshs      d         push argument
                    ldd       12,s      operand subtree
                    pshs      d         push argument
                    ldd       10,s      node pointer
                    pshs      d         push argument
                    lbsr      CalcTypeSize build cast expression
                    leas      6,s        drop arguments
                    ldd       6,s       result node pointer
                    leas      14,s       release locals
                    puls      pc,u      return node

AllocExprNode       pshs      u         save the caller u register
                    ldd       #$FFBA    stack frame size
                    lbsr      stkcheck  check stack space
                    ldd       GlbVar000D free-node list head
                    beq       AllocNodeFromHeap empty so allocate from heap
                    ldu       GlbVar000D take node off free list
                    ldd       10,u      next free node
                    std       GlbVar000D update free list head
                    bra       FillNodeFields fill node fields

AllocNodeFromHeap   ldd       #22       node size in bytes
                    pshs      d         push size argument
                    lbsr      AllocMem  allocate memory
                    leas      2,s        drop argument
                    tfr       d,u       U equals new node
FillNodeFields      ldd       4,s       argument field zero
                    std       6,u       store in node
                    ldd       6,s       argument field one
                    std       10,u      store in node
                    ldd       8,s       argument field two
                    std       12,u      store in node
                    ldd       10,s      argument field three
                    std       8,u       store in node
                    ldd       12,s      argument field four
                    std       14,u      store in node
                    ldd       14,s      argument field five
                    std       16,u      store in node
                    clra                clear high byte
                    clrb                clear low byte
                    std       20,u      clear node link field
                    tfr       u,d       return node pointer
                    puls      pc,u      return to caller

ExprMissingErr      pshs      u         save the caller u register
                    ldd       #$FFBA    stack frame size
                    lbsr      stkcheck  check stack space
                    leax      MsgExprMissing,pcr expression missing message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    lbra      EmitOperandDone return to caller

EmitOperand         pshs      u         save the caller u register
                    ldd       #$FFB6    stack frame size
                    lbsr      stkcheck  check stack space
                    ldu       [4,s]     U equals target node
                    ldx       6,u       X equals node kind
                    bra       EmitOperandDispatch dispatch on node kind

EmitOperandCopy     pshs      u         save the caller u register
                    lbsr      CopyExprTree copy expression subtree
                    leas      2,s        drop argument
                    std       [4,s]     store copied subtree
                    tfr       d,u       U equals copied node
                    leax      ,s        point at stack slot
                    bra       EmitFromStack emit operand

EmitIndirect        ldd       [8,u]     indirect operand value
                    std       ,u        store into node
                    pshs      u         push node argument
                    lbsr      ReportUndeclared process indirect node
                    leas      2,s        drop argument
                    ldu       8,u       follow pointer field
                    bra       EmitOperandDesc emit operand descriptor

EmitFromStack       leas      ,x        restore stack pointer
EmitOperandDesc     ldd       4,u       node field two
                    pshs      d         push argument
                    ldd       2,u       node field one
                    pshs      d         push argument
                    ldd       ,u        node field zero
                    pshs      d         push argument
                    lbsr      ResolveTypeSize emit operand
                    leas      6,s        drop arguments
                    puls      pc,u      return to caller

EmitOffsetOperand   pshs      u         save the caller u register
                    ldd       #12       node record size
                    addd      ,s++      advance to next node
                    pshs      d         push node pointer
                    bsr       EmitOperand emit next operand
EmitOperandDone     leas      2,s        drop argument
                    puls      pc,u      return to caller

EmitOperandDispatch cmpx      #52       indirect node kind
                    beq       EmitIndirect emit indirect operand
                    cmpx      #32       leaf node kind
                    beq       EmitOperandDesc emit operand descriptor
                    cmpx      #69       offset node kind
                    beq       EmitOffsetOperand emit offset operand
                    cmpx      #70       offset node kind
                    lbeq      EmitOffsetOperand emit offset operand
                    lbra      EmitOperandCopy default copy and emit

                    puls      pc,u      unreachable return

MsgThirdExprMissing fcc       /third expression missing/
                    fcb       C$NULL
MsgOperandExpected  fcc       /operand expected/
                    fcb       C$NULL
MsgPrimaryExpected  fcc       /primary expected/
                    fcb       C$NULL
MsgConstRequired    fcc       /constant required/
                    fcb       C$NULL
MsgConstOperator    fcc       /constant operator/
                    fcb       C$NULL
MsgNameInCast       fcc       /name in a cast/
                    fcb       C$NULL
MsgExprMissing      fcc       /expression missing/
                    fcb       C$NULL
CopyExprTree        pshs      u         save the caller u register
                    ldd       #$FFAE    stack frame size
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U equals source node
                    leas      -12,s      allocate locals
                    stu       -2,s      save source sets zero if null
                    lbeq      ReturnNode2 null node return empty
                    ldd       10,u      left child pointer
                    pshs      d         push child argument
                    bsr       CopyExprTree copy left child
                    leas      2,s        drop argument
                    std       10,u      record copied left child
                    ldd       12,u      right child pointer
                    pshs      d         push child argument
                    lbsr      CopyExprTree copy right child
                    leas      2,s        drop argument
                    std       12,u      record copied right child
                    pshs      u         push node argument
                    lbsr      GenExprNode duplicate node record
                    leas      2,s        drop argument
                    tfr       d,u       U equals new node copy
                    pshs      u         push new node
                    lbsr      ReduceNode finalize copied node
                    std       ,s++      store result and pop
                    beq       FoldSelectOrMerge ReduceNode gave zero so try const-fold
                    leax      12,s      point X past the local frame
                    lbra      RestoreFrameX return the transformed node

FoldSelectOrMerge   pshs      u         save node for the folder
                    lbsr      FoldConstNode constant-fold this node
                    leas      2,s        drop the argument
                    tfr       d,u       U = folded node
                    ldd       10,u      D = node left child
                    std       10,s      stash left in record
                    ldd       12,u      D = node right child
                    std       8,s       stash right in record
                    ldd       6,u       D = node opcode
                    std       4,s       stash opcode in record
                    cmpd      #100      is it a conditional-select operator
                    bne       CheckPtrMerge no so try pointer merge
                    ldx       10,s      X = condition child
                    ldd       6,x       D = condition opcode
                    cmpd      #54       is the condition a constant
                    bne       CheckPtrMerge no so cannot fold
                    ldx       10,s      X = condition node
                    ldd       8,x       D = constant condition value
                    beq       SelectFalseBranch condition false so pick other branch
                    ldx       8,s       X = branch-pair node
                    ldd       10,x      D = discarded branch subtree
                    std       2,s       remember discarded branch
                    ldx       8,s       X = branch-pair node
                    ldd       12,x      D = kept branch subtree
                    bra       ReduceSelect reduce to the kept branch

SelectFalseBranch   ldx       8,s       X = branch-pair node
                    ldd       12,x      D = discarded branch subtree
                    std       2,s       remember discarded branch
                    ldx       8,s       X = branch-pair node
                    ldd       10,x      D = kept branch subtree
ReduceSelect        pshs      d         save the discarded subtree
                    lbsr      FreeExprTree free the discarded subtree
                    leas      2,s        drop the argument
                    ldd       8,s       D = branch-pair node
                    pshs      d         push it
                    lbsr      LinkFreeNode free the branch-pair node
                    leas      2,s        drop the argument
                    ldd       10,s      D = condition node
                    pshs      d         push it
                    lbsr      LinkFreeNode free the condition node
                    leas      2,s        drop the argument
                    pshs      u         push the kept node
                    bra       FreeAndReturnNode free record and return it

CheckPtrMerge       ldd       4,s       D = node opcode
                    cmpd      #66       is it operator B
                    bne       CheckPtrMergeAlt no so check the A form
                    ldx       10,s      X = left child
                    ldd       6,x       D = left opcode
                    cmpd      #65       is left operator A
                    beq       MergePtrOffset yes so merge pointer offsets
CheckPtrMergeAlt    ldd       4,s       D = node opcode
                    cmpd      #65       is it operator A
                    bne       ReturnNode2 no so nothing to do
                    ldx       10,s      X = left child
                    ldd       6,x       D = left opcode
                    cmpd      #66       is left operator B
                    bne       ReturnNode2 no so nothing to do
MergePtrOffset      ldx       10,s      X = left child
                    ldd       10,x      D = left's left field
                    std       2,s       save that pointer
                    ldd       ,u        D = node's first word
                    std       [2,s]     store it through saved pointer
                    ldd       2,u       D = node offset field
                    ldx       2,s       X = saved pointer
                    std       2,x       write offset into inner node
                    pshs      u         push the node
                    lbsr      LinkFreeNode free the node
                    leas      2,s        drop the argument
                    ldd       10,s      D = original left child
                    pshs      d         push it
FreeAndReturnNode   lbsr      LinkFreeNode free that node
                    leas      2,s        drop the argument
                    ldu       2,s       U = replacement node
                    bra       ReturnNode2 return the replacement

RestoreFrameX       leas      -12,x     restore stack from X frame
ReturnNode2         tfr       u,d       return node in D
                    leas      12,s       drop the local frame
                    puls      pc,u      restore U and return

FoldConstNode       pshs      u         save U
                    ldd       #$FFA8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       4,s       U = node argument
                    leas      -14,s      allocate local record
                    stu       -2,s      store node and set flags
                    bne       FoldSetup non-null so process it
                    clra                high byte of null result
                    clrb                low byte of null result
                    lbra      FoldReturn2 return null

FoldSetup           ldd       10,u      D = node left child
                    std       12,s      save left in record
                    ldd       12,u      D = node right child
                    std       10,s      save right in record
                    ldd       6,u       D = node opcode
                    std       6,s       save opcode in record
                    pshs      d         push opcode
                    lbsr      IsTypeCodeInRange is opcode a foldable operator
                    std       ,s++      save result and pop
                    bne       CheckConstOperands yes so try to fold
                    ldd       6,s       D = node opcode
                    cmpd      #71       is it operator G
                    beq       CheckConstOperands yes so foldable
                    ldd       6,s       D = node opcode
                    cmpd      #72       is it operator H
                    lbne      UnaryDispatchPrep not foldable try unary/convert
CheckConstOperands  ldx       12,s      X = left child
                    ldd       6,x       D = left opcode
                    cmpd      #54       is left a constant literal
                    bne       LeftNotConst no
                    ldd       #1        flag left constant
                    bra       SaveLeftConstFlag store the flag

LeftNotConst        clra                high byte cleared
                    clrb                flag left non-constant
SaveLeftConstFlag   std       2,s       save left-const flag
                    pshs      d         push the flag
                    ldx       12,s      X = left child
                    ldd       6,x       D = left opcode
                    cmpd      #54       is left a constant literal
                    bne       LeftNotConst2 no
                    ldd       #1        flag constant
                    bra       SaveConstFlag2 store the flag

LeftNotConst2       clra                high byte cleared
                    clrb                flag non-constant
SaveConstFlag2      std       2,s       save the flag
                    anda      ,s+       AND high byte with pushed flag
                    andb      ,s+       AND low byte with pushed flag
                    std       -2,s      both operands constant
                    beq       TryCommute not both constant so continue
                    leax      14,s      point X past record
                    lbra      BinaryConstFixup fold the two constants

TryCommute          ldd       2,s       D = left-const flag
                    beq       FoldDispatchPrep left not constant skip reorder
                    ldx       6,s       X = node opcode
                    bra       IsCommutative test commutativity

SwapOperands        ldd       12,s      D = left child
                    std       8,s       stash left
                    ldd       10,s      D = right child
                    std       12,s      record left = right
                    std       10,u      write swapped left into node
                    ldd       8,s       D = stashed left
                    std       10,s      record right = left
                    std       12,u      write swapped right into node
                    ldd       #1        flag operands swapped
                    std       ,s        save swap flag
                    bra       FoldDispatchPrep proceed to dispatch

IsCommutative       cmpx      #80       operator P
                    beq       SwapOperands commutative so swap
                    cmpx      #82       operator R
                    lbeq      SwapOperands commutative so swap
                    cmpx      #87       operator W
                    lbeq      SwapOperands commutative so swap
                    cmpx      #88       operator X
                    lbeq      SwapOperands commutative so swap
                    cmpx      #89       operator Y
                    lbeq      SwapOperands commutative so swap
FoldDispatchPrep    ldx       6,s       X = node opcode
                    lbra      FoldDispatch jump to fold dispatch

FoldZeroIdentity    ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       10,s      X = right operand
                    ldd       8,x       D = right value
                    lbeq      ReplaceWithOperand zero operand use the other
                    lbra      NoFold    else no fold

FoldAdd2            ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       10,s      X = right operand
                    ldd       8,x       D = right value
                    lbeq      ReplaceWithOperand add zero use other operand
                    ldx       12,s      X = left operand
                    ldx       6,x       X = left opcode
                    lbra      CheckAddPtr check pointer arithmetic

FoldPtrOffset       ldx       12,s      X = left operand
                    ldx       10,x      X = left's operand node
                    ldd       20,x      D = its offset field
                    leax      20,x      X = address of offset field
                    pshs      x,d       save pointer and offset
                    ldx       14,s      X = right operand
                    ldd       8,x       D = right value
                    addd      ,s++      add the saved offset
                    std       [,s++]    store folded offset back
                    bra       KeepOtherOperand reduce the node

KeepOperandFixup    leas      -14,x     restore stack from X
KeepOtherOperand    ldd       12,s      D = left operand
                    std       8,s       stash it as keeper
                    pshs      u         push the node
                    lbsr      LinkFreeNode free the node
                    leas      2,s        drop the argument
                    ldd       10,s      D = right operand
                    pshs      d         push it
                    lbsr      LinkFreeNode free the right operand
                    leas      2,s        drop the argument
                    ldu       8,s       U = kept operand
                    lbra      NoFold    return the kept operand

FoldNestedAdd       ldx       12,s      X = left operand
                    ldx       12,x      X = left's right child
                    ldd       6,x       D = its opcode
                    cmpd      #54       is it a constant
                    lbne      NoFold    no so cannot fold
                    ldx       12,s      X = left operand
                    ldx       12,x      X = left's right child
                    ldd       8,x       D = that constant value
                    leax      8,x       X = address of value
                    pshs      x,d       save pointer and value
                    ldx       14,s      X = right operand
                    ldd       8,x       D = right value
                    addd      ,s++      add the two constants
                    lbra      StoreFoldedConst store the folded value

CheckAddPtr         cmpx      #65       left is operator A
                    lbeq      FoldPtrOffset fold pointer offset
                    cmpx      #80       left is operator P
                    beq       FoldNestedAdd fold nested add constant
                    lbra      NoFold    else no fold

FoldSubtract        ldd       ,s        D = swap flag
                    beq       FoldZeroMinus not swapped check zero minuend
                    ldx       10,s      X = right operand
                    ldd       8,x       D = right value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #0        finish two's complement negate
                    ldx       10,s      X = right operand
                    std       8,x       store negated value
                    ldd       #80       change opcode to add P
                    std       6,u       subtract-const becomes add-negated
                    pshs      u         push the node
                    lbsr      FoldConstNode re-fold the node
                    leas      2,s        drop the argument
                    lbra      FoldReturn2 return the re-folded node

FoldZeroMinus       ldd       2,s       D = left-const flag
                    lbeq      NoFold    left not constant so no fold
                    ldx       12,s      X = left operand
                    ldd       8,x       D = left value
                    lbne      NoFold    nonzero minuend so no fold
                    ldd       #67       set opcode to negate C
                    std       6,u       zero minus x becomes negate
                    ldd       10,s      D = right operand
                    std       10,u      make it the child
                    clra                high byte cleared
                    clrb                low byte cleared
                    std       12,u      clear the right child
                    ldd       12,s      D = old left operand
                    lbra      FreeChildDone free it and finish

FoldZeroOperand     ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       10,s      X = right operand
                    ldd       8,x       D = right value
                    beq       MakeZeroFixup operand zero so result zero
                    lbra      NoFold    else no fold

FoldMultiply        ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       10,s      X = right operand
                    ldx       8,x       X = right value
                    bra       DispatchMultiplier dispatch on the multiplier

MakeZeroFixup       leax      14,s      point X past record
                    lbra      MakeZeroFixup2 make node constant zero

FoldNestedMul       ldx       12,s      X = left operand
                    ldd       6,x       D = left opcode
                    cmpd      #82       is left a multiply R
                    lbne      NoFold    no so cannot fold
                    ldx       12,s      X = left operand
                    ldx       12,x      X = left's right child
                    ldd       6,x       D = its opcode
                    cmpd      #54       is it a constant
                    lbne      NoFold    no so cannot fold
                    ldx       12,s      X = left operand
                    ldx       12,x      X = left's right child
                    ldd       8,x       D = that constant
                    leax      8,x       X = address of value
                    pshs      x,d       save pointer and value
                    ldx       14,s      X = right operand
                    ldd       8,x       D = right multiplier
                    lbsr      MulEntry  multiply the two constants
StoreFoldedConst    std       [,s++]    store the folded product back
                    bra       ReplaceWithOperand reduce to that operand

DispatchMultiplier  stx       -2,s      save the multiplier value
                    beq       MakeZeroFixup times zero so result zero
                    cmpx      #1        times one
                    beq       ReplaceWithOperand identity so use other operand
                    bra       FoldNestedMul else try nested multiply

FoldDivide          ldd       ,s        D = swap flag
                    beq       CheckZeroDividend not swapped check divide
                    ldx       10,s      X = right operand
                    ldd       8,x       D = right value
                    cmpd      #1        divide by one
                    bne       CheckZeroDividend no so check zero dividend
ReplaceWithOperand  leax      14,s      point X past record
                    lbra      KeepOperandFixup replace node with kept operand

CheckZeroDividend   ldd       2,s       D = left-const flag
                    lbeq      NoFold    left not constant so no fold
                    ldx       12,s      X = left operand
                    ldd       8,x       D = left value
                    lbne      NoFold    nonzero dividend so no fold
                    bra       MakeConstZero zero divided so result zero

MakeZeroFixup2      leas      -14,x     restore stack from X
MakeConstZero       ldd       #54       constant node type
                    std       6,u       make node a constant
                    clra                high byte cleared
                    clrb                value zero
StoreConstFreeChildren std       8,u       store value into node
                    clra                high byte cleared
                    clrb                low byte cleared
                    std       12,u      clear the right child
                    std       10,u      clear the left child
                    ldd       12,s      D = old left operand
                    pshs      d         push it
                    lbsr      LinkFreeNode free old left operand
                    leas      2,s        drop the argument
                    ldd       10,s      D = old right operand
FreeChildDone       pshs      d         push it
                    lbsr      LinkFreeNode free old right operand
FoldRet             leas      2,s        drop the argument
                    lbra      NoFold    return the folded node

FoldDispatch        cmpx      #88       operator X
                    lbeq      FoldZeroIdentity fold zero identity
                    cmpx      #89       operator Y
                    lbeq      FoldZeroIdentity fold zero identity
                    cmpx      #80       operator P is add
                    lbeq      FoldAdd2  fold addition
                    cmpx      #81       operator Q is subtract
                    lbeq      FoldSubtract fold subtraction
                    cmpx      #87       operator W
                    lbeq      FoldZeroOperand fold zero-operand product
                    cmpx      #82       operator R is multiply
                    lbeq      FoldMultiply fold multiplication
                    cmpx      #83       operator S is divide
                    lbeq      FoldDivide fold division
                    lbra      NoFold    no handler so no fold

UnaryDispatchPrep   ldx       6,s       X = node opcode
                    lbra      UnaryDispatch dispatch unary/convert handlers

FoldUnaryConst      ldx       12,s      X = left operand
                    ldd       6,x       D = left opcode
                    cmpd      #54       is operand a constant
                    bne       FoldConvertJ no so try convert op
                    bra       EvalBinaryConst fold the unary constant

BinaryConstFixup    leas      -14,x     restore stack from X
EvalBinaryConst     ldd       #54       constant node type
                    std       6,u       make node a constant
                    clra                high byte cleared
                    clrb                low byte cleared
                    std       18,u      clear the extra field
                    ldx       10,s      X = right operand
                    ldd       8,x       D = right value
                    pshs      d         push right value
                    ldx       14,s      X = left operand
                    ldd       8,x       D = left value
                    pshs      d         push left value
                    ldd       10,s      D = operator code
                    pshs      d         push the operator
                    lbsr      FoldConstOp evaluate operator on constants
                    leas      6,s        drop the arguments
                    lbra      StoreConstFreeChildren store result and free children

FoldConvertJ        ldx       12,s      X = left operand
                    ldd       6,x       D = left opcode
                    cmpd      #74       is it convert-J
                    bne       FoldConvertK no so try convert-K
                    leas      -2,s       make a scratch slot
                    ldx       14,s      X = left operand
                    ldd       8,x       D = left value
                    std       ,s        save it
                    bne       ConvSetup nonzero so keep it
                    ldd       #4        request four bytes
                    pshs      d         push the size
                    lbsr      AllocMem  allocate a node
                    leas      2,s        drop the argument
                    std       ,s        save new node pointer
ConvSetup           ldx       8,s       X = target type field
                    bra       ConvDispatch dispatch the conversion

ConvSigned          ldx       ,s        X = source node
                    pshs      x         push it
                    ldx       2,s       X = value node
                    lbsr      NegateInt32 convert as signed
                    bra       ConvFinalize apply the conversion

ConvUnsigned        ldx       ,s        X = source node
                    pshs      x         push it
                    ldx       2,s       X = value node
                    lbsr      ComplementInt32 convert as unsigned
ConvFinalize        lbsr      StoreInt32 finalize the conversion
                    bra       StoreConverted store the converted value

ConvDispatch        cmpx      #67       target type C
                    beq       ConvSigned signed conversion
                    cmpx      #68       target type D
                    beq       ConvUnsigned unsigned conversion
StoreConverted      ldd       ,s        D = converted value
                    ldx       14,s      X = node
                    std       8,x       store into node value
                    bra       FreeNodeRet free node and finish

FoldConvertK        ldx       12,s      X = left operand
                    ldd       6,x       D = left opcode
                    cmpd      #75       is it convert-K
                    bne       NoFold    no so cannot fold
                    leas      -2,s       make a scratch slot
                    ldx       14,s      X = left operand
                    ldd       8,x       D = left value
                    std       ,s        save it
                    beq       FreeNodeRet zero so just free node
                    ldx       ,s        X = value node
                    pshs      x         push it
                    ldx       2,s       X = node
                    lbsr      NegateConstType perform K conversion
                    lbsr      CopyFloat finalize the conversion
FreeNodeRet         pshs      u         push the node
                    lbsr      LinkFreeNode free the node
                    leas      2,s        drop the argument
                    ldu       14,s      U = replacement operand
                    lbra      FoldRet   return it

UnaryDispatch       cmpx      #64       operator @
                    lbeq      FoldUnaryConst fold unary constant
                    cmpx      #68       operator D
                    lbeq      FoldUnaryConst fold unary constant
                    cmpx      #67       operator C
                    lbeq      FoldUnaryConst fold unary constant
NoFold              tfr       u,d       return node in D
FoldReturn2         leas      14,s       drop the local record
                    puls      pc,u      restore U and return

ReduceNode          pshs      u         save U
                    ldd       #$FFC0    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       4,s       U = node argument
                    stu       -2,s      store node and set flags
                    beq       IsLvalTypeFalse null node so nothing to do
                    ldx       6,u       X = node opcode
                    bra       ClassifyLvalType dispatch simplification

IsLvalTypeTrue      ldd       #1        return true, type is lvalue-capable
                    puls      pc,u      restore U and return

ClassifyLvalType    cmpx      #118      is node type $76
                    beq       IsLvalTypeTrue yes, return true
                    cmpx      #111      is node type $6F
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #54       is node type $36
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #74       is node type $4A
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #75       is node type $4B
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #52       is node type $34
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #55       is node type $37
                    lbeq      IsLvalTypeTrue yes, return true
IsLvalTypeFalse     clra                no match, result = 0
                    clrb                clear low byte
                    puls      pc,u      return false

DivByZeroErr        pshs      u         save caller U
                    ldd       #$FFBA    required stack frame size
                    lbsr      stkcheck  check stack space available
                    leax      MsgDivZero,pcr point to divide by zero message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report compiler error
                    leas      2,s        drop message argument
                    puls      pc,u      restore U and return

GenExprNode         pshs      u         save caller U
                    ldd       #$FF9C    required stack frame size
                    lbsr      stkcheck  check stack space available
                    leas      -20,s      allocate local frame
                    ldx       24,s      X = node pointer argument
                    ldu       10,x      U = node child pointer
                    ldx       24,s      reload node pointer
                    ldd       12,x      get node field $0C
                    std       18,s      save into local
                    ldd       #2        initial value 2
                    std       10,s      init local operand size
                    std       8,s       init local lvalue flag
                    clra                clear A
                    clrb                clear B
                    std       6,s       clear result field local
                    ldd       #1        initial value 1
                    std       12,s      init local result type
                    ldx       24,s      reload node pointer
                    ldd       6,x       get node operator type
                    std       14,s      save current type local
                    tfr       d,x       X = operator type for dispatch
                    lbra      DispatchOp jump into node-type dispatch

GenVarRef           ldx       24,s      X = node pointer
                    ldd       8,x       get symbol subtype pointer
                    std       16,s      save subtype pointer local
                    ldx       16,s      X = subtype descriptor
                    ldd       8,x       load descriptor kind
                    cmpd      #30       is it a typedef
                    bne       GenVarNotTypedef no, generate variable reference
                    leax      MsgTypedefNotVar,pcr point to typedef error message
                    pshs      x         push message pointer
                    ldd       26,s      push source context
                    pshs      d         push context argument
                    lbsr      ReportErrorAt report error at node
                    leas      4,s        drop arguments
                    ldd       24,s      node pointer
                    pshs      d         push node argument
                    lbsr      MakeErrorNode discard bad node
                    leas      2,s        drop argument
                    lbra      NodeDone  handler done, return

GenVarNotTypedef    ldd       [16,s]    load result type indirect
                    std       12,s      save result type local
                    ldx       16,s      X = subtype descriptor
                    ldd       4,x       get descriptor field $04
                    std       6,s       save into result field
                    ldd       12,s      reload result type
                    clra                clear high byte
                    andb      #$0f      keep low nibble
                    cmpd      #10       is storage class $0A
                    bne       GenVarStorageChk no, skip offset adjust
                    leas      -2,s       reserve temp local
                    ldx       18,s      context pointer
                    ldd       2,x       get base offset
                    std       ,s        save temp
                    ldd       14,s      current type value
                    andb      #$F0      keep high nibble
                    addd      [,s]      add member offset indirect
                    std       [18,s]    store back into context
                    std       14,s      update current type
                    ldx       ,s        temp pointer
                    ldd       2,x       get field
                    pshs      d         push argument
                    ldd       10,s      push argument
                    pshs      d         push argument
                    ldd       22,s      push argument
                    pshs      d         push argument
                    lbsr      CalcTypeSize call codegen helper
                    leas      6,s        drop arguments
                    leas      2,s        release temp local
GenVarStorageChk    ldx       16,s      X = subtype descriptor
                    ldd       2,x       get descriptor field $02
                    std       10,s      save operand local
                    ldd       12,s      result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #32       is static/extern class $20
                    beq       GenVarStaticAddr yes, take its address
                    ldd       12,s      result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #48       is class $30
                    lbne      GenVarRegister neither, register/local branch
GenVarStaticAddr    ldu       24,s      U = node pointer
                    ldd       10,s      operand local
                    std       2,u       store into node field $02
                    ldx       24,s      reload node
                    ldd       16,x      get node field $10
                    pshs      d         push argument
                    ldx       26,s      context pointer
                    ldd       14,x      get field $0e
                    pshs      d         push argument
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    pshs      u         push node child
                    ldd       #65       operator $41 address-of
                    pshs      d         push operator
                    lbsr      AllocExprNode build address-of node
                    leas      12,s       drop arguments
                    std       24,s      save new node pointer
                    ldd       12,s      result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #32       is static class $20
                    bne       GenVarLocalType no, use type directly
                    ldd       6,s       result field
                    pshs      d         push argument
                    lbsr      GetNodeType convert type helper
                    leas      2,s        drop argument
                    std       6,s       save result field
                    ldd       12,s      result type
                    pshs      d         push argument
                    lbsr      TypeRemoveLevel make pointer to type
                    leas      2,s        drop argument
                    bra       GenVarStoreType store new result type

GenVarLocalType     ldd       12,s      result type
GenVarStoreType     std       ,u        store type into node
                    pshs      d         push argument
                    lbsr      TypeAddLevel make pointer to type
                    leas      2,s        drop argument
                    std       12,s      save result type
                    ldd       #1        lvalue flag one
                    std       18,u      mark node as lvalue
                    bra       SetLvalTrue set lvalue and return

GenVarRegister      ldx       16,s      X = subtype descriptor
                    ldd       8,x       get descriptor kind
                    std       4,s       save local
                    tfr       d,x       X = type kind
                    bra       GenVarRegTypeChk test register type

GenVarClearField    ldd       4,s       type kind
                    ldx       24,s      node pointer
                    std       6,x       store type into node
                    clra                clear A
                    clrb                clear B
                    ldx       24,s      node pointer
                    std       8,x       clear node subtype field
                    bra       SetLvalTrue set lvalue and return

GenVarRegTypeChk    cmpx      #118      is type $76
                    beq       GenVarClearField yes, clear node fields
                    cmpx      #111      is type $6F
                    lbeq      GenVarClearField yes, clear node fields
SetLvalTrue         ldd       #1        lvalue flag one
                    bra       StoreLvalFlag store lvalue flag

SetLvalFalse        clra                clear A
                    clrb                clear B
StoreLvalFlag       std       8,s       store lvalue flag
                    lbra      NodeDone  handler done, return

GenConstType4A      ldd       #8        result type value $0008
                    std       12,s      set result type
                    ldd       #1        lvalue flag one
                    std       8,s       mark as lvalue
                    ldd       #4        operand size $0004
                    lbra      StoreOperandTail store operand and return

GenConstType4B      ldd       #6        result type value $0006
                    std       12,s      set result type
                    ldd       #1        lvalue flag one
                    std       8,s       mark as lvalue
                    ldd       #8        operand size $0008
                    lbra      StoreOperandTail store operand and return

GenConstType37      ldd       #18       result type value $0012
                    std       12,s      set result type
                    ldd       #1        lvalue flag one
                    lbra      StoreOperandTail store operand and return

GenCast             pshs      u         push node child
                    lbsr      ReportUndeclared evaluate cast operand
                    leas      2,s        drop argument
                    ldd       [24,s]    operand result type indirect
                    std       12,s      save result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #48       is pointer class $30
                    beq       CannotCastErr yes, cannot cast error
                    ldd       12,s      result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #32       is class $20
                    bne       CastArrayChk no, continue casting
CannotCastErr       leax      MsgCannotCast,pcr point to cannot cast message
                    pshs      x         push message pointer
                    ldd       26,s      push source context
                    pshs      d         push context argument
                    lbsr      ReportErrorAt report error at node
                    leas      4,s        drop arguments
                    ldd       12,s      result type
                    pshs      d         push argument
                    lbsr      TypeAddLevel make pointer to type
                    leas      2,s        drop argument
                    std       12,s      save result type
CastArrayChk        ldd       12,s      result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #16       is class $10 array
                    bne       CastConvert no, convert normally
                    ldd       #1        flag value one
                    pshs      d         push flag argument
                    pshs      u         push node child
                    lbsr      CoerceExpr cast/convert helper
                    leas      4,s        drop arguments
                    bra       CastFinalize skip normal convert

CastConvert         ldd       12,s      result type
                    pshs      d         push type argument
                    pshs      u         push node child
                    lbsr      CoerceExpr cast/convert helper
                    leas      4,s        drop arguments
                    std       12,s      save result type
CastFinalize        ldx       24,s      node pointer
                    ldd       4,x       get node field $04
                    std       6,s       save result field
                    ldx       24,s      node pointer
                    ldd       2,x       get node field $02
                    std       10,s      save operand local
                    ldd       24,s      node pointer
                    pshs      d         push node argument
                    lbsr      LinkFreeNode free cast node
                    leas      2,s        drop argument
                    stu       24,s      replace with operand node
                    lbra      NodeDone  handler done, return

GenAddrOf           ldd       #1        lvalue flag one
                    pshs      d         push flag argument
                    pshs      u         push node child
                    lbsr      RequireLvalue evaluate operand as lvalue
                    leas      4,s        drop arguments
                    ldd       6,u       operand type field
                    cmpd      #118      is type $76
                    beq       CantTakeAddrErr yes, cannot take address
                    ldd       6,u       operand type field
                    cmpd      #111      is type $6F
                    bne       GenAddrFinalize no, build pointer result
CantTakeAddrErr     leax      MsgCantTakeAddr,pcr point to cant-take-address message
                    pshs      x         push message pointer
                    ldd       26,s      push source context
                    pshs      d         push context argument
                    lbsr      ReportErrorAt report error at node
                    leas      4,s        drop arguments
                    pshs      u         push node child
                    lbsr      MakeErrorNode discard bad node
                    leas      2,s        drop argument
GenAddrFinalize     ldd       18,u      operand lvalue flag
                    std       8,s       save lvalue flag
                    ldd       2,u       operand field $02
                    std       10,s      save operand local
                    ldd       ,u        operand type
                    pshs      d         push argument
                    lbsr      TypeAddLevel make pointer to operand type
                    leas      2,s        drop argument
                    std       12,s      save result type
                    ldd       4,u       operand field $04
                    std       6,s       save result field
                    lbra      NodeDone  handler done, return

GenDeref            ldd       4,u       operand field $04
                    std       6,s       save result field
                    ldd       ,u        operand type
                    std       12,s      save result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #16       is class $10 array
                    bne       PointerRequiredErr no, pointer required error
                    ldd       12,s      result type
                    pshs      d         push argument
                    lbsr      TypeRemoveLevel convert type helper
                    leas      2,s        drop argument
                    std       12,s      save result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #32       is class $20
                    bne       GenDerefFinalize no, finalize dereference
                    ldd       12,s      result type
                    pshs      d         push argument
                    lbsr      TypeRemoveLevel convert type helper
                    std       ,s        save temp
                    lbsr      TypeAddLevel make pointer to type
                    leas      2,s        drop argument
                    std       12,s      save result type
                    ldd       24,s      node pointer
                    pshs      d         push node argument
                    lbsr      LinkFreeNode free node
                    leas      2,s        drop argument
                    stu       24,s      replace with operand node
                    bra       GenDerefFinalize finalize dereference

PointerRequiredErr  leax      MsgPtrRequired,pcr point to pointer-required message
                    pshs      x         push message pointer
                    pshs      u         push node child
                    lbsr      ReportErrorAt report error at node
                    leas      4,s        drop arguments
                    pshs      u         push node child
                    lbsr      MakeErrorNode discard bad node
                    leas      2,s        drop argument
                    ldd       #17       default result type $11
                    std       ,u        store into node type
                    ldd       #1        result type one
