                    leas      2,s        drop arg
                    std       2,s       save right type
                    ldd       ,u        D = left operand type
                    std       12,s      save left type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       is it pointer class
                    bne       CmpCheckRight skip if not pointer
                    ldd       2,s       D = right type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       right also pointer
                    beq       CmpCheckRight skip if both pointers
                    ldd       2,s       D = right type
                    pshs      d         push it
                    lbsr      IsIntegralType test right pointer/scalar
                    std       ,s++      pop result
                    lbeq      BadPtrErr error if not scalar
CmpCheckRight       ldd       2,s       D = right type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       is right pointer
                    bne       CmpConvertJoin skip if not pointer
                    ldd       12,s      D = left type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       left also pointer
                    beq       CmpConvertJoin skip if both pointers
                    ldd       12,s      D = left type
                    pshs      d         push it
                    lbsr      IsIntegralType test left pointer/scalar
                    std       ,s++      pop result
                    lbeq      BadPtrErr error if not scalar
CmpConvertJoin      ldd       12,s      D = left type
                    pshs      d         push it
                    ldd       20,s      D = operand node
                    pshs      d         push it
                    lbsr      CoerceExpr convert operand helper
                    leas      4,s        drop two args
                    leax      20,s      X = frame save pointer
                    lbra      CmpFinishJoin join comparison finish

UnaryHighOp         leas      -20,x     restore stack frame
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero word
                    pshs      u         push node pointer
                    lbsr      RequireLvalue fetch operand helper
                    leas      4,s        drop two args
                    ldd       18,s      D = operand node
                    pshs      d         push it
                    lbsr      CheckOperand check operand type
                    leas      2,s        drop arg
                    ldd       18,s      D = operand node
                    pshs      d         push it
                    lbsr      RejectAggregate convert operand helper
                    leas      2,s        drop arg
                    std       2,s       save converted operand
                    ldd       ,u        D = operand type
                    std       12,s      save type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       is pointer class
                    bne       ScalarUnaryOp branch if not pointer
                    ldx       14,s      X = operator code
                    bra       CheckIncDecOp check inc/dec operator

IncDecScale         ldd       #1        scale factor = 1
                    pshs      d         push it
                    ldd       20,s      D = operand node
                    pshs      d         push it
                    lbsr      CoerceExpr convert/scale operand
                    leas      4,s        drop two args
                    leax      20,s      X = frame save pointer
                    bra       AsgnOpJoin join assign-op body

BadPtrErr           leax      20,s      X = frame save pointer
                    lbra      ReportPtrErr go report pointer error

CheckIncDecOp       cmpx      #161      operator == $A1
                    beq       IncDecScale handle pointer inc/dec
                    cmpx      #160      operator == $A0
                    lbeq      IncDecScale handle pointer inc/dec
                    bra       BadPtrErr else pointer error

ScalarUnaryOp       ldx       14,s      X = operator code
                    lbra      CheckAsgnDeref check deref assign operator

PromoteAndConvert   ldd       12,s      D = operand type
                    cmpd      #5        type == 5 (float?)
                    bne       UseOperandType skip if not
                    ldd       #6        promote to type 6
                    bra       ConvertOperand go convert operand

UseOperandType      ldd       12,s      D = operand type
ConvertOperand      pshs      d         push it
                    ldd       20,s      D = operand node
                    pshs      d         push it
                    lbsr      CoerceExpr convert operand helper
                    leas      4,s        drop two args
                    bra       AsgnOpBody go to assign-op body

AsgnOpJoin          leas      -20,x     restore stack frame
AsgnOpBody          ldd       14,s      D = operator code
                    addd      #$FFB0    subtract $50 offset
                    ldx       24,s      X = result node
                    std       6,x       store adjusted operator
                    ldd       24,s      D = result node
                    pshs      d         push it
                    lbsr      GenExprNode process node helper
                    leas      2,s        drop arg
                    std       24,s      save result node
                    ldd       12,s      D = operand type
                    cmpd      #2        type == 2
                    bne       AsgnOpTypeFix skip if not
                    ldd       10,u      D = node offset field
                    ldx       24,s      X = result node
                    std       10,x      store offset field
                    pshs      u         push node pointer
                    lbsr      LinkFreeNode helper call
                    leas      2,s        drop arg
                    ldx       24,s      X = result node
                    ldu       10,x      U = node offset field
                    ldd       #1        D = int type 1
                    std       12,s      set type to int
AsgnOpTypeFix       ldd       14,s      D = operator code
                    addd      #$FFB0    subtract $50 offset
                    ldx       24,s      X = result node
                    cmpd      6,x       compare stored operator
                    bne       CmpFinish skip if different
                    ldd       14,s      D = operator code
                    ldx       24,s      X = result node
                    std       6,x       store operator field
                    bra       CmpFinish go finish comparison

CheckAsgnDeref      cmpx      #166      operator == $A6
                    beq       AsgnOpBody go to assign-op body
                    cmpx      #165      operator == $A5
                    lbeq      AsgnOpBody go to assign-op body
                    lbra      PromoteAndConvert else promote and convert

CmpFinishJoin       leas      -20,x     restore stack frame
CmpFinish           ldd       2,u       D = node field2
                    std       10,s      save field2
                    ldd       18,u      D = node offset
                    ldx       18,s      X = left node
                    addd      18,x      add left offset
                    std       8,s       save combined offset
                    ldd       4,u       D = node operator field
                    lbra      StoreOpFinish store operator and finish

ReportPtrErr        leas      -20,x     restore stack frame
                    leax      MsgTypeMismatch,pcr X = error message text
                    pshs      x         push message pointer
                    ldd       26,s      D = source line/node
                    pshs      d         push it
                    lbsr      ReportErrorAt report error
                    lbra      DropArgsDone drop args and finish

DerefOp             ldd       ,u        D = node type word
                    std       12,s      save type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       is pointer class
                    bne       DerefPtrType branch if not pointer
                    ldd       2,u       D = node field2
                    std       10,s      save field2
                    ldd       18,u      D = node offset
                    std       8,s       save offset
                    ldd       2,u       D = node field2
                    std       6,s       save field4
                    ldd       [18,s]    deref operand type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       is pointed-to pointer
                    bne       ForceIntJoin branch if not
                    ldd       12,s      D = node type
                    cmpd      [18,s]    compare operand type
                    bne       IncompatPtrErr differ, error
                    ldd       2,u       D = node field2
                    ldx       18,s      X = operand node
                    cmpd      2,x       compare sub-type
                    beq       ClearField4 match, clear field4
IncompatPtrErr      leax      MsgPtrMismatch2,pcr X = error message text
                    pshs      x         push message pointer
                    ldd       26,s      D = source line/node
                    pshs      d         push it
                    lbsr      ReportErrorAt report error
                    leas      4,s        drop args
                    lbra      NodeDone  finish node

ClearField4         clra                clear A
                    clrb                clear B
                    std       6,s       clear result field4
                    lbra      NodeDone  finish node

ForceIntJoin        ldd       18,s      D = operand node
                    pshs      d         push it
ForceIntCall        lbsr      ForceIntType force operand to int
                    leas      2,s        drop arg
                    lbra      NodeDone  finish node

DerefPtrType        ldd       [18,s]    deref operand type
                    std       12,s      save type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #16       is pointer class
                    bne       CombineTypesOp branch if not pointer
                    ldx       18,s      X = operand node
                    ldd       2,x       D = operand field2
                    std       10,s      save field2
                    ldx       18,s      X = operand node
                    ldd       18,x      D = operand offset
                    std       8,s       save offset
                    ldx       18,s      X = operand node
                    ldd       4,x       D = operand field4
                    std       6,s       save field4
                    pshs      u         push node pointer
                    bra       ForceIntCall go force operand int

CombineTypesOp      ldd       18,s      D = operand node
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      BalanceOperands combine operand types
                    leas      4,s        drop two args
StoreResultType     std       12,s      store result type
                    lbra      NodeDone  finish node

CopyNodeType        ldd       [18,s]    deref operand type
                    std       12,s      save type
                    ldx       18,s      X = operand node
                    ldd       2,x       D = operand field2
                    std       10,s      save field2
                    ldx       18,s      X = operand node
                    ldd       4,x       D = operand field4
StoreOpFinish       std       6,s       store operator field
                    lbra      NodeDone  finish node

OpDefault           ldd       14,s      D = operator code
                    cmpd      #160      compare against $A0
                    blt       BadOpErr  branch if below range
                    leax      20,s      X = frame save pointer
                    lbra      UnaryHighOp handle high unary operator

BadOpErr            leax      MsgTypeCheck,pcr X = error message text
                    pshs      x         push message pointer
                    ldd       26,s      D = source line/node
                    pshs      d         push it
                    lbsr      InternalErr report error
DropArgsDone        leas      4,s        drop error args
                    lbra      NodeDone  finish node

DispatchOp          cmpx      #52       operator == $34
                    lbeq      GenVarRef dispatch to handler
                    cmpx      #54       operator == $36
                    lbeq      SetLvalFalse dispatch to handler
                    cmpx      #74       operator == $4A
                    lbeq      GenConstType4A dispatch to handler
                    cmpx      #75       operator == $4B
                    lbeq      GenConstType4B dispatch to handler
                    cmpx      #55       operator == $37
                    lbeq      GenConstType37 dispatch to handler
                    cmpx      #32       operator == $20
                    lbeq      GenCast   dispatch to handler
                    cmpx      #65       operator == $41
                    lbeq      GenAddrOf dispatch to handler
                    cmpx      #66       operator == $42
                    lbeq      GenDeref  dispatch to handler
                    cmpx      #69       operator == $45
                    lbeq      GenBinOpType45 dispatch to handler
                    cmpx      #70       operator == $46
                    lbeq      GenBinOpType46 dispatch to handler
                    cmpx      #101      operator == $65
                    lbeq      GenNode65 dispatch to handler
                    cmpx      #11       operator == $0B
                    lbeq      GenNode0B dispatch to handler
                    cmpx      #48       operator == $30
                    lbeq      GenNode30 dispatch to handler
                    cmpx      #64       operator == $40
                    lbeq      GenNode40 dispatch to handler
                    cmpx      #67       operator == $43
                    lbeq      GenNode43 dispatch to handler
                    cmpx      #68       operator == $44
                    lbeq      GenNode44 dispatch to handler
                    cmpx      #60       operator == $3C (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #62       operator == $3E (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #61       operator == $3D (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #63       operator == $3F (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #71       operator == $47
                    lbeq      GenNode47 dispatch to handler
                    cmpx      #72       operator == $48
                    lbeq      GenNode47 dispatch to handler
                    cmpx      #83       operator == $53
                    lbeq      CombineTypesOp combine-types handler
                    cmpx      #82       operator == $52
                    lbeq      CombineTypesOp combine-types handler
                    cmpx      #87       operator == $57
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #88       operator == $58
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #89       operator == $59
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #84       operator == $54
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #86       operator == $56
                    lbeq      GenNode56 dispatch to handler
                    cmpx      #85       operator == $55
                    lbeq      GenNode56 dispatch to handler
                    cmpx      #93       operator == $5D
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #95       operator == $5F
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #92       operator == $5C
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #94       operator == $5E
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #90       operator == $5A
                    lbeq      GenNode5A dispatch to handler
                    cmpx      #91       operator == $5B
                    lbeq      GenNode5A dispatch to handler
                    cmpx      #80       operator == $50
                    lbeq      GenNode50 dispatch to handler
                    cmpx      #81       operator == $51
                    lbeq      GenNode51 dispatch to handler
                    cmpx      #120      operator == $78
                    lbeq      PtrRelOp  pointer-relational handler
                    cmpx      #47       operator == $2F
                    lbeq      DerefOp   dereference handler
                    cmpx      #100      operator == $64
                    lbeq      CopyNodeType copy-type handler
                    lbra      OpDefault default operator handler

NodeDone            ldd       12,s      D = result type word
                    std       [24,s]    store type into node
                    ldd       10,s      D = result field2
                    ldx       24,s      X = result node
                    std       2,x       store field2
                    ldd       8,s       D = result offset
                    ldx       24,s      X = result node
                    std       18,x      store offset field
                    ldd       6,s       D = result field4
                    ldx       24,s      X = result node
                    std       4,x       store field4
                    ldd       24,s      D = result node pointer
                    leas      20,s       drop local frame
                    puls      pc,u      return result node

ForceIntType        pshs      u         save U on stack
                    ldd       #$FFB8    D = stack check size
                    lbsr      stkcheck  verify stack space
                    ldu       4,s       U = target node
                    ldd       6,u       D = node operator/type
                    cmpd      #54       already int type $36
                    bne       LoadNullMsg branch if not int
                    ldd       8,u       D = node sub-type
                    beq       RetU      ok if zero
LoadNullMsg         leax      MsgShouldBeNull,pcr X = error message text
                    pshs      x         push message pointer
                    pshs      u         push node pointer
                    lbsr      ReportErrorAt report error
                    leas      4,s        drop args
                    ldd       #54       force type to int $36
                    std       6,u       store type
                    clra                clear A
                    clrb                clear B
                    std       8,u       clear node sub-type
RetU                puls      pc,u      return

CheckOperand        pshs      u         save U on stack
                    ldd       #$FFB6    D = stack check size
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       U = expression node argument
                    leas      -2,s       reserve local type slot
                    pshs      u         pass node pointer
                    lbsr      ReportUndeclared resolve node base type
                    leas      2,s        drop argument
                    ldd       ,u        D = node type word
                    std       ,s        save current type
                    tfr       d,x       X = type for dispatch
                    bra       PromoteTypeDispatch dispatch on type

PromoteToInt        ldd       #1        result type = int
                    bra       StoreExprType store result type

PromoteToDouble     ldd       #6        result type = double
StoreExprType       std       ,s        save result type
                    pshs      d         push target type
                    pshs      u         push node pointer
                    bsr       CoerceExpr coerce node to double
                    leas      4,s        drop arguments
                    bra       StoreTypeRet store type and return

BadTypeErr          leax      MsgTypeError,pcr point to error message text
                    pshs      x         push message pointer
                    pshs      u         push node pointer
                    lbsr      ReportErrorAt report type error
                    leas      4,s        drop arguments
                    ldd       #1        default type = int
                    std       ,s        save result type
                    bra       StoreTypeRet store type and return

PromoteTypeDispatch cmpx      #2        type is char
                    beq       PromoteToInt promote char to int
                    cmpx      #5        type is unsigned long
                    beq       PromoteToDouble promote unsigned long to double
                    cmpx      #6        type is double
                    beq       StoreTypeRet already widest, keep
                    cmpx      #8        type is long
                    beq       StoreTypeRet keep as-is
                    cmpx      #1        type is int
                    beq       StoreTypeRet keep as-is
                    cmpx      #7        type is unsigned int
                    beq       StoreTypeRet keep as-is
                    bra       BadTypeErr unknown type error

StoreTypeRet        ldd       ,s        D = resolved type
                    std       ,u        store type into node
                    leas      2,s        drop local slot
                    puls      pc,u      restore U and return

CoerceExpr          pshs      u         save node pointer
                    ldd       #$FFAC    stack frame size
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       U = node argument
                    leas      -4,s       reserve local slots
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        clear conversion opcode
                    ldx       ,u        X = source type
                    lbra      CoerceSrcDispatch dispatch on source type

CoerceFromChar      ldx       10,s      X = target type
                    bra       CoerceCharDisp dispatch char conversions

CharToInt           ldd       #133      char-to-int opcode
                    bra       StoreOpEmit store opcode and emit

CharToLong          ldd       #1        intermediate type int
                    pshs      d         push target type
                    pshs      u         push node pointer
                    bsr       CoerceExpr coerce char to int first
                    leas      4,s        drop arguments
                    ldd       #131      int-to-long opcode
StoreOpEmit         std       ,s        save conversion opcode
                    lbra      EmitConvNode emit conversion node

CharToWide          ldd       #1        intermediate type int
                    pshs      d         push target type
                    pshs      u         push node pointer
                    lbsr      CoerceExpr coerce char to int
                    leas      4,s        drop arguments
                    ldd       10,s      D = final target type
                    pshs      d         push target type
                    pshs      u         push node pointer
                    lbsr      CoerceExpr coerce to target
                    leas      4,s        drop arguments
                    lbra      EmitConvNode emit conversion node

CoerceCharDisp      cmpx      #1        target int
                    beq       CharToInt handle char to int
                    cmpx      #7        target unsigned int
                    lbeq      CharToInt handle char to int
                    cmpx      #8        target long
                    beq       CharToLong handle char to long
                    cmpx      #6        target double
                    beq       CharToWide handle char to wide
                    cmpx      #5        target unsigned long
                    lbeq      CharToWide handle char to wide
                    lbra      EmitConvNode no conversion needed

CoercePtrDefault    ldd       ,u        D = node type word
                    clra                keep low byte only
                    andb      #$30      isolate type-class bits
                    cmpd      #16       pointer class
                    lbne      EmitConvNode emit if not pointer
CoerceFromInt       ldx       10,s      X = target type
                    lbra      CoerceIntDisp dispatch int conversions

IntToLong           ldd       6,u       D = node opcode
                    cmpd      #54       integer constant node
                    bne       EmitIntToLong not a constant
                    ldd       #4        allocate four bytes
                    pshs      d         push size
                    lbsr      AllocMem  allocate long buffer
                    leas      2,s        drop size
                    std       2,s       save buffer pointer
                    ldd       8,u       D = constant value
                    ldx       2,s       X = long buffer
                    std       2,x       store low word
                    bge       IntConstNonNeg value non-negative
                    ldd       #$FFFF    sign-extend negative value
                    bra       StoreLongHigh store high word

IntConstNonNeg      clra                clear high byte
                    clrb                clear low byte
StoreLongHigh       std       [2,s]     store high word into buffer
                    ldd       2,s       D = buffer pointer
                    std       8,u       node now points to long
                    bra       SetLongConst finish long constant

FreeConvTemp        leas      -4,x      adjust conversion temp
SetLongConst        ldd       #74       long-constant opcode
                    std       6,u       set node opcode
                    ldd       #4        long size
SetNodeSizeEmit     std       2,u       set node size
                    lbra      EmitConvNode emit conversion node

EmitIntToLong       ldd       #131      int-to-long opcode
                    bra       StoreOpEmitInt store opcode and emit

IntToChar           ldd       #1        result type = int
                    std       10,s      store char as int type
                    lbra      EmitConvNode emit conversion node

IntToUlong          ldd       #6        intermediate double
                    pshs      d         push target type
                    pshs      u         push node pointer
                    lbsr      CoerceExpr coerce to double first
                    leas      4,s        drop arguments
                    ldd       #141      double-to-unsigned opcode
                    bra       StoreOpEmitInt store opcode and emit

IntToDouble         ldd       6,u       D = node opcode
                    cmpd      #54       integer constant node
                    bne       EmitIntToDouble not a constant
                    ldd       #8        allocate eight bytes
                    pshs      d         push size
                    lbsr      AllocMem  allocate double buffer
                    leas      2,s        drop size
                    std       2,s       save buffer pointer
                    ldx       2,s       X = buffer
                    pshs      x         push buffer pointer
                    ldd       8,u       D = constant value
                    lbsr      BuildByteType convert int to double
                    lbsr      CopyFloat free temporary
                    bra       SetDoubleConst finish double constant

FreeConvTemp2       leas      -4,x      adjust conversion temp
SetDoubleConst      ldd       2,s       D = buffer pointer
                    std       8,u       node points to double
                    ldd       #75       double-constant opcode
                    std       6,u       set node opcode
                    ldd       #8        double size
                    bra       SetNodeSizeEmit set node size and emit

EmitIntToDouble     ldd       #142      int-to-double opcode
StoreOpEmitInt      std       ,s        save conversion opcode
                    lbra      EmitConvNode emit conversion node

CoerceIntDisp       cmpx      #8        target long
                    lbeq      IntToLong handle int to long
                    cmpx      #2        target char
                    lbeq      IntToChar handle int to char
                    cmpx      #5        target unsigned long
                    beq       IntToUlong handle int to unsigned long
                    cmpx      #6        target double
                    beq       IntToDouble handle int to double
                    lbra      EmitConvNode no conversion needed

CoerceFromUint      ldx       10,s      X = target type
                    bra       CoerceUintDisp dispatch unsigned int conversions

UintToLong          ldd       #134      unsigned-int-to-long opcode
                    bra       StoreOpEmitUint store opcode and emit

UintToUlong         ldd       #6        intermediate double
                    pshs      d         push target type
                    pshs      u         push node pointer
                    lbsr      CoerceExpr coerce to double first
                    leas      4,s        drop arguments
                    ldd       #141      double-to-unsigned opcode
                    bra       StoreOpEmitUint store opcode and emit

UintToDouble        ldd       #146      unsigned-int-to-double opcode
StoreOpEmitUint     std       ,s        save conversion opcode
                    lbra      EmitConvNode emit conversion node

UintToChar          ldd       #1        result type = int
                    std       10,s      store as int type
                    lbra      EmitConvNode emit conversion node

CoerceUintDisp      cmpx      #8        target long
                    beq       UintToLong handle uint to long
                    cmpx      #5        target unsigned long
                    beq       UintToUlong handle uint to unsigned long
                    cmpx      #6        target double
                    beq       UintToDouble handle uint to double
                    cmpx      #2        target char
                    beq       UintToChar handle uint to char
                    lbra      EmitConvNode no conversion needed

CoerceFromLong      ldx       10,s      X = target type
                    lbra      CoerceLongDisp dispatch long conversions

CoerceLongDefault   ldd       10,s      D = target type
                    clra                keep low byte only
                    andb      #$30      isolate type-class bits
                    cmpd      #16       pointer class
                    lbne      EmitConvNode emit if not pointer
LongToInt           ldd       6,u       D = node opcode
                    cmpd      #74       long constant node
                    bne       EmitLongToInt not a constant
                    ldd       8,u       D = long value pointer
                    std       2,s       save pointer
                    ldx       2,s       X = long buffer
                    ldd       2,x       D = low word
                    std       8,u       node value truncated to int
                    bra       SetIntConst finish int constant

FreeConvTemp3       leas      -4,x      adjust conversion temp
SetIntConst         ldd       #54       integer-constant opcode
                    std       6,u       set node opcode
                    ldd       #2        int size
                    std       2,u       set node size
                    lbra      EmitConvNode emit conversion node

EmitLongToInt       ldd       #132      long-to-int opcode
                    bra       StoreOpEmitLong store opcode and emit

LongToUlong         ldd       #6        intermediate double
                    pshs      d         push target type
                    pshs      u         push node pointer
                    lbsr      CoerceExpr coerce to double first
                    leas      4,s        drop arguments
                    ldd       #141      double-to-unsigned opcode
                    bra       StoreOpEmitLong store opcode and emit

LongToDouble        ldd       6,u       D = node opcode
                    cmpd      #74       long constant node
                    bne       EmitLongToDouble not a constant
                    ldd       #8        allocate eight bytes
                    pshs      d         push size
                    lbsr      AllocMem  allocate double buffer
                    leas      2,s        drop size
                    std       2,s       save buffer pointer
                    ldx       2,s       X = buffer
                    pshs      x         push buffer pointer
                    ldx       8,u       X = long value pointer
                    lbsr      BuildPtrType convert long to double
                    lbsr      CopyFloat free temporary
                    leax      4,s       point to conversion temp
                    lbra      FreeConvTemp2 finish double constant

EmitLongToDouble    ldd       #144      long-to-double opcode
StoreOpEmitLong     std       ,s        save conversion opcode
                    lbra      EmitConvNode emit conversion node

CoerceLongDisp      cmpx      #1        target char
                    lbeq      LongToInt handle long to int
                    cmpx      #7        target unsigned int
                    lbeq      LongToInt handle long to int
                    cmpx      #2        target int
                    lbeq      LongToInt handle long to int
                    cmpx      #5        target unsigned long
                    beq       LongToUlong handle long to unsigned long
                    cmpx      #6        target double
                    beq       LongToDouble handle long to double
                    lbra      CoerceLongDefault default handling

CoerceFromUlong     ldx       10,s      X = target type
                    bra       CoerceUlongDisp dispatch unsigned long conversions

UlongViaDouble      ldd       #6        intermediate double
                    pshs      d         push target type
                    pshs      u         push node pointer
                    lbsr      CoerceExpr coerce to double first
                    leas      4,s        drop arguments
                    ldd       10,s      D = final target type
                    pshs      d         push target type
                    pshs      u         push node pointer
                    lbsr      CoerceExpr coerce to target
                    leas      4,s        drop arguments
                    lbra      EmitConvNode emit conversion node

UlongToDouble       ldd       #140      unsigned-long-to-double opcode
                    std       ,s        save conversion opcode
                    lbra      EmitConvNode emit conversion node

CoerceUlongDisp     cmpx      #8        target double
                    beq       UlongViaDouble handle ulong via double
                    cmpx      #7        target unsigned int
                    lbeq      UlongViaDouble handle ulong via double
                    cmpx      #2        target int
                    lbeq      UlongViaDouble handle ulong via double
                    cmpx      #1        target char
                    lbeq      UlongViaDouble handle ulong via double
                    cmpx      #6        target double
                    beq       UlongToDouble handle ulong to double
                    lbra      EmitConvNode no conversion needed

CoerceFromDouble    ldx       10,s      X = target type
                    bra       CoerceDoubleDisp dispatch double conversions

DoubleToInt         ldd       6,u       D = node opcode
                    cmpd      #75       double constant node
                    bne       EmitDoubleToInt not a constant
                    ldx       8,u       X = double value pointer
                    lbsr      LoadDerefValue convert double to int
                    std       8,u       store int result
                    leax      4,s       point to conversion temp
                    lbra      FreeConvTemp3 finish int constant

EmitDoubleToInt     ldd       #143      double-to-int opcode
                    bra       StoreOpEmitDbl store opcode and emit

DoubleToLong        ldd       6,u       D = node opcode
                    cmpd      #75       double constant node
                    bne       EmitDoubleToLong not a constant
                    ldx       8,u       X = double value pointer
                    pshs      x         push value pointer
                    ldx       8,u       X = double value pointer
                    lbsr      DerefExpr convert double to long
                    lbsr      StoreInt32 free temporary
                    leax      4,s       point to conversion temp
                    lbra      FreeConvTemp finish long constant

EmitDoubleToLong    ldd       #145      double-to-long opcode
                    bra       StoreOpEmitDbl store opcode and emit

DoubleToUlong       ldd       #141      double-to-unsigned opcode
StoreOpEmitDbl      std       ,s        save conversion opcode
                    bra       EmitConvNode emit conversion node

CoerceDoubleDisp    cmpx      #2        target int
                    beq       DoubleToInt handle double to int
                    cmpx      #7        target unsigned int
                    lbeq      DoubleToInt handle double to int
                    cmpx      #1        target char
                    lbeq      DoubleToInt handle double to int
                    cmpx      #8        target long
                    beq       DoubleToLong handle double to long
                    cmpx      #5        target unsigned long
                    beq       DoubleToUlong handle double to unsigned long
                    bra       EmitConvNode no conversion needed

CoerceSrcDispatch   cmpx      #2        source int
                    lbeq      CoerceFromChar coerce from int
                    cmpx      #1        source char
                    lbeq      CoerceFromInt coerce from char
                    cmpx      #7        source unsigned int
                    lbeq      CoerceFromUint coerce from unsigned int
                    cmpx      #8        source double
                    lbeq      CoerceFromLong coerce from double
                    cmpx      #5        source unsigned long
                    lbeq      CoerceFromUlong coerce from unsigned long
                    cmpx      #6        source long
                    lbeq      CoerceFromDouble coerce from long
                    lbra      CoercePtrDefault pointer default handling

EmitConvNode        ldd       ,s        D = conversion opcode
                    beq       CoerceRet nothing to emit
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero template field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero template field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero template field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero template field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero template field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero template field
                    lbsr      AllocExprNode allocate expression node
                    leas      12,s       drop template arguments
                    std       2,s       save new node pointer
                    pshs      d         push new node
                    pshs      u         push child node
                    lbsr      ReportDiag22 link child to node
                    leas      4,s        drop arguments
                    ldd       ,s        D = conversion opcode
                    std       6,u       set node opcode
                    ldd       2,s       D = new node pointer
                    std       10,u      set node operand pointer
                    clra                clear high byte
                    clrb                clear low byte
                    std       12,u      clear extra field
CoerceRet           ldd       10,s      D = resulting type
                    lbra      StoreResultType2 return converted node

BalanceOperands     pshs      u         save node pointer
                    ldd       #$FFB4    stack frame size
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       U = binary-op node
                    leas      -4,s       reserve local slots
                    pshs      u         push node pointer
                    lbsr      CheckOperand resolve left operand type
                    leas      2,s        drop argument
                    std       2,s       save left type
                    ldd       10,s      D = right operand node
                    pshs      d         push right operand
                    lbsr      CheckOperand resolve right operand type
                    leas      2,s        drop argument
                    std       ,s        save right type
                    ldd       2,s       D = left type
                    cmpd      #6        left is double
                    bne       ChkRightDouble left not double
                    ldd       #6        common type double
                    bra       CoerceRightOperand coerce right operand

ChkRightDouble      ldd       ,s        D = right type
                    cmpd      #6        right is double
                    bne       ChkLeftLong right not double
                    ldd       #6        common type double
                    bra       CoerceLeftOperand coerce left operand

ChkLeftLong         ldd       2,s       D = left type
                    cmpd      #8        left is long
                    bne       ChkRightLong left not long
                    ldd       #8        common type long
CoerceRightOperand  pshs      d         push target type
                    ldd       12,s      D = right operand node
                    pshs      d         push right operand
                    bra       CoerceOperand coerce right operand

ChkRightLong        ldd       ,s        D = right type
                    cmpd      #8        right is long
                    bne       ChkType7  right not long
                    ldd       #8        common type long
CoerceLeftOperand   pshs      d         push target type
                    pshs      u         push left operand node
CoerceOperand       lbsr      CoerceExpr coerce operand to type
                    leas      4,s        drop arguments
                    bra       CombineTypeDone continue with balanced operands

ChkType7            ldd       2,s       load first operand result type
                    cmpd      #7        is it type 7 (float)
                    beq       ResultType7 yes, common type is 7
                    ldd       ,s        load second operand type
                    cmpd      #7        is it type 7
                    bne       ResultTypeInt neither, result is int
ResultType7         ldd       #7        common result type is 7
                    std       [10,s]    store type via result pointer
StoreResultType2    std       ,u        store result type into node
                    bra       CombineTypeDone done

ResultTypeInt       ldd       #1        default common type is int
CombineTypeDone     leas      4,s        drop locals
                    puls      pc,u      return

ScaleSubscript      pshs      u         save the caller u register
                    ldd       #$FFB0    frame size -80
                    lbsr      stkcheck  check stack space
                    ldd       8,s       load element node argument
                    pshs      d         push it
                    ldd       6,s       load index node argument
                    pshs      d         push it
                    ldd       10,s      load base node argument
                    pshs      d         push it
                    lbsr      TypeRemoveLevel build combined subscript node
                    std       ,s        save result node
                    lbsr      ResolveTypeSize evaluate and reduce node
                    leas      6,s        drop pushed arguments
                    std       4,s       save result
                    cmpd      #1        is result plain int type
                    bne       BuildScaleNode no, build scaling node
                    ldd       10,s      return base node unchanged
                    puls      pc,u      return

BuildScaleNode      ldx       10,s      X = base node
                    ldd       16,x      get element size field
                    pshs      d         push size
                    ldx       12,s      X = type node
                    ldd       14,x      get its size field
                    pshs      d         push it
                    ldd       8,s       push element node
                    pshs      d         push it
                    clra                high byte zero
                    clrb                low byte zero
                    pshs      d         push zero
                    clra                high byte zero
                    clrb                low byte zero
                    pshs      d         push zero
                    ldd       #54       node kind 54 (constant)
                    pshs      d         push kind
                    lbsr      AllocExprNode build constant size node
                    leas      12,s       drop arguments
                    tfr       d,u       U = new node
                    ldd       #1        mark value one
                    std       ,u        set node kind one
                    ldx       10,s      X = base node
                    ldd       16,x      element size again
                    pshs      d         push size
                    ldx       12,s      X = type node
                    ldd       14,x      get its size field
                    pshs      d         push it
                    clra                high byte zero
                    clrb                low byte zero
                    pshs      d         push zero
                    pshs      u         push constant node
                    ldd       18,s      push saved index value
                    pshs      d         push it
                    ldd       #82       operator 82 (multiply)
                    pshs      d         push operator
                    lbsr      AllocExprNode build multiply node
                    leas      12,s       drop arguments
                    pshs      d         save node
                    lbsr      FoldConstNode finalize node type
                    leas      2,s        drop temp
                    tfr       d,u       U = node
                    ldd       6,u       get result type
                    cmpd      #54       is it constant type
                    bne       ScaleWidth2 no, width is 2
                    clra                high byte zero
                    clrb                width zero
                    bra       SetScaleWidth store width

ScaleWidth2         ldd       #2        scaled width is 2 bytes
SetScaleWidth       std       18,u      store width in node
                    ldd       #1        kind one
                    std       ,u        set node kind
                    ldd       #2        type 2
                    std       2,u       set node type
                    tfr       u,d       return node pointer
                    puls      pc,u      return

RequireLvalue       pshs      u         save the caller u register
                    ldd       #$FFB6    frame size -74
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U = node argument
                    leas      -2,s       reserve local
                    ldd       6,u       get node type
                    std       ,s        save it
                    tfr       d,x       X = node type
                    cmpx      #118      lvalue type 0x76
                    lbeq      RvalueDone accept as lvalue
                    cmpx      #111      lvalue type 0x6F
                    lbeq      RvalueDone accept as lvalue
                    cmpx      #66       lvalue type 0x42
                    lbeq      RvalueDone accept as lvalue
                    ldd       ,s        reload type
                    cmpd      #52       is it error type
                    bne       LvalueErr no, report lvalue error
                    pshs      u         push node
                    bsr       ReportUndeclared report undeclared if needed
                    leas      2,s        drop
                    ldd       8,s       get returned flag
                    lbne      RvalueDone nonzero, accept
                    ldd       ,u        get node kind
                    clra                clear high byte
                    andb      #$30      mask addressable flag bits
                    cmpd      #32       addressable flag set
                    bne       NotAddressable no, flag false
                    ldd       #1        flag true
                    bra       LvalFlagChk join flag check

NotAddressable      clra                high byte zero
                    clrb                flag false
LvalFlagChk         bne       LvalueErr not addressable, report error
                    ldd       ,u        get node kind
                    cmpd      #4        is kind 4
                    lbne      RvalueDone other kinds accept
LvalueErr           leax      MsgLvalueRequired,pcr error string lvalue required
                    pshs      x         push message
                    pshs      u         push node
                    lbsr      ReportErrorAt report error
                    leas      4,s        drop arguments
                    pshs      u         push node
                    lbsr      MakeErrorNode poison node to error type
                    leas      2,s        drop
                    lbra      RvalueDone done

ReportUndeclared    pshs      u         save the caller u register
                    ldd       #$FFB8    frame size -72
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U = node argument
                    ldd       6,u       get node type
                    cmpd      #52       is it error type
                    lbne      NodeRet   no, just return
                    ldd       ,u        get node kind
                    lbne      NodeRet   nonzero, return
                    leax      MsgUndeclaredVar,pcr error string undeclared variable
                    pshs      x         push message
                    pshs      u         push node
                    lbsr      ReportErrorAt report error
                    leas      4,s        drop arguments
                    pshs      u         push node
                    lbsr      MakeErrorNode poison node
                    lbra      RvalueDone done

LoadRvalue          pshs      u         save the caller u register
                    ldd       #$FFB6    frame size -74
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U = node argument
                    leas      -2,s       reserve local
                    ldd       ,u        get node kind
                    std       [8,s]     store kind via result pointer
                    ldd       6,u       get node type
                    cmpd      #65       is it array type
                    bne       NotArray  no, clear decay flag
                    ldd       #1        flag array decay
                    std       [10,s]    store decay flag via pointer
                    ldd       10,u      get array element child
                    std       ,s        save it
                    ldd       4,u       get element type
                    ldx       ,s        X = child node
                    std       4,x       set child type
                    pshs      u         push node
                    ldd       2,s       load child
                    pshs      d         push it
                    lbsr      ReportDiag22 relink replacing node
                    leas      4,s        drop arguments
                    ldd       ,s        get child
                    pshs      d         push it
                    lbsr      LinkFreeNode free old node
                    leas      2,s        drop
                    bra       DerefCheck continue to deref check

NotArray            clra                high byte zero
                    clrb                clear decay flag
                    std       [10,s]    store zero flag via pointer
DerefCheck          pshs      u         push node
                    lbsr      ReportUndeclared report undeclared if needed
                    leas      2,s        drop
                    ldd       6,u       get node type
                    cmpd      #52       is it error type
                    bne       StructMemberErr no, struct-member error
                    ldd       8,u       get referenced symbol node
                    std       ,s        save it
                    ldx       ,s        X = referenced node
                    ldd       8,x       get its field
                    cmpd      #17       is it type 17
                    beq       MemberFound yes, member found
                    leax      2,s       point past local
                    bra       MemberErrAdj struct-member error

MemberFound         ldd       #54       constant type 54
                    std       6,u       set node type
                    ldx       ,s        X = referenced node
                    ldd       6,x       get its type
                    std       8,u       copy into node
                    clra                high byte zero
                    clrb                low byte zero
                    std       18,u      clear width
                    ldd       #1        kind one
                    std       ,u        set node kind
                    ldx       ,s        X = referenced node
                    ldd       2,x       get its value
                    bra       RvalueDone done

                    bra       StructMemberErr struct-member error (dead)

MemberErrAdj        leas      -2,x      adjust stack pointer
StructMemberErr     leax      MsgStructMember,pcr error string struct member required
                    pshs      x         push message
                    pshs      u         push node
                    lbsr      ReportErrorAt report error
                    leas      4,s        drop arguments
                    pshs      u         push node
                    lbsr      MakeErrorNode poison node
                    leas      2,s        drop
                    ldd       #54       constant type 54
                    std       6,u       set node type
                    clra                high byte zero
                    clrb                low byte zero
                    std       8,u       clear child pointer
                    clra                high byte zero
                    clrb                low byte zero
                    std       18,u      clear width
                    ldd       #1        kind one
                    std       [8,s]     store kind via result pointer
                    ldd       #2        type 2 return value
RvalueDone          leas      2,s        drop local
NodeRet             puls      pc,u      restore u and return

RejectAggregate     pshs      u         save the caller u register
                    ldd       #$FFB8    frame size -72
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U = node argument
                    ldd       ,u        get node kind
                    cmpd      #4        is it struct kind 4
                    beq       AggregateErr reject aggregate
                    ldd       ,u        reload kind
                    cmpd      #3        is it union kind 3
                    bne       ScalarOk  scalar is fine
AggregateErr        leax      MsgAggregateBad,pcr error string aggregate inappropriate
                    pshs      x         push message
                    pshs      u         push node
                    lbsr      ReportErrorAt report error
                    leas      4,s        drop arguments
                    pshs      u         push node
                    bsr       MakeErrorNode poison node
                    leas      2,s        drop
ScalarOk            ldd       ,u        return node kind
                    puls      pc,u      restore u and return

MakeErrorNode       pshs      u         save the caller u register
                    ldd       #$FFB6    frame size -74
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U = node argument
                    ldd       #6        length 6 bytes
                    pshs      d         push length
                    pshs      u         push dest node
                    leax      >ErrorTypeTemplate,y  error type template pointer
                    pshs      x         push source
                    lbsr      CopyMem   copy type descriptor
                    leas      6,s        drop arguments
                    ldd       #1        flag value
                    std       18,u      set width field
                    ldd       10,u      get left child
                    pshs      d         push it
                    lbsr      FreeExprTree free child node
                    leas      2,s        drop
                    ldd       12,u      get right child
                    pshs      d         push it
                    lbsr      FreeExprTree free child node
                    leas      2,s        drop
                    clra                high byte zero
                    clrb                low byte zero
                    std       12,u      clear right child
                    std       10,u      clear left child
                    ldd       #52       error type 52
                    std       6,u       set node type
                    leax      >ErrorTypeTemplate,y  error type descriptor
                    stx       8,u       point node at it
                    puls      pc,u      restore u and return

IsIntegralType      pshs      u         save the caller u register
                    ldd       #$FFC0    frame size -64
                    lbsr      stkcheck  check stack space
                    ldx       4,s       X = type code argument
                    bra       IntTypeChk test the type

IntTypeYes          ldd       #1        return true
                    puls      pc,u      return

IntTypeChk          cmpx      #1        type int
                    beq       IntTypeYes integral
                    cmpx      #2        type 2
                    lbeq      IntTypeYes integral
                    cmpx      #8        type long
                    lbeq      IntTypeYes integral
                    cmpx      #7        type 7
                    lbeq      IntTypeYes integral
                    clra                high byte zero
                    clrb                return false
                    puls      pc,u      return

ReportNotIntegral   pshs      u         save the caller u register
                    ldd       #$FFB8    frame size -72
                    lbsr      stkcheck  check stack space
                    leax      MsgMustBeIntegral,pcr error string must be integral
                    pshs      x         push message
                    ldd       6,s       get node argument
                    pshs      d         push node
                    lbsr      ReportErrorAt report error
                    leas      4,s        drop arguments
                    puls      pc,u      return

MsgDivZero          fcc       /divide by zero/
                    fcb       C$NULL
MsgTypedefNotVar    fcc       /typedef - not a variable/
                    fcb       C$NULL
MsgCannotCast       fcc       /cannot cast/
                    fcb       C$NULL
MsgCantTakeAddr     fcc       /can't take address/
                    fcb       C$NULL
MsgPtrRequired      fcc       /pointer required/
                    fcb       C$NULL
MsgPtrOrIntRequired fcc       /pointer or integer required/
                    fcb       C$NULL
MsgNotAFunction     fcc       /not a function/
                    fcb       C$NULL
MsgBothIntegral     fcc       /both must be integral/
                    fcb       C$NULL
MsgPtrMismatch1     fcc       /pointer mismatch/
                    fcb       C$NULL
MsgTypeMismatch     fcc       /type mismatch/
                    fcb       C$NULL
MsgPtrMismatch2     fcc       /pointer mismatch/
                    fcb       C$NULL
MsgTypeCheck        fcc       /type check/
                    fcb       C$NULL
MsgShouldBeNull     fcc       /should be NULL/
                    fcb       C$NULL
MsgTypeError        fcc       /type error/
                    fcb       C$NULL
MsgLvalueRequired   fcc       /lvalue required/
                    fcb       C$NULL
MsgUndeclaredVar    fcc       /undeclared variable/
                    fcb       C$NULL
MsgStructMember     fcc       /struct member required/
                    fcb       C$NULL
MsgAggregateBad     fcc       /structure or union inappropriate/
                    fcb       C$NULL
MsgMustBeIntegral   fcc       /must be integral/
                    fcb       C$NULL
ParseStatement      pshs      u         save the caller u register
                    ldd       #$FFBA    frame size -70
                    lbsr      stkcheck  check stack space
                    ldd       GlbVar003F load current token
                    cmpd      #40       is it token 0x28
                    beq       StmtDispatch yes, dispatch
                    clra                high byte zero
                    clrb                low byte zero
                    std       GlbVar002F clear pending-label global
                    bra       StmtDispatch dispatch statement

NextStmt            leas      ,x        restore saved stack pointer
StmtDispatch        ldx       GlbVar003F X = current token
                    lbra      DispatchStmtToken dispatch statement token

DispatchKeyword     ldx       GlbVar0041 X = keyword token
                    bra       KeywordDispatch dispatch keyword

ParseKw13           lbsr      CompileIf handle keyword 0x13
                    puls      pc,u      return

ParseKw14           lbsr      CompileWhile handle keyword 0x14
                    puls      pc,u      return

ParseKw12           lbsr      GenReturnStmt handle keyword 0x12
                    lbra      EmitStmtEnd finish statement

ParseKw17           lbsr      CompileCase handle keyword 0x17
                    puls      pc,u      return

ParseKw16           lbsr      CompileSwitch handle keyword 0x16
                    puls      pc,u      return

ParseKw18           lbsr      GenBreakStmt handle keyword 0x18
                    lbra      EmitStmtEnd finish statement

ParseKw19           lbsr      GenContinueStmt handle keyword 0x19
                    lbra      EmitStmtEnd finish statement

ParseKw1B           lbsr      CompileDefault handle keyword 0x1B
                    puls      pc,u      return

ParseKw1C           lbsr      GenForStmt handle keyword 0x1C
                    puls      pc,u      return

ParseKw1A           lbsr      CompileFor handle keyword 0x1A
                    lbra      EmitStmtEnd finish statement

ParseKwStart        lbsr      GenGotoStmt handle keyword (else body)
                    lbra      EmitStmtEnd finish statement

ElseNoIfErr         leax      MsgNoIfForElse,pcr error string no if for else
                    pshs      x         push message
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop
                    lbsr      ParseStatement2 parse the statement
                    lbra      StmtLoop  loop for next statement

StmtNotKeyword      leax      ,s        X = stack frame
                    lbra      ParseDeclStmt parse as declaration

KeywordDispatch     cmpx      #19       keyword 0x13
                    beq       ParseKw13 branch to handler
                    cmpx      #20       keyword 0x14
                    beq       ParseKw14 branch to handler
                    cmpx      #18       keyword 0x12
                    beq       ParseKw12 branch to handler
                    cmpx      #23       keyword 0x17
                    beq       ParseKw17 branch to handler
                    cmpx      #22       keyword 0x16
                    beq       ParseKw16 branch to handler
                    cmpx      #24       keyword 0x18
                    beq       ParseKw18 branch to handler
                    cmpx      #25       keyword 0x19
                    beq       ParseKw19 branch to handler
                    cmpx      #27       keyword 0x1B
                    beq       ParseKw1B branch to handler
                    cmpx      #28       keyword 0x1C
                    beq       ParseKw1C branch to handler
                    cmpx      #26       keyword 0x1A
                    beq       ParseKw1A branch to handler
                    cmpx      #29       keyword (else)
                    beq       ParseKwStart branch to handler
                    cmpx      #21       keyword 0x15
                    beq       ElseNoIfErr branch to else error
                    bra       StmtNotKeyword none match, try declaration

ParseExprStmt       lbsr      ParseDeclarations parse expression statement
                    lbsr      ParseStatement2 parse the statement
                    puls      pc,u      return

EmptyStmtRet        puls      pc,u      empty statement returns

ParseLabelStmt      lbsr      SkipSpaces parse expression
                    ldb       GlbVar0045 get current char
                    cmpb      #':      is it a colon
                    bne       StmtNotLabel not a label
                    lbsr      GenLabelStmt install label
StmtLoop            leax      ,s        X = stack frame
                    lbra      NextStmt  loop for next statement

StmtNotLabel        leax      ,s        X = stack frame
                    bra       CompileExprStmt handle expression statement

ParseDeclStmt       leas      ,x        restore saved stack pointer
CheckDeclSpec       lbsr      IsStorageKeyword parse declaration specifier
                    std       -2,s      save result
                    bne       IllegalDeclErr got one, illegal here
                    lbsr      IsTypeSpecifier try storage class
                    std       -2,s      save result
                    beq       EvalExprStmt none, it is a real statement
IllegalDeclErr      leax      MsgIllegalDecl,pcr error string illegal declaration
                    pshs      x         push message
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop
ParseDeclStmtBody   lbsr      ParseStatement2 parse remainder as statement
                    ldd       GlbVar003F get current token type
                    cmpd      #40       is it the statement terminator
                    bne       ParseDeclStmtBody keep skipping tokens until terminator
                    bra       EmitStmtEnd emit end of statement

CompileExprStmt     leas      ,x        restore stack pointer
EvalExprStmt        clra                D = 0
                    clrb                D = 0
                    pshs      d         reserve local for expression tree
                    lbsr      MakeInvertedCond parse the expression statement
                    std       ,s++      save expression tree pointer
                    bne       EmitStmtEnd got expression, emit statement
                    leax      MsgSyntaxError,pcr point to syntax error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop message pointer
                    lbsr      SkipToRecover resync to next statement
                    puls      pc,u      restore and return

                    bra       EmitStmtEnd emit end of statement

DispatchStmtToken   cmpx      #40       is token the statement terminator
                    beq       EmitStmtEnd empty statement, done
                    cmpx      #51       is it a keyword token
                    lbeq      DispatchKeyword dispatch a keyword statement
                    cmpx      #41       is it token type $29
                    lbeq      ParseExprStmt handle it
                    cmpx      #$FFFF    end of input
                    lbeq      EmptyStmtRet return at end of file
                    cmpx      #52       is it an identifier
                    lbeq      ParseLabelStmt handle label or expression
                    lbra      CheckDeclSpec otherwise parse as expression

EmitStmtEnd         ldd       #40       load statement-terminator marker
                    pshs      d         push the marker
                    lbsr      ExpectToken emit the terminator
                    leas      2,s        drop the marker
                    puls      pc,u      restore and return

CompileIf           pshs      u         save caller U
                    ldd       #$FFAE    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -6,s       allocate locals
                    lbsr      ParseStatement2 get next token past if
                    lbsr      ParseParenCond parse parenthesized condition
                    std       ,s        save condition tree
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate false-branch label
                    std       GlbVar000B update label counter
                    tfr       d,u       U = false-branch label
                    ldd       GlbVar000B get label counter again
                    addd      #1        allocate end label
                    std       GlbVar000B update label counter
                    std       4,s       save end label
                    ldd       GlbVar003F get current token
                    cmpd      #40       is the body empty
                    bne       IfCompileBody no, compile the body
                    lbsr      ParseStatement2 get next token
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       6,s       get condition tree
                    pshs      d         push condition
                    pshs      u         push false-branch label
                    ldd       6,s       reload condition tree
                    pshs      d         push condition
                    lbsr      EmitStmtAndFree emit conditional branch
                    leas      8,s        drop arguments
                    ldd       4,s       get end label
                    pshs      d         push end label
                    lbsr      EmitLocalLabel place the label
                    leas      2,s        drop argument
                    stu       2,s       save false-branch label
                    bra       IfCheckElse continue to else check

IfCompileBody       ldd       #1        push flag one
                    pshs      d         push it
                    ldd       6,s       get condition tree
                    pshs      d         push condition
                    pshs      u         push false-branch label
                    ldd       6,s       reload condition tree
                    pshs      d         push condition
                    lbsr      EmitStmtAndFree emit conditional branch
                    leas      8,s        drop arguments
                    pshs      u         push false-branch label
                    lbsr      EmitLocalLabel place the label
                    leas      2,s        drop argument
                    lbsr      ParseStatement compile the then-statement
                    ldd       4,s       get end label
                    std       2,s       save it as active label
IfCheckElse         ldd       GlbVar003F get current token
                    cmpd      #51       is it a keyword
                    bne       IfEmitEndLabel no, no else clause
                    ldd       GlbVar0041 get keyword value
                    cmpd      #21       is it else
                    bne       IfEmitEndLabel no, no else clause
                    lbsr      ParseStatement2 get next token past else
                    ldd       GlbVar003F get current token
                    cmpd      #40       is the else body empty
                    beq       IfEmitEndLabel yes, skip jump emit
                    cmpu      2,s       compare active label to false label
                    beq       IfCompileElse same label, skip jump emit
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate new end label
                    std       GlbVar000B update label counter
                    std       4,s       save end label
                    pshs      d         push end label
                    ldd       #124      jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to end label
                    leas      6,s        drop arguments
                    ldd       4,s       get end label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place false-branch label here
                    leas      2,s        drop argument
IfCompileElse       lbsr      ParseStatement compile the else-statement
IfEmitEndLabel      ldd       2,s       get end label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place end label here
                    leas      2,s        drop argument
                    leas      6,s        release locals
                    puls      pc,u      restore and return

CompileWhile        pshs      u         save caller U
                    ldd       #$FFAA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -10,s      allocate locals
                    ldd       GlbVar0033 get current break label
                    std       8,s       save outer break label
                    ldd       GlbVar0035 get current continue label
                    std       6,s       save outer continue label
                    ldd       LoopContextLow,y   save loop-context field
                    std       4,s       stash it
                    ldd       LoopContextHigh,y   save loop-context field
                    std       2,s       stash it
                    lbsr      ParseStatement2 get next token past while
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate loop-top label
                    std       GlbVar000B update label counter
                    std       GlbVar0033 set break-target label
                    ldd       GlbVar000F get current context value
                    std       LoopContextHigh,y   store loop context
                    std       LoopContextLow,y   store loop context
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate continue label
                    std       GlbVar000B update label counter
                    std       GlbVar0035 set continue-target label
                    lbsr      ParseParenCond parse parenthesized condition
                    std       ,s        save condition tree
                    ldd       GlbVar003F get current token
                    cmpd      #40       is the body empty
                    bne       WhileCompileBody no, compile the body
                    ldu       GlbVar0035 get continue label
                    bra       WhileEmitTest skip body compilation

WhileCompileBody    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       GlbVar0035 get continue label
                    pshs      d         push it
                    ldd       #124      jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to loop label
                    leas      6,s        drop arguments
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate loop-body label
                    std       GlbVar000B update label counter
                    tfr       d,u       U = new label
                    pshs      u         push it
                    lbsr      EmitLocalLabel place loop-body label
                    leas      2,s        drop argument
                    lbsr      ParseStatement compile the loop body
WhileEmitTest       ldd       GlbVar0035 get continue label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place continue label here
                    leas      2,s        drop argument
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       GlbVar0033 get break/test label
                    pshs      d         push it
                    pshs      u         push loop-body label
                    ldd       6,s       get saved condition tree
                    pshs      d         push condition
                    lbsr      EmitStmtAndFree emit conditional back-branch
                    leas      8,s        drop arguments
                    ldd       GlbVar0033 get break label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place break label here
                    leas      2,s        drop argument
                    ldd       8,s       get saved outer break label
                    std       GlbVar0033 restore outer break label
                    ldd       6,s       get saved outer continue label
                    std       GlbVar0035 restore outer continue label
                    ldd       4,s       get saved loop-context field
                    std       LoopContextLow,y   restore it
                    ldd       2,s       get saved loop-context field
                    std       LoopContextHigh,y   restore it
                    leas      10,s       release locals
                    puls      pc,u      restore and return

CompileSwitch       pshs      u         save caller U
                    ldd       #$FFA8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -14,s      allocate locals
                    lbsr      ParseStatement2 get next token past switch
                    ldd       GlbVar0037 get switch nesting depth
                    addd      #1        increment nesting depth
                    std       GlbVar0037 store new depth
                    ldd       F003bYLink get case-list tail pointer
                    std       ,s        save outer tail
                    ldd       GlbVar0039 get case-list head pointer
                    std       10,s      save outer head
                    clra                D = 0
                    clrb                D = 0
                    std       GlbVar0039 clear case-list head
                    ldd       GlbVar0033 get current break label
                    std       12,s      save outer break label
                    ldd       DefaultLabel,y   get current default label
                    std       8,s       save outer default label
                    ldd       LoopContextLow,y   get context field
                    std       2,s       save outer context field
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate break label
                    std       GlbVar000B update label counter
                    std       GlbVar0033 set switch break label
                    ldd       GlbVar000F get context value
                    std       LoopContextLow,y   store context field
                    clra                D = 0
                    clrb                D = 0
                    std       DefaultLabel,y   clear default label
                    ldd       #45       switch-start marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit switch start
                    leas      2,s        drop marker
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         reserve local for expression
                    lbsr      ParseBinaryExpr parse parenthesized expression
                    std       ,s        save expression tree
                    lbsr      CopyExprTree get expression type info
                    leas      2,s        drop argument
                    tfr       d,u       U = type node
                    stu       -2,s      save type node
                    beq       SwitchTypeErr no type, error path
                    pshs      u         push type node
                    lbsr      ReportUndeclared resolve base type
                    leas      2,s        drop argument
                    ldx       ,u        X = type code
                    bra       SwitchTypeDispatch dispatch on type code

SwitchPromoteInt    ldd       #1        push flag one
                    pshs      d         push it
                    pshs      u         push type node
                    lbsr      CoerceExpr promote integral expression
                    leas      4,s        drop arguments
                    bra       SwitchEmitExpr continue to emit

SwitchCoerceInt     pshs      u         push type node
                    lbsr      ReportNotIntegral dereference to value
                    leas      2,s        drop argument
                    pshs      u         push type node
                    lbsr      MakeErrorNode convert toward int
                    leas      2,s        drop argument
                    bra       SwitchEmitExpr continue to emit

SwitchTypeDispatch  cmpx      #2        type code int
                    beq       SwitchPromoteInt promote it
                    cmpx      #8        type code $08
                    lbeq      SwitchPromoteInt promote it
                    cmpx      #1        type code char
                    beq       SwitchEmitExpr use directly
                    cmpx      #7        type code $07
                    beq       SwitchEmitExpr use directly
                    bra       SwitchCoerceInt otherwise coerce to int

SwitchEmitExpr      pshs      u         push expression node
                    lbsr      CoerceToFloat finalize expression
                    leas      2,s        drop argument
                    pshs      u         push expression node
                    lbsr      FreeExprTree emit the expression
                    leas      2,s        drop argument
                    bra       EmitSwitchDispatch continue to dispatch

SwitchTypeErr       lbsr      ExprMissingErr report non-integral switch error
EmitSwitchDispatch  ldd       #46       switch-dispatch marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit dispatch marker
                    leas      2,s        drop marker
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate dispatch-table label
                    std       GlbVar000B update label counter
                    std       8,s       save table label
                    pshs      d         push it
                    ldd       #124      jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to dispatch table
                    leas      6,s        drop arguments
                    lbsr      ParseStatement compile the switch body
                    ldd       GlbVar002F test fall-through flag
                    bne       SwitchEmitTable set, skip break jump
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       GlbVar0033 get break label
                    pshs      d         push it
                    ldd       #124      jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to break label
                    leas      6,s        drop arguments
SwitchEmitTable     ldd       6,s       get dispatch-table label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place dispatch-table label
                    leas      2,s        drop argument
                    ldu       GlbVar0039 get case-list head
                    bra       CaseEntryLoopTest enter case-emit loop

EmitCaseEntryLoop   ldd       ,u        get next-node pointer
                    std       4,s       save it
                    ldd       2,u       get case label word
                    pshs      d         push it
                    ldd       4,u       get case value word
                    pshs      d         push it
                    ldd       #125      case-entry marker
                    pshs      d         push marker
                    lbsr      GenNode   emit case-table entry
                    leas      6,s        drop arguments
                    ldd       GlbFreeList get free-list head
                    std       ,u        link node onto free list
                    stu       GlbFreeList update free-list head
                    ldu       4,s       get next case node
CaseEntryLoopTest   stu       -2,s      save case-node pointer
                    bne       EmitCaseEntryLoop loop while nodes remain
                    ldd       DefaultLabel,y   get default label
                    beq       SwitchRestore none, skip default jump
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       DefaultLabel,y   get default label
                    pshs      d         push it
                    ldd       #124      jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to default
                    leas      6,s        drop arguments
SwitchRestore       ldd       GlbVar0033 get break label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place break label here
                    leas      2,s        drop argument
                    ldd       10,s      get saved outer case-list head
                    std       GlbVar0039 restore case-list head
                    ldd       8,s       get saved outer default label
                    std       DefaultLabel,y   restore default label
                    ldd       GlbVar0037 get switch nesting depth
                    addd      #$FFFF    decrement nesting depth
                    std       GlbVar0037 store new depth
                    ldd       ,s        get saved outer case-list tail
                    std       F003bYLink restore case-list tail
                    ldd       12,s      get saved outer break label
                    std       GlbVar0033 restore break label
                    ldd       2,s       get saved outer context field
                    std       LoopContextLow,y   restore context field
                    lbra      ForExit   release locals and return

CompileCase         pshs      u         save caller U
                    ldd       #$FFB8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -2,s       allocate local
                    lbsr      ParseStatement2 get next token past case
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         reserve local for value
                    lbsr      ParseConstExpr parse constant expression
                    leas      2,s        drop argument
                    std       ,s        save case value
                    ldd       #47       case-label marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit case marker
                    leas      2,s        drop marker
                    ldd       GlbVar0037 get switch nesting depth
                    beq       CaseNotInSwitchErr zero, case outside switch
                    ldu       GlbFreeList get a node off the free list
                    beq       AllocCaseNode empty, allocate one
                    ldd       ,u        get next-node link
                    std       GlbFreeList advance free-list head
                    bra       LinkCaseNode use this node

AllocCaseNode       ldd       #6        node size six bytes
                    pshs      d         push size
                    lbsr      AllocMem  allocate case node
                    leas      2,s        drop argument
                    tfr       d,u       U = new node
LinkCaseNode        ldd       GlbVar0039 get case-list head
                    beq       SetCaseListHead empty list, set head
                    stu       [>F003bYLink,y] link node onto previous tail
                    bra       FillCaseNode skip head assignment

SetCaseListHead     stu       GlbVar0039 set case-list head
FillCaseNode        stu       F003bYLink set case-list tail
                    clra                D = 0
                    clrb                D = 0
                    std       ,u        clear node next-link
                    ldd       ,s        get case value
                    std       2,u       store value in node
                    ldd       GlbVar000B get label counter
                    addd      #1        allocate case label
                    std       GlbVar000B update label counter
                    std       4,u       store case label in node
                    pshs      d         push case label
                    lbsr      EmitLocalLabel place case label here
                    leas      2,s        drop argument
                    bra       CaseDefaultRet return

CaseNotInSwitchErr  bsr       NoSwitchErr report case outside switch
                    bra       CaseDefaultRet return

CompileDefault      pshs      u         save caller U
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    lbsr      ParseStatement2 get next token past default
                    ldd       GlbVar0037 get switch nesting depth
                    bne       DefaultCheckDup inside switch, continue
                    bsr       NoSwitchErr report default outside switch
DefaultCheckDup     ldd       DefaultLabel,y   get current default label
                    beq       SetDefaultLabel none yet, set it
                    leax      MsgMultipleDefaults,pcr point to multiple-defaults message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    bra       DefaultEmitMarker skip label allocation

SetDefaultLabel     ldd       GlbVar000B get label counter
                    addd      #1        allocate default label
                    std       GlbVar000B update label counter
                    std       DefaultLabel,y   store default label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place default label here
DefaultEmitMarker   leas      2,s        drop argument
                    ldd       #47       default marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit default marker
                    bra       CaseDefaultRet return

NoSwitchErr         pshs      u         save caller U
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leax      MsgNoSwitch,pcr point to no-switch message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
CaseDefaultRet      leas      2,s        drop argument
                    puls      pc,u      restore and return

CompileFor          pshs      u         save caller U
                    ldd       #$FFAA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -10,s      allocate locals
                    ldd       GlbVar0033 get current break label
                    std       8,s       save outer break label
                    ldd       GlbVar0035 get current continue label
                    std       6,s       save outer continue label
                    ldd       LoopContextHigh,y   get loop-context field
                    std       ,s        save token value into local
                    ldd       LoopContextLow,y   load saved loop context low
                    std       2,s       stash it in local frame
                    ldd       GlbVar000F zero base value
                    std       LoopContextHigh,y   reset loop context high
                    std       LoopContextLow,y   reset loop context low
                    ldd       GlbVar000B current label counter
                    addd      #1        allocate next label number
                    std       GlbVar000B update label counter
                    std       GlbVar0035 set continue label
                    ldd       GlbVar000B current label counter
                    addd      #1        allocate next label number
                    std       GlbVar000B update label counter
                    std       GlbVar0033 set break label
                    lbsr      ParseStatement2 advance to next token
                    ldd       GlbVar000B current label counter
                    addd      #1        allocate loop-top label
                    std       GlbVar000B update label counter
                    std       4,s       save loop-top label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit loop-top label
                    leas      2,s        drop argument
                    lbsr      ParseStatement parse loop body statement
                    ldd       GlbVar003F current token type
                    cmpd      #51       is it the while keyword
                    bne       DoWhileNoWhileErr no, report syntax error
                    ldd       GlbVar0041 token value
                    cmpd      #20       matches while token value
                    beq       DoWhileEmitCond yes, emit loop condition
DoWhileNoWhileErr   leax      MsgWhileExpected,pcr address of syntax error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop argument
DoWhileEmitCond     lbsr      ParseStatement2 advance past while
                    ldd       GlbVar0035 continue label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit continue label
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       GlbVar0033 break label
                    pshs      d         push break label
                    ldd       8,s       loop-top label
                    pshs      d         push loop-top label
                    lbsr      ParseParenCond parse and emit condition
                    pshs      d         push condition result
                    lbsr      EmitStmtAndFree emit conditional branch back
                    leas      8,s        drop arguments
                    ldd       GlbVar0033 break label
                    pshs      d         push break label
                    lbsr      EmitLocalLabel emit break label
                    leas      2,s        drop argument
                    ldd       8,s       restore saved break label
                    std       GlbVar0033 restore break label
                    ldd       6,s       restore saved continue label
                    std       GlbVar0035 restore continue label
                    ldd       2,s       restore saved context low
                    std       LoopContextLow,y   restore loop context low
                    ldd       ,s        restore saved context high
                    std       LoopContextHigh,y   restore loop context high
                    leas      10,s       release local frame
                    puls      pc,u      restore U and return

GenForStmt          pshs      u         save U register
                    ldd       #$FFA6    stack space needed
                    lbsr      stkcheck  verify stack room
                    leas      -14,s      allocate local frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       2,s       clear local slot
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        clear local slot
                    ldu       GlbVar0033 save current break label
                    ldd       GlbVar0035 current continue label
                    std       12,s      save it in frame
                    ldd       LoopContextLow,y   saved loop context low
                    std       6,s       save it in frame
                    ldd       LoopContextHigh,y   loop context high
                    std       4,s       save it in frame
                    ldd       GlbVar000F zero base value
                    std       LoopContextLow,y   reset loop context low
                    std       LoopContextHigh,y   reset loop context high
                    ldd       GlbVar000B label counter
                    addd      #1        allocate loop-back label
                    std       GlbVar000B update label counter
                    std       10,s      save loop-back label
                    ldd       GlbVar000B label counter
                    addd      #1        allocate break label
                    std       GlbVar000B update label counter
                    std       GlbVar0033 set new break label
                    lbsr      ParseStatement2 advance to next token
                    ldd       #45       for keyword op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match for init clause
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      MakeInvertedCond parse for init clause
                    leas      2,s        drop argument
                    ldd       #'(       open-paren op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match opening delimiter
                    leas      2,s        drop argument
                    ldd       GlbVar003F current token type
                    cmpd      #40       is condition clause empty
                    beq       ForParseCond yes, skip condition
                    lbsr      ParseCondExpr parse condition expression
                    std       2,s       save condition node
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       GlbVar000B label counter
                    addd      #1        allocate exit label
                    std       GlbVar000B update label counter
                    std       10,s      save condition-exit label
                    pshs      d         push label argument
                    ldd       #124      branch-if-false op code
                    pshs      d         push op argument
                    lbsr      GenNode   emit conditional branch
                    leas      6,s        drop arguments
ForParseCond        ldd       #'(       open-paren op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match second clause delimiter
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      ParseBinaryExpr parse increment expression
                    std       ,s        save increment node
                    lbsr      CopyExprTree reduce increment expression
                    leas      2,s        drop argument
                    std       ,s        save reduced increment
                    beq       ForNoIncr no increment present
                    ldd       ,s        increment node
                    pshs      d         push node argument
                    lbsr      ReportUndeclared process increment expression
                    leas      2,s        drop argument
                    ldd       GlbVar000B label counter
                    addd      #1        allocate increment label
                    std       GlbVar000B update label counter
                    bra       ForSetContinue set continue label

ForNoIncr           ldd       10,s      reuse condition-exit label
ForSetContinue      std       GlbVar0035 set continue label
                    ldd       #46       clause-end op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match closing delimiter
                    leas      2,s        drop argument
                    ldd       10,s      loop-back label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit loop-back label
                    leas      2,s        drop argument
                    lbsr      ParseStatement parse loop body statement
                    ldd       ,s        increment node
                    beq       ForCheckCond none, skip increment emit
                    ldd       GlbVar0035 continue label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit continue label
                    leas      2,s        drop argument
                    ldd       ,s        increment node
                    pshs      d         push node argument
                    lbsr      InvertCompareNode emit increment code
                    leas      2,s        drop argument
ForCheckCond        ldd       2,s       condition node
                    beq       ForUncondBack none, unconditional loop back
                    ldd       8,s       loop-back label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit label reference
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       GlbVar0033 break label
                    pshs      d         push break label
                    ldd       14,s      loop-back label
                    pshs      d         push loop-back label
                    ldd       8,s       condition-exit label
                    pshs      d         push label argument
                    lbsr      EmitStmtAndFree emit conditional branch back
                    leas      8,s        drop arguments
                    bra       ForEmitEnd finish for loop

ForUncondBack       clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       12,s      loop-back target label
                    pshs      d         push label argument
                    ldd       #124      branch op code
                    pshs      d         push op argument
                    lbsr      GenNode   emit unconditional loop back
                    leas      6,s        drop arguments
ForEmitEnd          ldd       GlbVar0033 break label
                    pshs      d         push break label
                    lbsr      EmitLocalLabel emit break label
                    leas      2,s        drop argument
                    stu       GlbVar0033 restore break label
                    ldd       12,s      saved continue label
                    std       GlbVar0035 restore continue label
                    ldd       6,s       saved loop context low
                    std       LoopContextLow,y   restore context low
                    ldd       4,s       saved loop context high
                    std       LoopContextHigh,y   restore context high
ForExit             leas      14,s       release local frame
                    puls      pc,u      restore U and return

GenReturnStmt       pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       GlbVar003F current token type
                    cmpd      #40       is it an empty return
                    lbeq      RetEmitDone yes, emit bare return
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      ParseBinaryExpr parse return expression
                    leas      2,s        drop argument
                    tfr       d,u       U = expression node
                    stu       -2,s      stash node below stack
                    lbeq      RetEmitDone null expression, bare return
                    pshs      u         push expression node
                    lbsr      CopyExprTree reduce expression
                    leas      2,s        drop argument
                    tfr       d,u       U = reduced node
                    pshs      u         push node
                    lbsr      ReportUndeclared process return value
                    leas      2,s        drop argument
                    pshs      u         push node
                    lbsr      RejectAggregate coerce to return type
                    leas      2,s        drop argument
                    ldd       GlbVar002D expression result type
                    clra                keep low type byte
                    andb      #$30      mask type-class bits
                    cmpd      #16       is it a pointer type
                    bne       RetTypeActual no, use actual type
                    ldd       #1        pointer type code
                    bra       RetEmitLoad proceed with load

RetTypeActual       ldd       GlbVar002D actual expression type
RetEmitLoad         pshs      d         push type argument
                    pshs      u         push node
                    lbsr      CoerceExpr generate value load
                    leas      4,s        drop arguments
                    ldx       GlbVar002D expression type
                    lbra      RetTypeDispatch dispatch on return type

RetStructType       pshs      u         push node
                    lbsr      GenExpr   handle structure return
                    leas      2,s        drop argument
                    leax      ,s        point X at result
                    bra       RetAfterStruct continue conversion

RetScalarType       pshs      u         push node
                    lbsr      GenOperand handle scalar return
                    leas      2,s        drop argument
                    bra       RetCheckReg continue conversion

RetAfterStruct      leas      ,x        adjust stack pointer
RetCheckReg         ldd       6,u       node type field
                    cmpd      #128      already in accumulator
                    lbeq      RetEmitValue yes, emit value directly
                    ldd       #128      target register code
                    pshs      d         push argument
                    ldd       #111      source operand code
                    pshs      d         push argument
                    ldd       #127      register move op code
                    pshs      d         push argument
                    lbsr      GenNode   emit register move
                    leas      6,s        drop arguments
                    ldd       #111      operand code
                    pshs      d         push argument
                    ldd       #122      conversion op code
                    pshs      d         push argument
                    lbsr      GenNode   emit conversion op
                    leas      4,s        drop arguments
                    ldx       GlbVar002D expression type
                    bra       RetWidthDispatch dispatch on type width

RetWidenInt         ldd       GlbVar002D expression type
                    pshs      d         push type argument
                    ldd       #137      operand code
                    pshs      d         push argument
                    ldd       #135      widen op code
                    pshs      d         push argument
                    lbsr      GenNode   emit widening op
                    leas      6,s        drop arguments
                    bra       RetEmitValue emit return value

RetNarrow           ldd       #137      operand code
                    pshs      d         push argument
                    ldd       #136      narrow op code
                    pshs      d         push argument
                    lbsr      GenNode   emit narrowing op
                    leas      4,s        drop arguments
                    bra       RetEmitValue emit return value

RetWidthDispatch    cmpx      #5        is type int
                    beq       RetWidenInt yes, widen it
                    cmpx      #6        is type unsigned int
                    lbeq      RetWidenInt yes, widen it
                    bra       RetNarrow else narrow it

RetOtherType        pshs      u         push node
                    lbsr      CoerceToDouble handle other return type
                    leas      2,s        drop argument
                    bra       RetEmitValue emit return value

RetTypeDispatch     cmpx      #8        type is struct/pointer
                    lbeq      RetStructType handle structure return
                    cmpx      #5        type is int
                    lbeq      RetScalarType handle scalar return
                    cmpx      #6        type is unsigned int
                    lbeq      RetScalarType handle scalar return
                    bra       RetOtherType handle other type

RetEmitValue        pshs      u         push node
                    lbsr      FreeExprTree emit return value load
                    leas      2,s        drop argument
RetEmitDone         clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      EmitReserveSpace emit return marker
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       #18       return op code
                    pshs      d         push argument
                    lbsr      GenNode   emit return operation
                    leas      6,s        drop arguments
                    ldd       #18       return statement kind
                    lbra      StoreStmtKind store statement kind

GenBreakStmt        pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       GlbVar0033 break label
                    bne       BreakEmit inside loop, emit branch
                    leax      MsgBreakError,pcr break-outside-loop error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop argument
                    bra       BreakDone finish break statement

BreakEmit           ldd       LoopContextLow,y   loop context value
                    pshs      d         push argument
                    lbsr      EmitReserveSpace emit label reference
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       GlbVar0033 break label
                    pshs      d         push break label
                    ldd       #124      branch op code
                    pshs      d         push argument
                    lbsr      GenNode   emit branch to break label
                    leas      6,s        drop arguments
BreakDone           ldd       #24       break statement kind
                    lbra      StoreStmtKind store statement kind

GenContinueStmt     pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       GlbVar0035 continue label
                    bne       ContinueEmit inside loop, emit branch
                    leax      MsgContinueError,pcr continue-outside-loop error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop argument
                    bra       ContinueDone finish continue statement

ContinueEmit        ldd       LoopContextHigh,y   loop context value
                    pshs      d         push argument
                    lbsr      EmitReserveSpace emit label reference
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       GlbVar0035 continue label
                    pshs      d         push continue label
                    ldd       #124      branch op code
                    pshs      d         push argument
                    lbsr      GenNode   emit branch to continue label
                    leas      6,s        drop arguments
ContinueDone        ldd       #25       continue statement kind
                    bra       StoreStmtKind store statement kind

GenGotoStmt         pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       GlbVar003F current token type
                    cmpd      #52       is it an identifier label
                    beq       GotoResolve yes, resolve goto target
                    leax      MsgLabelRequired,pcr missing-label error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop argument
                    bra       GotoRet   finish goto statement

GotoResolve         lbsr      LookupLabelSym look up label symbol
                    tfr       d,u       U = symbol pointer
                    stu       -2,s      stash symbol pointer
                    beq       GotoDone  not found, skip emit
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       6,u       symbol label number
                    pshs      d         push label argument
                    ldd       #29       jump op code
                    pshs      d         push argument
                    lbsr      GenNode   emit jump to label
                    leas      6,s        drop arguments
                    ldd       10,u      symbol flags
                    orb       #$02      mark label referenced
                    std       10,u      store flags back
GotoDone            lbsr      ParseStatement2 advance past label name
GotoRet             ldd       #29       goto statement kind (zero)
StoreStmtKind       std       GlbVar002F store statement kind
                    puls      pc,u      restore U and return

GenLabelStmt        pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    bsr       LookupLabelSym look up label symbol
                    tfr       d,u       U = symbol pointer
                    stu       -2,s      stash symbol pointer
                    beq       LabelDone not found, skip
                    ldd       8,u       symbol definition state
                    cmpd      #15       already defined here
                    bne       LabelDefine no, define it now
                    lbsr      ErrMultiDef report duplicate label error
                    bra       LabelDone finish label statement

LabelDefine         ldd       #15       defined-state marker
                    std       8,u       mark label defined
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       6,u       symbol label number
                    pshs      d         push label argument
                    ldd       #9        label-define op code
                    pshs      d         push argument
                    lbsr      GenNode   emit label definition
                    leas      6,s        drop arguments
                    ldd       10,u      symbol flags
                    orb       #$01      mark label defined
                    std       10,u      store flags back
LabelDone           lbsr      ParseStatement2 advance to next token
                    lbsr      ParseStatement2 advance past colon
                    puls      pc,u      restore U and return

LookupLabelSym      pshs      u         save U register
                    ldd       #$FFBA    stack space needed
                    lbsr      stkcheck  verify stack room
                    ldu       GlbVar0041 U = current token value
                    ldd       ,u        load node type field
                    cmpd      #9        is it already a label node type 9
                    lbeq      ReturnNode3 yes just return the node
                    ldd       ,u        reload node type field
                    beq       BuildLabelNode empty node so build label in place
                    ldd       12,u      load local-variable field
                    beq       FreeNodeForLabel free existing contents first
                    leax      MsgAlreadyLocal,pcr point to already-a-local-variable message
                    pshs      x         pass message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      2,s
                    clra                clear high byte of result
                    clrb                return null node
                    puls      pc,u      restore and return

FreeNodeForLabel    pshs      u         pass the node pointer
                    lbsr      AllocBlk  release old node contents
                    leas      2,s        drop argument
BuildLabelNode      ldd       #9        label node type code 9
                    std       ,u        set node type to label
                    ldd       #13       label kind code $0D
                    std       8,u       store kind field
                    ldd       GlbVar000B load global label counter
                    addd      #1        bump the label number
                    std       GlbVar000B save incremented counter
                    std       6,u       store new label number in node
                    clra                clear high byte
                    clrb                clear low byte
                    std       10,u      clear operand field
                    ldd       GlbVar0031 load current scope value
                    std       12,u      store scope into node
                    ldd       NodeBuilderBase load head of label list
                    std       16,u      link node to previous head
                    stu       NodeBuilderBase make node the new list head
                    lbra      ReturnNode3 return the finished node

MakeInvertedCond    pshs      u         save caller node pointer
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldd       4,s       load argument node
                    pshs      d         pass it to parser
                    lbsr      ParseBinaryExpr parse expression
                    leas      2,s        drop argument
                    tfr       d,u       result node into U
                    stu       -2,s      save result in frame
                    lbeq      ReturnNode3 null expression so return
                    pshs      u         pass result node
                    lbsr      CopyExprTree coerce to rvalue
                    std       ,s        replace with coerced node
                    bsr       InvertCompareNode invert the condition
                    leas      2,s        drop argument
                    tfr       d,u       inverted node into U
                    lbra      ReturnNode3 return the inverted condition

InvertCompareNode   pshs      u         save node pointer
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       4,s       load argument node
                    pshs      u         pass it
                    lbsr      ReportUndeclared build compare tree
                    leas      2,s        drop argument
                    ldx       6,u       load node operator code
                    bra       CheckRelationalOp dispatch on the operator

SetInvOp3C          ldd       #60       inverted operator for relational $3E
                    bra       StoreInvertedOp store it

SetInvOp3D          ldd       #61       inverted operator for relational $3F
StoreInvertedOp     std       6,u       replace operator in node
                    bra       FinishInvertedCond continue after inversion

CheckRelationalOp   cmpx      #62       is operator relational $3E
                    beq       SetInvOp3C invert it to $3C
                    cmpx      #63       is operator relational $3F
                    beq       SetInvOp3D invert it to $3D
FinishInvertedCond  pshs      u         pass the node
                    lbsr      EvalSubtreeType generate condition-code tree
                    leas      2,s        drop argument
                    tfr       d,u       result into U
                    pshs      u         pass result node
                    lbsr      FreeExprTree free the working tree
                    lbra      ExprGenDone return via common exit

ParseParenCond      pshs      u         save caller node
                    ldd       #$FFB8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -2,s       reserve a local slot
                    ldd       #'-       expected token open paren
                    pshs      d         pass expected token
                    lbsr      ExpectToken require opening paren
                    leas      2,s        drop argument
                    bsr       ParseCondExpr parse the condition expression
                    std       ,s        save parsed node
                    ldd       #'.       expected token close paren
                    pshs      d         pass expected token
                    lbsr      ExpectToken require closing paren
                    leas      2,s        drop argument
                    ldd       ,s        reload parsed node
                    lbra      EmitStmtDone return the condition

ParseCondExpr       pshs      u         save node
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    clra                clear high byte
                    clrb                clear low byte seed
                    pshs      d         pass null seed
                    lbsr      ParseBinaryExpr parse expression
                    std       ,s        save result node
                    lbsr      CopyExprTree coerce to rvalue
                    leas      2,s        drop argument
                    tfr       d,u       result into U
                    stu       -2,s      save in frame
                    beq       CondNeededErr null so condition-needed error
                    pshs      u         pass node
                    lbsr      ReportUndeclared build compare tree
                    bra       ExprGenDone return via common exit

CondNeededErr       leax      MsgCondNeeded,pcr point to condition-needed message
                    pshs      x         pass message pointer
                    lbsr      BuildMsgBuf report the error
ExprGenDone         leas      2,s        drop argument
ReturnNode3         tfr       u,d       move node into D for return
                    puls      pc,u      restore and return

EmitStmtAndFree     pshs      u         save caller node
                    ldd       #$FFB4    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       4,s       load argument node
                    stu       -2,s      save in frame
                    beq       EmitStmtRet null so nothing to emit
                    ldd       10,s      load first caller argument
                    pshs      d         pass it
                    ldd       10,s      load second caller argument
                    pshs      d         pass it
                    ldd       10,s      load third caller argument
                    pshs      d         pass it
                    pshs      u         pass the node
                    lbsr      GenTestExpr emit statement code
                    leas      8,s        drop four arguments
                    pshs      u         pass node
                    lbsr      FreeExprTree free the tree
EmitStmtDone        leas      2,s        drop argument
EmitStmtRet         puls      pc,u      restore and return

MsgNoIfForElse      fcc       /no 'if' for 'else'/
                    fcb       C$NULL
MsgIllegalDecl      fcc       /illegal declaration/
                    fcb       C$NULL
MsgSyntaxError      fcc       /syntax error/
                    fcb       C$NULL
MsgMultipleDefaults fcc       /multiple defaults/
                    fcb       C$NULL
MsgNoSwitch         fcc       /no switch statement/
                    fcb       C$NULL
MsgWhileExpected    fcc       /while expected/
                    fcb       C$NULL
MsgBreakError       fcc       /break error/
                    fcb       C$NULL
MsgContinueError    fcc       /continue error/
                    fcb       C$NULL
MsgLabelRequired    fcc       /label required/
                    fcb       C$NULL
MsgAlreadyLocal     fcc       /already a local variable/
                    fcb       C$NULL
MsgCondNeeded       fcc       /condition needed/
                    fcb       C$NULL
GenExpr             pshs      u         save node
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldd       4,s       load argument node
                    pshs      d         pass it
                    bsr       GenExprDispatch dispatch expression codegen
                    leas      2,s        drop argument
                    ldd       4,s       reload node
                    pshs      d         pass it
                    lbsr      GenTypeExtend emit result and cleanup
                    leas      2,s        drop argument
                    puls      pc,u      restore and return

GenExprDispatch     pshs      u         save node
                    ldd       #$FFAE    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       4,s       load argument node
                    leas      -6,s       reserve temp frame
                    ldd       6,u       load node operator code
                    std       2,s       save operator
                    tfr       d,x       operator into X for switch
                    lbra      OpDispatch jump to operator switch

GenIncDecOp         pshs      u         save node
                    lbsr      GenIndirection generate left operand
                    leas      2,s        drop argument
                    pshs      u         pass node
                    lbsr      FixFlaggedNode generate right operand
                    leas      2,s        drop argument
                    ldx       6,u       load node operator code
                    bra       CheckIncDecOp2 check operator type

GenAutoIncDec       ldd       8,u       load node kind field
                    lbeq      GenExprDone plain case take common exit
                    pshs      u         save node
                    ldd       #119      opcode $77
                    pshs      d         pass it
                    ldd       #123      opcode $7B
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      6,s        drop three arguments
                    lbra      SetLongResult continue at emit tail

CheckIncDecOp2      cmpx      #147      pre/post inc-dec operator
                    beq       GenAutoIncDec handle it
                    cmpx      #148      another inc-dec variant
                    lbeq      GenAutoIncDec handle it
                    cmpx      #149      third inc-dec variant
                    lbeq      GenAutoIncDec handle it
                    lbra      GenExprDone otherwise common exit

GenNegOp            ldd       10,u      load left operand node
                    pshs      d         pass it
                    lbsr      CoerceToDouble generate left operand
                    leas      2,s        drop argument
                    ldd       #134      result operator opcode $86
                    lbra      EmitOpTail emit at common tail

GenAssignAddrOp     ldd       10,u      load left operand
                    pshs      d         pass it
                    lbsr      GenOperand generate address operand
                    leas      2,s        drop argument
                    ldd       10,u      reload left operand
                    pshs      d         pass it
                    ldd       #145      opcode $91
                    pshs      d         pass it
                    ldd       #135      opcode $87
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      6,s        drop three arguments
                    lbra      SaveFrameSetResult continue at emit tail

GenLoadOp           ldd       10,u      load left operand
                    pshs      d         pass it
                    lbsr      CoerceToDouble generate left operand
                    leas      2,s        drop argument
                    ldd       #131      opcode $83
                    pshs      d         pass it
                    ldd       #136      opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      4,s        drop two arguments
                    bra       SetResultOp80 set result operator

RestoreFrameSetResult leas      -6,x      restore temp frame
SetResultOp80       ldd       #128      result operator $80
                    std       6,u       set node operator
                    lbra      GenExprDone common exit

GenAddrRefOp        ldd       8,u       load node kind field
                    pshs      d         pass it
                    ldd       #74       opcode $4A
                    pshs      d         pass it
                    ldd       #136      opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      6,s        drop three arguments
                    bra       SaveFrameEmitTail continue at emit tail

GenViaCallback      leax      GenExpr,pcr address of expression codegen
                    pshs      x         pass as callback
                    pshs      u         pass node
                    lbsr      GenBoolValueCB generate via callback
                    bra       DropTwoArgs continue

GenLeftWithOp       ldd       10,u      load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      2,s        drop argument
                    ldd       2,s       load saved operator
                    pshs      d         pass it
                    ldd       #136      opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
DropTwoArgs         leas      4,s        drop two arguments
SaveFrameEmitTail   leax      6,s       save current frame in X
                    lbra      SetLongNorm continue at emit tail

GenLogicalOp        clra                clear high byte
                    clrb                clear low byte
                    pshs      d         pass zero value
                    ldd       #128      opcode $80
                    pshs      d         pass it
                    ldd       #113      opcode $71
                    pshs      d         pass it
                    ldd       #127      opcode $7F
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      8,s        drop four arguments
                    ldd       #113      opcode $71
                    pshs      d         pass it
                    ldd       #122      opcode $7A
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      4,s        drop two arguments
                    ldd       10,u      load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      2,s        drop argument
                    ldd       2,s       load saved operator
                    pshs      d         pass it
                    ldd       #136      opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      4,s        drop two arguments
                    ldd       #137      opcode $89
                    pshs      d         pass it
                    ldd       #136      opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      4,s        drop two arguments
                    ldd       2,s       load saved operator
                    cmpd      #62       is it relational $3E
                    bne       SetResultOp3E no so use $3E result
                    ldd       #63       result operator $3F
                    lbra      EmitOpTail emit at common tail

SetResultOp3E       ldd       #62       result operator $3E
                    lbra      EmitOpTail emit at common tail

GenSimpleOp         pshs      u         save node
                    lbsr      GenExprList generate subtree
                    leas      2,s        drop argument
                    lbra      SaveFrameSetResult continue at emit tail

GenCommutativeOp    ldx       10,u      load left operand node
                    ldd       6,x       load its operator code
                    cmpd      #74       is left a constant node
                    bne       CheckRightConst no so keep operand order
                    leas      -2,s       temp slot for swap
                    ldd       10,u      load left operand
                    std       ,s        stash it
                    ldd       12,u      load right operand
                    std       10,u      move right into left
                    ldd       ,s        reload stashed left
                    std       12,u      move it into right
                    leas      2,s        drop temp slot
CheckRightConst     ldx       12,u      load right operand node
                    ldd       6,x       load its operator code
                    cmpd      #74       is right a constant node
                    bne       GenBinaryGeneral no so general case
                    ldx       12,u      reload right operand
                    ldd       8,x       load its value pointer
                    std       4,s       save in frame
                    ldd       [4,s]     dereference the value
                    bne       GenBinaryGeneral nonzero so general case
                    ldx       4,s       value pointer into X
                    ldd       2,x       load symbol field
                    pshs      d         pass it
                    lbsr      FindTableIndex look up the symbol
                    leas      2,s        drop argument
                    std       ,s        save lookup result
                    beq       GenBinaryGeneral not found so general case
                    ldd       12,u      load right operand
                    std       4,s       save in frame
                    ldd       ,s        load looked-up node
                    ldx       4,s       right operand pointer
                    std       8,x       store into value field
                    ldd       #54       operator code $36
                    ldx       4,s       right operand pointer
                    std       6,x       set its operator
                    ldd       #1        value one
                    std       [4,s]     mark node as resolved
                    ldd       2,s       load saved operator
                    cmpd      #82       is it operator $52
                    bne       SetFoldedOp55 no so use $55
                    ldd       #86       folded result operator $56
                    bra       StoreFoldedOp store it

SetFoldedOp55       ldd       #85       folded result operator $55
StoreFoldedOp       std       2,s       save chosen result operator
                    leax      6,s       save the caller u register in X
                    bra       RestoreFrameEmitBin restore and emit binary

GenBinaryGeneral    ldd       10,u      load left operand
                    std       4,s       save in frame
                    ldx       4,s       left operand pointer
                    ldd       6,x       load its operator code
                    cmpd      #74       is left a constant node
                    bne       GenLeftGeneral no so general codegen
                    ldd       4,s       load left operand
                    pshs      d         pass it
                    lbsr      GenAddConst emit constant operand
                    leas      2,s        drop argument
                    bra       GenRightOperand do the right operand

GenLeftGeneral      ldd       4,s       load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      2,s        drop argument
                    ldd       #110      opcode $6E
                    pshs      d         pass it
                    ldd       #136      opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      4,s        drop two arguments
GenRightOperand     ldd       12,u      load right operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate right operand
                    bra       LoadSavedOp emit at common tail

RestoreFrameEmitBin leas      -6,x      restore temp frame
EmitBinLeft         ldd       10,u      load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      2,s        drop argument
