SetupInitStorage    ldd       GlbVar0031 defining/pass flag
                    bne       EmitExternRef branch if externally referenced
                    leax      20,u      point at node data field
                    stx       2,s       save data pointer
                    ldd       10,s      load type code
                    cmpd      #15       type $000F needs full size
                    beq       SetSize12 use size twelve
                    ldd       10,s      reload type code
                    cmpd      #35       type $0023 needs full size
                    beq       SetSize12 use size twelve
                    ldd       #1        default size one
                    bra       EmitDefWithSize emit with size

SetSize12           ldd       #12       size twelve
                    std       8,u       store node size
                    clra                clear A
                    clrb                clear B
EmitDefWithSize     pshs      d         push the size
                    ldd       4,s       node data pointer
                    pshs      d         push it
                    lbsr      EmitLabelDef emit the definition
                    leas      4,s        drop arguments
                    bra       CheckStringInit continue to string check

EmitExternRef       ldd       6,u       node type field
                    pshs      d         push it
                    lbsr      EmitLabelName emit external reference
                    leas      2,s        drop argument
                    lbsr      EmitNewline emit follow-up
CheckStringInit     ldd       12,s      reload saved type code
                    cmpd      #34       char-array type?
                    bne       NotStringInit not a string init
                    ldd       #1        init mode one
                    std       GlbPassMode set init mode flag
                    lbsr      ParseStatement2 get next token
                    ldd       GlbVar003F current token code
                    cmpd      #55       string constant token?
                    bne       StringNotToken not a string constant
                    ldd       4,u       node size field pointer
                    std       2,s       save it
                    ldd       [2,s]     array size already set?
                    bne       StringHasRoom yes, compute padding
                    ldd       GlbVar0060 string length global
                    std       [2,s]     set array size from string
                    bra       NextAfterString skip padding

StringHasRoom       ldd       [2,s]     declared array size
                    subd      GlbVar0060 minus string length
                    std       ,s        save remaining bytes
                    blt       StringTooLongErr negative means too long
                    ldd       ,s        reload remaining count
                    pshs      d         push it
                    lbsr      EmitCharDecimal pad remaining bytes
                    bra       AfterStringPad continue

StringTooLongErr    leax      MsgTooLong,pcr too-long error message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
AfterStringPad      leas      2,s        drop temp
NextAfterString     lbsr      ParseStatement2 advance token past string
                    leax      4,s       compute cleanup pointer
                    lbra      InitCleanupViaX go clean up and finish

StringNotToken      ldd       #2        init mode two
                    std       GlbPassMode set init mode flag
                    bra       DispatchInitByClass dispatch by class

NotStringInit       ldd       #2        init mode two
                    std       GlbPassMode set init mode flag
                    lbsr      ParseStatement2 get next token
DispatchInitByClass ldd       12,s      reload type code
                    cmpd      #4        struct/union type?
                    bne       CheckArrayClass not a struct
                    clra                clear A
                    clrb                clear B
                    pshs      d         push flag zero
                    ldd       10,u      struct member list
CallAggInit         pshs      d         push member list
                    pshs      u         push node pointer
                    ldd       18,s      depth/param
                    pshs      d         push it
                    bsr       ParseAggregateInit parse aggregate init
                    leas      8,s        drop arguments
                    bra       FinishInit finish

CheckArrayClass     ldd       12,s      reload type code
                    clra                clear A
                    andb      #$30      isolate class bits
                    cmpd      #32       array class?
                    bne       InitScalarValue not an array
                    clra                clear A
                    clrb                clear B
                    pshs      d         push flag zero
                    ldd       4,u       array element type
                    bra       CallAggInit parse aggregate init

InitScalarValue     ldd       #1        flag one for scalar
                    pshs      d         push flag
                    ldd       4,u       scalar value/type
                    pshs      d         push it
                    pshs      u         push node pointer
                    ldd       18,s      depth/param
                    pshs      d         push it
                    bsr       ParseAggregateInit parse scalar init
                    leas      8,s        drop arguments
                    std       -2,s      save result
                    bne       FinishInit non-zero means ok
                    lbsr      SkipToInitDelim flag the error
                    bra       FinishInit finish

InitCleanupViaX     leas      -4,x      restore stack via X
FinishInit          lbsr      EmitEndsect finish the emit
                    clra                clear A
                    clrb                clear B
                    std       GlbPassMode clear init mode flag
InitReturn          leas      4,s        drop locals
                    puls      pc,u      restore U and return

ParseAggregateInit  pshs      u         save U
                    ldd       #$FFA8    frame size request
                    lbsr      stkcheck  check the stack frame
                    ldu       6,s       load node pointer
                    leas      -12,s      allocate locals
                    ldd       22,s      brace-required flag
                    bne       CheckOpenBrace flag set, check brace
                    ldd       #')       expected open brace token
                    pshs      d         push expected token
                    lbsr      ExpectToken report expected-token error
                    leas      2,s        drop argument
                    bra       CheckArrayType continue

CheckOpenBrace      ldd       GlbVar003F current token code
                    cmpd      #')       open brace?
                    bne       NoOpenBrace no brace present
                    ldd       #1        had-brace flag one
                    std       10,s      store had-brace flag
                    lbsr      ParseStatement2 consume the brace
                    bra       CheckArrayType continue

NoOpenBrace         clra                clear A
                    clrb                clear B
                    std       10,s      store had-brace zero
CheckArrayType      ldd       16,s      load type code
                    clra                clear A
                    andb      #$30      isolate class bits
                    cmpd      #32       array class?
                    lbne      InitStructOrScalar not array, try struct
                    ldd       [20,s]    declared array count
                    std       2,s       save it
                    bne       ArrayInitSetup count present
                    ldd       #$FFFF    unspecified size marker
                    std       2,s       save marker
ArrayInitSetup      ldd       16,s      reload type code
                    pshs      d         push it
                    lbsr      TypeRemoveLevel get element type/size
                    leas      2,s        drop argument
                    std       8,s       save element type
                    cmpd      #4        struct element?
                    bne       ArrayElemSubtype not a struct element
                    ldd       10,u      member list pointer
                    bra       ArrayLoopInit use it

ArrayElemSubtype    ldx       20,s      element node pointer
                    ldd       2,x       element subtype
ArrayLoopInit       std       4,s       save subtype
                    clra                clear A
                    clrb                clear B
                    std       6,s       element index zero
                    bra       ArrayLoopCond test loop condition

ArrayElemBody       ldd       22,s      depth counter
                    addd      #1        increment depth
                    pshs      d         push depth
                    ldd       6,s       element type
                    pshs      d         push it
                    pshs      u         push node pointer
                    ldd       14,s      element subtype
                    pshs      d         push it
                    lbsr      ParseAggregateInit recurse element init
                    leas      8,s        drop arguments
                    std       -2,s      save result
                    lbeq      InitFailure failure returns zero
                    ldd       6,s       element index
                    addd      #1        increment index
                    std       6,s       store index
                    cmpd      2,s       compare index to count
                    bcc       ArrayCountDone reached the count limit
                    ldd       GlbVar003F current token code
                    cmpd      #'0       comma?
                    bne       ArrayCountDone no comma, stop
                    lbsr      ParseStatement2 consume the comma
                    bra       ArrayLoopCond continue loop

ArrayLoopCond       ldd       GlbVar003F current token code
                    cmpd      #'*       close brace?
                    bne       ArrayElemBody not close, parse element
ArrayCountDone      ldd       2,s       declared count
                    cmpd      #$FFFF    was size unspecified?
                    bne       PadArrayTail count was specified
                    ldd       6,s       actual element count
                    std       [20,s]    set array size from count
                    bra       FinishAggregate finish aggregate

PadArrayTail        ldd       6,s       actual element count
                    cmpd      2,s       compare to declared
                    bcc       FinishAggregate all elements provided
                    ldx       20,s      element node pointer
                    ldd       2,x       element subtype
                    pshs      d         push it
                    ldd       2,u       node data field
                    pshs      d         push it
                    ldd       12,s      element size
                    pshs      d         push it
                    lbsr      ResolveTypeSize compute total element bytes
                    leas      6,s        drop arguments
                    pshs      d         push result
                    ldd       4,s       reload value
                    subd      8,s       remaining byte count
                    lbsr      MulEntry  scale remaining count
                    pshs      d         push it
                    lbsr      FillInitElements fill remaining elements
                    leas      2,s        drop argument
                    bra       FinishAggregate finish aggregate

AggCleanupViaX      leas      -12,x     restore stack via X
FinishAggregate     ldd       22,s      brace-required flag
                    beq       SkipTrailingComma none, skip brace close
                    ldd       10,s      had-brace flag
                    lbeq      InitSuccess no brace, done
SkipTrailingComma   ldd       GlbVar003F current token code
                    cmpd      #'0       comma?
                    bne       ExpectCloseBrace no trailing comma
                    lbsr      ParseStatement2 consume trailing comma
ExpectCloseBrace    ldd       GlbVar003F current token code
                    cmpd      #'*       close brace?
                    bne       TooManyElemsErr missing close brace
                    lbsr      ParseStatement2 consume the brace
                    lbra      InitSuccess done ok

TooManyElemsErr     leax      MsgTooManyElem,pcr too-many-elements message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop argument
                    lbsr      SkipToInitDelim flag the error
                    lbra      InitSuccess done

InitStructOrScalar  ldd       16,s      load type code
                    cmpd      #4        struct type?
                    lbne      InitScalar no, handle scalar
                    ldd       20,s      member list pointer
                    std       ,s        save it
                    bne       StructLoopCond members present
                    leax      MsgNoUnions,pcr unions-not-allowed message
                    lbra      ReportInitErr report and fail

StructMemberBody    ldx       ,s        member list entry
                    ldu       2,x       member node pointer
                    ldd       22,s      depth counter
                    addd      #1        increment depth
                    pshs      d         push depth
                    ldd       ,u        member type
                    cmpd      #4        struct member?
                    bne       MemberSubtype not a struct member
                    ldd       10,u      member sub-list
                    bra       CallMemberInit use it

MemberSubtype       ldd       4,u       member subtype
CallMemberInit      pshs      d         push it
                    pshs      u         push node pointer
                    ldd       ,u        member type
                    pshs      d         push it
                    lbsr      ParseAggregateInit recurse member init
                    leas      8,s        drop arguments
                    std       -2,s      save result
                    lbeq      InitFailure failure returns zero
                    ldd       [,s]      next member link
                    std       ,s        advance member entry
                    beq       FillMemberCond no more members
                    ldd       GlbVar003F current token code
                    cmpd      #'0       comma?
                    bne       FillMemberCond no comma, stop
                    lbsr      ParseStatement2 consume the comma
                    bra       StructLoopCond check loop condition

StructLoopCond      ldd       GlbVar003F current token code
                    cmpd      #'*       close brace?
                    bne       StructMemberBody not close, next member
                    bra       FillMemberCond stop the loop

FillMemberLoop      ldx       ,s        member list entry
                    ldu       2,x       member node pointer
                    ldd       4,u       member subtype
                    pshs      d         push it
                    ldd       2,u       member offset
                    pshs      d         push it
                    ldd       ,u        member type
                    pshs      d         push it
                    lbsr      ResolveTypeSize compute member size
                    leas      6,s        drop arguments
                    pshs      d         push result
                    bsr       FillInitElements zero-fill this member
                    leas      2,s        drop argument
                    ldd       [,s]      next member link
                    std       ,s        advance member entry
FillMemberCond      ldd       ,s        member entry present?
                    bne       FillMemberLoop more members to fill
                    leax      12,s      compute cleanup pointer
                    lbra      AggCleanupViaX go clean up

InitScalar          ldd       16,s      load type code
                    pshs      d         push it
                    bsr       EmitInitExpr parse scalar init expression
                    std       ,s++      save result and pop
                    beq       ConstExprErr2 zero means const required
                    ldd       10,s      had-brace flag
                    beq       InitSuccess no brace, done ok
                    ldd       #'*       expected close brace token
                    pshs      d         push expected token
                    lbsr      ExpectToken report expected-token error
                    leas      2,s        drop argument
InitSuccess         ldd       #1        return one for success
                    bra       AggInitReturn go to epilogue

ConstExprErr2       leax      MsgConstExprReq,pcr constant-expression message
ReportInitErr       pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop argument
                    lbsr      SkipToInitDelim flag the error
InitFailure         clra                clear A
                    clrb                clear B for failure
AggInitReturn       leas      12,s       drop locals
                    puls      pc,u      restore U and return

FillInitElements    pshs      u         save U
                    ldd       #$FFBA    frame size request
                    lbsr      stkcheck  check stack space
                    leax      MsgRzbDirective,pcr point to rzb directive text
                    pshs      x         push string argument
                    lbsr      EmitSpacedStr output the rzb directive
                    leas      2,s        drop argument
                    ldd       4,s       load reserved byte count
                    pshs      d         push the count
                    lbsr      EmitNumber emit the number
                    leas      2,s        drop argument
                    lbsr      EmitNewline emit end of line
                    puls      pc,u      restore and return

EmitInitExpr        pshs      u         save the caller u register
                    ldd       #$FFAE    stack frame size
                    lbsr      stkcheck  check stack space
                    leas      -8,s       reserve locals
                    ldd       #2        constant two
                    pshs      d         push argument
                    lbsr      ParseBinaryExpr get subexpression context
                    std       ,s        save result
                    lbsr      CopyExprTree parse initializer expression
                    leas      2,s        drop argument
                    tfr       d,u       U = expression node
                    stu       -2,s      save node pointer
                    bne       InitExprGotNode got a node, continue
                    clra                result high byte zero
                    clrb                result low byte zero
                    lbra      InitExprRet return null result

InitExprGotNode     clra                zero high byte
                    clrb                zero low byte
                    std       4,s       clear offset local
                    ldd       #1        constant one
                    std       2,s       set flag local
                    ldd       ,u        load node kind
                    std       ,s        save node kind
                    ldd       12,s      load target type
                    clra                high byte zero
                    andb      #$30      mask storage-class bits
                    cmpd      #16       is it an aggregate
                    bne       NotArrayType no, other handling
                    ldx       ,s        X = node kind
                    bra       DispatchNodeKind dispatch on kind

KindSize1           ldd       #1        size one byte
                    bra       CoerceNode go coerce node

CheckAggClass       ldd       ,s        reload node kind
                    clra                high byte zero
                    andb      #$30      mask class bits
                    cmpd      #16       is it aggregate class
                    beq       CheckAddrNode yes, emit directly
                    bra       EmitPadded else adjust stack

DispatchNodeKind    cmpx      #8        node kind eight
                    beq       KindSize1 handle as size one
                    cmpx      #1        node kind one
                    beq       CheckAddrNode emit directly
                    cmpx      #7        node kind seven
                    beq       CheckAddrNode emit directly
                    bra       CheckAggClass else check class

NotArrayType        ldd       ,s        node kind
                    clra                high byte zero
                    andb      #$30      mask class bits
                    cmpd      #16       aggregate class
                    bne       CoerceType no, needs conversion
                    ldd       12,s      target type
                    pshs      d         push it
                    lbsr      IsIntegralType types compatible
                    std       ,s++      save result and drop
                    bne       CheckAddrNode compatible, emit
EmitPadded          leax      8,s       adjust stack pointer
                    bra       EmitPaddedFix go emit padded

CoerceType          ldd       12,s      target type
                    cmpd      #5        is it float
                    bne       UseTargetType no
                    ldd       #6        use double type
                    bra       CoerceNode coerce node

UseTargetType       ldd       12,s      target type
CoerceNode          pshs      d         push type
                    pshs      u         push node
                    lbsr      CoerceExpr coerce node to type
                    leas      4,s        drop arguments
CheckAddrNode       ldd       6,u       node operator
                    cmpd      #80       address-of node
                    beq       AddrNode  yes
                    ldd       6,u       node operator
                    cmpd      #81       negated-address node
                    bne       CheckStringNode neither, other emit
AddrNode            ldd       12,u      child node pointer
                    std       6,s       save child pointer
                    tfr       d,x       X = child node
                    ldd       6,x       child operator
                    cmpd      #54       is it a symbol ref
                    beq       SymbolAddrNode yes
                    bra       EmitZeroWord else emit zero

EmitPaddedFix       leas      -8,x      stack fixup entry
EmitZeroWord        clra                zero high byte
                    clrb                zero low byte
                    std       2,s       clear flag
                    leax      8,s       restore locals pointer
                    lbra      EmitTailFix emit and return

SymbolAddrNode      ldd       6,u       node operator
                    cmpd      #81       negated-address node
                    bne       PosAddrOffset no
                    ldx       6,s       child node
                    ldd       8,x       its offset value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #0        finish negation
                    bra       StoreOffset store the offset

PosAddrOffset       ldx       6,s
                    ldd       8,x       its offset value
StoreOffset         std       4,s       save offset
                    ldd       6,s       child node pointer
                    pshs      d         push it
                    lbsr      FreeExprTree release the node
                    leas      2,s        drop argument
                    stu       6,s       save current node
                    ldu       10,u      follow to symbol node
                    ldd       6,s       restore node pointer
                    pshs      d         push it
                    lbsr      LinkFreeNode release the node
                    leas      2,s        drop argument
CheckStringNode     ldd       6,u       node operator
                    cmpd      #65       string or name node
                    lbne      CheckLeafOp no, other kinds
                    ldd       10,u      child pointer
                    std       6,s       save it
                    tfr       d,x       X = child node
                    ldx       8,x       follow link
                    ldx       8,x       follow link again
                    bra       DispatchRefKind dispatch on kind

EmitZeroFlag        clra                zero high byte
                    clrb                zero low byte
                    std       2,s       clear flag
                    lbra      EmitTail  emit and return

EmitRefExpr         lbsr      EmitFdb   prepare data emission
                    ldd       #1        flag one
                    std       GlbVar005A set reloc flag
                    ldd       4,s       offset value
                    pshs      d         push it
                    ldd       8,s       node value
                    pshs      d         push it
                    ldd       #119      reference selector
                    pshs      d         push it
                    lbsr      EmitOperand2 emit reference expression
                    leas      6,s        drop arguments
                    clra                zero high byte
                    clrb                zero low byte
                    std       GlbVar005A clear reloc flag
                    lbsr      EmitNewline emit end of line
                    lbra      EmitTail  return

DispatchRefKind     cmpx      #15       kind fifteen
                    beq       EmitRefExpr emit reference
                    cmpx      #14       kind fourteen
                    lbeq      EmitRefExpr emit reference
                    cmpx      #12       kind twelve
                    lbeq      EmitRefExpr emit reference
                    cmpx      #33       kind thirty-three
                    lbeq      EmitRefExpr emit reference
                    cmpx      #34       kind thirty-four
                    lbeq      EmitRefExpr emit reference
                    bra       EmitZeroFlag else emit zero

CheckLeafOp         ldx       6,u       node operator
                    bra       DispatchLeafOp dispatch on operator

FloatConst          ldd       12,s      target type
                    cmpd      #5        is it float
                    bne       EmitScalar no
                    ldx       8,u       node value pointer
                    pshs      x         push it
                    ldx       8,u       node value pointer
                    lbsr      BuildWordType convert to float
                    lbsr      CopyInt32 push float value
EmitScalar          ldd       12,s      target type
                    pshs      d         push it
                    ldd       8,u       node value
                    pshs      d         push it
                    bsr       EmitScalarByType emit scalar by type
                    leas      4,s        drop arguments
                    bra       EmitTail  return

EmitCharVal         lbsr      EmitFdb   prepare data emission
                    ldd       8,u       node value
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit the value
                    leas      2,s        drop argument
                    bra       EmitTail  return

DispatchLeafOp      cmpx      #75       operator four-B
                    beq       FloatConst float constant handling
                    cmpx      #54       symbol ref operator
                    beq       EmitScalar emit scalar
                    cmpx      #74       operator four-A
                    lbeq      EmitScalar emit scalar
                    cmpx      #55       operator three-seven
                    beq       EmitCharVal emit value
                    lbra      EmitZeroFlag else emit zero

EmitTailFix         leas      -8,x      stack fixup entry
EmitTail            pshs      u         push node
                    lbsr      FreeExprTree free the node
                    leas      2,s        drop argument
                    ldd       2,s       load result flag
InitExprRet         leas      8,s        release locals
                    puls      pc,u      restore and return

EmitScalarByType    pshs      u         save the caller u register
                    ldd       #$FFB6    stack frame size
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U = node argument
                    leas      -2,s       reserve local
                    ldx       8,s       X = type argument
                    bra       DispatchTypeSize dispatch on type

EmitTypeTwo         lbsr      EmitFcb   prepare data emission
                    pshs      u         push node
                    lbsr      EmitNumber emit number
                    leas      2,s        drop argument
                    lbsr      EmitNewline emit end of line
                    bra       ScalarByTypeRet return

SetSize1            ldd       #1        size one byte
                    bra       StoreSize store size

SetSize2            ldd       #2        size two bytes
                    bra       StoreSize store size

SetSize4            ldd       #4        size four bytes
StoreSize           std       ,s        save the size
                    bra       EmitSizedVal emit value

DispatchTypeSize    cmpx      #2        type two
                    beq       EmitTypeTwo special emission
                    cmpx      #1        type one char
                    beq       SetSize1  size one
                    cmpx      #7        type seven
                    lbeq      SetSize1  size one
                    cmpx      #8        type eight
                    beq       SetSize2  size two
                    cmpx      #5        type five
                    lbeq      SetSize2  size two
                    cmpx      #6        type six
                    beq       SetSize4  size four
                    lbra      SetSize1  default size one

EmitSizedVal        ldd       ,s        load size
                    pshs      d         push size
                    pshs      u         push node
                    lbsr      EmitInlineArgs emit value of size
                    leas      4,s        drop arguments
ScalarByTypeRet     leas      2,s        release local
                    puls      pc,u      restore and return

ReportCannotInit    pshs      u         save the caller u register
                    ldd       #$FFBA    stack frame size
                    lbsr      stkcheck  check stack space
                    leax      MsgCannotInit,pcr cannot-initialize message
                    pshs      x         push the message
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop argument
                    bsr       SkipToInitDelim skip to delimiter
                    puls      pc,u      restore and return

SkipToInitDelim     pshs      u         save the caller u register
                    ldd       #$FFBC    stack frame size
                    lbsr      stkcheck  check stack space
SkipTokLoop2        ldx       GlbVar003F current token
                    bra       TestSkipTok test the token

SkipDone2           puls      pc,u      get next token

SkipNextTok         lbsr      ParseStatement2 loop
                    bra       SkipTokLoop2

TestSkipTok         cmpx      #'0       is it a semicolon
                    beq       SkipDone2 stop
                    cmpx      #'(       is it a close brace
                    lbeq      SkipDone2 stop
                    cmpx      #$FFFF    end of input
                    lbeq      SkipDone2 stop
                    bra       SkipNextTok else skip token

                    puls      pc,u      return (unreachable)

MsgTooLong          fcc       /too long/
                    fcb       C$NULL
MsgTooManyElem      fcc       /too many elements/
                    fcb       C$NULL
MsgNoUnions         fcc       /unions not allowed/
                    fcb       C$NULL
MsgConstExprReq     fcc       /constant expression required/
                    fcb       C$NULL
MsgRzbDirective     fcc       /rzb /
                    fcb       C$NULL
MsgCannotInit       fcc       /cannot initialize/
                    fcb       C$NULL
ResetInputBuf       pshs      u         save the caller u register
                    leax      LineBuffer,y   line buffer address
                    stx       F004aYFirst set input pointer
                    clra                zero high byte
                    clrb                zero low byte
                    stb       LineBuffer,y   clear the buffer
                    ldd       #'        space character
                    bra       StoreCurChar store as current char

SkipSpaces          pshs      u         save the caller u register
                    bra       SkipSpaceLoop enter skip loop

SkipSpaceNext       bsr       NextChar  fetch next char
SkipSpaceLoop       ldb       GlbVar0045 current char
                    cmpb      #'        is it a space
                    beq       SkipSpaceNext skip it
                    ldb       GlbVar0045 current char
                    cmpb      #9        is it a tab
                    lbeq      SkipSpaceNext skip it
                    puls      pc,u      return

NextChar            pshs      u         save the caller u register
                    ldx       F004aYFirst input pointer
                    leax      1,x       advance pointer
                    stx       F004aYFirst save pointer
                    ldb       -1,x      get the char
                    stb       GlbVar0045 store current char
                    bne       NextCharRet non-null, done
                    bsr       RefillLine refill line buffer
StoreCurChar        stb       GlbVar0045 store current char
NextCharRet         puls      pc,u      return

RefillLine          pshs      u         save the caller u register
                    leas      -8,s       reserve locals
                    ldd       GlbFirstCall first-call flag
                    bne       ReadDirectiveLine already primed
                    ldd       #1        flag one
                    std       GlbFirstCall mark as primed
                    leax      EmptyLine,pcr initial newline string
                    stx       F004aYFirst point input at it
                    lbra      RetSpace  return

ReadDirectiveLine   clra                zero high byte
                    clrb                zero low byte
                    std       GlbFirstCall clear the flag
                    leax      LineBuffer,y   line buffer
                    pshs      x         push destination
                    leax      SecondSourceBuffer,y   source buffer
                    pshs      x         push source
                    lbsr      StrCpy    read the next line
                    leas      4,s        drop arguments
DirectiveLoop       lbsr      ReadLine  get next word
                    std       F004aYFirst save word pointer
                    lbeq      DirectiveEof none, return end of input
                    ldb       [>F004aYFirst,y] first char of word
                    cmpb      #'#      is it a hash
                    lbne      CountLine not a directive
                    ldx       F004aYFirst word pointer
                    ldb       1,x       second char
                    sex                 sign-extend to D
                    std       4,s       save directive char
                    lbsr      ReadLine  get next word
                    std       -2,s      save pointer
                    lbeq      DirectiveEof none, return end of input
                    ldx       4,s       restore directive char
                    lbra      DirectiveDispatch dispatch on directive

SetLineNumber       leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    leas      2,s        drop argument
                    std       GlbVar0007 set current line number
                    bra       DirectiveLoop continue loop

EmitDefaultLine     lbsr      EmitCommentStar prepare default line
FormatLineDir       leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    leax      FmtLineOut,pcr default format string
                    bra       WriteFormatTail print it

MatchKeyword        leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    leax      XNameBuffer,y   compare buffer
                    pshs      x         push it
                    lbsr      StrCpy    compare or copy
                    leas      4,s        drop arguments
                    lbsr      ReadLine  get next word
                    std       -2,s      save pointer
                    lbne      DirectiveLoop got one, continue loop
                    lbra      DirectiveEof else return end of input

HandleLineFile      leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    leax      OutputBuffer,y   output buffer
                    pshs      x         push it
                    lbsr      StrCpy    copy line to output buffer
                    leas      4,s        drop arguments
                    lbsr      ReadLine  get next word
                    std       -2,s      save pointer
                    lbeq      DirectiveEof none, return end of input
                    leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    std       ,s        save value
                    leax      OutputBuffer,y   output buffer
                    pshs      x         push it
                    leax      FmtPsect,pcr format string
                    pshs      x         push it
                    ldd       GlbVar0005 output file handle
                    pshs      d         push it
                    lbsr      fprintf   write formatted line
                    leas      8,s        drop arguments
                    leax      OutputBuffer,y   output buffer
                    pshs      x         push it
                    leax      FmtNam,pcr format string
WriteFormatTail     pshs      x         push format string
                    ldd       GlbVar0005 output file handle
                    pshs      d         push it
                    lbsr      fprintf   write formatted line
                    leas      6,s        drop arguments
                    lbra      DirectiveLoop continue loop

HandleLineRange     leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    leax      OutputBuffer,y   output buffer
                    pshs      x         push it
                    lbsr      StrCpy    copy line to output buffer
                    leas      4,s        drop arguments
                    lbsr      ReadLine  get next word
                    std       -2,s      save pointer
                    beq       DirectiveEof none, return end of input
                    leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    leas      2,s        drop argument
                    std       6,s       save first value
                    lbsr      ReadLine  get next word
                    std       -2,s      save pointer
                    beq       DirectiveEof none, return end of input
                    leax      LineBuffer,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    leas      2,s        drop argument
                    std       2,s       save second value
                    lbsr      ReadLine  get next word
                    std       -2,s      save pointer
                    bne       DirectiveHaveVal got token, continue
DirectiveEof        ldd       #$FFFF    end-of-input result
                    lbra      DirExit   return it

DirectiveHaveVal    ldd       6,s       first value
                    beq       ErrPrintArg zero, skip
                    ldd       6,s       first value
                    pshs      d         push it
                    leax      XNameBuffer,y   scratch buffer
                    pshs      x         push it
                    leax      FmtFileLine,pcr format string
                    pshs      x         push it
                    lbsr      PrintfToBuf format into buffer
                    leas      6,s        drop arguments
                    bra       ErrPrintLine continue

ErrPrintArg         leax      StrArgPrefix,pcr point X at 'argument : ' string
                    pshs      x         push the format-string argument
                    lbsr      PrintfToBuf fprintf the argument label
                    leas      2,s        drop the pushed argument
ErrPrintLine        leax      LineBuffer,y   point X at the input line buffer
                    pshs      x         push the line as the %s argument
                    leax      FmtErrLine,pcr point X at the '**** %s ****' format
                    pshs      x         push the format string
                    lbsr      PrintfToBuf fprintf the offending line
                    leas      4,s        drop the two arguments
                    ldb       OutputBuffer,y   get the extra-text pointer or flag
                    beq       ErrCheckFatal none present, skip to exit check
                    leax      OutputBuffer,y   point X at the extra message
                    pshs      x         push it as the %s argument
                    lbsr      EmitStringLine print the extra string
                    leas      2,s        drop the argument
                    bra       ErrPadTest enter the caret padding loop

ErrPadLoop          leax      XStderrStruct,y   point X at the output file handle
                    pshs      x         push the stream argument
                    ldd       #'        space character to emit
                    pshs      d         push the space character
                    lbsr      PutByte   fputc a padding space
                    leas      4,s        drop the two arguments
ErrPadTest          ldd       2,s       load the remaining pad count
                    addd      #$FFFF    decrement the count by one
                    std       2,s       store the updated count
                    subd      #$FFFF    test whether it was nonzero
                    bne       ErrPadLoop more spaces still to emit
                    leax      StrCaret,pcr point X at the '^' caret string
                    pshs      x         push the caret argument
                    lbsr      EmitStringLine print the caret under the column
                    leas      2,s        drop the argument
ErrCheckFatal       ldd       4,s       load the error severity code
                    cmpd      #49       is it a fatal error
                    lbne      DirectiveLoop not fatal, resume reading lines
                    ldd       #1        exit status one
                    pshs      d         push the exit code
                    lbsr      exit      terminate the compiler
                    leas      2,s        drop the exit code (unreached)
                    lbra      DirectiveLoop resume reading lines

DirectiveDispatch   cmpx      #53       directive code '5' line number
                    lbeq      SetLineNumber handle the line-number directive
                    cmpx      #54       directive code '6'
                    lbeq      EmitDefaultLine handle it
                    cmpx      #50       directive code '2'
                    lbeq      FormatLineDir handle it
                    cmpx      #55       directive code '7' filename
                    lbeq      MatchKeyword handle the filename directive
                    cmpx      #80       directive code 'P' psect
                    lbeq      HandleLineFile handle the psect directive
                    cmpx      #48       directive code '0'
                    lbeq      HandleLineRange handle the line/column directive
                    cmpx      #49       directive code '1'
                    lbeq      HandleLineRange handle the line/column directive
                    lbra      DirectiveLoop unknown code, read next line

CountLine           ldd       GlbVar0007 load the current line counter
                    addd      #1        bump the line count
                    std       GlbVar0007 store it back
RetSpace            ldd       #'        return the space status value
DirExit             leas      8,s        discard the local frame
                    puls      pc,u      restore U and return

ParseDecimal        pshs      u         save the U register
                    ldu       4,s       U points at the digit string
                    leas      -4,s       reserve scratch locals
                    clra                clear accumulator high byte
                    clrb                clear accumulator low byte
                    bra       ParseDecimalBody begin the digit scan

ParseDecimalLoop    ldd       ,s        load the running value
                    pshs      d         save it for the multiply
                    ldd       #10       multiplier ten
                    lbsr      MulEntry  multiply the value by ten
                    pshs      d         save the product
                    ldd       4,s       load the current digit character
                    addd      #$FFD0    subtract ASCII '0'
                    addd      ,s++      add to value times ten
ParseDecimalBody    std       ,s        store the updated accumulator
                    ldb       ,u+       fetch the next character
                    sex                 sign-extend it into D
                    std       2,s       save the character
                    leax      CtypeTab,y point X at the char-class table
                    leax      d,x       index by the character
                    ldb       ,x        load its class byte
                    cmpb      #107      is it a digit class
                    beq       ParseDecimalLoop yes, accumulate another digit
                    ldd       ,s        load the final value
                    leas      4,s        release the scratch locals
                    puls      pc,u      restore U and return

ReadLine            pshs      u,d       save U and reserve a slot
                    leau      LineBuffer,y   U points at the line buffer
                    ldd       GlbVar0003 load the input stream handle
                    pshs      d         push the stream argument
                    lbsr      GetByte   getc the first character
                    leas      2,s        drop the argument
                    std       ,s        save the character
                    cmpd      #$FFFF    was it end of file
                    lbne      ReadLineCheckFull no, store it in the buffer
                    ldx       GlbVar0003 load the stream pointer
                    ldd       6,x       load its status flags
                    clra                clear the high byte
                    andb      #$20      test the temp-file bit
                    beq       ReadLineEofRet clean EOF, return empty
                    leax      XStderrStream,y   point X at the filename argument
                    pshs      x         push it as the %s argument
                    leax      MsgTempFileErr,pcr point at the temp-file error message
                    pshs      x         push the format string
                    lbsr      CopyStringToBuf print the error to stderr
                    leas      4,s        drop the arguments
                    ldd       #1        exit status one
                    pshs      d         push the exit code
                    lbsr      exit      abort the compiler
                    leas      2,s        drop the exit code (unreached)
ReadLineEofRet      clra                clear the return high byte
                    clrb                return zero for EOF
                    bra       ReadLineExit exit the reader

ReadLineNext        ldx       ,s        reload the current character
                    bra       ReadLineTest test for a line terminator

ReadLineDone        clra                clear the terminator high byte
                    clrb                zero to null-terminate
                    stb       ,u        write the string terminator
                    leax      LineBuffer,y   point X at the buffer start
                    tfr       x,d       return the buffer pointer in D
                    bra       ReadLineExit exit the reader

ReadLineStore       ldd       ,s        load the current character
                    stb       ,u+       store it and advance
                    ldd       GlbVar0003 load the input stream handle
                    pshs      d         push the stream argument
                    lbsr      GetByte   getc the next character
                    leas      2,s        drop the argument
                    std       ,s        save the character
                    bra       ReadLineCheckFull check the buffer capacity

ReadLineTest        cmpx      #13       is the character a carriage return
                    beq       ReadLineDone yes, terminate the line
                    cmpx      #$FFFF    is it end of file
                    lbeq      ReadLineDone yes, terminate the line
                    bra       ReadLineStore otherwise store the character

ReadLineCheckFull   cmpu      BufferLimit,y   reached the buffer limit
                    bne       ReadLineNext room left, continue reading
                    ldd       GlbVar0007 load the line counter
                    addd      #1        bump it
                    std       GlbVar0007 store it back
                    std       GlbSrcLine record the current line number
                    leax      LineBuffer,y   point X at the line buffer
                    stx       GlbVar0043 save the buffer pointer for the error
                    leax      >MsgLineTooLong,pcr point at 'input line too long'
                    pshs      x         push the message argument
                    lbsr      PrintMsg  report the warning
                    leas      2,s        drop the argument
ReadLineExit        leas      2,s        discard the saved slot
                    puls      pc,u      restore U and return

EmptyLine           fcb       C$NULL
FmtLineOut          fcc       /%s/
                    fcb       C$CR,C$NULL
FmtPsect            fcc       / psect %s,0,0,%d,0,0/
                    fcb       C$CR,C$NULL
FmtNam              fcc       / nam %s/
                    fcb       C$CR,C$NULL
FmtFileLine         fcc       /%s : line %d /
                    fcb       C$NULL
StrArgPrefix        fcc       /argument : /
                    fcb       C$NULL
FmtErrLine          fcc       /**** %s ****/
                    fcb       C$CR,C$NULL
StrCaret            fcb       $5E
                    fcb       C$NULL
MsgTempFileErr      fcc       /INPUT FILE ERROR : TEMPORARY FILE/
                    fcb       C$CR,C$NULL
MsgLineTooLong      fcc       /input line too long/
                    fcb       C$NULL
GenNode             pshs      u         save the U register
                    ldu       10,s      U points at the node
                    leas      -8,s       reserve the local frame
                    ldd       12,s      load the node opcode
                    cmpd      #136      is it opcode $88
                    bne       GenNodeOp87 no, try the next case
                    ldd       16,s      load the right operand
                    pshs      d         push it
                    ldd       16,s      load the left operand
                    pshs      d         push it
                    lbsr      GenLongOp generate the $88 operation
                    lbra      GenDone4  finish the node

GenNodeOp87         ldd       12,s      reload the node opcode
                    cmpd      #135      is it opcode $87
                    bne       GenNodeDispatch no, use the jump table
                    ldd       16,s      load the right operand
                    pshs      d         push it
                    ldd       16,s      load the left operand
                    pshs      d         push it
                    lbsr      GenFloatOp generate the $87 operation
                    lbra      GenDone4  finish the node

GenNodeDispatch     ldx       12,s      node opcode into X
                    lbra      DispatchOperator dispatch on the opcode

GenPushReg          ldd       14,s      load the register-code operand
                    pshs      d         push it
                    lbsr      TypeRegChar map to a register name char
                    std       ,s        save the character
                    leax      StrPshsFmt,pcr point at the ' pshs %c' format
                    pshs      x         push the format string
                    ldd       GlbVar0005 load the output stream handle
                    pshs      d         push the stream argument
                    lbsr      fprintf   emit the pshs instruction
                    leas      6,s        drop the arguments
                    ldd       GlbVar000F load the current stack offset
                    subd      #2        account for the pushed word
                    std       GlbVar000F store the new offset
                    cmpd      GlbVar001B compare against the low-water mark
                    lbge      Pop8Ret   not deeper, node done
                    ldd       GlbVar000F load the new offset
                    std       GlbVar001B record deeper stack use
                    lbra      Pop8Ret   node done

GenCondBranch       ldd       16,s      load the node operand
                    pshs      d         push it as an argument
                    ldd       #54       node code $36
                    pshs      d         push it
                    ldd       #113      node code $71
                    pshs      d         push it
                    ldd       #129      node code $81
                    pshs      d         push it
                    lbsr      GenNode   recursively generate the subtree
                    leas      8,s        drop the arguments
                    ldd       14,s      load the condition operand
                    std       16,s      store it as the branch target
                    ldd       #90       node code $5A
                    std       14,s      set it as the operand
GenLongBranch       leax      StrLb,pcr point at the 'lb' branch prefix
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit the 'lb' prefix
                    leas      2,s        drop the argument
                    ldd       14,s      load the condition code
                    pshs      d         push it
                    lbsr      GetLongMnemonic map to the branch mnemonic
                    std       ,s        save it
                    lbra      GenOperandTail emit the operand and finish

GenReturn           ldd       GlbVar0017 any pending cleanup
                    beq       GenReturnEmit none, skip it
                    lbsr      EmitFuncEpilogue emit the function-exit cleanup
GenReturnEmit       leax      StrPulsUpc,pcr point at 'puls u,pc'
                    lbra      EmitMnemDone emit and finish the node

GenCompare          pshs      u         save the node pointer
                    ldd       18,s      load the right operand
                    pshs      d         push it
                    ldd       16,s      load the left operand
                    pshs      d         push it
                    lbsr      EmitLogicalOperand generate the comparison
                    leas      6,s        drop the arguments
                    lbra      Pop8Ret   node done

GenMult             leax      StrCcmult,pcr point at the 'ccmult' helper name
                    bra       GenRuntimeCall emit the runtime call

GenUDiv             leax      StrCcudiv,pcr point at the 'ccudiv' helper name
                    bra       GenRuntimeCall emit the runtime call

GenDiv              leax      StrCcdiv,pcr point at the 'ccdiv' helper name
                    bra       GenRuntimeCall emit the runtime call

GenShiftLeft        leax      StrCcasl,pcr point at the 'ccasl' helper name
                    bra       GenRuntimeCall emit the runtime call

GenShiftRight       leax      StrCcasr,pcr point at the 'ccasr' helper name
                    bra       GenRuntimeCall emit the runtime call

GenLShiftRight      leax      StrCclsr,pcr point at the 'cclsr' helper name
                    bra       GenRuntimeCall emit the runtime call

GenUMod             leax      StrCcumod,pcr point at the 'ccumod' helper name
                    bra       GenRuntimeCall emit the runtime call

GenMod              leax      StrCcmod,pcr point at the 'ccmod' helper name
GenRuntimeCall      pshs      x         push the helper name
                    lbsr      EmitInstrPush2 emit the jsr to the helper
                    lbra      EmitOpDone finish the node

GenNegate           leax      StrNegate,pcr point at the 'nega' mnemonic
                    lbra      EmitMnemDone emit and finish

GenComplement       leax      StrComplement,pcr point at the 'coma' mnemonic
                    lbra      EmitMnemDone emit and finish

GenLeaLocal         leax      StrLeax,pcr point at the 'leax ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'leax '
                    leas      2,s        drop the argument
                    ldd       GlbVar000F load the stack offset
                    nega                negate the high byte
                    negb                negate the low byte
                    sbca      #0        finish the two's complement
                    pshs      d         push the negated offset
                    lbsr      EmitNumber emit the offset number
                    leas      2,s        drop the argument
                    ldd       StackPointerRegister,y   load the stack-pointer register name
                    pshs      d         push it
                    lbsr      EmitStr   emit the ',s' operand
                    leas      2,s        drop the argument
                    lbsr      EmitNewline emit the newline
GenBaseRef          ldd       BaseRegisterName,y   load the base register name
                    pshs      d         push it
                    lbsr      EmitSpacedStr emit the register reference
                    leas      2,s        drop the argument
                    ldd       14,s      load the operand value
                    bra       GenValueTail emit the operand and finish

GenTempSlot         ldd       BaseRegisterName,y   load the base register name
                    pshs      d         push it
                    lbsr      EmitSpacedStr emit the register reference
                    leas      2,s        drop the argument
                    ldd       GlbVar000B load the temp-label counter
                    addd      #1        allocate a new label number
                    std       GlbVar000B store the updated counter
                    std       16,s      save the label number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit the temp label
                    leas      2,s        drop the argument
                    ldd       14,s      load the operand value
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit it
                    leas      2,s        drop the argument
                    leax      StrLeas,pcr point at the 'leas ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'leas '
                    leas      2,s        drop the argument
                    ldd       GlbVar000F load the stack offset
                    pshs      d         push it
                    lbsr      EmitNumber emit the offset number
                    leas      2,s        drop the argument
                    leax      StrCommaX,pcr point at the ',x' operand
                    pshs      x         push the operand argument
GenOperandTail      lbsr      EmitStr   emit the operand string
                    leas      2,s        drop the argument
                    ldd       16,s      load the value to emit
GenValueTail        pshs      d         push it
                    lbsr      EmitLocalLabel emit it
                    lbra      EmitOpDone finish the node

GenFuncCall         ldd       #4        operand size four
                    std       GlbVar0013 record it
                    ldx       16,s      load the node pointer
                    ldd       6,x       load its subtype
                    cmpd      #52       is it an array reference
                    bne       GenCallIndirect no, emit an indirect call
                    ldx       16,s      reload the node pointer
                    ldd       8,x       load the array element operand
                    std       4,s       save it
                    beq       GenCallIndirect zero element, indirect call
                    ldd       PendingMnemonicString,y   load the base register name
                    pshs      d         push it
                    lbsr      EmitSpacedStr emit the register reference
                    leas      2,s        drop the argument
                    clra                clear the high byte
                    clrb                zero addend
                    pshs      d         push it
                    ldd       6,s       load the saved element operand
                    addd      #20       offset to the element field
                    pshs      d         push the address
                    lbsr      EmitLabelDef emit the array element load
                    lbra      GenDone4  finish the node

GenCallIndirect     leax      StrJsr,pcr point at the 'jsr ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'jsr '
                    leas      2,s        drop the argument
                    clra                clear the high byte
                    clrb                zero flag
                    pshs      d         push it
                    ldd       18,s      load the call target operand
                    pshs      d         push it
                    ldd       18,s      load it again
                    pshs      d         push it
                    lbsr      EmitOperand2 emit the call target
                    leas      6,s        drop the arguments
                    lbra      GenEmitDone emit newline and finish

GenSignExtend       leax      StrSex,pcr point at the 'sex' mnemonic
                    bra       EmitMnemDone emit and finish

GenLoadWord         leax      StrLd,pcr point at the 'ld' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'ld'
                    leas      2,s        drop the argument
                    ldd       #2        operand size two
                    pshs      d         push it
                    ldd       18,s      load the operand node
                    pshs      d         push it
                    ldd       18,s      load it again
                    pshs      d         push it
                    ldd       #100      load flag $64
                    pshs      d         push it
                    lbsr      EmitInstrLine emit the load operand
                    lbra      GenDone8  finish the node

GenAslb             leax      StrAslbRola,pcr point at the 'aslb' mnemonic
                    bra       EmitMnemDone emit and finish

GenAsra             leax      StrAsraRorb,pcr point at the 'asra' mnemonic
                    bra       EmitMnemDone emit and finish

GenLsra             leax      StrLsraRorb,pcr point at the 'lsra' mnemonic
EmitMnemDone        pshs      x         push the mnemonic argument
                    lbra      EmitOpLine emit the bare mnemonic and finish

GenLoadY            leax      StrLdy,pcr point at the 'ldy ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'ldy '
                    leas      2,s        drop the argument
                    leax      8,s       point at the operand frame slot
                    bra       GenLoadRegAdj adjust the frame and emit the operand

GenLoadU            leax      StrLdu,pcr point at the 'ldu ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'ldu '
                    leas      2,s        drop the argument
                    bra       GenLoadRegBody emit the operand

GenLoadRegAdj       leas      -8,x      back up to the operand slot
GenLoadRegBody      ldd       14,s      load the operand value
                    pshs      d         push it
                    lbsr      EmitNumber emit the operand number
                    leas      2,s        drop the argument
                    ldd       StackPointerRegister,y   load the stack register name
                    pshs      d         push it
                    lbsr      EmitStr   emit the ',s' operand
                    leas      2,s        drop the argument
GenEmitDone         lbsr      EmitNewline emit the newline
                    lbra      Pop8Ret   finish the node

GenLeaIndexed       leax      StrLeax2,pcr point at the 'leax ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'leax '
                    leas      2,s        drop the argument
                    ldx       14,s      load the addressing-mode code
                    bra       DispatchIndexMode dispatch on it

GenIndexBase        ldx       16,s      load the node pointer
                    ldd       6,x       load its subtype
                    std       6,s       save it
                    cmpd      #148      is it subtype $94
                    bne       GenIndexBaseAlt no, check the next
                    ldd       #121      emit code $79
                    bra       EmitIndexOperand format the operand

GenIndexBaseAlt     ldd       6,s       reload the subtype
                    cmpd      #149      is it subtype $95
                    bne       RegLetterX no, use the default
                    ldd       #117      emit code $75
                    bra       EmitIndexOperand format the operand

RegLetterX          ldd       #'x       default index register letter x
EmitIndexOperand    std       6,s       save register letter local
                    pshs      d         push register letter as arg
                    ldx       18,s      X = node pointer
                    ldd       8,x       D = node offset field
                    pshs      d         push offset value
                    leax      StrOffRegFmt,pcr X = %d,%c format string
                    pshs      x         push format string
                    ldd       GlbVar0005 D = output file pointer
                    pshs      d         push file pointer
                    lbsr      fprintf   emit offset,reg operand
                    lbra      GenDone8  clean up and finish

EmitAccIndex        ldd       16,s      D = operand type
                    pshs      d         push type
                    lbsr      TypeRegChar map type to register letter
                    std       ,s        store letter over arg
                    leax      StrDRegFmt,pcr X = d,%c format string
                    lbra      EmitFmtDone emit operand and finish

DispatchIndexMode   cmpx      #119      index mode with variable
                    beq       GenIndexBase handle register-indirect
                    cmpx      #112      accumulator index mode
                    beq       EmitAccIndex handle d,reg operand
                    lbra      Pop8Ret   otherwise just finish

DispatchOperator    cmpx      #122      opcode 0x7A
                    lbeq      GenPushReg dispatch to handler
                    cmpx      #125      opcode 0x7D
                    lbeq      GenCondBranch dispatch to handler
                    cmpx      #130      opcode 0x82
                    lbeq      GenLongBranch dispatch to handler
                    cmpx      #18       opcode 0x12
                    lbeq      GenReturn dispatch to handler
                    cmpx      #87       opcode 0x57
                    lbeq      GenCompare dispatch to handler
                    cmpx      #88       opcode 0x58
                    lbeq      GenCompare same handler
                    cmpx      #89       opcode 0x59
                    lbeq      GenCompare same handler
                    cmpx      #82       opcode 0x52
                    lbeq      GenMult   dispatch to handler
                    cmpx      #78       opcode 0x4E
                    lbeq      GenUDiv   dispatch to handler
                    cmpx      #83       opcode 0x53
                    lbeq      GenDiv    dispatch to handler
                    cmpx      #86       opcode 0x56
                    lbeq      GenShiftLeft dispatch to handler
                    cmpx      #85       opcode 0x55
                    lbeq      GenShiftRight dispatch to handler
                    cmpx      #77       opcode 0x4D
                    lbeq      GenLShiftRight dispatch to handler
                    cmpx      #76       opcode 0x4C
                    lbeq      GenUMod   dispatch to handler
                    cmpx      #84       opcode 0x54
                    lbeq      GenMod    dispatch to handler
                    cmpx      #67       opcode 0x43
                    lbeq      GenNegate dispatch to handler
                    cmpx      #68       opcode 0x44
                    lbeq      GenComplement dispatch to handler
                    cmpx      #29       opcode == _start value
                    lbeq      GenLeaLocal dispatch to handler
                    cmpx      #124      opcode 0x7C
                    lbeq      GenBaseRef dispatch to handler
                    cmpx      #9        opcode 0x09
                    lbeq      GenTempSlot dispatch to handler
                    cmpx      #101      opcode 0x65
                    lbeq      GenFuncCall dispatch to handler
                    cmpx      #133      opcode 0x85
                    lbeq      GenSignExtend dispatch to handler
                    cmpx      #132      opcode 0x84
                    lbeq      GenLoadWord dispatch to handler
                    cmpx      #152      opcode 0x98
                    lbeq      GenAslb   dispatch to handler
                    cmpx      #150      opcode 0x96
                    lbeq      GenAsra   dispatch to handler
                    cmpx      #151      opcode 0x97
                    lbeq      GenLsra   dispatch to handler
                    cmpx      #118      opcode 0x76
                    lbeq      GenLoadY  dispatch to handler
                    cmpx      #111      opcode 0x6F
                    lbeq      GenLoadU  dispatch to handler
                    cmpx      #123      opcode 0x7B
                    lbeq      GenLeaIndexed dispatch to handler
                    ldd       14,s      default: D = result type arg
                    pshs      d         push type
                    lbsr      TypeRegChar map to register letter
                    leas      2,s        drop arg
                    std       6,s       save register letter local
                    ldd       16,s      D = operand type
                    cmpd      #119      is it a variable operand
                    lbne      GenOperand2 no, generate operand
                    ldd       6,u       D = child node opcode
                    cmpd      #133      is child a conversion node
                    bne       CheckByteDemote no, check byte demote
                    ldd       10,u      D = grandchild field
                    pshs      d         push as recursion arg
                    ldd       #119      push type 0x77
                    pshs      d         push it
                    ldd       #112      push type 0x70
                    pshs      d         push it
                    ldd       18,s      push node pointer arg
                    pshs      d         push it
                    lbsr      GenNode   recurse to gen child code
                    leas      8,s        drop four args
                    ldx       12,s      X = child opcode
                    bra       DispatchExtend dispatch the extension

EmitSex             leax      StrSex2,pcr X = sex mnemonic
                    bra       EmitConvOp emit conversion line

EmitAdca            leax      StrAdca0,pcr X = adca #0 mnemonic
                    bra       EmitConvOp emit conversion line

EmitSbca            leax      StrSbca0,pcr X = sbca #0 mnemonic
EmitConvOp          pshs      x         push mnemonic string
                    lbsr      EmitLine  emit instruction line
                    leas      2,s        drop string
                    bra       ConvDone  set type and finish

DispatchExtend      cmpx      #117      conversion opcode 0x75
                    beq       EmitSex   emit sex
                    cmpx      #79       opcode 0x4F
                    beq       EmitAdca  emit adca #0
                    cmpx      #80       opcode 0x50
                    lbeq      EmitAdca  emit adca #0
                    cmpx      #81       opcode 0x51
                    beq       EmitSbca  emit sbca #0
ConvDone            ldd       #112      result type d register
                    std       6,u       store type into node
                    lbra      Pop8Ret   finish

CheckByteDemote     ldd       ,u        D = node primary type
                    cmpd      #2        is it a byte type
                    bne       GenOperand2 no, generate operand
                    ldd       12,s      local operand code
                    cmpd      #127      is it member access
                    beq       GenOperand2 yes, skip demote
                    ldd       6,s       register letter local
                    cmpd      #'x       is it letter x
                    beq       GenOperand2 yes, skip demote
                    ldd       #98       else use byte register b
                    std       6,s       demote to byte register
GenOperand2         ldx       12,s      X = operand opcode
                    lbra      DispatchOperand dispatch operand generation

LoadVarOperand      ldd       16,s      D = operand type
                    cmpd      #119      is it a variable
                    lbne      EmitLoad  no, alternate load path
                    ldd       8,u       D = node right child
                    std       ,s        save local
                    ldd       6,u       D = node left child opcode
                    std       2,s       save local
                    tfr       d,x       X = child opcode
                    lbra      DispatchLoadSrc dispatch load source

EmitRegIndex        ldd       14,s      D = result type arg
                    cmpd      #112      is it d register
                    beq       EmitAddToD yes, add-into-d path
                    ldd       6,s       register letter local
                    pshs      d         push it
                    lbsr      EmitFmtOperand emit prefix with register
                    leas      2,s        drop arg
                    ldd       2,s       saved child opcode
                    pshs      d         push it
                    lbsr      TypeRegChar map to register letter
                    std       ,s        store letter
                    ldd       2,s       child opcode again
                    pshs      d         push it
                    leax      StrOffRegFmt2,pcr X = %d,%c format
                    lbra      EmitFmt2Done emit operand and finish

EmitAddToD          ldd       #'d       push register letter d
                    pshs      d         push it
                    ldd       4,s       local operand
                    pshs      d         push it
                    lbsr      TypeRegChar map to register letter
                    std       ,s        store letter
                    lbsr      EmitTfr   emit tfr instruction
                    leas      4,s        drop args
                    ldd       ,s        local offset value
                    lbeq      Pop8Ret   zero means finish
                    ldd       ,s        offset value again
                    pshs      d         push it
                    ldd       #54       push type 0x36
                    pshs      d         push it
                    ldd       #112      push type 0x70
                    pshs      d         push it
                    ldd       #80       push add opcode 0x50
                    pshs      d         push it
                    lbsr      GenNode   recurse to gen add
                    lbra      GenDone8  finish

EmitTfrToD          ldd       14,s      D = result type
                    cmpd      #112      is it d register
                    lbeq      Pop8Ret   yes, nothing to do
                    ldd       6,s       register letter local
                    pshs      d         push it
                    ldd       #'d       target letter d
                    lbra      EmitTfrDone emit tfr and finish

EmitCombinedOperand ldd       8,u       D = node right child
                    pshs      d         push it
                    ldd       8,s       operand value
                    pshs      d         push it
                    lbsr      EmitLabelRef emit combined operand
                    lbra      GenDone4  finish

SetConstType        ldd       #54       constant type 0x36
                    std       16,s      set operand type
                    ldu       ,s        U = local node pointer
                    bra       EmitLoad  go emit load

DispatchLoadSrc     cmpx      #113      child opcode 0x71
                    lbeq      EmitRegIndex emit register-indexed
                    cmpx      #118      child opcode 0x76
                    lbeq      EmitRegIndex emit register-indexed
                    cmpx      #111      child opcode 0x6F
                    lbeq      EmitRegIndex emit register-indexed
                    cmpx      #112      child opcode 0x70
                    beq       EmitTfrToD transfer into d
                    cmpx      #55       child opcode 0x37
                    beq       EmitCombinedOperand emit combined operand
                    cmpx      #54       child opcode 0x36
                    beq       SetConstType set constant type
EmitLoad            ldd       14,s      D = result type
                    cmpd      #112      is it d register
                    bne       EmitLd    no, emit ld
                    ldd       16,s      D = operand type
                    cmpd      #54       is it constant
                    bne       EmitLd    no, emit ld
                    cmpu      #0        is node null
                    bne       EmitLd    no, emit ld
                    leax      StrClraClrb,pcr X = clra/clrb mnemonic
                    pshs      x         push it
EmitOpLine          lbsr      EmitLine  emit instruction line
EmitOpDone          leas      2,s        drop string
                    lbra      Pop8Ret   finish

EmitLd              leax      StrLd2,pcr X = ld mnemonic
                    lbra      EmitOpStr emit op and operand

GenCompareOp        ldd       16,s      D = operand type
                    cmpd      #54       is it constant
                    bne       EmitCmpOp no, emit compare
                    cmpu      #0        is node null
                    bne       EmitCmpOp no, emit compare
                    ldd       6,s       register letter local
                    pshs      d         push it
                    leax      StrStTemp,pcr X = st%c -2,s format
EmitFmtDone         pshs      x         push format
                    ldd       GlbVar0005 output file pointer
                    pshs      d         push it
                    lbsr      fprintf   emit spill store
                    leas      6,s        drop args
                    lbra      Pop8Ret   finish

EmitCmpOp           leax      strcmp,pcr X = cmp mnemonic
                    pshs      x         push it
                    lbsr      EmitSpacedStr emit op string
                    leas      2,s        drop string
                    ldd       6,s       register letter local
                    cmpd      #98       is it byte register b
                    bne       OperandBase no, continue operand
                    ldd       #100      else promote to d
                    std       6,s       store d register letter
                    bra       OperandBase continue operand

GenVarSub           ldd       16,s      D = operand type
                    cmpd      #119      is it a variable
                    bne       EmitSt    no, emit sub
                    ldd       6,u       D = node left child opcode
                    std       2,s       save local
                    pshs      d         push it
                    lbsr      IsFloatType test if u/y register
                    std       ,s++      store result, drop arg
                    beq       EmitSt    not a register, emit sub
                    ldd       2,s       saved opcode
                    cmpd      14,s      equals result type
                    lbeq      Pop8Ret   yes, finish
                    ldd       2,s       opcode again
                    pshs      d         push it
                    lbsr      TypeRegChar map to register letter
                    std       ,s        store letter
                    ldd       8,s       operand value
EmitTfrDone         pshs      d         push it
                    lbsr      EmitTfr   emit tfr instruction
GenDone4            leas      4,s        drop args
                    lbra      Pop8Ret   finish

EmitSt              leax      StrSt,pcr X = st mnemonic
                    bra       EmitOpStr emit op and operand

EmitSub             leax      StrSub,pcr X = sub mnemonic
EmitOpStr           pshs      x         push mnemonic
                    lbsr      EmitSpacedStr emit op string
                    leas      2,s        drop string
OperandBase         leax      8,s       X = argument frame base
                    bra       BuildOperand build operand

GenAddChild         ldd       #67       push opcode 0x43
                    pshs      d         push it
                    lbsr      GenNode   recurse to gen code
                    leas      2,s        drop arg
EmitAdd             leax      StrAdd,pcr X = add mnemonic
                    lbra      EmitOpAndBinary emit op and finish

BuildOperand        leas      -8,x      S = adjusted frame
                    lbra      GenBinaryOperand generate operand

LoadMemberNode      ldd       16,s      D = operand type
                    cmpd      #119      is it a variable
                    lbne      EmitLea   no, generic operand
                    ldx       8,u       X = node right child
                    ldd       8,x       child's field
                    std       2,s       save local
                    tfr       d,x       X = that value
                    bra       DispatchMember dispatch member subtype

EmitMemberRef       ldd       6,s       register letter local
                    pshs      d         push it
                    lbsr      EmitFmtOperand emit prefix with register
                    leas      2,s        drop arg
                    ldd       #62       greater-than char
                    pshs      d         push it
                    lbsr      EmitChar  emit > char
                    leas      2,s        drop arg
                    ldd       2,s       saved value
                    cmpd      #35       is it subtype 0x23
                    bne       EmitOffsetRef no, offset form
                    ldx       8,u       X = node right child
                    ldd       6,x       child's field
                    pshs      d         push it
                    lbsr      EmitLabelName emit operand
                    bra       EmitMemberTail continue member tail

EmitOffsetRef       ldd       8,u       D = node right child
                    addd      #20       add field offset 0x14
                    pshs      d         push it
                    lbsr      EmitLabelText emit operand
EmitMemberTail      leas      2,s        drop arg
                    ldd       20,u      node field 0x14
                    pshs      d         push it
                    lbsr      EmitSignedOffset emit number or label
                    leas      2,s        drop arg
                    ldd       RegNameTab,y global suffix field
                    pshs      d         push it
                    lbsr      EmitStr   emit suffix string
                    lbra      EmitNlDone emit newline and finish

DispatchMember      cmpx      #33       member subtype 0x21
                    beq       EmitMemberRef handle member reference
                    cmpx      #34       member subtype 0x22
                    lbeq      EmitMemberRef handle member reference
                    cmpx      #35       member subtype 0x23
                    lbeq      EmitMemberRef handle member reference
EmitLea             leax      StrLea,pcr X = lea mnemonic
EmitOpAndBinary     pshs      x         push mnemonic
                    lbsr      EmitSpacedStr emit op string
                    leas      2,s        drop string
GenBinaryOperand    clra                zero high byte
                    clrb                zero low byte
                    pshs      d         push null arg
                    pshs      u         push node pointer
                    ldd       20,s      push arg
                    pshs      d         push it
                    ldd       12,s      push opcode arg
                    pshs      d         push it
                    lbsr      EmitInstrLine emit two-operand instruction
                    bra       GenDone8  finish

EmitExg             ldd       16,s      D = operand type
                    pshs      d         push it
                    lbsr      TypeRegChar map to register letter
                    std       ,s        store letter
                    ldd       8,s       operand value
                    pshs      d         push it
                    leax      StrExgFmt,pcr X = exg %c,%c format
EmitFmt2Done        pshs      x         push format
                    ldd       GlbVar0005 output file pointer
                    pshs      d         push it
                    lbsr      fprintf   emit exg instruction
GenDone8            leas      8,s        drop four args
                    lbra      Pop8Ret   finish

GenIndexed          ldd       6,s       register letter local
                    pshs      d         push it
                    lbsr      EmitFmtOperand emit prefix with register
                    leas      2,s        drop arg
                    ldx       16,s      X = operand type
                    bra       DispatchIndexOperand dispatch indexed operand

EmitDComma          leax      StrDComma,pcr X = d, operand text
                    pshs      x         push it
                    lbsr      EmitStr   emit string
                    leas      2,s        drop arg
                    leax      8,s       X = argument frame base
                    bra       RegOperand build register operand

EmitConstComma      pshs      u         push node pointer
                    lbsr      EmitNumber emit operand
                    leas      2,s        drop arg
                    ldd       #',       comma char
                    pshs      d         push it
                    lbsr      EmitChar  emit comma
                    leas      2,s        drop arg
                    bra       EmitRegChar emit register letter

RegOperand          leas      -8,x      S = adjusted frame
EmitRegChar         ldd       6,s       register letter local
                    pshs      d         push it
                    lbsr      EmitChar  emit register char
EmitNlDone          leas      2,s        drop arg
                    lbsr      EmitNewline emit newline
                    lbra      Pop8Ret   finish

LeaArgErr           leax      StrLeaArg,pcr X = LEA arg message
                    pshs      x         push it
                    lbsr      BuildMsgBuf print error message
                    leas      2,s        drop arg
                    lbra      Pop8Ret   finish

DispatchIndexOperand cmpx      #112      operand type d register
                    beq       EmitDComma emit d, form
                    cmpx      #54       operand type constant
                    beq       EmitConstComma emit constant operand
                    bra       LeaArgErr else report error

GenUnknownErr       ldd       GlobalMessageField,y   global message field
                    pshs      d         push it
                    lbsr      BuildMsgBuf print error message
                    leas      2,s        drop arg
                    lbra      Pop8Ret   finish

DispatchOperand     cmpx      #117      operand opcode 0x75
                    lbeq      LoadVarOperand handle it
                    cmpx      #129      operand opcode 0x81
                    lbeq      GenCompareOp handle compare
                    cmpx      #121      operand opcode 0x79
                    lbeq      GenVarSub handle it
                    cmpx      #81       operand opcode 0x51
                    lbeq      EmitSub   emit sub
                    cmpx      #79       operand opcode 0x4F
                    lbeq      GenAddChild emit add child
                    cmpx      #80       operand opcode 0x50
                    lbeq      EmitAdd   emit add
                    cmpx      #127      operand opcode 0x7F
                    lbeq      LoadMemberNode handle member access
                    cmpx      #115      operand opcode 0x73
                    lbeq      EmitExg   emit exg
                    cmpx      #116      operand opcode 0x74
                    lbeq      GenIndexed handle indexed
                    bra       GenUnknownErr default error

TypeRegChar         pshs      u         save U
                    ldx       4,s       X = type argument
                    bra       MapRegLetter classify the type

RegCharD            ldd       #'d       return register letter d
                    puls      pc,u      return with register letter d

RegLetterX2         ldd       #'x       register letter x for token $71
                    puls      pc,u      return letter to caller

RegLetterY          ldd       #'y       register letter y for token $76
                    puls      pc,u      return letter to caller

RegLetterU          ldd       #'u       register letter u for token $6F
                    puls      pc,u      return letter to caller

RegLetterNone       ldd       #'        default space when not a register
                    puls      pc,u      return letter to caller

MapRegLetter        cmpx      #112      is register token d
                    beq       RegCharD  yes emit letter d
                    cmpx      #113      is register token x
                    beq       RegLetterX2 yes emit letter x
                    cmpx      #118      is register token y
                    beq       RegLetterY yes emit letter y
                    cmpx      #111      is register token u
                    beq       RegLetterU yes emit letter u
                    bra       RegLetterNone otherwise emit a space

                    puls      pc,u      return letter to caller

EmitTfr             pshs      u         save the caller u register
                    ldd       6,s       second register letter argument
                    pshs      d         push for fprintf
                    ldd       6,s       first register letter argument
                    pshs      d         push for fprintf
                    leax      StrTfrFmt,pcr address of tfr format string
                    pshs      x         push format string
                    ldd       GlbVar0005 output file stream
                    pshs      d         push stream
                    lbsr      fprintf   emit tfr reg,reg line
Pop8Ret             leas      8,s        drop the pushed arguments
                    puls      pc,u      return to caller

GenLongOp           pshs      u         save the caller u register
                    ldx       4,s       load node operator code
                    lbra      GenLongOpDisp dispatch long-operator codegen

GenLongStack        ldd       #2        result size two bytes
                    pshs      d         push size argument
                    ldd       #147      push synthetic node type
                    pshs      d         push node field
                    ldd       #112      push node field
                    pshs      d         push node field
                    ldd       #117      push node field
                    pshs      d         push node field
                    lbsr      GenNode   generate code for sub-node
                    leas      8,s        drop the pushed arguments
                    ldd       #112      push node field
                    pshs      d         push node field
                    ldd       #122      push node field
                    pshs      d         push node field
                    lbsr      GenNode   generate code for sub-node
                    leas      4,s        drop the pushed arguments
                    clra                zero high byte
                    clrb                zero low byte
                    pshs      d         push zero field
                    ldd       #147      push synthetic node type
                    pshs      d         push node field
                    ldd       #112      push node field
                    pshs      d         push node field
                    ldd       #117      push node field
                    pshs      d         push node field
                    lbsr      GenNode   generate code for sub-node
                    leas      8,s        drop the pushed arguments
                    ldd       #112      push node field
                    pshs      d         push node field
                    ldd       #122      push node field
                    pshs      d         push node field
                    lbsr      GenNode   generate code for sub-node
                    lbra      Pop4Ret   return via four-byte cleanup

GenLongDeref        leax      StrOrBytes,pcr address of lda 0,x text
                    pshs      x         push instruction string
                    lbsr      EmitLine  emit the instruction line
                    lbra      EmitOpRet clean up and return

GenLongMove         leax      StrLmove,pcr address of _lmove routine name
                    bra       EmitLongShiftCall emit long move call

GenLongAdd          leax      StrLadd,pcr address of _ladd routine name
                    bra       EmitLongBinCall emit long binary call

GenLongSub          leax      StrLsub,pcr address of _lsub routine name
                    bra       EmitLongBinCall emit long binary call

GenLongMul          leax      StrLmul,pcr address of _lmul routine name
                    bra       EmitLongBinCall emit long binary call

GenLongDiv          leax      StrLdiv,pcr address of _ldiv routine name
                    bra       EmitLongBinCall emit long binary call

GenLongMod          leax      StrLmod,pcr address of _lmod routine name
                    bra       EmitLongBinCall emit long binary call

GenLongAnd          leax      StrLand,pcr address of _land routine name
                    bra       EmitLongBinCall emit long binary call

GenLongOr           leax      StrLor,pcr address of _lor routine name
                    bra       EmitLongBinCall emit long binary call

GenLongXor          leax      StrLxor,pcr address of _lxor routine name
                    bra       EmitLongBinCall emit long binary call

GenLongShl          leax      StrLshl,pcr address of _lshl routine name
                    bra       EmitLongShiftCall emit long shift call

GenLongShr          leax      StrLshr,pcr address of _lshr routine name
EmitLongShiftCall   pshs      x         push routine name
                    lbsr      EmitInstrPush4 emit lbsr to runtime routine
                    leas      2,s        drop the argument
                    ldd       GlbVar000F current arg-stack depth
                    subd      #2        shift consumed two bytes
                    lbra      StoreStkOffset store depth and return

GenLongCmp          leax      StrLcmpr,pcr address of _lcmpr routine name
EmitLongBinCall     pshs      x         push routine name
                    lbsr      EmitInstrPush4 emit lbsr to runtime routine
                    lbra      EmitOpRet clean up and return

GenLongNeg          leax      StrLneg,pcr address of _lneg routine name
                    bra       EmitLongUnaryCall emit long unary call

GenLongCompl        leax      StrLcompl,pcr address of _lcompl routine name
                    bra       EmitLongUnaryCall emit long unary call

GenLongItoL         leax      StrLitol,pcr address of _litol routine name
                    bra       EmitLongUnaryCall emit long unary call

GenLongUtoL         leax      StrLutol,pcr address of _lutol routine name
                    bra       EmitLongUnaryCall emit long unary call

GenLongInc          leax      StrLinc,pcr address of _linc routine name
                    bra       EmitLongUnaryCall emit long unary call

GenLongDec          leax      StrLdec,pcr address of _ldec routine name
EmitLongUnaryCall   pshs      x         push routine name
                    lbsr      EmitInstrPush4 emit lbsr to runtime routine
                    leas      2,s        drop the argument
                    ldd       GlbVar000F current arg-stack depth
                    subd      #4        operand consumed four bytes
                    lbra      StoreStkOffset store depth and return

GenLongCall         ldd       #2        result size two bytes
                    pshs      d         push size
                    ldd       8,s       node pointer argument
                    pshs      d         push node pointer
                    lbra      EmitCallSeq emit inline call sequence

GenLongDefault      leax      StrCodgenLongs,pcr address of codgen longs message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report compiler error
                    leas      2,s        drop the argument
                    ldd       GlobalMessageField,y   long op mnemonic string
                    pshs      d         push string
                    lbsr      EmitStr   emit string
                    leas      2,s        drop the argument
                    ldd       4,s       operator code value
                    pshs      d         push value
                    lbsr      EmitNumber emit number
                    leas      2,s        drop the argument
                    lbsr      EmitNewline emit newline
                    lbra      GenLongDone return to caller

GenLongOpDisp       cmpx      #110      long stack operator
                    lbeq      GenLongStack generate stacking code
                    cmpx      #139      long dereference operator
                    lbeq      GenLongDeref generate load
                    cmpx      #137      long move operator
                    lbeq      GenLongMove generate move call
                    cmpx      #80       long add operator
                    lbeq      GenLongAdd generate add call
                    cmpx      #81       long subtract operator
                    lbeq      GenLongSub generate subtract call
                    cmpx      #82       long multiply operator
                    lbeq      GenLongMul generate multiply call
                    cmpx      #83       long divide operator
                    lbeq      GenLongDiv generate divide call
                    cmpx      #84       long modulo operator
                    lbeq      GenLongMod generate modulo call
                    cmpx      #87       long bitwise-and operator
                    lbeq      GenLongAnd generate and call
                    cmpx      #88       long bitwise-or operator
                    lbeq      GenLongOr generate or call
                    cmpx      #89       long bitwise-xor operator
                    lbeq      GenLongXor generate xor call
                    cmpx      #86       long shift-left operator
                    lbeq      GenLongShl generate shift-left call
                    cmpx      #85       long shift-right operator
                    lbeq      GenLongShr generate shift-right call
                    cmpx      #90       long compare operator
                    lbeq      GenLongCmp generate compare call
                    cmpx      #91       long compare operator
                    lbeq      GenLongCmp generate compare call
                    cmpx      #94       long compare operator
                    lbeq      GenLongCmp generate compare call
                    cmpx      #92       long compare operator
                    lbeq      GenLongCmp generate compare call
                    cmpx      #95       long compare operator
                    lbeq      GenLongCmp generate compare call
                    cmpx      #93       long compare operator
                    lbeq      GenLongCmp generate compare call
                    cmpx      #67       long negate operator
                    lbeq      GenLongNeg generate negate call
                    cmpx      #68       long complement operator
                    lbeq      GenLongCompl generate complement call
                    cmpx      #131      signed int to long conversion
                    lbeq      GenLongItoL generate conversion call
                    cmpx      #134      unsigned int to long conversion
                    lbeq      GenLongUtoL generate conversion call
                    cmpx      #60       long increment operator
                    lbeq      GenLongInc generate increment call
                    cmpx      #62       long increment operator
                    lbeq      GenLongInc generate increment call
                    cmpx      #61       long decrement operator
                    lbeq      GenLongDec generate decrement call
                    cmpx      #63       long decrement operator
                    lbeq      GenLongDec generate decrement call
                    cmpx      #74       long function call operator
                    lbeq      GenLongCall generate call sequence
                    lbra      GenLongDefault unhandled long operator

GenLongDone         puls      pc,u      return from long codegen

GenFloatOp          pshs      u         save the caller u register
                    ldu       6,s       float size flag argument
                    ldx       4,s       load node operator code
