UseLtPrefix         ldd       #'<       less-than character
EmitLabelPrefix     pshs      d         push argument
                    lbsr      EmitChar  emit prefix character
                    leas      2,s        drop argument
EmitLabelBody       ldd       6,u       load node subtype
                    pshs      d         push argument
                    lbsr      EmitLabelName emit label reference
                    leas      2,s        drop argument
                    leax      4,s       X is argument frame
                    bra       EmitOperandIndex continue to offset suffix

EmitNamedOperand    ldd       GlbVar005A load addressing-mode flag
                    bne       EmitNamedField direct mode, skip prefix
                    ldd       8,s       load flag byte
                    anda      #$80      isolate indirect bit
                    clrb                clear low byte
                    std       -2,s      save flag
                    beq       UseLtPrefix2 not indirect, use less-than
                    ldd       #'>       greater-than character
                    bra       EmitNamePrefix emit prefix

UseLtPrefix2        ldd       #'<       less-than character
EmitNamePrefix      pshs      d         push argument
                    lbsr      EmitChar  emit prefix character
                    leas      2,s        drop argument
EmitNamedField      pshs      u         push node pointer
                    ldd       #20       offset to name field
                    addd      ,s++      compute field address
                    pshs      d         push argument
                    lbsr      EmitLabelText emit eight-char name
                    leas      2,s        drop argument
                    bra       EmitOperandOffset continue to offset suffix

EmitOperandIndex    leas      -4,x      restore stack to frame
EmitOperandOffset   ldd       12,s      load displacement
                    pshs      d         push argument
                    lbsr      EmitSignedOffset emit signed offset
                    leas      2,s        drop argument
                    ldd       8,s       load flag byte
                    anda      #$80      isolate indirect bit
                    clrb                clear low byte
                    std       -2,s      save flag
                    bne       EmitRegisterField indirect, emit register
                    ldd       GlbVar005A load addressing-mode flag
                    lbne      EmitIndirectSuffix direct mode, done
                    ldd       ,s        load node type code
                    cmpd      #33       type '!'
                    lbeq      EmitIndirectSuffix done, no register
                    ldd       ,s        load node type code
                    cmpd      #34       type '"'
                    lbeq      EmitIndirectSuffix done, no register
                    ldd       ,s        load node type code
                    cmpd      #35       type '#'
                    lbeq      EmitIndirectSuffix done, no register
EmitRegisterField   ldd       ,u        load node register field
                    clra                clear high byte
                    andb      #$30      isolate index register bits
                    cmpd      #48       compare node op code to $30
                    bne       EmitNameOperand not $30, emit node name operand
                    leax      StrPcr,pcr point to default operand text
                    pshs      x         push string argument
                    bra       EmitOperandStr go emit the operand string

EmitNameOperand     ldd       RegNameTab,y load node name field pointer
PushStrOperand      pshs      d         push string argument
EmitOperandStr      lbsr      EmitStr   emit the operand string
                    lbra      PopOperandDone drop arg and finish

DefaultOperandStr   leax      StrStorageError,pcr point to default operand text
                    lbra      EmitStrL0450 emit string via BuildMsgBuf

ClassifyIndirectOp  cmpx      #13       indirect op code $0D
                    lbeq      EmitLocalOffset handle it
                    cmpx      #35       op code $23
                    lbeq      EmitLabelOperand handle it
                    cmpx      #15       op code $0F
                    lbeq      EmitLabelBody handle it
                    cmpx      #33       op code $21
                    lbeq      EmitNamedOperand handle it
                    cmpx      #34       op code $22
                    lbeq      EmitNamedOperand handle it
                    cmpx      #14       op code $0E
                    lbeq      EmitNamedField handle it
                    cmpx      #12       op code $0C
                    lbeq      EmitNamedField handle it
                    bra       DefaultOperandStr none matched, default operand

EmitOffsetNum2      ldd       12,s      load offset value
EmitNumArg          pshs      d         push as number arg
                    lbsr      EmitNumber emit the number
                    lbra      PopOperandDone drop arg and finish

EmitIndexedOperand  ldd       10,s      load base offset
                    addd      12,s      add displacement
                    std       10,s      store combined offset
                    pshs      d         push number arg
                    lbsr      EmitNumber emit the offset number
                    leas      2,s        drop arg
                    ldd       #',       comma separator character
                    pshs      d         push the comma
                    lbsr      EmitChar  emit the comma
                    leas      2,s        drop the char
                    ldd       8,s       load register op code
                    anda      #$7f      mask off the flag bit
                    tfr       d,x       into X for dispatch
                    bra       SelectIndexReg select index register letter

RegX                ldd       #'x       x register letter
                    bra       EmitRegLetter emit it

RegY                ldd       #'y       y register letter
                    bra       EmitRegLetter emit it

RegU                ldd       #'u       u register letter
EmitRegLetter       pshs      d         push register char
                    lbsr      EmitChar  emit register letter
                    leas      2,s        drop the char
                    lbra      EmitIndirectSuffix emit indirect suffix

SelectIndexReg      cmpx      #147      X register op code
                    beq       RegX      emit x
                    cmpx      #148      Y register op code
                    beq       RegY      emit y
                    cmpx      #149      U register op code
                    beq       RegU      emit u
                    bra       EmitIndirectSuffix none, just emit suffix

EmitPcrOperand      ldd       StackPointerRegister,y   load node value or name
                    pshs      d         push string argument
                    lbsr      EmitStr   emit the string
                    leas      2,s        drop arg
                    leax      Data5B69,pcr point to pcr suffix text
                    pshs      x         push string
                    lbsr      EmitStr   emit the suffix
                    leas      2,s        drop arg
                    ldd       GlbVar000F load location counter
                    addd      #2        advance by two bytes
                    std       GlbVar000F update location counter
                    bra       EmitIndirectSuffix emit indirect suffix

DefaultOperand      leax      StrDereference,pcr default operand text pointer
EmitStrL0450        pshs      x         push string
                    lbsr      BuildMsgBuf print string to output
PopOperandDone      leas      2,s        drop arg
                    bra       EmitIndirectSuffix emit indirect suffix

ClassifyOperandOp   cmpx      #119      op code $77
                    lbeq      EmitIndexedRef handle it
                    cmpx      #54       op code $36
                    lbeq      EmitImmediate handle it
                    cmpx      #128      op code $80
                    lbeq      EmitFlaccRef handle it
                    cmpx      #52       op code $34
                    lbeq      EmitMemRef handle it
                    cmpx      #147      X register op code
                    lbeq      EmitIndexedOperand emit indexed operand
                    cmpx      #148      Y register op code
                    lbeq      EmitIndexedOperand emit indexed operand
                    cmpx      #149      U register op code
                    lbeq      EmitIndexedOperand emit indexed operand
                    cmpx      #110      op code $6E
                    beq       EmitPcrOperand emit pcr operand
                    bra       DefaultOperand none matched, default operand

EmitIndirectSuffix  ldd       8,s       load the flags word
                    anda      #$80      test indirect bit
                    clrb                clear low byte
                    std       -2,s      save the flag
                    lbeq      EmitRet4  not indirect, done
                    ldd       #']       close bracket character
                    pshs      d         push the char
                    lbsr      EmitChar  emit close bracket
                    leas      2,s        drop the char
                    lbra      EmitRet4  done

GetLongMnemonic     pshs      u         save u
                    ldx       4,s       load operator code arg
                    bra       LookupMnemonicLoop look up its mnemonic

UnknownOpErr        leax      StrRelOp,pcr unknown operator message
                    pshs      x         push string
                    lbsr      BuildMsgBuf print the message
                    leas      2,s        drop arg
Mnemonic5A          leax      Data5B7F,pcr default mnemonic pointer
                    bra       ReturnMnemonic return it

Mnemonic5B          leax      Data5B83,pcr mnemonic for op $5B
                    bra       ReturnMnemonic return it

Mnemonic5C          leax      Data5B87,pcr mnemonic for op $5C
                    bra       ReturnMnemonic return it

Mnemonic5D          leax      Data5B8B,pcr mnemonic for op $5D
                    bra       ReturnMnemonic return it

Mnemonic5E          leax      Data5B8F,pcr mnemonic for op $5E
                    bra       ReturnMnemonic return it

Mnemonic5F          leax      Data5B93,pcr mnemonic for op $5F
                    bra       ReturnMnemonic return it

Mnemonic60          leax      Data5B97,pcr mnemonic for op $60
                    bra       ReturnMnemonic return it

Mnemonic61          leax      Data5B9B,pcr mnemonic for op $61
                    bra       ReturnMnemonic return it

Mnemonic62          leax      Data5B9F,pcr mnemonic for op $62
                    bra       ReturnMnemonic return it

Mnemonic63          leax      Data5BA3,pcr mnemonic for op $63
ReturnMnemonic      tfr       x,d       return pointer in D
                    puls      pc,u      restore and return

LookupMnemonicLoop  cmpx      #90       op code $5A
                    beq       Mnemonic5A return its mnemonic
                    cmpx      #91       op code $5B
                    beq       Mnemonic5B return its mnemonic
                    cmpx      #92       op code $5C
                    beq       Mnemonic5C return its mnemonic
                    cmpx      #93       op code $5D
                    beq       Mnemonic5D return its mnemonic
                    cmpx      #94       op code $5E
                    beq       Mnemonic5E return its mnemonic
                    cmpx      #95       op code $5F
                    beq       Mnemonic5F return its mnemonic
                    cmpx      #96       op code $60
                    beq       Mnemonic60 return its mnemonic
                    cmpx      #97       op code $61
                    beq       Mnemonic61 return its mnemonic
                    cmpx      #98       op code $62
                    beq       Mnemonic62 return its mnemonic
                    cmpx      #99       op code $63
                    beq       Mnemonic63 return its mnemonic
                    lbra      UnknownOpErr none matched, unknown operator

                    puls      pc,u      return (unreached)

EmitSpacedStr       pshs      u         save u
                    ldd       GlbVar0005 output stream pointer
                    pshs      d         push stream arg
                    ldd       #'        space character
                    pshs      d         push the char
                    lbsr      PutByte   emit leading space
                    leas      4,s        drop args
                    ldd       4,s       load format string arg
                    pshs      d         push it
                    bsr       EmitStr   emit the string
                    lbra      EmitRet2  drop arg and return

EmitLine            pshs      u         save u
                    ldd       4,s       load string arg
                    pshs      d         push it
                    bsr       EmitSpacedStr emit space plus string
                    lbra      LabelColonDone drop arg, newline, return

EmitNewline         pshs      u         save u
                    ldd       GlbVar0005 output stream pointer
                    pshs      d         push stream
                    ldd       #13       carriage return character
                    bra       EmitCharEntry emit char and return

EmitChar            pshs      u         save u
                    ldd       GlbVar0005 output stream pointer
                    pshs      d         push stream
                    ldd       6,s       load char arg
EmitCharEntry       pshs      d         push the char
                    lbsr      PutByte   emit char to output
                    bra       EmitRet4  drop args and return

EmitStr             pshs      u         save u
                    ldd       4,s       load string arg
                    pshs      d         push string
                    ldd       GlbVar0005 output stream pointer
                    pshs      d         push stream
                    lbsr      fprintf   print the string
EmitRet4            leas      4,s        drop args
                    puls      pc,u      restore and return

EmitNumber          pshs      u         save u
                    ldd       4,s       load number arg
                    pshs      d         push it
                    leax      Data5BA7,pcr point to decimal format
                    lbra      EmitFmtArg fprintf and return

EmitLocalLabel      pshs      u         save u
                    ldd       4,s       load label number arg
                    pshs      d         push it
                    bsr       EmitLabelName emit _NNN label
                    leas      2,s        drop arg
                    clra                clear high byte
                    clrb                clear low byte
                    std       GlbVar002F reset pending flag
                    lbra      EmitNewlineRet newline and return

EmitLabelName       pshs      u         save u
                    ldd       #'_       underscore label prefix
                    pshs      d         push the char
                    bsr       EmitChar  emit underscore
                    leas      2,s        drop the char
                    ldd       4,s       load label number
                    pshs      d         push it
                    bsr       EmitNumber emit the number
                    bra       EmitRet2  drop arg and return

EmitLabelText       pshs      u         save u
                    ldd       4,s       load arg
                    pshs      d         push it
                    leax      Str8s,pcr point to label format string
                    lbra      EmitFmtArg fprintf and return

EmitReserveSpace    pshs      u,d       save u and value
                    ldd       6,s       load target address arg
                    subd      GlbVar000F minus current location
                    std       ,s        save the gap size
                    beq       ReserveDone no gap needed, skip
                    leax      StrLeas2,pcr point to reservation directive
                    pshs      x         push string
                    lbsr      EmitSpacedStr emit space plus directive
                    leas      2,s        drop arg
                    ldd       ,s        load the gap value
                    pshs      d         push it
                    lbsr      EmitNumber emit gap size
                    leas      2,s        drop arg
                    ldd       StackPointerRegister,y   load node comment or name
                    pshs      d         push it
                    lbsr      EmitStr   emit the string
                    leas      2,s        drop arg
                    lbsr      EmitNewline emit newline
ReserveDone         ldd       6,s       reload the arg
EmitRet2            leas      2,s        drop arg
                    puls      pc,u      restore and return

EmitLabelDef        pshs      u         save u
                    ldd       4,s       load label arg
                    pshs      d         push it
                    bsr       EmitLabelText emit the label
                    leas      2,s        drop arg
                    ldd       6,s       reload the value
                    beq       EmitNewlineRet zero, just newline
                    ldd       #':       colon character
                    pshs      d         push the char
                    lbsr      EmitChar  emit the colon
LabelColonDone      leas      2,s        drop arg
EmitNewlineRet      lbsr      EmitNewline emit newline
                    puls      pc,u      restore and return

EmitFmtOperand      pshs      u         save u
                    ldd       4,s       load arg
                    pshs      d         push it
                    leax      StrLeaC,pcr point to default format
EmitFmtArg          pshs      x         push the format
                    ldd       GlbVar0005 output stream pointer
                    pshs      d         push stream
                    lbsr      fprintf   print formatted operand
                    leas      6,s        drop args
                    puls      pc,u      restore and return

EmitLabelRef        pshs      u         save u
                    ldd       4,s       load arg
                    pshs      d         push it
                    bsr       EmitFmtOperand emit formatted operand
                    leas      2,s        drop arg
                    ldd       6,s       reload the value
                    pshs      d         push number arg
                    ldd       #'_       underscore label prefix char
                    pshs      d         push the char
                    leax      StrCDPcr,pcr point to _%d format
                    pshs      x         push the format
                    ldd       GlbVar0005 output stream pointer
                    pshs      d         push stream
                    lbsr      fprintf   print label reference
                    leas      8,s        drop args
                    puls      pc,u      restore and return

