EmitProgramEnd      pshs      u         save the caller u register
                    lbsr      DumpStrings dump string literals
                    lbsr      EmitEndsect emit endsect directive
                    ldd       CacheUserId load source error count
                    lbeq      EmitRet   no errors, done
                    leax      StrFailSourceErrors,pcr point at "fail source errors"
                    lbra      PushAndEmit emit the fail marker

EmitVsectRmb        pshs      u         save the caller u register
                    ldd       8,s       get direct-page flag argument
                    pshs      d         pass to vsect emitter
                    lbsr      EmitVsect emit vsect header
                    leas      2,s        drop argument
                    ldd       4,s       get variable name pointer
                    pshs      d         pass to name emitter
                    lbsr      EmitLabelName emit the symbol name
                    leas      2,s        drop argument
                    ldd       6,s       get size in bytes
                    pshs      d         pass to fprintf
                    leax      StrRmbD,pcr " rmb %d" format string
                    pshs      x         push format pointer
                    ldd       GlbVar0005 output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit rmb reservation
                    bra       EndVsectRet close vsect and return

EmitColonRmb        pshs      u         save the caller u register
                    ldd       8,s       get direct-page flag argument
                    pshs      d         pass to vsect emitter
                    lbsr      EmitVsect emit vsect header
                    leas      2,s        drop argument
                    ldd       #58       ':' label separator
                    bra       EmitLabeledRmb emit labeled rmb

EmitSpaceRmb        pshs      u         save the caller u register
                    ldd       8,s       get direct-page flag argument
                    pshs      d         pass to vsect emitter
                    lbsr      EmitVsect emit vsect header
                    leas      2,s        drop argument
                    ldd       #32       ' ' label separator
EmitLabeledRmb      pshs      d         save separator char
                    ldd       8,s       get variable name
                    pshs      d         push name
                    ldd       8,s       get size
                    pshs      d         push size
                    bsr       EmitNameRmb emit "name: rmb size"
EndVsectRet         leas      6,s        drop the three args
                    lbsr      EmitEndsect emit endsect
                    puls      pc,u      return

EmitNameRmb         pshs      u         save the caller u register
                    ldd       6,s       get size argument
                    pshs      d         push size
                    ldb       11,s      get separator char
                    sex                 extend to word
                    pshs      d         push char
                    ldd       8,s       get name record pointer
                    addd      #20       skip to name field
                    pshs      d         push name pointer
                    leax      Str8sCRmbD,pcr "%.8s%c rmb %d" format
                    pshs      x         push format
                    ldd       GlbVar0005 output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit labeled reservation
                    leas      10,s       drop five args
                    puls      pc,u      return

EmitStringConst     pshs      u         save the caller u register
                    ldd       6,s       get string record pointer
                    std       GlbVar005E save current string
                    pshs      d         push it
                    lbsr      EmitLabelName emit the label name
                    leas      2,s        drop argument
                    ldd       4,s       get string text pointer
                    pshs      d         push text
                    leax      StrFcc,pcr " fcc \"%.8s\" fcb 0" format
                    lbra      EmitFmtArg2 emit constant and return

EmitFuncPrologue    pshs      u         save the caller u register
                    ldu       4,s       get function name pointer
                    pshs      u         push name
                    leax      StrTtl8s,pcr " ttl %.8s" format
                    pshs      x         push format
                    ldd       GlbVar0005 output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit module title
                    leas      6,s        drop args
                    ldd       6,s       get second argument
                    pshs      d         push it
                    pshs      u         push function name
                    lbsr      EmitLabelDef emit label definition
                    leas      4,s        drop args
                    leax      StrPshsU,pcr "pshs u" prologue line
                    pshs      x         push text
                    lbsr      EmitLine  emit prologue line
                    leas      2,s        drop arg
                    ldd       GlbVar0015 stack-check disabled flag
                    bne       EmitProfEntry skip stkcheck call
                    ldd       GlbVar000B next label counter
                    addd      #1        bump it
                    std       GlbVar000B store back
                    std       GlbFrameLbl remember frame-size label
                    pshs      d         push label number
                    leax      StrLddD,pcr " ldd #_%d / lbsr _stkcheck"
                    pshs      x         push format
                    ldd       GlbVar0005 output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit stack-check call
                    leas      6,s        drop args
EmitProfEntry       ldd       GlbVar0017 profiling enabled flag
                    lbeq      EmitRet   not profiling, done
                    leax      StrLeax3,pcr "leax " opcode text
                    pshs      x         push text
                    lbsr      EmitSpacedStr emit opcode text
                    leas      2,s        drop arg
                    ldd       8,s       get function name
                    pshs      d         push name
                    lbsr      EmitLabelName emit the name
                    leas      2,s        drop arg
                    leax      StrPcr2,pcr ",pcr / pshs x / leax " text
                    pshs      x         push text
                    lbsr      EmitStr   emit text line
                    leas      2,s        drop arg
                    pshs      u         push function name again
                    lbsr      EmitLabelText emit name label
                    leas      2,s        drop arg
                    leax      StrPcr3,pcr ",pcr ... lbsr _prof" text
                    lbra      EmitTextLine emit profiling entry

EmitFuncEpilogue    pshs      u         save the caller u register
                    ldd       GlbVar0017 profiling enabled flag
                    beq       EmitEpilogueDone not profiling, skip
                    ldd       GlbVar005E current function label
                    pshs      d         push it
                    leax      StrPshsD,pcr "_eprof" exit block format
EmitFmtArg2         pshs      x         push format
                    ldd       GlbVar0005 output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit profile-exit code
                    leas      6,s        drop args
EmitEpilogueDone    puls      pc,u      return

EmitFrameEqu        pshs      u         save the caller u register
                    ldd       GlbVar0015 stack-check disabled flag
                    bne       FrameEquDone skip frame equate
                    ldd       GlbVar001B current frame offset
                    subd      GlbVar0013 minus base offset
                    addd      #$FFC0    adjust frame size
                    pshs      d         push size
                    ldd       GlbFrameLbl frame-size label number
                    pshs      d         push it
                    leax      StrDEquD,pcr "_%d equ %d" format
                    pshs      x         push format
                    ldd       GlbVar0005 output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit frame-size equate
                    leas      8,s        drop args
FrameEquDone        puls      pc,u      return

EmitFcb             pshs      u         save the caller u register
                    leax      StrFcb,pcr "fcb " directive prefix
                    bra       EmitDirectiveText emit it

EmitFdb             pshs      u         save the caller u register
                    leax      StrFdb,pcr "fdb " directive prefix
EmitDirectiveText   pshs      x         push text
                    lbsr      EmitSpacedStr emit directive text
                    lbra      EmitDone  return via common tail

EmitCommentStar     pshs      u         save the caller u register
                    leax      Data5F00,pcr "* " comment prefix
EmitTextLine        pshs      x         push text
                    lbsr      EmitStr   emit comment line
                    lbra      EmitDone  return via common tail

EmitVsect           pshs      u         save the caller u register
                    ldd       4,s       direct-page flag
                    beq       EmitVsectPlain not dp, use plain vsect
                    leax      StrVsectDp,pcr "vsect dp" keyword
                    bra       PushVsectName emit it

EmitVsectPlain      leax      StrVsect,pcr "vsect" keyword
PushVsectName       tfr       x,d       keyword pointer to D
                    pshs      d         push it
                    bra       EmitStrTail emit the directive

EmitEndsect         pshs      u         save the caller u register
                    leax      StrEndsect,pcr "endsect" keyword
PushAndEmit         pshs      x         push it
EmitStrTail         lbsr      EmitLine  emit directive
                    lbra      EmitDone  return via common tail

DumpStrings         pshs      u         save the caller u register
                    ldd       GlbStrList string list head
                    lbeq      EmitRet   empty, nothing to dump
                    ldd       GlbStrList reload list head
                    pshs      d         push it
                    lbsr      RewindBuf rewind list to first
                    leas      2,s        drop arg
                    bra       DumpStrLoop enter dump loop

DumpStrEmit         ldd       GlbVar0005 output stream handle
                    pshs      d         push stream
                    pshs      u         push string node pointer
                    lbsr      PutByte   emit one string entry
                    leas      4,s        drop args
DumpStrLoop         ldd       GlbStrList string list
                    pshs      d         push it
                    lbsr      GetByte   get next entry
                    leas      2,s        drop arg
                    tfr       d,u       node pointer to U
                    cmpu      #$FFFF    end of list
                    bne       DumpStrEmit emit next string
                    ldx       GlbStrList string list head
                    ldd       6,x       load attribute flags
                    clra                keep low byte only
                    andb      #$20      test dump-debug flag
                    beq       DumpStrFree not set, skip banner
                    leax      StrDumpstrings,pcr "dumpstrings" banner
                    pshs      x         push it
                    lbsr      PrintMsg  print debug message
                    leas      2,s        drop arg
DumpStrFree         ldd       GlbStrList string list
                    pshs      d         push it
                    lbsr      CloseBuf  release the list
                    leas      2,s        drop arg
                    leax      StringListVariable,y   string list variable
                    pshs      x         push its address
                    lbsr      unlink    clear the list pointer
                    bra       EmitDone  return via common tail

FlushStringPool     pshs      u,d       save u and temp
                    ldd       Errno,y   saved count value
                    beq       FlushDefaultCount zero, default to one
                    ldd       Errno,y   reload count
                    bra       FlushStrDo use it

FlushDefaultCount   ldd       #1        default count of one
FlushStrDo          std       ,s        save on stack
                    ldd       GlbStrList string list head
                    beq       FlushStrCall empty, skip free
                    ldd       GlbStrList reload list head
                    pshs      d         push it
                    lbsr      CloseBuf  release the list
                    leas      2,s        drop arg
                    leax      StringListVariable,y   string list variable
                    pshs      x         push its address
                    lbsr      unlink    clear the list pointer
                    leas      2,s        drop arg
FlushStrCall        ldd       ,s        reload count
                    pshs      d         push it
                    lbsr      _exit     flush/free with count
                    leas      2,s        drop arg
EmitDone            leas      2,s        drop temp slot
EmitRet             puls      pc,u      restore u and return

StrFailSourceErrors fcc       /fail source errors/
                    fcb       C$NULL
StrRmbD             fcc       / rmb %d/
                    fcb       C$CR,C$NULL
Str8sCRmbD          fcc       /%.8s%c rmb %d/
                    fcb       C$CR,C$NULL
StrFcc              fcc       / fcc "%.8s"/
                    fcb       C$CR
                    fcc       / fcb 0/
                    fcb       C$CR,C$NULL
StrTtl8s            fcc       / ttl %.8s/
                    fcb       C$CR,C$NULL
StrPshsU            fcc       /pshs u/
                    fcb       C$NULL
StrLddD             fcc       / ldd #_%d/
                    fcb       C$CR
                    fcc       / lbsr _stkcheck/
                    fcb       C$CR,C$NULL
StrLeax3            fcc       /leax /
                    fcb       C$NULL
StrPcr2             fcc       /,pcr/
                    fcb       C$CR
                    fcc       / pshs x/
                    fcb       C$CR
                    fcc       / leax /
                    fcb       C$NULL
StrPcr3             fcc       /,pcr/
                    fcb       C$CR
                    fcc       / pshs x/
                    fcb       C$CR
                    fcc       / lbsr _prof/
                    fcb       C$CR
                    fcc       / leas 4,s/
                    fcb       C$CR,C$NULL
StrPshsD            fcc       / pshs d/
                    fcb       C$CR
                    fcc       / leax _%d,pcr/
                    fcb       C$CR
                    fcc       / pshs x/
                    fcb       C$CR
                    fcc       / lbsr _eprof/
                    fcb       C$CR
                    fcc       / leas 2,s/
                    fcb       C$CR
                    fcc       / puls d/
                    fcb       C$CR,C$NULL
StrDEquD            fcc       /_%d equ %d/
                    fcb       C$CR,C$CR,C$NULL
StrFcb              fcc       /fcb /
                    fcb       C$NULL
StrFdb              fcc       /fdb /
                    fcb       C$NULL
Data5F00            fcc       /* /
                    fcb       C$NULL
StrVsectDp          fcc       /vsect dp/
                    fcb       C$NULL
StrVsect            fcc       /vsect/
                    fcb       C$NULL
StrEndsect          fcc       /endsect/
                    fcb       C$NULL
StrDumpstrings      fcc       /dumpstrings/
                    fcb       C$NULL
ParseStatement2     pshs      u         save the caller u register
                    leas      -21,s      allocate line buffer
                    lbsr      SkipSpaces fetch next token
                    ldb       GlbVar0045 current token type
                    sex                 extend to word
                    cmpd      #$FFFF    end-of-input token
                    bne       GotToken  got a real token
                    ldd       #$FFFF    end-of-input sentinel
                    std       GlbVar003F flag end of compilation
                    leas      21,s       release line buffer
                    puls      pc,u      return

GotToken            ldd       F004aYFirst current line position
                    addd      #$FFFF    back up one
                    std       GlbVar0043 save statement start
                    ldd       GlbVar0007 current input pointer
                    std       GlbSrcLine remember it
                    bra       StmtDispatchLoop enter dispatch loop

SkipBadToken        leax      MsgBadChar,pcr error message string
                    pshs      x         push it
                    lbsr      BuildMsgBuf print it
                    leas      2,s        drop arg
                    lbsr      NextChar  advance past token
                    ldd       F004aYFirst current position
                    std       GlbVar0043 update statement start
StmtDispatchLoop    ldb       GlbVar0045 current token type
                    sex                 extend to word
                    leax      CtypeTab,y keyword dispatch table
                    leax      d,x       index by token type
                    ldb       ,x        read operator class from table
                    sex                 sign-extend class byte to D
                    std       GlbVar003F save operator code
                    beq       SkipBadToken class zero means skip this token
                    ldb       GlbVar0045 reload the lookahead char
                    sex                 sign-extend to D
                    leax      AttributeTable,y   point at attribute table
                    leax      d,x       index by char
                    ldb       ,x        read attribute byte
                    sex                 sign-extend to D
                    std       GlbVar0041 save attribute / precedence
                    ldx       GlbVar003F X = operator code
                    lbra      ClassifyPrimaryTok dispatch on operator code

ClassifyNameTok     leax      10,s      point at local scratch buffer
                    pshs      x         pass scratch pointer
                    lbsr      ScanIdentifier look up the symbol
                    leas      2,s        drop argument
                    leax      10,s      point at scratch again
                    pshs      x         pass pointer
                    lbsr      LookupOrAddSym resolve symbol entry
                    leas      2,s        drop argument
                    tfr       d,u       U = symbol entry pointer
                    ldd       ,u        load entry type field
                    std       GlbVar003F save as op code
                    cmpd      #51       is it an enum constant
                    bne       PlainNameTok no, treat as plain name
                    ldd       8,u       load enum value
                    std       GlbVar0041 save as attribute
                    cmpd      #59       is value the sentinel $3B
                    lbne      ClassifyDone no, done
                    ldd       #59       force op code $3B
                    std       GlbVar003F store op code
                    ldd       #14       attribute $0E
                    std       GlbVar0041 store attribute
                    lbra      ClassifyDone done

PlainNameTok        ldd       #52       op code = name token $34
                    std       GlbVar003F store op code
                    stu       GlbVar0041 attribute = symbol pointer
                    lbra      ClassifyDone done

ClassifyNumConst    leax      ,s        point at stack slot
                    pshs      x         pass pointer
                    ldd       #1        request size 1
                    pshs      d         push size argument
                    lbsr      ParseNumber allocate work node
                    leas      4,s        drop arguments
                    std       19,s      save node pointer
                    bra       NumConstBuild build the constant node

NumConstRealign     leas      -21,x     realign stack after node alloc
NumConstBuild       leax      ,s        X = stack frame base
                    stx       8,s       save value pointer
                    ldx       19,s      X = numeric kind
                    bra       NumKindDispatch dispatch on kind

IntConstTok         ldd       [8,s]     load the integer value
                    bra       EmitIntConst emit int constant

LongConstTok        ldd       #4        request 4-byte buffer
                    pshs      d         push size argument
                    lbsr      AllocMem  allocate constant storage
                    leas      2,s        drop argument
                    tfr       d,u       U = storage pointer
                    leax      ,u        X = storage pointer
                    pshs      x         pass destination
                    ldx       10,s      X = source value
                    lbsr      StoreInt32 copy long value
                    stu       GlbVar0041 attribute = value pointer
                    ldd       #74       op code = long constant $4A
                    bra       EmitOpDone2 emit op code

FloatConstTok       ldd       #8        request 8-byte buffer
                    pshs      d         push size argument
                    lbsr      AllocMem  allocate constant storage
                    leas      2,s        drop argument
                    tfr       d,u       U = storage pointer
                    leax      ,u        X = storage pointer
                    pshs      x         pass destination
                    ldx       10,s      X = source value
                    lbsr      CopyFloat copy double value
                    stu       GlbVar0041 attribute = value pointer
                    ldd       #75       op code = float constant $4B
                    bra       EmitOpDone2 emit op code

BadConstTok         leax      MsgConstOverflow,pcr point at error message text
                    pshs      x         pass string pointer
                    lbsr      BuildMsgBuf report the message
                    leas      2,s        drop argument
                    ldd       #1        default attribute 1
EmitIntConst        std       GlbVar0041 save attribute
                    ldd       #54       op code = int constant $36
EmitOpDone2         std       GlbVar003F save op code
                    lbra      ClassifyDone done

NumKindDispatch     cmpx      #1        kind 1 = int
                    beq       IntConstTok handle int constant
                    cmpx      #8        kind 8 = long
                    beq       LongConstTok handle long constant
                    cmpx      #6        kind 6 = double
                    beq       FloatConstTok handle float constant
                    bra       BadConstTok unknown kind

IntNumberTok        lbsr      ParseCharConst parse numeric literal
                    ldd       #54       op code = int constant $36
                    bra       EmitConstDone emit op code

StringConstTok      lbsr      ParseStringConst parse string literal
                    ldd       #55       op code = string constant $37
EmitConstDone       std       GlbVar003F save op code
                    lbra      ClassifyDone done

ClassifyOperatorTok lbsr      NextChar  consume the token character
                    ldx       GlbVar003F X = operator code
                    lbra      ClassifyCompoundOp recognize compound operator

DotNumberTok        ldb       GlbVar0045 lookahead char
                    sex                 sign-extend to D
                    leax      CtypeTab,y point at class table
                    leax      d,x       index by char
                    ldb       ,x        read class of lookahead
                    cmpb      #107      is it a digit class
                    lbne      ClassifyDone no, done
                    leax      ,s        point at stack slot
                    pshs      x         pass pointer
                    ldd       #6        request size 6
                    pshs      d         push size argument
                    lbsr      ParseNumber allocate work node
                    leas      4,s        drop arguments
                    std       19,s      save node pointer
                    leax      21,s      X = node pointer plus frame
                    lbra      NumConstRealign build float constant node

AmpOpTok            ldb       GlbVar0045 lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       AmpDispatch dispatch ampersand variants

LogAndTok           ldd       #71       op code = logical and $47
                    std       GlbVar003F save op code
                    lbsr      NextChar  consume second ampersand
                    ldd       #5        attribute $05
                    bra       SetAttrDone store attribute and finish

AndAssignTok        ldd       #167      op code = and-assign $A7
                    std       GlbVar003F save op code
                    ldd       #2        attribute $02
                    lbra      EmitOpConsume consume = and finish

AmpDispatch         cmpx      #38       next char is ampersand
                    beq       LogAndTok logical and
                    cmpx      #61       next char is equals
                    beq       AndAssignTok and-assign
                    lbra      ClassifyDone plain ampersand, done

EqualEqualTok       ldb       GlbVar0045 lookahead char
                    cmpb      #'=      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       #90       op code = equality $5A
                    std       GlbVar003F save op code
                    ldd       #9        attribute $09
                    lbra      EmitOpConsume consume = and finish

PipeOpTok           ldb       GlbVar0045 lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       PipeDispatch dispatch pipe variants

LogOrTok            ldd       #72       op code = logical or $48
                    std       GlbVar003F save op code
                    lbsr      NextChar  consume second pipe
                    ldd       #4        attribute $04
                    bra       SetAttrDone store attribute and finish

OrAssignTok         ldd       #168      op code = or-assign $A8
EmitAssignOp        std       GlbVar003F save op code
                    lbsr      NextChar  consume equals
                    ldd       #2        attribute $02
SetAttrDone         std       GlbVar0041 save attribute
                    lbra      ClassifyDone done

PipeDispatch        cmpx      #124      next char is pipe
                    beq       LogOrTok  logical or
                    cmpx      #61       next char is equals
                    beq       OrAssignTok or-assign
                    lbra      ClassifyDone plain pipe, done

NotEqualTok         ldb       GlbVar0045 lookahead char
                    cmpb      #'=      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       #91       op code = not-equal $5B
                    std       GlbVar003F save op code
                    lbsr      NextChar  consume equals
                    ldd       #9        attribute $09
                    bra       SetAttrDone store attribute and finish

StarAssignTok       ldb       GlbVar0045 lookahead char
                    cmpb      #'=      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       #162      op code = compound assign $A2
                    bra       EmitAssignOp emit assign op

AssignFromBinaryTok ldb       GlbVar0045 lookahead char
                    cmpb      #'=      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       GlbVar003F current base op code
                    addd      #80       form assign variant
                    lbra      EmitAssignOp emit assign op

LessOpTok           ldb       GlbVar0045 lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       LessDispatch dispatch less-than variants

ShiftLeftTok        ldd       #86       op code = shift left $56
                    std       GlbVar003F save op code
                    ldd       #11       attribute $0B
                    std       GlbVar0041 save attribute
                    lbsr      NextChar  consume second less-than
                    ldb       GlbVar0045 lookahead char
                    cmpb      #'=      is it equals
                    lbne      ClassifyDone no, plain shift left
                    ldd       #166      op code = shift-left-assign $A6
                    std       GlbVar003F save op code
                    ldd       #2        attribute $02
                    lbra      EmitOpConsume consume = and finish

LessEqTok           ldd       #92       op code = less-or-equal $5C
                    std       GlbVar003F save op code
                    ldd       #10       attribute $0A
                    lbra      EmitOpConsume consume = and finish

LessDispatch        cmpx      #60       next char is less-than
                    beq       ShiftLeftTok shift left
                    cmpx      #61       next char is equals
                    beq       LessEqTok less-or-equal
                    lbra      ClassifyDone plain less-than, done

GreaterOpTok        ldb       GlbVar0045 lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       GreaterDispatch dispatch greater-than variants

ShiftRightTok       ldd       #85       op code = shift right $55
                    std       GlbVar003F save op code
                    ldd       #11       attribute $0B
                    std       GlbVar0041 save attribute
                    lbsr      NextChar  consume second greater-than
                    ldb       GlbVar0045 lookahead char
                    cmpb      #'=      is it equals
                    lbne      ClassifyDone no, plain shift right
                    ldd       #165      op code = shift-right-assign $A5
                    std       GlbVar003F save op code
                    ldd       #2        attribute $02
                    lbra      EmitOpConsume consume = and finish

GreaterEqTok        ldd       #94       op code = greater-or-equal $5E
                    std       GlbVar003F save op code
                    ldd       #10       attribute $0A
                    lbra      EmitOpConsume consume = and finish

GreaterDispatch     cmpx      #62       next char is greater-than
                    beq       ShiftRightTok shift right
                    cmpx      #61       next char is equals
                    beq       GreaterEqTok greater-or-equal
                    lbra      ClassifyDone plain greater-than, done

PlusOpTok           ldb       GlbVar0045 lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       PlusDispatch dispatch plus variants

IncrementTok        ldd       #60       op code = increment $3C
                    std       GlbVar003F save op code
                    ldd       #14       attribute $0E
                    bra       EmitOpConsume consume + and finish

PlusAssignTok       ldd       #160      op code = plus-assign $A0
                    std       GlbVar003F save op code
                    ldd       #2        attribute $02
                    bra       EmitOpConsume consume = and finish

PlusDispatch        cmpx      #43       next char is plus
                    beq       IncrementTok increment
                    cmpx      #61       next char is equals
                    beq       PlusAssignTok plus-assign
                    lbra      ClassifyDone plain plus, done

MinusOpTok          ldb       GlbVar0045 lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       MinusDispatch dispatch minus variants

DecrementTok        ldd       #61       op code = decrement $3D
                    std       GlbVar003F save op code
                    ldd       #14       attribute $0E
                    bra       EmitOpConsume consume - and finish

MinusAssignTok      ldd       #161      op code = minus-assign $A1
                    std       GlbVar003F save op code
                    ldd       #2        attribute $02
                    bra       EmitOpConsume consume = and finish

ArrowTok            ldd       #70       op code = arrow $46
                    std       GlbVar003F save op code
                    ldd       #15       attribute $0F
EmitOpConsume       std       GlbVar0041 save attribute
                    lbsr      NextChar  consume the character
                    lbra      ClassifyDone done

MinusDispatch       cmpx      #45       next char is minus
                    beq       DecrementTok decrement
                    cmpx      #61       next char is equals
                    beq       MinusAssignTok minus-assign
                    cmpx      #62       next char is greater-than
                    beq       ArrowTok  arrow operator
                    lbra      ClassifyDone plain minus, done

ClassifyCompoundOp  cmpx      #69       base op dot
                    lbeq      DotNumberTok dot/number handler
                    cmpx      #65       base op ampersand
                    lbeq      AmpOpTok  ampersand handler
                    cmpx      #120      base op equals
                    lbeq      EqualEqualTok equality handler
                    cmpx      #88       base op pipe
                    lbeq      PipeOpTok pipe handler
                    cmpx      #64       base op not
                    lbeq      NotEqualTok not-equal handler
                    cmpx      #66       base op star
                    lbeq      StarAssignTok star-assign handler
                    cmpx      #'S       base op slash
                    lbeq      AssignFromBinaryTok slash-assign handler
                    cmpx      #84       base op percent
                    lbeq      AssignFromBinaryTok percent-assign handler
                    cmpx      #'Y       base op caret
                    lbeq      AssignFromBinaryTok xor-assign handler
                    cmpx      #93       base op less-than
                    lbeq      LessOpTok less-than handler
                    cmpx      #95       base op greater-than
                    lbeq      GreaterOpTok greater-than handler
