CoerceToDouble      pshs      u         save node pointer
                    ldd       #$FFB4    frame size for stack check
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       get node pointer argument
                    pshs      u         pass node
                    lbsr      ResolveExprType resolve node result type
                    leas      2,s        drop argument
                    ldd       6,u       get node result type
                    cmpd      #112      already double
                    beq       CoerceRet2 yes nothing to do
                    pshs      u         save node
                    ldd       #119      conversion operator code
                    pshs      d         push operator
                    ldd       #112      target type double
                    pshs      d         push target type
                    ldd       #117      cast node tag
                    pshs      d         push tag
                    lbsr      GenNode   build conversion tree node
                    leas      8,s        drop the arguments
                    ldd       #112      result type double
                    bra       SetNodeTypeRet store type and return

CoerceToFloat       pshs      u         save node pointer
                    ldd       #$FFB4    frame size for stack check
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       get node pointer argument
                    pshs      u         pass node
                    lbsr      EvalOperand resolve node result type
                    leas      2,s        drop argument
                    ldd       6,u       get node result type
                    cmpd      #113      already float
                    beq       CoerceRet2 yes nothing to do
                    pshs      u         save node
                    ldd       #119      conversion operator code
                    pshs      d         push operator
                    ldd       #113      target type float
                    pshs      d         push target type
                    ldd       #117      cast node tag
                    pshs      d         push tag
                    lbsr      GenNode   build conversion tree node
                    leas      8,s        drop the arguments
                    ldd       #113      result type float
SetNodeTypeRet      std       6,u       set node result type
CoerceRet2          puls      pc,u      restore and return

ResolveExprType     pshs      u         save node pointer
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       get node pointer argument
                    ldx       ,u        get node operator
                    bra       ResolveTypeDispatch dispatch on operator

ResolveOp8          pshs      u         pass node
                    lbsr      GenExpr   resolve operator $0008
                    bra       ResolveOpDone drop and finish

ResolveOp56         pshs      u         pass node
                    lbsr      GenOperand resolve operators $0005/$0006
                    bra       ResolveOpDone drop and finish

ResolveOpGeneric    pshs      u         pass node
                    lbsr      EvalSubtreeType evaluate subtree type
                    leas      2,s        drop argument
                    pshs      u         pass node
                    bsr       NormalizeFPType normalize result type
ResolveOpDone       leas      2,s        drop argument
                    bra       ResolveTypeRet return

ResolveTypeDispatch cmpx      #8        handle it
                    beq       ResolveOp8 operator is $0005
                    cmpx      #5        handle it
                    beq       ResolveOp56 operator is $0006
                    cmpx      #6        handle it
                    lbeq      ResolveOp56 otherwise generic handling
                    bra       ResolveOpGeneric

ResolveTypeRet      puls      pc,u      restore and return

NormalizeFPType     pshs      u         save node pointer
                    ldd       #$FFB4    frame size for stack check
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       get node pointer argument
                    ldx       6,u       get node result type
                    lbra      NormalizeFPDispatch dispatch on result type

ConvType37ToFloat   pshs      u         save node
                    ldd       #119      conversion operator code
                    pshs      d         push operator
                    ldd       #113      target type float
                    pshs      d         push target type
                    ldd       #117      cast node tag
                    pshs      d         push tag
                    lbsr      GenNode   build conversion tree node
                    leas      8,s        drop the arguments
                    ldd       #113      result type float
                    std       6,u       set node result type
                    clra                clear high byte
                    clrb                clear low byte
                    std       8,u       clear node extra field
                    lbra      NormalizeFPRet return

ConvChildToFloat    ldd       10,u      get node child pointer
                    pshs      d         push child
                    ldd       #119      conversion operator code
                    pshs      d         push operator
                    ldd       #113      target type float
                    pshs      d         push target type
                    ldd       #127      cast node tag
                    pshs      d         push tag
                    lbsr      GenNode   build conversion tree node
                    leas      8,s        drop the arguments
                    clra                clear high byte
                    clrb                clear low byte
                    std       8,u       clear node extra field
                    ldd       #113      result type float
                    bra       SetResultType set type and return

ConvToDoubleDefault pshs      u         save node
                    ldd       #119      conversion operator code
                    pshs      d         push operator
                    ldd       #112      target type double
                    pshs      d         push target type
                    ldd       #117      cast node tag
                    pshs      d         push tag
                    lbsr      GenNode   build conversion tree node
                    leas      8,s        drop the arguments
                    bra       SetTypeDouble set result type double

                    leas      ,x        unreachable filler after branch
SetTypeDouble       ldd       #112      result type double
SetResultType       std       6,u       set node result type
                    bra       NormalizeFPRet return

NormalizeFPDispatch cmpx      #55       type is $0037
                    lbeq      ConvType37ToFloat convert to float
                    cmpx      #65       type is $0041
                    beq       ConvChildToFloat convert child to float
                    cmpx      #113      already float
                    beq       NormalizeFPRet nothing to do
                    cmpx      #112      already double
                    beq       NormalizeFPRet nothing to do
                    cmpx      #111      type is $006F
                    beq       NormalizeFPRet nothing to do
                    cmpx      #118      type is $0076
                    beq       NormalizeFPRet nothing to do
                    bra       ConvToDoubleDefault otherwise convert to double

NormalizeFPRet      puls      pc,u      restore and return

EvalSubtreeType     pshs      u         save node pointer
                    ldd       #$FFB4    frame size for stack check
                    lbsr      stkcheck  check for stack overflow
                    ldu       4,s       get node pointer argument
                    leas      -2,s       reserve local slot
                    ldd       6,u       get node result type
                    std       ,s        save the type
                    cmpd      #48       is it an assignment node
                    bne       EvalNotAssign no other handling
                    leas      -2,s       reserve another local
                    ldd       12,u      get right child pointer
                    std       ,s        save it
                    ldd       10,u      get left child pointer
                    pshs      d         pass to recursion
                    bsr       EvalSubtreeType recurse on left child
                    std       ,s        save resulting type
                    lbsr      FreeExprTree tree helper call
                    leas      2,s        drop argument
                    pshs      u         save node
                    ldd       2,s       get saved value
                    pshs      d         pass it
                    lbsr      ReportDiag22 tree helper call
                    leas      4,s        drop the arguments
                    ldd       ,s        reload local
                    pshs      d         pass it
                    lbsr      LinkFreeNode tree helper call
                    leas      2,s        drop argument
                    pshs      u         save node
                    lbsr      EvalSubtreeType recurse on node
                    leas      2,s        drop argument
                    leas      2,s        release local slot
                    lbra      GenNodeDone3 return result type

EvalNotAssign       ldd       ,u        get node operator
                    cmpd      #8        operator is $0008
                    bne       EvalCheckOp5 no keep checking
                    pshs      u         pass node
                    lbsr      GenExprDispatch handle it
                    leas      2,s        drop argument
                    lbra      GenNodeDone3 return result type

EvalCheckOp5        ldd       ,u        get node operator
                    cmpd      #5        operator is $0005
                    beq       GenKind56 handle it
                    ldd       ,u        load node kind field
                    cmpd      #6        is it kind 6
                    bne       GenInteriorNode no, handle as interior node
GenKind56           pshs      u         pass node pointer
                    lbsr      GenExpr2  emit kind 5/6 leaf
                    leas      2,s        drop argument
                    lbra      GenNodeDone3 return node

GenInteriorNode     ldd       ,s        load operator code argument
                    pshs      d         pass it
                    lbsr      IsTypeCodeInRange test if binary operator
                    std       ,s++      save result and pop
                    beq       GenOpDispatch not binary, dispatch on operator
                    pshs      u         pass node
                    ldd       2,s       load argument code
                    pshs      d         pass it
                    lbsr      GenBinOp  generate binary operator code
                    leas      4,s        drop arguments
                    lbra      GenNodeDone3 return node

GenOpDispatch       ldx       ,s        load operator code
                    lbra      OpDispatch2 dispatch on operator

GenOp78             pshs      u         pass node
                    lbsr      GenIndexedBinOp generate operator 78
                    lbra      PopRet    pop and return

GenOp85             ldd       10,u      load child node
                    pshs      d         pass it
                    lbsr      EvalSubtreeType generate operand
                    lbra      PopRet    pop and return

GenOp84             ldd       10,u      load child node
                    pshs      d         pass it
                    lbsr      GenExprDispatch generate child
                    leas      2,s        drop argument
                    ldd       10,u      reload child node
                    pshs      d         pass it
                    ldd       #119      result type code
                    pshs      d         push it
                    ldd       #132      operator code 84
                    pshs      d         push it
                    lbsr      GenNode   emit instruction node
                    leas      6,s        drop arguments
                    bra       SetType70 set result type and return

GenOp8F             ldd       10,u      load child node
                    pshs      d         pass it
                    lbsr      GenOperand generate child
                    leas      2,s        drop argument
                    ldd       #143      operator code 8F
                    pshs      d         push it
                    ldd       #135      operand code 87
                    pshs      d         push it
                    lbsr      GenNode   emit instruction node
                    bra       PopSetType70 cleanup and set result

GenOp42             pshs      u         pass node
                    lbsr      GenIndirection generate operator 42
                    bra       PopRet    pop and return

GenOp40             pshs      u         pass node
                    lbsr      GenBoolValue generate operators 40/47/48
                    bra       PopRet    pop and return

GenOp44             ldd       10,u      load child node
                    pshs      d         pass it
                    lbsr      CoerceToDouble evaluate operand into register
                    leas      2,s        drop argument
                    ldd       ,s        load operator code
                    pshs      d         push it
                    lbsr      GenNode   emit instruction node
                    leas      2,s        drop argument
                    bra       SetType70 set result type and return

GenOp64             leax      CoerceToDouble,pcr address of operand emitter
                    pshs      x         pass callback
                    pshs      u         pass node
                    lbsr      GenBoolValueCB generate operator 64
PopSetType70        leas      4,s        drop arguments
SetType70           ldd       #112      result type code 70
                    std       6,u       set node operator field
                    lbra      GenNodeDone3 return node

GenRelOp2           ldd       #112      result type code 70
                    pshs      d         push it
                    pshs      u         pass node
                    lbsr      GenBinOp2 generate relational operator
                    bra       Pop4Ret2  pop and return

GenOp65             pshs      u         pass node
                    lbsr      GenExprList generate operator 65
PopRet              leas      2,s        drop argument
                    lbra      GenNodeDone3 return node

GenDefaultOp        ldd       ,s        load operator code
                    cmpd      #160      compare against internal code base
                    blt       GenUnknownOpErr below range, report error
                    ldd       ,s        reload operator code
                    pshs      d         push it
                    pshs      u         pass node
                    lbsr      GenIndexAddr generate high operator
                    bra       Pop4Ret2  pop and return

GenUnknownOpErr     leax      StrTranslation,pcr address of translation message
                    pshs      x         push it
                    pshs      u         pass node
                    lbsr      InternalErr print compiler error
                    leas      4,s        drop arguments
                    ldd       ,s        load operator code
                    pshs      d         push it
                    leax      Data815F,pcr address of hex format
                    pshs      x         push it
                    lbsr      PrintfToBuf print formatted value
Pop4Ret2            leas      4,s        drop arguments
                    lbra      GenNodeDone3 return node

OpDispatch2         cmpx      #55       leaf operator 37
                    lbeq      GenNodeDone3 return unchanged
                    cmpx      #52       leaf operator 34
                    lbeq      GenNodeDone3 return unchanged
                    cmpx      #118      leaf operator 76
                    lbeq      GenNodeDone3 return unchanged
                    cmpx      #111      leaf operator 6F
                    lbeq      GenNodeDone3 return unchanged
                    cmpx      #65       leaf operator 41
                    beq       GenNodeDone3 return unchanged
                    cmpx      #54       constant node 36
                    beq       GenNodeDone3 return unchanged
                    cmpx      #120      operator 78
                    lbeq      GenOp78   handle it
                    cmpx      #133      operator 85
                    lbeq      GenOp85   handle it
                    cmpx      #132      operator 84
                    lbeq      GenOp84   handle it
                    cmpx      #143      operator 8F
                    lbeq      GenOp8F   handle it
                    cmpx      #66       operator 42
                    lbeq      GenOp42   handle it
                    cmpx      #64       operator 40
                    lbeq      GenOp40   handle it
                    cmpx      #71       operator 47
                    lbeq      GenOp40   handle it
                    cmpx      #72       operator 48
                    lbeq      GenOp40   handle it
                    cmpx      #68       operator 44
                    lbeq      GenOp44   handle it
                    cmpx      #67       operator 43
                    lbeq      GenOp44   handle it
                    cmpx      #100      operator 64
                    lbeq      GenOp64   handle it
                    cmpx      #60       operator 3C
                    lbeq      GenRelOp2 handle relational
                    cmpx      #62       operator 3E
                    lbeq      GenRelOp2 handle relational
                    cmpx      #61       operator 3D
                    lbeq      GenRelOp2 handle relational
                    cmpx      #63       operator 3F
                    lbeq      GenRelOp2 handle relational
                    cmpx      #101      operator 65
                    lbeq      GenOp65   handle it
                    lbra      GenDefaultOp default operator handler

GenNodeDone3        tfr       u,d       return value equals node pointer
                    leas      2,s        drop argument
                    puls      pc,u      restore U and return

GenBinOp            pshs      u         save caller U
                    ldd       #$FFAE    stack need in bytes
                    lbsr      stkcheck  check stack space
                    leas      -6,s       allocate local frame
                    ldx       12,s      load node argument
                    ldu       10,x      load left child node
                    ldx       12,s      reload node argument
                    ldd       12,x      load right field
                    std       4,s       save right field to local
                    ldd       ,u        load child kind
                    cmpd      #7        is it kind 7
                    bne       LoadBinOp no, load binary operator
                    ldx       10,s      load operator code
                    bra       ClassifyPtrOp classify pointer operator

SetType4E           ldd       #78       pointer result type 4E
                    bra       StoreOpType store type

SetType4C           ldd       #76       pointer result type 4C
                    bra       StoreOpType store type

SetType4D           ldd       #77       pointer result type 4D
StoreOpType         std       10,s      store chosen result type
                    bra       DispatchBinOp continue to dispatch

ClassifyPtrOp       cmpx      #83       operator 53
                    beq       SetType4E type 4E
                    cmpx      #84       operator 54
                    beq       SetType4C type 4C
                    cmpx      #85       operator 55
                    beq       SetType4D type 4D
                    bra       DispatchBinOp dispatch

LoadBinOp           ldx       10,s      load operator code
                    bra       ClassifyDerefOp classify deref operator

CheckOp41           ldd       6,u       load child operator
                    cmpd      #65       is it operator 41
                    bne       DispatchBinOp no, dispatch
                    ldx       4,s       load right node
                    ldd       6,x       its operator
                    cmpd      #54       is it a constant
                    beq       DispatchBinOp yes, dispatch
                    ldd       12,s      load node argument
                    pshs      d         push it
                    lbsr      EvalOperand fold and generate
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    std       GlbVar0066 clear change flag
                    lbra      GenNodeExit return from binary generation

                    bra       DispatchBinOp fall through to dispatch

ClassifyDerefOp     cmpx      #80       operator 50
                    beq       CheckOp41 handle op 41 case
                    cmpx      #81       operator 51
                    lbeq      CheckOp41 handle op 41 case
DispatchBinOp       ldx       10,s      load operator code
                    lbra      BinOpDispatch dispatch on binary operator

GenAssign2          ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      IsConstNode test operand is simple
                    std       ,s++      save result and pop
                    bne       GenAssignEval not simple, evaluate directly
                    ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      ResolveExprType evaluate operand address
                    leas      2,s        drop argument
                    ldx       4,s       load right node
                    ldd       6,x       its operator
                    pshs      d         push it
                    ldd       #122      operand code 7A
                    pshs      d         push it
                    lbsr      GenNode   emit instruction node
                    leas      4,s        drop arguments
                    ldd       #110      store operator 6E
                    ldx       4,s       load right node
                    std       6,x       set its operator field
                    pshs      u         pass node
                    lbsr      CoerceToDouble evaluate into register
                    bra       GenAssignStore build store node

GenAssignEval       pshs      u         pass node
                    lbsr      CoerceToDouble evaluate into register
                    leas      2,s        drop argument
                    ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      EvalSubtreeType generate operand
GenAssignStore      leas      2,s        drop argument
                    ldd       4,s       load right node
                    pshs      d         push it
                    ldd       #119      result type 77
                    pshs      d         push it
                    ldd       #112      result type 70
                    pshs      d         push it
                    ldd       #81       assign operator 51
                    lbra      EmitBinNode emit binary instruction node

GenCommuteOp        pshs      u         pass node
                    lbsr      IsConstNode test left operand simple
                    std       ,s++      save result and pop
                    beq       CommuteCheckConst not simple
                    ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      IsConstNode test right operand simple
                    std       ,s++      save result and pop
                    beq       SwapOperands2 simple, swap operands
CommuteCheckConst   ldd       6,u       load child operator
                    cmpd      #54       is it a constant
                    bne       TryConstFold no, try fold
SwapOperands2       leas      -2,s       make room to swap
                    stu       ,s        store U
                    ldu       6,s       load other operand
                    ldd       ,s        load saved U
                    std       6,s       store swapped operand
                    leas      2,s        drop temp
TryConstFold        ldd       6,u       load child operator
                    pshs      d         push it
                    lbsr      IsFloatType test constant fold possible
                    std       ,s++      save result and pop
                    beq       GenNonConstOperand cannot fold
                    ldd       6,u       load child operator
EmitLoadStore       pshs      d         push it
                    ldd       #122      operand code 7A
                    pshs      d         push it
                    lbsr      GenNode   emit instruction node
                    leas      4,s        drop arguments
                    ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      CoerceToDouble evaluate into register
                    leas      2,s        drop argument
                    ldd       #110      store operator 6E
                    ldx       4,s       load right node
                    std       6,x       set its operator field
                    bra       GenBinFinish build final node

GenNonConstOperand  pshs      u         pass node
                    lbsr      CoerceToDouble evaluate into register
                    leas      2,s        drop argument
                    ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      IsConstNode test operand simple
                    std       ,s++      save result and pop
                    bne       GenLoadOperand not simple
                    ldd       #112      result type 70
                    bra       EmitLoadStore emit load/store

GenLoadOperand      ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      EvalSubtreeType generate operand
                    leas      2,s        drop argument
                    ldd       10,s      load result type
                    cmpd      #80       is it operator 50
                    beq       GenBinFinish yes, finish
                    ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      FixFlaggedNode generate operand load
                    leas      2,s        drop argument
GenBinFinish        ldd       4,s       load right node
                    pshs      d         push it
                    ldd       #119      result type 77
                    pshs      d         push it
                    ldd       #112      result type 70
                    pshs      d         push it
                    ldd       16,s      load operator code
EmitBinNode         pshs      d         push it
                    lbsr      GenNode   emit binary instruction node
                    leas      8,s        drop arguments
                    lbra      ClrFlagSetResult finish binary generation

GenUnaryOp          ldd       12,s      load node argument
                    pshs      d         push it
                    lbsr      GenBoolValue generate unary operator
                    lbra      GenUnaryDone finish generation

GenShiftByConst     ldx       4,s       load right node
                    ldd       6,x       its operator
                    cmpd      #54       is it a constant
                    lbne      GenBinFallback no, use general path
                    ldx       4,s       load right node
                    ldd       8,x       load constant value
                    std       ,s        save as count
                    bra       CheckShiftCount check count

ShiftRetry          leas      -6,x      restore stack
CheckShiftCount     ldd       ,s        load count
                    cmpd      #4        small enough to expand
                    bhi       GenBinFallback too big, general path
                    pshs      u         pass node
                    lbsr      CoerceToDouble evaluate into register
ShiftLoopNext       leas      2,s        drop argument
                    bra       ShiftCountLoop enter count loop test

EmitShiftStep       ldx       10,s      load operator code
                    bra       ShiftCodeSwitch pick shift-add code

ShiftCode98         ldd       #152      shift-add code 98
                    bra       EmitShiftCode emit it

ShiftCode96         ldd       #150      shift-add code 96
                    bra       EmitShiftCode emit it

ShiftCode97         ldd       #151      shift-add code 97
EmitShiftCode       pshs      d         push code
                    lbsr      GenNode   emit shift-add node
                    bra       ShiftLoopNext next iteration

ShiftCodeSwitch     cmpx      #86       operator 56
                    beq       ShiftCode98 code 98
                    cmpx      #85       operator 55
                    beq       ShiftCode96 code 96
                    cmpx      #77       operator 4D
                    beq       ShiftCode97 code 97
ShiftCountLoop      ldd       ,s        load count
                    addd      #$FFFF    decrement
                    std       ,s        save count
                    subd      #$FFFF    test original count
                    bne       EmitShiftStep more steps to emit
                    ldd       #1        changed flag
                    std       GlbVar0066 set change flag
                    leax      6,s       drop locals
                    lbra      AdjStackSetResult set result type and return

GenBinFallback      leax      6,s       drop locals
                    bra       GenBinRestore emit general binary sequence

GenConstFold        ldd       6,u       load child operator
                    cmpd      #54       is it a constant
                    bne       FoldCheckConst no, check right operand
                    leas      -2,s       make room to swap
                    stu       ,s        store U
                    ldu       6,s       load other operand
                    ldd       ,s        load saved U
                    std       6,s       store swapped operand
                    leas      2,s        drop temp
FoldCheckConst      ldx       4,s       load right node
                    ldd       6,x       its operator
                    cmpd      #54       is it a constant
                    bne       EmitBinGeneral no, emit general
                    ldx       4,s       load right node
                    ldd       8,x       load constant value
                    pshs      d         push it
                    lbsr      FindTableIndex fold constant operation
                    leas      2,s        drop argument
                    std       ,s        save folded value
                    beq       EmitBinGeneral no fold, emit general
                    ldd       ,s        load folded value
                    ldx       4,s       load right node
                    std       8,x       store folded constant
                    ldd       10,s      load result type
                    cmpd      #82       is it operator 52
                    bne       FoldCode4D no, use code 4D
                    ldd       #86       folded result code 56
                    bra       StoreFoldType store type

FoldCode4D          ldd       #77       folded result code 4D
StoreFoldType       std       10,s      store result type
                    leax      6,s       drop locals
                    lbra      ShiftRetry retry shift reduction

GenBinRestore       leas      -6,x      restore stack
EmitBinGeneral      pshs      u         pass node
                    lbsr      ResolveExprType evaluate operand address
                    leas      2,s        drop argument
                    ldd       6,u       load child operator
                    pshs      d         push it
                    ldd       #122      operand code 7A
                    pshs      d         push it
                    lbsr      GenNode   emit instruction node
                    leas      4,s        drop arguments
                    ldd       4,s       load right node
                    pshs      d         push it
                    lbsr      CoerceToDouble evaluate into register
                    leas      2,s        drop argument
                    ldd       10,s      load operator code
                    pshs      d         push it
                    lbsr      GenNode   emit binary instruction node
GenUnaryDone        leas      2,s        drop argument
                    lbra      ClrFlagSetResult finish binary generation

GenBinOpErr         leax      StrBinaryOp,pcr address of binary op message
                    pshs      x         push it
                    ldd       14,s      load operator code
                    pshs      d         push it
                    lbsr      InternalErr print compiler error
                    leas      4,s        drop arguments
                    lbra      ClrFlagSetResult finish binary generation

BinOpDispatch       cmpx      #81       assign operator 51
                    lbeq      GenAssign2 generate assignment
                    cmpx      #87       commutative operator 57
                    lbeq      GenCommuteOp generate commutative op
                    cmpx      #88       operator 58
                    lbeq      GenCommuteOp matches, dispatch to GenCommuteOp handler
                    cmpx      #89       operator code $59
                    lbeq      GenCommuteOp matches, dispatch to GenCommuteOp handler
                    cmpx      #80       operator code $50
                    lbeq      GenCommuteOp matches, dispatch to GenCommuteOp handler
                    cmpx      #90       operator code $5A
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #91       operator code $5B
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #95       operator code $5F
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #93       operator code $5D
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #92       operator code $5C
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #94       operator code $5E
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #99       operator code $63
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #97       operator code $61
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #96       operator code $60
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #98       operator code $62
                    lbeq      GenUnaryOp matches, compare handler GenUnaryOp
                    cmpx      #77       operator code $4D
                    lbeq      GenShiftByConst matches, handler GenShiftByConst
                    cmpx      #85       operator code $55
                    lbeq      GenShiftByConst matches, handler GenShiftByConst
                    cmpx      #86       operator code $56
                    lbeq      GenShiftByConst matches, handler GenShiftByConst
                    cmpx      #82       operator code $52
                    lbeq      GenConstFold matches, handler GenConstFold
                    cmpx      #78       operator code $4E
                    lbeq      FoldCheckConst matches, handler FoldCheckConst
                    cmpx      #83       operator code $53
                    lbeq      EmitBinGeneral matches, handler EmitBinGeneral
                    cmpx      #76       operator code $4C
                    lbeq      EmitBinGeneral matches, handler EmitBinGeneral
                    cmpx      #84       operator code $54
                    lbeq      EmitBinGeneral matches, handler EmitBinGeneral
                    lbra      GenBinOpErr no match, default handler GenBinOpErr

                    leas      -6,x      set stack to frame minus locals
ClrFlagSetResult    clra                clear high byte
                    clrb                clear low byte
                    std       GlbVar0066 clear temp flag $0066
                    bra       SetResultType2 go set node result type

AdjStackSetResult   leas      -6,x      restore stack from frame in X
SetResultType2      ldd       #112      result node type $0070 (value in register)
                    ldx       12,s      get the node pointer
                    std       6,x       store result type into node
                    lbra      GenNodeExit jump to common node exit

FindTableIndex      pshs      u         save u
                    ldd       #$FFC0    frame size -64 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       #0        table index starts at zero
                    bra       FindTableTest enter search loop test

FindTableLoop       tfr       u,d       index into D for offset calculation
                    leau      1,u       pre-advance table index
                    aslb                index times two, low byte
                    rola                high byte of word offset
                    leax      TableBase,y   point at table base
                    leax      d,x       address of this table entry
                    ldd       ,x        load the entry value
                    cmpd      4,s       equals the search key
                    bne       FindTableTest no, continue scanning
                    tfr       u,d       return matching index
                    puls      pc,u      restore and return

FindTableTest       cmpu      #14       scanned all 14 entries
                    blt       FindTableLoop no, test next entry
                    lbra      PredFalse not found, return zero

GenBoolValue        pshs      u         save u
                    ldd       #$FFB0    frame size -80 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       4,s       node pointer argument
                    leas      -4,s       allocate locals
                    ldd       #1        constant one
                    pshs      d         push it
                    ldd       GlbVar000B global label counter
                    addd      #1        next label number
                    std       GlbVar000B update the counter
                    std       2,s       save as label1
                    pshs      d         push it
                    ldd       GlbVar000B global label counter
                    addd      #1        next label number
                    std       GlbVar000B update the counter
                    std       6,s       save as label2
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      GenTestExpr emit compare and branch to labels
                    leas      8,s        drop arguments
                    ldd       2,s       label1 number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit label1 definition
                    leas      2,s        drop argument
                    ldd       #1        immediate value one
                    pshs      d         push it
                    ldd       #54       operand kind $36
                    pshs      d         push it
                    ldd       #112      result type $70
                    pshs      d         push it
                    ldd       #117      load-immediate opcode $75
                    pshs      d         push it
                    lbsr      GenNode   emit load of one
                    leas      8,s        drop arguments
                    ldd       #1        value one
                    pshs      d         push it
                    ldd       GlbVar000B global label counter
                    addd      #1        next label number
                    std       GlbVar000B update the counter
                    std       4,s       save as label3
                    pshs      d         push it
                    ldd       #124      jump opcode $7C
                    pshs      d         push it
                    lbsr      GenNode   emit jump to label3
                    leas      6,s        drop arguments
                    ldd       ,s        label2 number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit label2 definition
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                value zero
                    pshs      d         push it
                    ldd       #54       operand kind $36
                    pshs      d         push it
                    ldd       #112      result type $70
                    pshs      d         push it
                    ldd       #117      load-immediate opcode $75
                    pshs      d         push it
                    lbsr      GenNode   emit load of zero
                    leas      8,s        drop arguments
                    ldd       2,s       label3 number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit label3 definition
                    leas      2,s        drop argument
                    ldd       #112      result type $70
                    std       6,u       mark node result type
                    lbra      OperandRet jump to common exit

GenBoolValueCB      pshs      u         save u
                    ldd       #$FFAE    frame size -82 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       4,s       node pointer argument
                    leas      -6,s       allocate locals
                    ldd       #1        value one
                    pshs      d         push it
                    ldd       GlbVar000B global label counter
                    addd      #1        next label number
                    std       GlbVar000B update the counter
                    std       2,s       save as label1
                    pshs      d         push it
                    ldd       GlbVar000B global label counter
                    addd      #1        next label number
                    std       GlbVar000B update the counter
                    std       8,s       save as label2
                    pshs      d         push it
                    ldd       10,u      left child pointer
                    pshs      d         push it
                    lbsr      GenTestExpr emit compare and branch
                    leas      8,s        drop arguments
                    ldu       12,u      right child pointer
                    ldd       4,s       label1 number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit label1 definition
                    leas      2,s        drop argument
                    ldd       10,u      operand pointer
                    pshs      d         push it
                    jsr       [14,s]    call operand-generator callback
                    leas      2,s        drop argument
                    clra                clear high byte
                    clrb                value zero
                    pshs      d         push it
                    ldd       GlbVar000B global label counter
                    addd      #1        next label number
                    std       GlbVar000B update the counter
                    std       4,s       save as label3
                    pshs      d         push it
                    ldd       #124      jump opcode $7C
                    pshs      d         push it
                    lbsr      GenNode   emit jump to label3
                    leas      6,s        drop arguments
                    ldd       ,s        label2 number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit label2 definition
                    leas      2,s        drop argument
                    ldd       12,u      operand pointer
                    pshs      d         push it
                    jsr       [14,s]    call operand-generator callback
                    leas      2,s        drop argument
                    ldd       2,s       label3 number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit label3 definition
                    leas      2,s        drop argument
GenNodeExit         leas      6,s        drop locals
                    puls      pc,u      restore and return

GenExprList         pshs      u         save u
                    ldd       #$FFB2    frame size -78 bytes
                    lbsr      stkcheck  check for stack space
                    leas      -4,s       allocate locals
                    ldd       GlbVar000F save current global pointer $000F
                    std       ,s        stash on stack
                    ldd       8,s       list head argument
                    std       2,s       iterator = head
                    lbra      GenListLoop enter the list loop

GenListItem         ldx       2,s       current list node
                    ldu       10,x      its child expression
                    ldd       ,u        child node type
                    cmpd      #8        is it type $08
                    bne       GenListCheckType no
                    ldd       6,u       child op field
                    cmpd      #74       is it $4A
                    bne       GenChildOp88 no
                    pshs      u         push child
                    lbsr      GenAddConst handle special $4A node
                    leas      2,s        drop argument
                    lbra      GenListLoop go to next list item

GenChildOp88        pshs      u         push child
                    lbsr      GenExpr   evaluate the child
                    leas      2,s        drop argument
                    ldd       #110      operand $6E
                    pshs      d         push it
                    ldd       #136      opcode $88
                    bra       EmitListOp emit and continue

GenListCheckType    ldd       ,u        child node type
                    cmpd      #5        is it type $05
                    beq       GenChildOp87 yes
                    ldd       ,u        child node type
                    cmpd      #6        is it type $06
                    bne       GenListDefault neither, general case
GenChildOp87        pshs      u         push child
                    lbsr      GenOperand generate for type $05/$06
                    leas      2,s        drop argument
                    ldd       #110      operand $6E
                    pshs      d         push it
                    ldd       #135      opcode $87
                    bra       EmitListOp emit and continue

GenListDefault      pshs      u         push child
                    lbsr      EvalSubtreeType evaluate expression to operand
                    leas      2,s        drop argument
                    ldx       6,u       result operand type
                    bra       CheckInReg already register-resident

ForceToReg          pshs      u         push operand
                    lbsr      NormalizeFPType load operand into register
                    leas      2,s        drop argument
                    bra       EmitListStmt emit the statement

CheckInReg          cmpx      #112      result type $70
                    beq       EmitListStmt yes, already usable
                    cmpx      #113      result type $71
                    beq       EmitListStmt yes, already usable
                    cmpx      #111      result type $6F
                    beq       EmitListStmt yes, already usable
                    cmpx      #118      result type $76
                    beq       EmitListStmt yes, already usable
                    bra       ForceToReg otherwise force into register

EmitListStmt        ldd       6,u       result operand
                    pshs      d         push it
                    ldd       #122      statement opcode $7A
EmitListOp          pshs      d         push it
                    lbsr      GenNode   emit statement code
                    leas      4,s        drop arguments
GenListLoop         ldx       2,s       current list node
                    ldd       12,x      next-in-list link
                    std       2,s       advance iterator
                    lbne      GenListItem process it if not end of list
                    ldx       8,s       list head node
                    ldd       10,x      head expression
                    pshs      d         push it
                    lbsr      EvalSubtreeType evaluate final expression
                    leas      2,s        drop argument
                    ldx       8,s       list head node
                    ldd       10,x      head expression again
                    pshs      d         push it
                    ldd       #119      operand $77
                    pshs      d         push it
                    ldd       #101      opcode $65
                    pshs      d         push it
                    lbsr      GenNode   emit final operation
                    leas      6,s        drop arguments
                    ldd       ,s        saved global pointer
                    pshs      d         push it
                    lbsr      EmitReserveSpace restore and emit
                    leas      2,s        drop argument
                    std       GlbVar000F restore global $000F
                    ldd       #112      result type $70
                    ldx       8,s       list node
                    std       6,x       mark result type
                    lbra      OperandRet jump to common exit

IsIndexable         pshs      u         save u
                    ldd       #$FFB8    frame size -72 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       4,s       node pointer argument
                    leas      -2,s       allocate a local
                    ldx       6,u       node operand type
                    bra       ClassifyNode classify the node

InspectDeref        ldd       10,u      left child pointer
                    std       ,s        save the child
                    tfr       d,x       child into X
                    ldx       6,x       child operand type
                    bra       ClassifyChild classify the child

IndexTrue           ldd       #1        result true
                    bra       IsIndexableExit go return it

TestChildAddr       ldd       ,s        saved child
                    pshs      d         push it
                    bsr       IsConstOffset is child a constant-offset address
                    leas      2,s        drop argument
                    bra       IsIndexableExit go return result

ClassifyChild       cmpx      #54       child type $36
                    beq       IndexTrue yes, indexable
                    cmpx      #52       child type $34
                    lbeq      IndexTrue yes, indexable
                    cmpx      #118      child type $76
                    lbeq      IndexTrue yes, indexable
                    cmpx      #111      child type $6F
                    lbeq      IndexTrue yes, indexable
                    bra       TestChildAddr else test via IsConstOffset

ClassifyNode        cmpx      #52       node type $34
                    lbeq      IndexTrue indexable
                    cmpx      #54       node type $36
                    lbeq      IndexTrue indexable
                    cmpx      #66       node type $42 (deref)
                    beq       InspectDeref inspect its child
                    clra                clear high byte
                    clrb                result false
IsIndexableExit     leas      2,s        drop local
                    puls      pc,u      restore and return

IsConstOffset       pshs      u         save u
                    ldd       #$FFBA    frame size -70 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       4,s       node pointer argument
                    ldx       6,u       node operand type
                    bra       IsConstOffsetCheck classify the node

CheckAddrOperands   ldx       10,u      left child pointer
                    ldd       6,x       child operand type
                    pshs      d         push it
                    lbsr      IsFloatType is it a constant
                    std       ,s++      save result and drop
                    lbeq      PredFalse not constant, return zero
                    ldx       12,u      right child pointer
                    ldd       6,x       right operand type
                    cmpd      #54       is base type $36
                    lbne      PredFalse no, return zero
                    bra       PredTrue  yes, return one

                    lbra      PredFalse (unreached) return zero

IsConstOffsetCheck  cmpx      #80       op $50 (add)
                    beq       CheckAddrOperands check operands
                    cmpx      #81       op $51 (subtract)
                    lbeq      CheckAddrOperands check operands
                    bra       PredFalse else return zero

IsLowRefCount       pshs      u         save u
                    ldd       #$FFC0    frame size -64 bytes
                    lbsr      stkcheck  check for stack space
                    ldx       4,s       node pointer argument
                    ldd       18,x      node use/size field
                    cmpd      #2        is it two or more
                    bge       PredFalse yes, return zero
                    ldd       #1        else return one
                    bra       PredExit  go return it

IsLocalAddr         pshs      u         save u
                    ldd       #$FFC0    frame size -64 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       4,s       node pointer argument
                    ldx       6,u       node operand type
                    bra       ClassifyFrameNode classify the node

CheckFrameChild     ldx       10,u      left child pointer
                    ldd       6,x       child operand type
                    cmpd      #65       is it type $41
                    bne       PredFalse no, return zero
PredTrue            ldd       #1        return one
                    puls      pc,u      restore and return

                    bra       PredFalse (unreached) return zero

ClassifyFrameNode   cmpx      #80       op $50
                    beq       CheckFrameChild check the child
                    cmpx      #81       op $51
                    lbeq      CheckFrameChild check the child
                    cmpx      #55       node type $37
                    beq       PredTrue  return one
                    cmpx      #65       node type $41
                    lbeq      PredTrue  return one
PredFalse           clra                clear high byte
                    clrb                return zero
PredExit            puls      pc,u      restore and return

FixFlaggedNode      pshs      u         save u
                    ldd       #$FFB4    frame size -76 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       4,s       node pointer argument
                    ldd       6,u       node operand type
                    anda      #$80      test high flag bit
                    clrb                clear low byte
                    std       -2,s      save the flag
                    beq       FixFlaggedDone bit clear, nothing to do
                    ldd       6,u       node operand type
                    anda      #$7f      clear the flag bit
                    std       6,u       store cleaned type back
                    pshs      u         push node
                    ldd       #119      operand $77
                    pshs      d         push it
                    ldd       #113      result type $71
                    pshs      d         push it
                    ldd       #117      load-immediate opcode $75
                    pshs      d         push it
                    lbsr      GenNode   emit load for flagged node
                    leas      8,s        drop arguments
                    ldd       #147      new result type $93
                    std       6,u       update node type
                    clra                clear high byte
                    clrb                value zero
                    std       8,u       clear node field $08
FixFlaggedDone      puls      pc,u      restore and return

GenIndexedBinOp     pshs      u         save u
                    ldd       #$FFB0    frame size -80 bytes
                    lbsr      stkcheck  check for stack space
                    leas      -4,s       allocate locals
                    ldx       8,s       node pointer argument
                    ldd       12,x      right child pointer
                    std       ,s        save the right child
                    ldx       8,s       node pointer argument
                    ldu       10,x      left child pointer
                    ldd       6,u       left operand type
                    pshs      d         push it
                    lbsr      IsFloatType is left a constant
                    std       ,s++      save result and drop
                    lbeq      GenAddrFold not constant, take other path
                    ldd       ,s        right child
                    pshs      d         push it
                    lbsr      IsConstOffset is right a constant-offset address
                    std       ,s++      save result and drop
                    beq       GenPlainOperand no, plain evaluation
                    ldd       ,s        right child
                    pshs      d         push it
                    lbsr      EvalOperand generate indexed via address expr
                    bra       GenIndexedNext continue

GenPlainOperand     ldd       ,s        right child
                    pshs      d         push it
                    lbsr      EvalSubtreeType evaluate right operand
GenIndexedNext      leas      2,s        drop argument
                    ldx       ,s        reload local
                    ldx       6,x       get subtree operator field
                    bra       SubOpDispatch dispatch on operator

EmitLoad41          ldx       ,s        X = saved node pointer
                    ldd       10,x      D = node subtree field
                    pshs      d         push as emit operand
                    ldd       #119      code template $77
                    pshs      d         push template
                    ldd       6,u       D = subtree operator
                    pshs      d         push operand
                    ldd       #127      code template $7F
                    bra       EmitLoadTail join shared emit tail

EmitLoad85          ldd       ,s        D = saved value
                    pshs      d         push operand
                    ldd       #119      code template $77
                    pshs      d         push template
                    ldd       #112      code template $70
                    pshs      d         push template
                    ldd       #117      code template $75
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
EmitLoadDefault     ldd       ,s        D = saved value
                    pshs      d         push operand
                    ldd       #119      code template $77
                    pshs      d         push template
                    ldd       6,u       D = subtree operator
                    pshs      d         push operand
                    ldd       #117      code template $75
EmitLoadTail        pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
                    lbra      StoreResultOp go store result

SubOpDispatch       cmpx      #65       operator $41
                    beq       EmitLoad41 yes, emit case $41
                    cmpx      #133      operator $85
                    beq       EmitLoad85 yes, emit case $85
                    bra       EmitLoadDefault else default emit

GenAddrFold         pshs      u         save node pointer
                    lbsr      IsIndexable test node type
                    std       ,s++      save result, pop
                    beq       TryFieldOpt false, try field path
                    ldd       ,u        D = node type field
                    cmpd      #2        compare to 2
                    beq       TryFieldOpt equal, field path
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      IsConstOffset test node type
                    std       ,s++      save result, pop
                    bne       GenAddrSub true, generate address
                    ldd       ,s        reload operand
                    pshs      d         push arg
                    lbsr      IsLocalAddr test node type
                    std       ,s++      save result, pop
                    beq       TryFieldOpt false, field path
GenAddrSub          pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    leas      2,s        drop arg
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      ForceRegister emit address code
                    lbra      DropArg   go finish

TryFieldOpt         ldx       ,s        X = node pointer
                    ldd       6,x       D = node operator
                    pshs      d         push arg
                    lbsr      IsFloatType test node type
                    std       ,s++      save result, pop
                    beq       TryAutoOpt false, try auto path
                    pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    leas      2,s        drop arg
                    ldd       ,u        D = node type field
                    cmpd      #2        compare to 2
                    lbne      EmitAddrResult not 2, emit result
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    bra       DropArg   go finish

TryAutoOpt          pshs      u         push node pointer
                    lbsr      IsLowRefCount test node type
                    std       ,s++      save result, pop
                    beq       GenPtrAddr false, try pointer path
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    leas      2,s        drop arg
                    pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    bra       DropArg   go finish

GenPtrAddr          pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    leas      2,s        drop arg
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      IsIndexable test node type
                    std       ,s++      save result, pop
                    bne       EmitAddrOp true, emit address op
                    ldd       6,u       D = node operator
                    anda      #$7f      mask indirect bit
                    tfr       d,x       X = operator
                    bra       CheckSkipNorm check operator

NormalizeSub        pshs      u         push node pointer
                    lbsr      NormalizeNode normalize node
                    leas      2,s        drop arg
                    bra       EmitAddrOp emit address op

CheckSkipNorm       cmpx      #149      operator $95
                    beq       EmitAddrOp skip normalize
                    cmpx      #148      operator $94
                    beq       EmitAddrOp skip normalize
                    bra       NormalizeSub else normalize node

EmitAddrOp          ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      ResolveExprType emit code
DropArg             leas      2,s        drop arg
EmitAddrResult      pshs      u         push node pointer
                    ldd       #119      code template $77
                    pshs      d         push template
                    ldx       4,s       X = node pointer
                    ldd       6,x       D = node operator
                    pshs      d         push operand
                    ldd       #121      code template $79
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
                    ldx       ,s        X = node pointer
                    ldd       6,x       D = node operator
                    lbra      StoreResult go store result

GenIndexAddr        pshs      u         save caller U
                    ldd       #$FFB0    frame size -80
                    lbsr      stkcheck  check and extend stack
                    leas      -4,s       allocate locals
                    ldx       8,s       X = arg node pointer
                    ldd       12,x      D = node field $0C
                    std       2,s       save to local
                    ldx       8,s       X = arg node pointer
                    ldu       10,x      U = subtree pointer
                    pshs      u         push subtree
                    lbsr      EvalSubtreeType generate subexpression
                    leas      2,s        drop arg
                    ldd       10,s      D = saved field
                    addd      #$FFB0    adjust by -80
                    std       10,s      store back
                    ldd       ,u        D = subtree type field
                    cmpd      #7        compare to 7
                    bne       AfterIndexSel not 7, skip reg select
                    ldx       10,s      X = adjusted value
                    bra       RegIndexSel dispatch register

SelTmpl4E           ldd       #78       code template $4E
                    bra       StoreIndexTmpl store template

SelTmpl4D           ldd       #77       code template $4D
                    bra       StoreIndexTmpl store template

SelTmpl4C           ldd       #76       code template $4C
StoreIndexTmpl      std       10,s      save selected template
                    bra       AfterIndexSel continue

RegIndexSel         cmpx      #83       register code $53
                    beq       SelTmpl4E select template $4E
                    cmpx      #85       register code $55
                    beq       SelTmpl4D select template $4D
                    cmpx      #84       register code $54
                    beq       SelTmpl4C select template $4C
AfterIndexSel       ldd       6,u       D = subtree operator
                    anda      #$7f      mask indirect bit
                    std       ,s        save operator local
                    pshs      d         push arg
                    lbsr      IsFloatType test node type
                    std       ,s++      save result, pop
                    lbeq      EmitIndirectLoad false, emit indirect load
                    ldx       10,s      X = index value
                    lbra      IndexOpDispatch dispatch index operator

GenConstIndex       ldx       2,s       X = local node field
                    ldd       6,x       D = operator
                    cmpd      #54       constant operator $36
                    bne       GenExprIndex not constant, expr index
                    ldd       10,s      D = index value
                    cmpd      #80       operator $50
                    bne       NegConstIndex else negate index
                    ldx       2,s       X = node pointer
                    ldd       8,x       D = constant value
                    bra       EmitConstIndex emit constant index

NegConstIndex       ldx       2,s       X = node pointer
                    ldd       8,x       D = constant value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #0        finish two's complement
EmitConstIndex      pshs      d         push const index
                    ldd       #54       code template $36
                    pshs      d         push template
                    ldd       4,s       D = operand
                    pshs      d         push operand
                    ldd       #116      code template $74
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
                    bra       StoreResultOp go store result

GenExprIndex        ldd       2,s       D = local node field
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit index code
                    leas      2,s        drop arg
                    ldd       10,s      D = index value
                    cmpd      #81       operator $51
                    bne       EmitExprIndex skip complement emit
                    ldd       #67       code template $43
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      2,s        drop arg
EmitExprIndex       ldd       #112      code template $70
                    pshs      d         push template
                    ldd       2,s       D = local operand
                    pshs      d         push operand
                    ldd       #116      code template $74
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      6,s        drop three args
StoreResultOp       ldd       6,u       D = subtree operator
StoreResult         ldx       8,s       X = result node
                    std       6,x       store result operator
                    clra                zero A
                    clrb                zero B
                    ldx       8,s       X = result node
                    std       8,x       clear node value field
                    lbra      OperandRet return

RegIndexIndirect    leax      4,s       X = frame base +4
                    bra       RestoreStack go restore stack

EmitAddrIndex       ldd       6,u       D = subtree operator
                    pshs      d         push operand
                    ldd       #122      code template $7A
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      4,s        drop two args
                    ldd       2,s       D = local operand
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    leas      2,s        drop arg
                    ldd       10,s      D = index value
                    pshs      d         push operand
                    lbsr      GenNode   emit code
                    leas      2,s        drop arg
                    lbra      EmitLoadResult emit load result

IndexOpDispatch     cmpx      #80       operator $50
                    lbeq      GenConstIndex constant/expr index
                    cmpx      #81       operator $51
                    lbeq      GenConstIndex constant/expr index
                    cmpx      #87       operator $57
                    beq       RegIndexIndirect register index
                    cmpx      #88       operator $58
                    lbeq      RegIndexIndirect register index
                    cmpx      #89       operator $59
                    lbeq      RegIndexIndirect register index
                    bra       EmitAddrIndex else emit address index

RestoreStack        leas      -4,x      reset stack from X
EmitIndirectLoad    pshs      u         push node pointer
                    ldd       #119      code template $77
                    pshs      d         push template
                    ldd       #112      code template $70
                    pshs      d         push template
                    ldd       #117      code template $75
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
                    ldd       ,u        D = node type field
                    cmpd      #2        compare to 2
                    bne       AfterMoveEmit not 2, skip extra emit
                    ldd       #133      code template $85
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      2,s        drop arg
AfterMoveEmit       ldx       10,s      X = index value
                    lbra      IndirectOpDispatch dispatch indirect operator

GenRegIndirect      ldd       2,s       D = local node field
                    pshs      d         push arg
                    lbsr      IsIndexable test node type
                    std       ,s++      save result, pop
                    beq       GenMemIndirect false, memory indirect
                    ldd       2,s       D = local node field
                    pshs      d         push arg
                    lbsr      EvalSubtreeType generate subexpression
                    leas      2,s        drop arg
                    ldx       10,s      X = index value
                    bra       SpillRegDispatch dispatch spill

SpillRegAddr        ldd       2,s       D = local node field
                    pshs      d         push arg
                    lbsr      FixFlaggedNode spill register address
                    leas      2,s        drop arg
                    bra       EmitRegLoad emit register load

SpillRegDispatch    cmpx      #87       operator $57
                    beq       SpillRegAddr spill register
                    cmpx      #88       operator $58
                    lbeq      SpillRegAddr spill register
                    cmpx      #89       operator $59
                    lbeq      SpillRegAddr spill register
EmitRegLoad         ldd       2,s       D = local node field
                    pshs      d         push operand
                    ldd       #119      code template $77
                    pshs      d         push template
                    ldd       #112      code template $70
                    pshs      d         push template
                    ldd       16,s      D = frame operand
                    pshs      d         push operand
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
                    lbra      EmitLoadResult emit load result

GenMemIndirect      ldd       ,s        D = local template
                    cmpd      #148      template $94
                    beq       EmitMemDeref skip normalize
                    ldd       ,s        reload template
                    cmpd      #149      template $95
                    beq       EmitMemDeref skip normalize
                    pshs      u         push node pointer
                    lbsr      NormalizeNode normalize node
                    leas      2,s        drop arg
EmitMemDeref        ldd       #112      code template $70
                    pshs      d         push template
                    ldd       #122      code template $7A
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      4,s        drop two args
                    ldd       2,s       D = local node field
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    leas      2,s        drop arg
                    ldd       10,s      D = index value
                    cmpd      #81       operator $51
                    bne       EmitMemLoad skip template swap
                    ldd       #79       code template $4F
                    std       10,s      replace index with $4F
EmitMemLoad         ldd       #110      code template $6E
                    pshs      d         push template
                    ldd       #112      code template $70
                    pshs      d         push template
                    ldd       14,s      D = frame operand
                    pshs      d         push operand
                    lbsr      GenNode   emit code
                    leas      6,s        drop three args
                    bra       EmitLoadResult emit load result

IndirectOpDispatch  cmpx      #87       operator $57
                    lbeq      GenRegIndirect register indirect
                    cmpx      #88       operator $58
                    lbeq      GenRegIndirect register indirect
                    cmpx      #89       operator $59
                    lbeq      GenRegIndirect register indirect
                    cmpx      #80       operator $50
                    lbeq      GenRegIndirect register indirect
                    cmpx      #81       operator $51
                    lbeq      GenRegIndirect register indirect
                    lbra      GenMemIndirect else memory indirect

EmitLoadResult      pshs      u         push node pointer
                    ldd       #119      code template $77
                    pshs      d         push template
                    ldd       #112      code template $70
                    pshs      d         push template
                    ldd       #121      code template $79
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
                    ldd       #112      result operator $70
                    ldx       8,s       X = result node
                    std       6,x       store result operator
                    lbra      OperandRet return

NormalizeNode       pshs      u         save caller U
                    ldd       #$FFB4    frame size -76
                    lbsr      stkcheck  check and extend stack
                    ldu       4,s       U = arg node pointer
                    ldd       6,u       D = node operator
                    anda      #$7f      mask indirect bit
                    cmpd      #52       operator $34 leaf
                    bne       NormEmitBase not leaf, process node
                    puls      pc,u      already normal, return

NormEmitBase        pshs      u         push node pointer
                    lbsr      FixFlaggedNode emit base address
                    leas      2,s        drop arg
                    ldd       8,u       D = node value field
                    beq       NormFinishOp zero offset, skip emit
                    ldd       8,u       D = node value
                    pshs      d         push operand
                    ldd       #54       code template $36
                    pshs      d         push template
                    ldd       #113      code template $71
                    pshs      d         push template
                    ldd       #116      code template $74
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
NormFinishOp        ldd       #113      code template $71
                    pshs      d         push template
                    ldd       #122      code template $7A
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      4,s        drop two args
                    ldd       #$806E    operator $6E with indirect bit
                    std       6,u       store node operator
                    puls      pc,u      return

GenIndirection      pshs      u         save caller U
                    ldd       #$FFB0    frame size -80
                    lbsr      stkcheck  check and extend stack
                    ldu       4,s       U = arg node pointer
                    leas      -4,s       allocate locals
                    ldd       10,u      D = subtree pointer
                    std       2,s       save to local
                    pshs      d         push arg
                    lbsr      EvalOperand process subtree
                    leas      2,s        drop arg
                    ldx       2,s       X = subtree pointer
                    ldd       6,x       D = subtree operator
                    std       ,s        save operator local
                    anda      #$80      isolate indirect bit
                    clrb                clear low byte
                    std       -2,s      save indirect flag
                    lbeq      ClassifyTop not indirect, other path
                    ldd       ,s        reload operator
                    anda      #$7f      mask indirect bit
                    std       ,s        save masked operator
                    tfr       d,x       X = operator
                    bra       OperandIsAddr dispatch operator

EmitIndConst        ldx       2,s       X = subtree pointer
                    ldd       8,x       D = subtree value
                    pshs      d         push operand
                    ldd       2,s       D = local operand
                    pshs      d         push operand
                    ldd       #113      code template $71
                    pshs      d         push template
                    ldd       #117      code template $75
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      8,s        drop four args
                    bra       MakePtrResult continue

IndirectionErr      leax      StrIndirection,pcr X = indirection message
                    pshs      x         push message pointer
                    ldd       4,s       D = line/node arg
                    pshs      d         push arg
                    lbsr      InternalErr report error
                    leas      4,s        drop two words of locals
                    bra       MakePtrResult build pointer-type result

OperandIsAddr       cmpx      #52       operand a constant node
                    beq       EmitIndConst yes, already address form
                    cmpx      #147      operand a pointer type
                    lbeq      EmitIndConst yes, already address form
                    cmpx      #148      operand a pointer type
                    lbeq      EmitIndConst yes, already address form
                    cmpx      #149      operand a pointer type
                    lbeq      EmitIndConst yes, already address form
                    bra       IndirectionErr not address, take value path

MakePtrResult       ldd       #$8093    indirect pointer result code
                    std       ,s        set top result code
                    clra                clear high byte
                    clrb                clear low byte
                    std       8,u       clear result node value field
                    lbra      SetResultOp store op and return

ClassifyTop         ldx       ,s        load top operand op code
                    lbra      ClassifyOperand classify and convert operand

MapCode95           ldd       #149      map to load-form code 95
                    bra       StoreConvCode store converted code

MapCode94           ldd       #148      map to load-form code 94
                    bra       StoreConvCode store converted code

MapCode93           ldd       #147      map to load-form code 93
                    bra       StoreConvCode store converted code

SetIndirectBit      ldd       ,s        load existing operand code
                    ora       #$80      set indirect high bit
StoreConvCode       std       ,s        store converted code on stack
                    leax      4,s       point past operand slot
                    bra       RealignStack continue with value load

ConstOperand        ldd       #$8034    indirect constant result code
                    std       ,s        store result code
                    ldx       2,s       get operand node pointer
                    ldd       20,x      copy operand offset field
                    std       20,u      into result node
                    bra       LoadOperandVal load operand value

RealignStack        leas      -4,x      realign stack pointer
LoadOperandVal      ldx       2,s       get operand node pointer
                    ldd       8,x       load operand value field
                    bra       StoreOperandVal store into result

RegOperand2         ldd       2,s       operand node pointer as arg
                    pshs      d         push for emitter
                    ldd       #119      emit opcode 77
                    pshs      d         push arg
                    ldd       #113      register operand code
                    pshs      d         push arg
                    ldd       #117      load-into-register op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      8,s        drop emit args
                    ldd       #147      result now register code
                    std       ,s        store result code
                    clra                clear high byte
                    clrb                clear low byte
StoreOperandVal     std       8,u       set result node value
                    bra       SetResultOp store op and return

FieldOperand        clra                clear high byte
                    clrb                clear low byte
                    std       8,u       clear result value
                    ldx       2,s       operand node pointer
                    ldd       8,x       operand value field
                    std       20,u      save as result offset
                    ldd       #52       constant result code
                    bra       StoreCodeExit store code and return

OperandErr          leax      StrIndirection2,pcr address of error message
                    pshs      x         push message pointer
                    pshs      u         push result node
                    lbsr      InternalErr report compiler error
                    leas      4,s        drop args
                    ldd       #147      default register code
StoreCodeExit       std       ,s        store result code
                    bra       SetResultOp store op and return

ClassifyOperand     cmpx      #111      operand op is 6F
                    lbeq      MapCode95 map to code 95
                    cmpx      #118      operand op is 76
                    lbeq      MapCode94 map to code 94
                    cmpx      #113      operand op is 71
                    lbeq      MapCode93 map to code 93
                    cmpx      #147      operand already pointer 93
                    lbeq      SetIndirectBit set indirect bit
                    cmpx      #148      pointer 94
                    lbeq      SetIndirectBit set indirect bit
                    cmpx      #149      pointer 95
                    lbeq      SetIndirectBit set indirect bit
                    cmpx      #52       constant node
                    lbeq      ConstOperand handle constant
                    cmpx      #112      register node
                    lbeq      RegOperand2 handle register
                    cmpx      #54       field/member node
                    beq       FieldOperand handle field
                    bra       OperandErr unknown, error

SetResultOp         ldd       ,s        final result code
                    std       6,u       set result node op
OperandRet          leas      4,s        drop locals
                    puls      pc,u      restore u and return

GenBinOp2           pshs      u         save node pointer
                    ldd       #$FFAC    stack need
                    lbsr      stkcheck  check stack space
                    leas      -8,s       allocate locals
                    ldx       12,s      get node pointer arg
                    ldu       10,x      get right child pointer
                    pshs      u         push child
                    lbsr      EvalSubtreeType evaluate right subtree
                    leas      2,s        drop arg
                    ldx       12,s      node pointer
                    ldd       6,x       node op code
                    std       2,s       save in local
                    ldd       6,u       right child op
                    std       ,s        save in local
                    pshs      d         push child op
                    lbsr      IsFloatType classify operand type
                    std       ,s++      pop result
                    beq       NormLeftMem zero: needs load
                    ldx       2,s       node op into x
                    bra       ChkLeftOp dispatch on op

LeftIsIndexed       ldd       14,s      left operand code
                    cmpd      #112      is register form
                    bne       SetLeftCode no, just store code
                    pshs      u         push node
                    ldd       #119      emit opcode 77
                    pshs      d         push arg
                    ldd       18,s      left operand value
                    pshs      d         push arg
                    ldd       #117      register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      8,s        drop args
                    bra       LoadRightChild continue

SetLeftCode         ldd       ,s        child code
                    std       14,s      store as left code
                    bra       LoadRightChild continue

ChkLeftOp           cmpx      #62       op is 3E
                    beq       LeftIsIndexed handle indexed left
                    cmpx      #63       op is 3F
                    lbeq      LeftIsIndexed handle indexed left
                    bra       SetLeftCode plain left

NormLeftMem         ldd       14,s      left code
                    cmpd      #113      is memory form
                    bne       EmitLeftLoad no, emit as-is
                    ldd       ,s        child code
                    anda      #$7f      strip indirect bit
                    cmpd      #52       is constant
                    beq       EmitLeftLoad yes, keep code
                    ldd       #112      force register form
                    std       14,s      update left code
EmitLeftLoad        pshs      u         push node
                    ldd       #119      emit opcode 77
                    pshs      d         push arg
                    ldd       18,s      left operand value
                    pshs      d         push arg
                    ldd       #117      register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      8,s        drop args
                    ldd       14,s      left code
                    std       ,s        into child slot
LoadRightChild      ldx       12,s      node pointer
                    ldd       8,x       node value field
                    std       6,s       save right value
                    ldx       2,s       node op
                    bra       ChkRightOp dispatch on op

NegRight            ldd       6,s       right value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #0        carry into high byte
                    std       6,s       store negated
EmitRight           ldd       ,s        child code
                    cmpd      #112      is register form
                    bne       EmitRightMem no, memory path
                    ldd       6,s       right value
                    pshs      d         push arg
                    ldd       #54       field op
                    pshs      d         push arg
                    ldd       4,s       child operand code
                    pshs      d         push arg
                    ldd       #80       register add op
                    bra       EmitRightNode emit

EmitRightMem        ldd       6,s       right value
                    pshs      d         push arg
                    ldd       #54       field op
                    pshs      d         push arg
                    ldd       4,s       child operand code
                    pshs      d         push arg
                    ldd       #116      memory add op
EmitRightNode       pshs      d         push arg
                    lbsr      GenNode   emit add
                    leas      8,s        drop args
                    bra       EmitCombine continue

ChkRightOp          cmpx      #61       op is 3D
                    beq       NegRight  negate right
                    cmpx      #63       op is 3F
                    lbeq      NegRight  negate right
                    bra       EmitRight no negate

EmitCombine         pshs      u         push node
                    ldd       #119      emit opcode 77
                    pshs      d         push arg
                    ldd       4,s       operand value for emit
                    pshs      d         push arg
                    ldd       #121      combine op
                    pshs      d         push arg
                    lbsr      GenNode   emit combine
                    leas      8,s        drop args
                    ldx       2,s       node op
                    bra       ChkFinalOp dispatch on op

ZeroFinalize        clra                clear high byte
                    clrb                zero result value
                    bra       StoreFinalVal store result

FinalizeReg         ldd       ,s        child code
                    cmpd      #112      is register form
                    bne       NegFinalize no, negate path
                    ldd       6,s       right value
                    pshs      d         push arg
                    ldd       #54       field op
                    pshs      d         push arg
                    ldd       #112      register operand
                    pshs      d         push arg
                    ldd       #81       register op
                    pshs      d         push arg
                    lbsr      GenNode   emit
                    leas      8,s        drop args
                    bra       BinOpDone finish

NegFinalize         ldd       6,s       right value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #0        carry into high byte
StoreFinalVal       ldx       12,s      node pointer
                    std       8,x       store result value
                    bra       BinOpDone finish

ChkFinalOp          cmpx      #62       op is 3E
                    beq       FinalizeReg indexed finalize
                    cmpx      #63       op is 3F
                    lbeq      FinalizeReg indexed finalize
                    bra       ZeroFinalize zero-value finalize

BinOpDone           ldd       14,s      left/result code
                    ldx       12,s      node pointer
                    std       6,x       set node op
                    clra                clear high byte
                    clrb                clear low byte
                    std       GlbVar0066 clear global flag
                    lbra      XlatDone  common exit

ForceRegister       pshs      u         save node pointer
                    ldd       #$FFB4    stack need
                    lbsr      stkcheck  check stack space
                    ldu       4,s       get operand node
                    pshs      u         push operand
                    bsr       EvalOperand evaluate operand
                    leas      2,s        drop arg
                    ldd       6,u       operand op
                    cmpd      #113      already register form
                    bne       EmitReg71Load no, emit load
                    ldd       8,u       operand value
                    beq       SetReg71Ret zero: skip load
EmitReg71Load       pshs      u         push operand
                    ldd       #119      emit opcode 77
                    pshs      d         push arg
                    ldd       #113      register operand
                    pshs      d         push arg
                    ldd       #117      register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      8,s        drop args
SetReg71Ret         ldd       #113      register result code
                    std       6,u       set operand op
                    puls      pc,u      restore and return

EvalOperand         pshs      u         save node pointer
                    ldd       #$FFAC    stack need
                    lbsr      stkcheck  check stack space
                    leas      -8,s       allocate locals
                    ldx       12,s      node pointer
                    ldu       10,x      left child pointer
                    ldx       12,s      node pointer
                    ldd       12,x      node right value
                    std       6,s       save in local
                    ldd       #113      register code
                    std       ,s        init child slot
                    ldx       12,s      node pointer
                    ldd       6,x       node op
                    std       2,s       save in local
                    tfr       d,x       op into x
                    lbra      XlatTypeDisp2 dispatch on op

CaseSubExpr         ldd       12,s      node pointer arg
                    pshs      d         push arg
                    lbsr      GenIndirection generate subexpression
                    lbra      XlatAfterEmit merge

CaseAssignReg       ldd       #113      register operand
                    pshs      d         push arg
                    ldd       14,s      operand value
                    pshs      d         push arg
                    lbsr      GenBinOp2 generate binary op
                    leas      4,s        drop args
                    lbra      XlatDone  common exit

CaseUnary7F         pshs      u         push node
                    ldd       #119      emit opcode 77
                    pshs      d         push arg
                    ldd       #113      register operand
                    pshs      d         push arg
                    ldd       #127      unary op
                    pshs      d         push arg
                    lbsr      GenNode   emit unary op
                    leas      8,s        drop args
                    clra                clear high byte
                    clrb                clear low byte
                    lbra      XlatStoreHi merge

CaseGenOperand      ldd       12,s      node pointer arg
                    pshs      d         push arg
                    lbsr      CoerceToDouble generate operand code
                    lbra      XlatAfterEmit merge

CaseStore           ldd       6,u       left child op
                    cmpd      #65       is special op 41
                    beq       ChkLvalueType yes, handle
                    ldx       6,s       right node pointer
                    ldd       18,x      right type field
                    lbne      StoreDone non-zero: done
ChkLvalueType       ldd       6,u       left child op
                    pshs      d         push arg
                    lbsr      IsFloatType classify operand type
                    std       ,s++      pop result
                    bne       ChkFieldStore non-zero: proceed
                    ldd       6,u       left child op
                    cmpd      #65       is op 41
                    bne       MaybeSwapOperands no, other path
ChkFieldStore       ldx       6,s       right node pointer
                    ldd       6,x       right op
                    cmpd      #54       is field op
                    bne       EmitStoreGeneral no, general path
                    pshs      u         push node
                    lbsr      EvalOperand evaluate operand
                    leas      2,s        drop arg
                    ldd       6,u       operand op
                    std       ,s        into child slot
                    ldx       6,s       right node pointer
                    ldd       8,x       right value
                    lbra      XlatSaveOff merge

EmitStoreGeneral    ldd       6,s       right value/pointer
                    pshs      d         push arg
                    lbsr      CoerceToDouble generate operand code
                    leas      2,s        drop arg
                    pshs      u         push node
                    lbsr      EvalOperand evaluate operand
                    leas      2,s        drop arg
                    ldd       2,s       saved op
                    cmpd      #81       is register op 51
                    bne       EmitStoreOp no, skip
                    ldd       #67       emit opcode 43
                    pshs      d         push arg
                    lbsr      GenNode   emit
                    leas      2,s        drop arg
EmitStoreOp         ldd       6,u       operand op
                    pshs      d         push arg
                    ldd       #112      register operand
                    pshs      d         push arg
                    ldd       #123      store op
                    pshs      d         push arg
                    lbsr      GenNode   emit store
                    leas      6,s        drop args
                    lbra      XlatZeroOff merge

MaybeSwapOperands   ldd       2,s       saved op
                    cmpd      #80       is register op 50
                    bne       TryCommute2 no, skip swap
                    ldd       18,u      left type field
                    ldx       6,s       right node pointer
                    cmpd      18,x      compare type ranks
                    bge       TryCommute2 left larger, no swap
                    leas      -2,s       make room
                    stu       ,s        save left pointer
                    ldu       8,s       load right pointer
                    ldd       ,s        get temp word
                    std       8,s       swap operand slots
                    leas      2,s        drop temp
TryCommute2         ldd       6,s       right node/value
                    pshs      d         push arg
                    lbsr      IsIndexable process operand
                    std       ,s++      pop result
                    bne       ReEvalOperand non-zero: reeval
                    ldx       6,s       right node pointer
                    ldd       6,x       right op
                    pshs      d         push arg
                    lbsr      IsFloatType classify operand type
                    std       ,s++      pop result
                    bne       ReEvalOperand non-zero: reeval
StoreDone           leax      8,s       point past locals
                    lbra      XlatRestoreB merge/exit

ReEvalOperand       pshs      u         push node
                    lbsr      EvalOperand evaluate operand
                    leas      2,s        drop arg
                    ldd       6,u       operand op
                    anda      #$7f      strip indirect bit
                    tfr       d,x       op into x
                    lbra      XlatTypeDisp dispatch

HandleReg50         ldd       2,s       saved op
                    cmpd      #80       is register op 50
                    bne       EmitDefaultLoad no, default emit
                    ldx       6,s       right node pointer
                    ldd       6,x       right op
                    cmpd      #54       is field op
                    beq       EmitDefaultLoad yes, default emit
                    ldd       6,s       right value
                    pshs      d         push arg
                    lbsr      CoerceToFloat generate operand code
                    leas      2,s        drop arg
                    clra                clear high byte
                    clrb                clear low byte
                    std       8,u       clear operand value
                    leax      8,s       point past locals
                    lbra      XlatRestoreA merge

EmitDefaultLoad     pshs      u         push node
                    ldd       #119      emit opcode 77
                    pshs      d         push arg
                    ldd       #113      register operand
                    pshs      d         push arg
                    ldd       #117      register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      8,s        drop args
                    clra                clear high byte
                    clrb                clear low byte
                    std       8,u       clear operand value
                    bra       XlatOperand merge

SaveOpMerge         ldd       6,u       operand op
                    std       ,s        into child slot
                    bra       XlatOperand merge

XlatTypeErr         leax      StrXTranslate,pcr point to 'x translate' message
                    pshs      x         push message pointer arg
                    pshs      u         push node pointer arg
                    lbsr      InternalErr print translation error
                    leas      4,s        drop the two args
                    bra       XlatOperand continue building node

XlatTypeDisp        cmpx      #112      node type $70
                    lbeq      HandleReg50 handle that type
                    cmpx      #52       node type $34
                    beq       EmitDefaultLoad handle that type
                    cmpx      #55       node type $37
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #147      node type $93
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #148      node type $94
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #149      node type $95
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #113      node type $71
                    beq       XlatOperand process as operand
                    cmpx      #118      node type $76 double
                    beq       SaveOpMerge handle float branch
                    cmpx      #111      node type $6F float
