XlatTypeDisp2       cmpx      #66       node type $42
                    lbeq      CaseSubExpr handle that type
                    cmpx      #52       node type $34
                    beq       XlatDone  just return
                    cmpx      #118      node type $76
                    beq       XlatDone  just return
                    cmpx      #111      node type $6F
                    beq       XlatDone  just return
                    cmpx      #54       node type $36
                    beq       XlatDone  just return
                    cmpx      #55       node type $37
                    beq       XlatDone  just return
                    cmpx      #62       node type $3E
                    lbeq      CaseAssignReg handle that type
                    cmpx      #60       node type $3C
                    lbeq      CaseAssignReg handle that type
                    cmpx      #61       node type $3D
                    lbeq      CaseAssignReg handle that type
                    cmpx      #63       node type $3F
                    lbeq      CaseAssignReg handle that type
                    cmpx      #65       node type $41
                    lbeq      CaseUnary7F handle that type
                    cmpx      #133      node type $85
                    lbeq      CaseGenOperand handle that type
                    cmpx      #81       node type $51
                    lbeq      CaseStore handle that type
                    cmpx      #80       node type $50
                    lbeq      ChkLvalueType handle that type
