UnaryTypeErr        leax      MsgStorageErr1,pcr point to message
                    pshs      x         push it
                    lbsr      BuildMsgBuf print trace
                    leas      2,s        drop arg
UnarySetDefault     ldd       #12       default type code $0C
                    std       10,s      store it
                    bra       UnaryProcess process operand

UnaryClassify       cmpx      #16       type $10
                    beq       UnaryTypeErr invalid type error
                    cmpx      #13       type $0D
                    lbeq      UnaryTypeErr invalid type error
                    stx       -2,s      save type, test for zero
                    beq       UnarySetDefault zero, use default
UnaryProcess        leax      ,s        pointer to local
                    pshs      x         push it
                    leax      6,s       pointer to local
                    pshs      x         push it
                    leax      22,s      pointer to local
                    pshs      x         push it
                    lbsr      ParseDeclSpec parse subscript expression
                    leas      6,s        drop args
                    std       8,s       save result
                    bne       UnarySubscrLoop nonzero, keep it
                    ldd       #1        default to one
                    std       8,s       store it
UnarySubscrLoop     ldd       4,s       load type
                    std       12,s      save type copy
                    ldd       8,s       load result
                    pshs      d         push it
                    leax      14,s      pointer to local
                    pshs      x         push it
                    leax      6,s       pointer to local
                    pshs      x         push it
                    lbsr      ParseDeclarator emit member access
                    leas      6,s        drop args
                    std       6,s       save returned code
                    ldu       2,s       load node pointer
                    bne       UnaryHaveNode nonzero, have node
                    ldd       6,s       load result code
                    cmpd      #4        code $04
                    beq       UnaryNoNode ok, finish
                    ldd       6,s       load result code
                    cmpd      #3        code $03
                    beq       UnaryNoNode ok, finish
                    lbsr      ErrIdentMissing otherwise report error
UnaryNoNode         leax      20,s      pointer past locals
                    lbra      UnaryJoinB restore and tail

UnaryHaveNode       ldd       6,s       load result code
                    clra                clear high
                    andb      #$30      mask storage class bits
                    cmpd      #48       both class bits set
                    bne       UnaryKeepType no, keep saved type
                    ldd       GlbVar003F current token
                    cmpd      #48       token $30
                    beq       UnarySetE select code fourteen
                    ldd       GlbVar003F current token
                    cmpd      #'(       is it open paren
                    bne       UnarySetC no, select code twelve
UnarySetE           ldd       #14       code fourteen
                    bra       UnaryStoreCode store it

UnarySetC           ldd       #12       code twelve
                    bra       UnaryStoreCode store it

UnaryKeepType       ldd       10,s      keep saved type
UnaryStoreCode      std       14,s      store selected code
                    ldd       ,u        node existing field
                    beq       UnaryInitNode empty, init new node
                    ldd       ,s        first arg
                    pshs      d         push it
                    ldd       8,s       result code arg
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      CheckTypeMatch compatibility check merge
                    leas      6,s        drop args
                    std       -2,s      save flag
                    lbne      UnaryDeref mismatch, do deref
                    ldd       14,s      selected code
                    cmpd      #14       is code fourteen
                    lbeq      UnaryDeref yes, do deref
                    ldd       8,u       node current code
                    cmpd      #14       is code fourteen
                    beq       UnaryFillNode yes, fill node
                    ldd       8,u       node current code
                    cmpd      #34       is code $22
                    beq       UnaryFillNode yes, fill node
                    lbsr      ErrMultiDef incompatible, report error
                    lbra      UnaryDeref then do deref

UnaryFillNode       ldd       14,s      selected code
                    std       8,u       set node type
                    ldd       12,s      type copy
                    std       4,u       store into node
                    ldd       ,s        first field
                    std       10,u      store into node
                    leax      20,s      pointer past locals
                    bra       UnaryJoinA join emit

UnaryInitNode       ldd       6,s       result code
                    std       ,u        init node field
                    clra                zero high
                    clrb                zero low
                    std       12,u      clear node field
                    ldd       14,s      selected code
                    std       8,u       store into node
                    ldd       ,s        first field
                    std       10,u      store into node
