                    leas      6,s        drop arguments
                    std       18,s      save type
                    ldu       10,s      load node pointer
                    bne       CheckLValue non-null, handle assign
                    ldd       18,s      load type
                    cmpd      #4        is it void type
                    lbeq      AssignCleanup yes, cleanup
                    ldd       18,s      reload type
                    cmpd      #3        is it type $0003
                    lbeq      AssignCleanup yes, cleanup
                    lbsr      ErrIdentMissing push error node
                    lbra      AssignCleanup cleanup

CheckLValue         ldd       18,s      load type
                    clra                clear high byte
                    andb      #$30      isolate class bits
                    cmpd      #48       is it class $30
                    beq       BuildEmptyAssign yes, simple assign
                    ldd       22,s      load node kind
                    cmpd      #14       is it kind $000E
                    bne       BuildAssignNode no, build node
BuildEmptyAssign    ldd       ,u        load node type field
                    bne       CheckAssignTypes non-zero, check types
                    ldd       18,s      store type into node
                    std       ,u
                    ldd       #14       node kind $000E
                    std       8,u       store kind
                    clra                zero value
                    clrb
                    std       12,u      clear flags field
                    ldd       8,s       store token into node
                    std       10,u
                    ldd       14,s      push size argument
                    pshs      d
                    ldd       2,s       push type argument
                    pshs      d
                    pshs      u         push node
                    lbsr      CalcTypeSize generate code
                    bra       AssignEmitted done

CheckAssignTypes    ldd       8,s       push token argument
                    pshs      d
                    ldd       20,s      push type argument
                    pshs      d
                    pshs      u         push node
                    lbsr      CheckTypeMatch check type match
AssignEmitted       leas      6,s        drop arguments
                    bra       AssignCleanup cleanup

BuildAssignNode     ldd       18,s      push type argument
                    pshs      d
                    ldd       24,s      push token argument
                    pshs      d
                    lbsr      CoerceOperandNode coerce operand node
                    leas      4,s        drop arguments
                    std       4,s       save size
                    ldd       ,u        load node type field
                    beq       EmitAssignNode empty, emit node
                    ldd       12,u      load node flag field
                    cmpd      GlbVar0031 compare flag with global $0031
                    bne       FreeOldNode differ, save old node
                    lbsr      ErrMultiDef emit end marker
AssignCleanup       leax      24,s      point past frame
                    lbra      RestoreStackB restore and exit

FreeOldNode         pshs      u         push node pointer
                    lbsr      AllocBlk  free old type
                    leas      2,s        drop argument
EmitAssignNode      ldd       18,s      store type into node
                    std       ,u
                    ldd       4,s       store size into node
                    std       8,u
                    ldd       8,s       store token into node
                    std       10,u
                    ldd       GlbVar0031 load global $0031 value
                    std       12,u      store into node flags
                    ldd       XAddressGlobal load current node chain
                    std       16,u      link previous into node
                    stu       XAddressGlobal make node current chain
                    ldd       14,s      push size argument
                    pshs      d
                    ldd       2,s       push type argument
                    pshs      d
                    pshs      u         push node
                    lbsr      CalcTypeSize generate code
                    leas      6,s        drop arguments
                    std       2,s       save result
                    bne       AfterAssignEmit success, continue
                    ldd       GlbVar003F load current token
                    cmpd      #120      is it token $0078
                    beq       AfterAssignEmit yes, continue
                    lbsr      ErrCannotEvalSize mark node invalid
AfterAssignEmit     ldx       4,s       load node kind
                    bra       DispatchNodeKind2 dispatch on kind

AdjustStackOffset   ldd       GlbVar0011 load stack offset
                    subd      2,s       subtract node size
                    std       GlbVar0011 update stack offset
                    ldd       GlbVar0011 reload offset
                    bra       StoreNodeSize store node size

BumpTempCounter     ldd       GlbVar000B load temp counter
                    addd      #1        increment counter
                    std       GlbVar000B save counter
StoreNodeSize       std       6,u       store size into node
                    bra       CheckAssignToken continue

DispatchNodeKind2   cmpx      #13       kind is $000D
                    beq       AdjustStackOffset adjust stack offset
                    cmpx      #35       kind is $0023
                    beq       BumpTempCounter bump temp counter
                    cmpx      #15       kind is $000F
                    lbeq      BumpTempCounter bump temp counter
CheckAssignToken    ldd       GlbVar003F load current token
                    cmpd      #120      is it token $0078
                    lbne      CheckOtherToken no, handle other
                    ldd       4,s       load node kind
                    cmpd      #15       is it kind $000F
                    beq       EmitInitializer yes, emit initializer
                    ldd       4,s       reload kind
                    cmpd      #35       is it kind $0023
                    bne       HandlePostAssign no, handle other
EmitInitializer     ldd       18,s      push type argument
                    pshs      d
                    ldd       6,s       push node-size argument
                    pshs      d
                    pshs      u         push node
                    lbsr      ParseInitializer emit initializer code
AssignReturn        leas      6,s        drop arguments
                    lbra      AssignEnd go to assign end

HandlePostAssign    lbsr      ParseStatement2 get next token
                    ldd       18,s      load type
                    clra                clear high byte
                    andb      #$30      isolate class bits
                    cmpd      #32       is it pointer class
                    lbeq      PostAssignErr yes, report error
                    ldd       18,s      reload type
                    cmpd      #4        is it void type
                    lbeq      PostAssignErr yes, report error
                    ldd       #2        request 2 bytes
                    pshs      d
                    lbsr      ParseBinaryExpr allocate expression slot
                    leas      2,s        drop argument
                    std       12,s      save slot pointer
                    beq       PostAssignErr null, report error
                    ldd       GlbVar006E load node free list
                    beq       AllocInitNode empty, allocate fresh
                    ldd       GlbVar006E load free list head
                    std       6,s       save it
                    tfr       d,x       copy into x
                    ldd       ,x        load next free pointer
                    std       GlbVar006E unlink from free list
                    clra                clear reused node
                    clrb
                    std       [6,s]
                    bra       LinkInitNode link node

AllocInitNode       ldd       #6        node size 6
                    pshs      d
                    lbsr      AllocMem  allocate node
                    leas      2,s        drop argument
                    std       6,s       save node pointer
LinkInitNode        ldd       12,s      load slot value
                    ldx       6,s       load node pointer
                    std       2,x       store slot into node
                    ldx       6,s       reload node pointer
                    stu       4,x       store expression into node
                    ldd       GlbNodePtr load list head
                    beq       SetInitListHead empty, set head
                    ldd       6,s       load node
                    std       [>GlbListTail,y] append after tail
                    bra       SetInitListTail update tail

SetInitListHead     ldd       6,s       load node
                    std       GlbNodePtr set list head
SetInitListTail     ldd       6,s       load node
                    std       GlbListTail set list tail
                    bra       AssignEnd assign end

PostAssignErr       lbsr      ReportCannotInit handle error token
                    bra       AssignEnd assign end

CheckOtherToken     ldx       4,s       load node kind
                    bra       DispatchOtherKind dispatch on kind

EmitCompareNode     ldd       4,s       load node kind
                    cmpd      #35       is it kind $0023
                    bne       ZeroCompareFlag no, use zero flag
                    ldd       #1        flag value 1
                    bra       PushCompareArgs push flag

ZeroCompareFlag     clra                flag value 0
                    clrb
PushCompareArgs     pshs      d         push flag
                    ldd       4,s       push node kind
                    pshs      d
                    ldd       6,u       push node size
                    pshs      d
                    lbsr      EmitVsectRmb emit comparison
                    lbra      AssignReturn return

DispatchOtherKind   cmpx      #15       kind is $000F
                    beq       EmitCompareNode emit comparison
                    cmpx      #35       kind is $0023
                    lbeq      EmitCompareNode emit comparison
                    bra       AssignEnd assign end

RestoreStackB       leas      -24,x     restore stack via x
AssignEnd           ldd       GlbVar003F load current token
                    cmpd      #48       is it operator $0030
                    beq       ContinueAssign yes, continue assign
                    leas      6,s        drop temp slots
                    bra       FreeAndExitB free and exit

ContinueAssign      lbsr      ParseStatement2 get next token
                    leas      6,s        drop temp slots
                    lbra      AssignLoop loop for next assign

FreeAndExitB        ldd       #40       node size $0028
                    pshs      d         push size
                    lbsr      ExpectToken free the node
                    leas      2,s        drop argument
ExprEpilogue        leas      18,s       release local frame
                    puls      pc,u      restore and return

CheckTypeMatch      pshs      u         save the caller u register
                    ldd       #$FFBA    frame size for check
                    lbsr      stkcheck  check stack space
                    ldu       4,s       load node pointer
                    ldd       ,u        load node type field
                    cmpd      6,s       compare with expected type
                    bne       TypeMismatchErr mismatch, report error
                    ldd       6,s       reload expected type
                    cmpd      #4        is it void type
                    bne       TypesMatchOk no, types ok
                    ldd       10,u      load node operand
                    cmpd      8,s       compare with argument
                    beq       TypesMatchOk equal, types ok
TypeMismatchErr     leax      MsgDeclMismatch,pcr point to error message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop argument
                    ldd       #1        return failure 1
                    puls      pc,u      restore and return

TypesMatchOk        clra                return success 0
                    clrb
                    puls      pc,u      restore and return

CoerceOperandNode   pshs      u         save the caller u register
                    ldd       #$FFC0    frame size for check
                    lbsr      stkcheck  check stack space
                    ldd       4,s       load type argument
                    cmpd      #16       is it pointer type $0010
                    bne       ReturnInputType no, skip pointer scan
                    ldd       GlbVar0068 load pointer nesting count
                    cmpd      #1        already at level 1
                    bge       ReturnType0D yes, skip scan
                    ldx       6,s       load node pointer
                    bra       CheckXTypeCode scan pointer chain

ScanPointerLoop     ldd       6,s       load node kind
                    clra                clear high byte
                    andb      #$30      isolate class bits
                    cmpd      #16       is it pointer class
                    bne       ReturnType0D no, stop scan
MarkPointerLevel    ldd       GlbVar0068 load nesting count
                    addd      #1        increment nesting
                    std       GlbVar0068 save count
                    cmpd      #1        reached level 1
                    bne       TypeCode76 no, continue scan
                    ldd       #111      load scale table base
                    bra       ClassifyRet return with type code

TypeCode76          ldd       #118      D = derived type tag $76
ClassifyRet         puls      pc,u      return type in D

CheckXTypeCode      cmpx      #1        base type code == 1
                    beq       MarkPointerLevel yes, bump type counter
                    cmpx      #7        base type code == 7
                    lbeq      MarkPointerLevel yes, bump type counter
                    bra       ScanPointerLoop else classify by mask

ReturnType0D        ldd       #13       D = type code $0D
                    puls      pc,u      return type in D

ReturnInputType     ldd       4,s       D = input type unchanged
                    puls      pc,u      return type in D

ParseStructBody     pshs      u         save the caller u register
                    ldd       #$FFAC    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -10,s      allocate 10 local bytes
                    ldd       #1        initial nesting depth 1
                    std       GlbVar0031 set nesting depth
                    clra                clear A
                    clrb                clear B
                    std       GlbVar000F clear working field $000F
                    std       GlbVar001B clear max offset
                    std       GlbVar0011 clear current offset
                    std       GlbVar0068 clear field counter
                    std       GlbVar0013 clear field $0013
                    bra       MemberLoopTest enter member loop test

ParseMemberLoop     lbsr      ParsePostfixExpr parse one struct member
MemberLoopTest      ldd       GlbVar003F D = current token
                    cmpd      #')       token == close brace
                    bne       ParseMemberLoop no, parse more members
                    ldd       14,s      D = local temp
                    addd      #20       add base displacement
                    std       2,s       save member list pointer
                    ldd       GlbVar0017 anonymous tag flag
                    beq       LayoutSetup skip if no tag
                    ldd       GlbVar000B D = tag counter
                    addd      #1        increment tag counter
                    std       GlbVar000B store bumped counter
                    std       ,s        save as argument
                    pshs      d         push argument
                    ldd       4,s       D = list pointer
                    pshs      d         push argument
                    lbsr      EmitStringConst create struct-tag symbol
                    leas      4,s        drop arguments
LayoutSetup         ldd       ,s        D = member list pointer
                    pshs      d         push argument
                    ldd       18,s      D = base type field
                    cmpd      #15       is type code $0F
                    beq       PackedFlagZero yes, packed flag zero
                    ldd       #1        flag = 1
                    bra       StoreStructSym store flag

PackedFlagZero      clra                clear A
                    clrb                packed flag zero
StoreStructSym      pshs      d         push packed flag
                    ldd       6,s       D = tag pointer
                    pshs      d         push argument
                    lbsr      EmitFuncPrologue create struct symbol entry
                    leas      6,s        drop arguments
                    ldu       IdentifierField U = member list head
                    ldd       #4        initial offset = 4
                    std       8,s       seed running offset
                    lbra      LayoutNext enter layout loop

LayoutMemberLoop    leas      -2,s       reserve loop temp
                    ldd       10,s      D = running offset
                    std       6,u       store offset into member
                    ldx       ,u        X = member type code
                    bra       SizeForType dispatch size by type

MemberSize4         ldd       #4        member size 4
                    bra       StoreMemberSize store size

MemberSize8         ldd       #8        member size 8
                    bra       StoreMemberSize store size

MemberSize2Bump     ldd       6,u       D = member offset
                    addd      #1        add one for int
                    std       6,u       bump member offset
MemberSize2         ldd       #2        member size 2
StoreMemberSize     std       ,s        save member size
                    bra       LayoutSubtype continue layout

SizeForType         cmpx      #8        type code == 8
                    beq       MemberSize4 size 4
                    cmpx      #5        type code == 5
                    lbeq      MemberSize4 size 4
                    cmpx      #6        type code == 6
                    beq       MemberSize8 size 8
                    cmpx      #2        type code == 2
                    beq       MemberSize2Bump int, size 2 with bump
                    bra       MemberSize2 default size 2

LayoutSubtype       ldd       8,u       D = member subtype
                    std       8,s       save subtype
                    tfr       d,x       X = subtype
                    bra       DispatchSubtype dispatch subtype

BuildMemberType     ldd       10,s      D = running offset
                    pshs      d         push argument
                    ldd       10,s      D = running offset
                    pshs      d         push argument
                    lbsr      GenNode   emit/build member type
                    leas      4,s        drop arguments
                    bra       AdvanceMember advance member

SetSubtype0D        ldd       #13       subtype $0D
                    std       8,u       store subtype
                    bra       AdvanceMember advance member

DispatchSubtype     cmpx      #111      subtype == $6F
                    beq       BuildMemberType build member type
                    cmpx      #118      subtype == $76
                    lbeq      BuildMemberType build member type
                    cmpx      #11       subtype == $0B
                    beq       SetSubtype0D set subtype $0D
AdvanceMember       ldd       10,s      D = running offset
                    addd      ,s        add member size
                    std       10,s      advance running offset
                    ldu       16,u      U = next member
                    leas      2,s        drop loop temp
LayoutNext          stu       -2,s      save current member pointer
                    lbne      LayoutMemberLoop loop while members remain
                    ldd       IdentifierField D = member list head
                    std       4,s       save it
                    clra                clear A
                    clrb                clear B
                    std       IdentifierField clear member list head
                    lbsr      ParseDeclarations parse declarations
                    leax      4,s       X = saved list pointer
                    pshs      x         push argument
                    lbsr      FreeLocalSymbols restore saved global
                    leas      2,s        drop argument
                    leax      >NodeBuilderBase,y  X = address of global $0029
                    pshs      x         push argument
                    lbsr      FreeLocalSymbols restore saved global
                    leas      2,s        drop argument
                    ldd       GlbVar002F D = current type field
                    cmpd      #18       already type $12
                    beq       AfterTypeEmit skip type emission
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    ldd       #18       type tag $12
                    pshs      d         push type tag
                    lbsr      GenNode   emit/build type
                    leas      6,s        drop arguments
AfterTypeEmit       clra                clear A
                    clrb                clear B
                    std       GlbVar002F clear type field $002F
                    lbsr      EmitFrameEqu finalize struct type
                    clra                clear A
                    clrb                clear B
                    std       GlbVar0031 clear nesting depth
                    ldd       GlbVar003F D = current token
                    cmpd      #$FFFF    end-of-input token
                    bne       StructBodyDone no, continue
                    leax      MsgFuncUnfinished,pcr X = error message
                    pshs      x         push argument
                    lbsr      BuildMsgBuf print error message
                    leas      2,s        drop argument
StructBodyDone      lbsr      ParseStatement2 get next token
                    leas      10,s       release locals
                    puls      pc,u      return

ParseDeclarations   pshs      u         save the caller u register
                    ldd       #$FFAA    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -6,s       allocate 6 local bytes
                    ldd       XAddressGlobal D = saved global $002B
                    std       2,s       save old value
                    clra                clear A
                    clrb                clear B
                    std       XAddressGlobal clear global $002B
                    lbsr      ParseStatement2 get next token
                    ldd       GlbVar0031 D = nesting depth
                    addd      #1        increment depth
                    std       GlbVar0031 bump nesting depth
                    ldd       GlbVar0011 D = current offset
                    std       ,s        save entry offset
                    bra       ParseDeclLoop enter parse loop

ProcessDeclLoop     lbsr      ParseAssignExpr process the declaration
ParseDeclLoop       lbsr      IsStorageKeyword parse one declaration
                    std       -2,s      save parse result
                    bne       ProcessDeclLoop loop while declaration parsed
                    lbsr      IsTypeSpecifier parse trailing declaration
                    std       -2,s      save parse result
                    lbne      ProcessDeclLoop loop while declaration parsed
                    ldd       GlbVar001B D = max offset
                    cmpd      GlbVar0011 vs current offset
                    ble       OffsetChecked skip if max already larger
                    ldd       GlbVar0011 D = current offset
                    std       GlbVar001B raise max offset
OffsetChecked       ldd       GlbVar0011 D = current offset
                    pshs      d         push argument
                    lbsr      EmitReserveSpace compute/allocate offset
                    leas      2,s        drop argument
                    std       GlbVar000F save resulting frame size
                    lbra      ReverseListTest enter list-reverse loop

ReverseListLoop     ldd       GlbNodePtr D = declaration list head
                    std       4,s       save node pointer
                    ldx       4,s       X = node
                    ldu       2,x       U = node type pointer
                    ldd       16,u      D = type high word
                    pshs      d         push argument
                    ldd       14,u      D = type field
                    pshs      d         push argument
                    ldx       8,s       X = node pointer
                    ldd       4,x       D = node size
                    pshs      d         push argument
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    ldd       #52       type tag $34
                    pshs      d         push tag
                    lbsr      AllocExprNode build type node
                    leas      12,s       drop arguments
                    tfr       d,u       U = new type node
                    ldd       16,u      D = type high word
                    pshs      d         push argument
                    ldd       14,u      D = type field
                    pshs      d         push argument
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    ldx       10,s      X = node pointer
                    ldd       2,x       D = node type
                    pshs      d         push argument
                    pshs      u         push node
                    ldd       #120      type tag $78
                    pshs      d         push tag
                    lbsr      AllocExprNode build type node
                    leas      12,s       drop arguments
                    tfr       d,u       U = new type node
                    pshs      u         push node
                    lbsr      CopyExprTree resolve/apply type
                    std       ,s        save result
                    lbsr      EvalSubtreeType finalize type node
                    std       ,s        save result
                    lbsr      FreeExprTree emit declaration
                    leas      2,s        drop argument
                    ldd       [4,s]     D = node next pointer
                    std       4,s       save next node
                    ldd       GlbVar006E D = reversed list head
                    std       [>GlbNodePtr,y] link node into reversed list
                    ldd       GlbNodePtr D = current node
                    std       GlbVar006E advance reversed head
                    ldd       4,s       D = next node
                    std       GlbNodePtr advance to next node
ReverseListTest     ldd       GlbNodePtr D = list head
                    lbne      ReverseListLoop loop while nodes remain
                    bra       StmtLoopTest begin statement parsing

ParseStmtLoop       lbsr      ParseStatement parse one statement
StmtLoopTest        ldd       GlbVar003F D = current token
                    cmpd      #42       token == close $2A
                    beq       BlockDone yes, block done
                    ldd       GlbVar003F D = current token
                    cmpd      #$FFFF    end-of-input token
                    bne       ParseStmtLoop no, parse more statements
BlockDone           leax      >XAddressGlobal,y  X = address of global $002B
                    pshs      x         push argument
                    lbsr      FreeLocalSymbols restore saved global
                    leas      2,s        drop argument
                    ldd       2,s       D = saved $002B value
                    std       XAddressGlobal restore global $002B
                    ldd       GlbVar0031 D = nesting depth
                    addd      #$FFFF    decrement
                    std       GlbVar0031 pop nesting depth
                    ldd       ,s        D = entry offset
                    std       GlbVar0011 restore current offset
                    ldd       GlbVar002F D = type field
                    cmpd      #18       already type $12
                    beq       UseOffsetAsIs use offset as-is
                    ldd       ,s        D = entry offset
                    pshs      d         push argument
                    lbsr      EmitReserveSpace compute offset
                    leas      2,s        drop argument
                    bra       StoreFrameSize store frame size

UseOffsetAsIs       ldd       ,s        D = entry offset
StoreFrameSize      std       GlbVar000F save the caller u register size
                    leas      6,s        release locals
                    puls      pc,u      return

ParseEnumMembers    pshs      u         save the caller u register
                    ldd       #$FFB8    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -2,s       allocate 2 local bytes
                    clra                clear A
                    clrb                clear B
                    std       [6,s]     clear list head
EnumMemberLoop      lbsr      ParseStatement2 get next token
                    ldd       GlbVar003F D = current token
                    cmpd      #46       token == close $2E
                    lbeq      EnumListDone end of member list
                    ldd       GlbVar003F D = current token
                    cmpd      #52       token == identifier
                    bne       ParseOtherEnum no, handle otherwise
                    ldu       GlbVar0041 U = symbol pointer
                    ldd       8,u       D = symbol type
                    cmpd      #11       already enum constant
                    bne       CheckSymUnset no
                    leax      MsgNamedTwice,pcr X = redefinition error message
                    pshs      x         push argument
                    lbsr      BuildMsgBuf print error message
                    bra       AfterFreeNode skip free

CheckSymUnset       ldd       ,u        D = symbol flags
                    beq       DefineEnumConst skip if unset
                    pshs      u         push symbol
                    lbsr      AllocBlk  free old node
AfterFreeNode       leas      2,s        drop argument
DefineEnumConst     ldd       #1        mark value 1
                    std       ,u        mark symbol defined
                    ldd       #11       enum-const type $0B
                    std       8,u       set symbol type
                    ldd       #1        storage class 1
                    std       12,u      set storage class
                    ldd       #2        size 2
                    std       2,u       set symbol size
                    ldd       [6,s]     D = current list head
                    beq       SetListHead first member
                    ldx       ,s        X = previous member
                    stu       16,x      link previous to this
                    bra       LinkEnumConst skip head set

SetListHead         stu       [6,s]     set list head
LinkEnumConst       clra                clear A
                    clrb                clear B
                    std       16,u      clear next pointer
                    stu       ,s        remember as previous
                    lbsr      ParseStatement2 get next token
                    bra       EnumSepTest test separator

ParseOtherEnum      lbsr      ErrIdentMissing handle other construct
EnumSepTest         ldd       GlbVar003F D = current token
                    cmpd      #'0       token == comma $30
                    lbeq      EnumMemberLoop continue member list
EnumListDone        ldd       #46       expected token $2E
                    pshs      d         push argument
                    lbsr      ExpectToken require closing token
                    leas      2,s        drop argument
                    bra       TypeNameRet finish

ParseTypeName       pshs      u         save the caller u register
                    ldd       #$FFBA    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -2,s       allocate 2 local bytes
                    lbsr      IsStorageKeyword parse declarator/type
                    std       -2,s      save result
                    beq       ReturnNoType none, return 0
                    ldd       GlbVar0041 D = token value
                    std       ,s        save type node
                    lbsr      ParseStatement2 get next token
                    ldd       GlbVar003F D = current token
                    cmpd      #51       token == keyword $33
                    bne       ReturnType no, return type
                    ldd       GlbVar0041 D = keyword value
                    cmpd      #33       value == $21
                    bne       ReturnType no, return type
                    ldx       ,s        X = type node
                    bra       CheckBaseType check base type

MapTypeUnsigned23   ldd       #35       mapped type $23
                    bra       StoreMappedType store it

MapTypeUnsigned22   ldd       #34       mapped type $22
StoreMappedType     std       ,s        store mapped type
                    bra       ConsumeUnsigned consume keyword

CheckBaseType       cmpx      #15       base type == $0F
                    beq       MapTypeUnsigned23 map to $23
                    cmpx      #14       base type == $0E
                    beq       MapTypeUnsigned22 map to $22
ConsumeUnsigned     lbsr      ParseStatement2 consume unsigned keyword
ReturnType          ldd       ,s        D = type node
                    bra       TypeNameRet return type

ReturnNoType        clra                clear A
                    clrb                return zero
TypeNameRet         leas      2,s        release locals
                    puls      pc,u      return

ParseDeclSpec       pshs      u         save the caller u register
                    ldd       #$FF98    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -26,s      allocate locals
                    clra                clear A
                    clrb                clear B
                    std       2,s       clear type field
                    ldd       #2        default size 2
                    std       ,s        set default size
                    clra                clear A
                    clrb                clear B
                    std       [34,s]    clear output pointer
                    ldd       GlbVar003F D = current token
                    cmpd      #51       token == keyword $33
                    lbne      CheckTypedefName not a type keyword
                    ldd       GlbVar0041 D = keyword value
                    std       2,s       save keyword
                    tfr       d,x       X = keyword
                    lbra      KeywordDispatch2 dispatch keyword

SetTypeShort        ldd       #1        type code 1
                    std       2,s       save type
SpecKeywordLoop     lbsr      ParseStatement2 get next token
                    ldd       GlbVar003F D = current token
                    cmpd      #51       token == keyword $33
                    lbne      ReturnDefaultType done with specifiers
                    ldd       GlbVar0041 D = keyword value
                    cmpd      #1        value == $01
                    lbne      ReturnDefaultType done
                    bra       NextSpecTok consume specifier

SetFlag1            ldd       #1        flag = 1
                    bra       StoreSpecSize store flag

SetSizeLong         lbsr      ParseStatement2 get next token
                    ldd       #4        size 4
                    std       ,s        set size
                    ldd       GlbVar003F D = current token
                    cmpd      #51       token == keyword $33
                    lbne      ReturnDefaultType done
                    ldd       GlbVar0041 D = keyword value
                    cmpd      #1        value == $01
                    beq       NextSpecTok consume specifier
                    ldd       GlbVar0041 D = keyword value
                    cmpd      #5        value == $05
                    lbne      ReturnDefaultType done
SetTypeDouble2      ldd       #6        type code 6 double
                    std       2,s       save type
                    ldd       #8        size 8
                    bra       StoreSpecSize store size

SetSize42           ldd       #4        size 4
StoreSpecSize       std       ,s        set size
NextSpecTok         lbsr      ParseStatement2 get next token
                    lbra      ReturnDefaultType done with specifiers

SetTypeVoid         clra                clear A
                    clrb                clear B
                    std       2,s       save void type
                    lbra      ReturnDefaultType done

ResetSpecState      clra                clear A
                    clrb                clear B
                    std       22,s      clear field $16
                    std       ,s        clear size
                    ldd       GlbNestDepth D = specifier counter
                    addd      #1        increment
                    std       GlbNestDepth bump specifier counter
                    clra                clear high byte of tag slot
                    clrb                clear low byte of tag slot
                    std       24,s      clear the tag symbol pointer slot
                    lbsr      ParseStatement2 get next token
                    ldd       GlbNestDepth load nesting depth counter
                    addd      #$FFFF    decrement it
                    std       GlbNestDepth save nesting depth
                    ldd       GlbVar003F D = current token type
                    cmpd      #52       is it an identifier (tag name)
                    lbne      StructNoTagBody no tag name, expect the brace
                    ldd       GlbVar0041 D = tag symbol pointer
                    std       24,s      save the tag symbol
                    ldd       [24,s]    load tag symbol kind field
                    bne       TagPreDeclared nonzero, tag already declared
                    ldd       #10       new tag kind marker
                    std       [24,s]    mark symbol as a tag
                    ldd       #8        initial struct size
                    ldx       24,s      X = tag symbol pointer
                    std       8,x       store initial size
                    bra       AfterTagName continue after the tag

TagPreDeclared      ldx       24,s      X = existing tag symbol
                    ldd       8,x       load its kind/size field
                    cmpd      #8        is it an incomplete tag
                    beq       AfterTagName yes, allow the definition
                    leax      MsgNameClash,pcr point to redeclaration error text
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop the argument
AfterTagName        lbsr      ParseStatement2 get next token
                    ldd       GlbVar003F D = current token
                    cmpd      #')       is it an opening brace
                    beq       TagBraceCheck yes, parse the body
                    ldd       [24,s]    load tag kind
                    cmpd      #4        is it a complete type
                    bne       ForwardTagRef no, treat as forward reference
                    ldx       24,s      X = tag symbol
                    ldd       2,x       load tag type
                    std       [30,s]    return type to caller
                    ldx       24,s      X = tag symbol
                    ldd       10,x      load tag size
                    std       [34,s]    return size to caller
                    ldd       #4        result kind = struct type
                    lbra      TypeSpecReturn return

ForwardTagRef       ldd       24,s      D = tag symbol pointer
                    std       [30,s]    return the tag pointer
                    ldd       #10       result kind = incomplete tag
                    lbra      TypeSpecReturn return

TagBraceCheck       ldd       [24,s]    load tag kind
                    cmpd      #4        already complete
                    bne       StructNoTagBody no, parse the body
                    lbsr      ErrMultiDef report redefinition error
StructNoTagBody     ldd       GlbVar003F D = current token
                    cmpd      #')       is it an opening brace
                    beq       ParseStructBody2 yes, parse struct body
                    leax      MsgStructSyntax,pcr point to open-brace expected error
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      2,s        drop the argument
                    lbra      ReturnDefaultType return

ParseStructBody2    ldd       GlbNestDepth load nesting depth
                    addd      #1        increment it
                    std       GlbNestDepth save nesting depth
MemberLoop          ldd       GlbNestDepth load nesting depth
                    std       16,s      save it on the frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       GlbNestDepth reset nesting depth
                    lbsr      ParseStatement2 get next token
                    ldd       16,s      restore saved depth
                    std       GlbNestDepth back into the global
                    ldd       GlbVar003F D = current token
                    cmpd      #'*       is it a closing brace
                    lbeq      EndStructBody yes, end of member list
                    leax      4,s       address of a local slot
                    pshs      x         push arg pointer
                    leax      14,s      address of a local slot
                    pshs      x         push arg pointer
                    leax      24,s      address of tag slot
                    pshs      x         push arg pointer
                    lbsr      ParseDeclSpec parse member type specifier (recurse)
                    leas      6,s        drop the three args
                    std       18,s      save member base type
                    bra       DeclaratorLoop parse the declarators

DeclaratorLoop      leas      -4,s       make room for declarator temps
                    ldd       16,s      load saved depth
                    std       2,s       store into frame
                    ldd       GlbVar003F D = current token
                    cmpd      #'(       is it a semicolon
                    lbeq      DropDeclTemps yes, empty declarator
                    ldd       GlbVar0031 load member level counter
                    addd      #1        increment it
                    std       GlbVar0031 save it
                    ldd       22,s      push type argument
                    pshs      d         onto the stack
                    leax      4,s       address of temp
                    pshs      x         push arg pointer
                    leax      4,s       address of temp
                    pshs      x         push arg pointer
                    lbsr      ParseDeclarator parse member declarator
                    leas      6,s        drop the args
                    std       18,s      save member name/type
                    ldu       ,s        U = declarator result
                    ldd       GlbVar0031 load level counter
                    addd      #$FFFF    decrement it
                    std       GlbVar0031 save it
                    cmpu      #0        was declarator empty
                    bne       CheckMemberDup no, add the member
                    lbsr      ErrIdentMissing report missing member name
                    leax      30,s      compute restore pointer
                    lbra      RestoreFrame2 continue after member

CheckMemberDup      ldd       ,u        load member name field
                    beq       FillMember unnamed, just link it
                    ldd       12,u      load member scope level
                    cmpd      GlbVar0031 same nesting level
                    bne       AllocMemberSym different, link as new
                    ldd       ,u        load member name
                    cmpd      18,s      matches the new name
                    bne       MemberRedeclErr no, redeclaration
                    ldd       8,u       load member kind
                    cmpd      #17       is it a field kind
                    bne       MemberRedeclErr no, redeclaration
                    ldd       6,u       load field type
                    cmpd      26,s      same type as before
                    beq       FillMember yes, reuse the entry
MemberRedeclErr     leax      MsgStructMemberMismatch,pcr point to redeclaration error
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    bra       AfterAllocSym continue

AllocMemberSym      pshs      u         allocate a new symbol entry
                    lbsr      AllocBlk  drop the argument
AfterAllocSym       leas      2,s        load member name
FillMember          ldd       18,s      is name a reserved value
                    cmpd      #10       no, store the fields
                    bne       StoreMemberFields point to error text
                    leax      MsgUndefStruct,pcr push message
                    pshs      x         report the error
                    lbsr      BuildMsgBuf drop the argument
                    leas      2,s        load member name
StoreMemberFields   ldd       18,s      store into the symbol
                    std       ,u        kind = struct field
                    ldd       #17       store the kind
                    std       8,u       load field type
                    ldd       26,s      store the type
                    std       6,u       load member attribute
                    ldd       8,s       store the attribute
                    std       10,u      push type argument
                    ldd       24,s      onto the stack
                    pshs      d         push size argument
                    ldd       4,s       onto the stack
                    pshs      d         push member symbol
                    pshs      u         compute member size/offset
                    lbsr      CalcTypeSize drop the args
                    leas      6,s        save returned size
                    std       14,s      zero size, report incomplete
                    beq       IncompleteMemberErr load aggregate kind
                    ldd       6,s       is it a struct (accumulate)
                    cmpd      #4        no, union (take max)
                    bne       UnionMemberSize load current offset
                    ldd       26,s      add member size
                    addd      14,s      update the offset
                    std       26,s      done with this member
                    bra       StoreUnionSize

UnionMemberSize     ldd       14,s      load member size
                    cmpd      4,s       compare with union max
                    ble       KeepUnionSize not larger, keep max
                    ldd       14,s      take the member size
                    bra       StoreUnionSize store the union size

KeepUnionSize       ldd       4,s       keep the current max
StoreUnionSize      std       4,s       store the union size
                    bra       LinkMemberSym finish the member

IncompleteMemberErr lbsr      ErrCannotEvalSize report incomplete member
LinkMemberSym       ldd       GlbVar0031 load level counter
                    std       12,u      store into symbol scope
                    ldd       XAddressGlobal load symbol list head
                    std       16,u      chain the previous head
                    stu       XAddressGlobal make this the new head
                    ldd       6,s       load aggregate kind
                    cmpd      #4        is it a struct field
                    bne       AfterMember no, skip node linking
                    ldd       #4        allocate a 4 byte node
                    pshs      d         onto the stack
                    lbsr      AllocMem  allocate the node
                    leas      2,s        drop the argument
                    std       12,s      save the node pointer
                    ldx       12,s      X = node
                    stu       2,x       store member symbol in node
                    ldd       [38,s]    load member list head
                    beq       SetMemberListHead empty list
                    ldd       12,s      load the new node
                    std       [10,s]    append to list tail
                    bra       UpdateMemberTail continue

SetMemberListHead   ldd       12,s      load the new node
                    std       [38,s]    set list head
UpdateMemberTail    ldd       12,s      load the node
                    std       10,s      update list tail
                    bra       AfterMember continue

RestoreFrame2       leas      -30,x     restore stack after error
AfterMember         ldd       GlbVar003F D = current token
                    cmpd      #'0       is it a comma
                    beq       NextDeclarator yes, another declarator
DropDeclTemps       leas      4,s        drop declarator temps
                    bra       CheckMemberSemi check for semicolon

NextDeclarator      lbsr      ParseStatement2 get next token
                    leas      4,s        drop declarator temps
                    lbra      DeclaratorLoop parse the next declarator

CheckMemberSemi     ldd       GlbVar003F D = current token
                    cmpd      #'(       is it a semicolon
                    lbeq      MemberLoop yes, parse next member
EndStructBody       ldd       GlbNestDepth load nesting depth
                    addd      #$FFFF    decrement it
                    std       GlbNestDepth save nesting depth
                    ldd       24,s      D = tag symbol pointer
                    beq       ExpectCloseBrace2 no tag, skip finalize
                    ldd       ,s        load computed struct size
                    ldx       24,s      X = tag symbol
                    std       2,x       store size into tag
                    ldd       #4        kind = complete struct
                    std       [24,s]    mark the tag complete
                    ldd       [34,s]    load total size
                    ldx       24,s      X = tag symbol
                    std       10,x      store the size field
ExpectCloseBrace2   ldd       #'*       expected closing brace token
                    pshs      d         push it
                    lbsr      ExpectToken expect/consume the token
                    leas      2,s        drop the argument
                    bra       ReturnDefaultType return

KeywordDispatch2    cmpx      #10       match keyword id $0A
                    lbeq      SetTypeShort handle that keyword
                    cmpx      #7        match keyword id $07
                    lbeq      SpecKeywordLoop handle that keyword
                    cmpx      #2        match keyword id $02
                    lbeq      SetFlag1  handle that keyword
                    cmpx      #1        match keyword id $01
                    lbeq      NextSpecTok handle that keyword
                    cmpx      #8        match keyword id $08
                    lbeq      SetSizeLong handle that keyword
                    cmpx      #6        match keyword id $06
                    lbeq      SetTypeDouble2 handle that keyword
                    cmpx      #5        match keyword id $05
                    lbeq      SetSize42 handle that keyword
                    cmpx      #3        match keyword struct
                    lbeq      ResetSpecState parse struct body
                    cmpx      #4        match keyword union
                    lbeq      ResetSpecState parse union body
                    lbra      SetTypeVoid not a type keyword

CheckTypedefName    ldd       GlbVar003F D = current token
                    cmpd      #52       is it an identifier
                    bne       ReturnDefaultType no, use default type
                    ldu       GlbVar0041 U = symbol pointer
                    ldd       8,u       load symbol kind
                    cmpd      #30       is it a typedef name
                    bne       ReturnDefaultType no, use default type
                    ldd       2,u       load typedef type
                    std       [30,s]    return the type
                    ldd       4,u       load typedef attribute
                    std       [32,s]    return the attribute
                    ldd       10,u      load typedef size
                    std       [34,s]    return the size
                    lbsr      ParseStatement2 consume the typedef name
                    ldd       ,u        load typedef base kind
                    bra       TypeSpecReturn return

ReturnDefaultType   ldd       ,s        load the parsed type code
                    std       [30,s]    return type to caller
                    clra                clear high byte
                    clrb                clear low byte
                    std       [32,s]    clear attribute return
                    ldd       2,s       load result kind
TypeSpecReturn      leas      26,s       drop the local frame
                    puls      pc,u      restore U and return

ParseDeclarator     pshs      u         save U (declarator parser)
                    ldd       #$FFAA    stack limit constant
                    lbsr      stkcheck  check stack space
                    leas      -12,s      allocate local frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       [16,s]    clear output type pointer
                    std       10,s      clear accumulated type
                    bra       DeclaratorTop enter the pointer loop

PointerLoop         ldd       10,s      load accumulated type
                    pshs      d         push it
                    lbsr      TypeAddLevel build pointer-to type
                    leas      2,s        drop the argument
                    std       10,s      save updated type
                    lbsr      ParseStatement2 get next token
DeclaratorTop       ldd       GlbVar003F D = current token
                    cmpd      #66       is it a pointer star
                    beq       PointerLoop yes, another pointer level
                    ldd       GlbVar003F D = current token
                    cmpd      #52       is it an identifier
                    bne       CheckGroupParen no, check for group/params
                    ldd       GlbVar0041 D = identifier symbol
                    std       [16,s]    return the declared name
                    lbsr      ParseStatement2 consume the name
                    bra       CheckFuncParams check for function/array suffix

CheckGroupParen     ldd       GlbVar003F D = current token
                    cmpd      #'-       is it a grouping paren
                    bne       CheckFuncParams no, check for params
                    lbsr      ParseStatement2 consume the open paren
                    ldd       GlbVar0031 load nesting level
                    addd      #1        increment it
                    std       GlbVar0031 save it
                    ldd       20,s      push arg
                    pshs      d         onto the stack
                    ldd       20,s      push arg
                    pshs      d         onto the stack
                    ldd       20,s      push arg
                    pshs      d         onto the stack
                    lbsr      ParseDeclarator parse nested declarator (recurse)
                    leas      6,s        drop the args
                    std       20,s      save the result
                    ldd       GlbVar0031 load nesting level
                    addd      #$FFFF    decrement it
                    std       GlbVar0031 save it
                    ldd       #'.       expected closing paren token
                    pshs      d         push it
                    lbsr      ExpectToken expect the close paren
                    leas      2,s        drop the argument
CheckFuncParams     ldd       GlbVar003F D = current token
                    cmpd      #'-       is it a function paren
                    bne       ArraySetup no, check for array
                    ldd       10,s      load current type
                    aslb                shift low byte left
                    rola                rotate into high byte
                    aslb                shift low byte again
                    rola                rotate into high byte
                    addd      #48       mark as function type
                    std       10,s      save the type
                    ldd       GlbVar0031 load nesting level
                    bne       NestedParams nested, use local scope
                    leax      >IdentifierField,y  point to parameter buffer
                    pshs      x         push it
                    lbsr      ParseEnumMembers parse the parameter list
                    bra       AfterParams continue after params

NestedParams        leax      ,s        push it
                    pshs      x         parse the parameter list
                    lbsr      ParseEnumMembers drop the argument
                    leas      2,s        address of local
                    leax      ,s        push it
                    pshs      x         discard nested params
                    lbsr      FreeLocalSymbols drop the argument
AfterParams         leas      2,s        finish the declarator
                    lbra      FinishDeclarator

ArraySetup          clra                clear high byte
                    clrb                clear low byte
                    std       6,s       clear array list head
                    std       4,s       clear dimension count
                    std       2,s       clear list tail
                    ldd       GlbNestDepth save nesting depth
                    std       8,s       onto the frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       GlbNestDepth reset nesting depth
                    lbra      ArrayDimTop enter the array loop

ArrayDimLoop        ldd       10,s      load current type
                    aslb                shift low byte left
                    rola                rotate into high byte
                    aslb                shift low byte again
                    rola                rotate into high byte
                    addd      #32       mark as array type
                    std       10,s      save the type
                    lbsr      ParseStatement2 consume the open bracket
                    ldd       #4        allocate a 4 byte node
                    pshs      d         onto the stack
                    lbsr      AllocMem  allocate the dimension node
                    leas      2,s        drop the argument
                    tfr       d,u       U = the new node
                    ldd       4,s       load dimension count
                    bne       ParseDimSize not the first, need a size
                    ldd       GlbVar003F D = current token
                    cmpd      #',       is it a closing bracket
                    bne       ParseDimSize no, parse a size
                    clra                clear high byte
                    clrb                unspecified dimension = 0
                    bra       StoreDim  store the dimension

ParseDimSize        clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push it
                    lbsr      ParseConstExpr parse constant dimension expr
                    leas      2,s        drop the argument
StoreDim            std       ,u        store dimension into node
                    ldd       6,s       load list head
                    beq       SetDimListHead empty list
                    ldx       6,s       X = list tail
                    stu       2,x       append the node
                    bra       AfterDimLink continue

SetDimListHead      stu       2,s       update the list tail
AfterDimLink        stu       6,s       expected closing bracket token
                    ldd       #44       push it
                    pshs      d         expect the close bracket
                    lbsr      ExpectToken drop the argument
                    leas      2,s        load dimension count
                    ldd       4,s       increment it
                    addd      #1        save it
                    std       4,s       D = current token
ArrayDimTop         ldd       GlbVar003F is it an open bracket
                    cmpd      #43       yes, another dimension
                    lbeq      ArrayDimLoop restore saved nesting depth
                    ldd       8,s       back into the global
                    std       GlbNestDepth load array list head
                    ldd       2,s       none, done
                    beq       FinishDeclarator load existing suffix chain
                    ldd       [18,s]    link into new node
                    std       2,u       load list head
                    ldd       2,s       store into the output
                    std       [18,s]    push accumulated type
FinishDeclarator    ldd       10,s      onto the stack
                    pshs      d         push arg
                    ldd       22,s      onto the stack
                    pshs      d         finalize declarator type
                    bsr       FinalizeDeclType drop the args
                    leas      4,s        drop the locals
                    leas      12,s       restore U and return
                    puls      pc,u

FinalizeDeclType    pshs      u         save U (finalize entry)
                    ldd       #$FFBC    stack limit constant
                    lbsr      stkcheck  check stack space
                    leas      -2,s       allocate a local
                    ldd       6,s       load the type chain
                    std       ,s        save a working copy
                    bra       DerivationTop enter the walk loop

DerivationLoop      ldd       ,s        load the type code
                    pshs      d         push it
                    ldd       #2        level width
                    lbsr      AsrEntry  extract next derivation level
                    std       ,s        save remaining chain
                    ldd       8,s       load the argument
                    pshs      d         push it
                    ldd       #2        level width
                    lbsr      AslEntry  apply derivation to type
                    std       8,s       save updated type
DerivationTop       ldd       ,s        load the type code
                    clra                keep only the low byte
                    andb      #$30      mask the derivation bits
                    bne       DerivationLoop more derivations, loop
                    ldd       6,s       load the final type
                    addd      8,s       add saved base offset to result
                    lbra      RetPop2   return with result

CalcTypeSize        pshs      u         save the caller u register
                    ldd       #$FFB2    reserve for stack check
                    lbsr      stkcheck  check stack room
                    ldu       4,s       U = type node pointer
                    leas      -4,s       allocate local words
                    ldd       ,u        load type word
                    std       2,s       save type word
                    clra                clear high byte
                    andb      #$0f      isolate base type nibble
                    tfr       d,x       X = base type code
                    bra       SizeDispatch dispatch on base type

SizeOne             ldd       #1        size = 1 for char
                    bra       StoreSize2 go store size

SizeTwo             ldd       #2        size = 2 for int
                    bra       StoreSize2 go store size

SizeFour            ldd       #4        size = 4 for long
                    bra       StoreSize2 go store size

SizeEight           ldd       #8        size = 8 for double
                    bra       StoreSize2 go store size

SizeFromArg         ldd       12,s      size from caller argument
                    bra       StoreSize2 go store size

SizeZero            clra                clear high byte
                    clrb                size = 0 for void
StoreSize2          std       ,s        store computed size
                    bra       ApplySize apply size to node

SizeDispatch        cmpx      #2        base type char
                    beq       SizeOne   take size 1
                    cmpx      #1        base type int
                    beq       SizeTwo   take size 2
                    cmpx      #7        unsigned int type
                    lbeq      SizeTwo   take size 2
                    cmpx      #8        long type
                    beq       SizeFour  take size 4
                    cmpx      #5        float type
                    lbeq      SizeFour  take size 4
                    cmpx      #6        double type
                    beq       SizeEight take size 8
                    cmpx      #3        struct type
                    beq       SizeFromArg take arg size
                    cmpx      #4        union type
                    lbeq      SizeFromArg take arg size
                    cmpx      #10       void type
                    beq       SizeZero  take size 0
ApplySize           ldd       ,s        load computed size
                    beq       UseArgSize zero means use arg size
                    ldd       ,s        reload nonzero size
                    bra       StoreSizeFields store size fields

UseArgSize          ldd       12,s      use caller-supplied size
StoreSizeFields     std       2,u       store size into node
                    ldd       10,s      load align/flags arg
                    std       4,u       store align into node
                    pshs      d         push flags
                    ldd       2,s       type word
                    pshs      d         push type word
                    ldd       6,s       storage class
                    pshs      d         push storage class
                    bsr       ResolveTypeSize resolve storage size
                    leas      6,s        drop pushed args
                    leas      4,s        drop local words
                    puls      pc,u      return

ResolveTypeSize     pshs      u         save the caller u register
                    ldd       #$FFB8    reserve for stack check
                    lbsr      stkcheck  check stack room
                    ldu       8,s       U = type node
                    leas      -2,s       allocate local word
                    ldd       6,s       load storage flags
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #16       register storage class
                    beq       SizePointer pointer size 2
                    ldd       6,s       reload storage flags
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #48       absolute storage class
                    bne       CheckArrayClass2 not pointer-like
SizePointer         ldd       #2        size = 2 for pointer
                    lbra      RetPop2   return size

CheckArrayClass2    ldd       6,s       reload storage flags
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #32       array storage class
                    bne       ReturnBaseSize not array, return size
                    ldd       #1        running total = 1
                    std       ,s        store running total
ArrayDimLoop2       ldd       ,s        load running total
                    pshs      d         push total
                    ldd       ,u        element type word
                    lbsr      MulEntry  multiply by dimension
                    std       ,s        update running total
                    ldu       2,u       follow to element type
                    ldd       6,s       current type word
                    pshs      d         push type word
                    lbsr      TypeRemoveLevel peel one array level
                    leas      2,s        drop arg
                    std       6,s       store reduced type
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #32       still an array
                    beq       ArrayDimLoop2 loop for next dimension
                    ldd       ,s        total element count
                    pshs      d         push count
                    ldd       8,s       element type word
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #16       pointer element
                    bne       ElemBaseSize use base element size
                    ldd       #2        pointer element size 2
                    bra       MultElemSize multiply total

ElemBaseSize        ldd       10,s      base element size
MultElemSize        lbsr      MulEntry  total = count times elem size
                    lbra      RetPop2   return total size

ReturnBaseSize      ldd       8,s       return base size
                    lbra      RetPop2   return

FreeLocalSymbols    pshs      u         save the caller u register
                    ldd       #$FF74    reserve for stack check
                    lbsr      stkcheck  check stack room
                    leas      -64,s      allocate work buffer
                    ldu       [68,s]    U = symbol list head
                    lbra      ScopeLoopTest enter loop test

ScopeSymLoop        ldd       16,u      load next symbol pointer
                    std       60,s      save next pointer
                    ldd       ,u        load symbol type
                    cmpd      #9        is it a label
                    bne       CheckSymTag not a label
                    ldd       10,u      load label flags
                    clra                clear high byte
                    andb      #$01      isolate defined bit
                    bne       CheckSymTag skip if defined
                    ldd       #8        error message length
                    pshs      d         push length
                    pshs      u         push symbol pointer
                    ldd       #20       name field offset
                    addd      ,s++      point at label name
                    pshs      d         push name pointer
                    leax      MsgLabelUndefined,pcr label undefined message
                    pshs      x         push message pointer
                    leax      6,s       point at buffer
                    pshs      x         push buffer pointer
                    lbsr      StrCpy    build message string
                    leas      4,s        drop args
                    pshs      d         push result
                    lbsr      strncat   append label name
                    leas      6,s        drop args
                    pshs      d         push result
                    lbsr      BuildMsgBuf report error
                    leas      2,s        drop arg
CheckSymTag         ldx       8,u       load symbol tag
                    bra       IsTagSym  check tag kind

DecTagCount         ldd       GlbVar0068 struct/union nesting count
                    addd      #$FFFF    decrement count
                    std       GlbVar0068 store count
                    bra       UnlinkSym continue unlink

IsTagSym            cmpx      #111      struct tag
                    beq       DecTagCount decrement tag count
                    cmpx      #118      union tag
                    lbeq      DecTagCount decrement tag count
UnlinkSym           ldd       14,u      load hash/scope link
                    std       62,s      save link
                    cmpd      GlbMemLow below hash table
                    bls       UnlinkFromBucket treat as bucket unlink
                    ldd       62,s      reload link
                    cmpd      GlbMemHigh above hash table
                    bcc       UnlinkFromBucket treat as bucket unlink
                    pshs      u         symbol in nested chain
                    lbsr      FreeBlk   unlink from chain
                    leas      2,s        drop arg
                    bra       NextScopeSym go to next symbol

UnlinkFromBucket    cmpu      [62,s]    symbol head of bucket
