                    lbsr      stkcheck  check stack space
                    ldx       4,s       X = operator token
                    bra       ReverseOpDisp dispatch on operator

Op5AReverse         ldd       #91       reversed operator 0x5B
                    puls      pc,u      restore and return

Op5BReverse         ldd       #90       reversed operator 0x5A
                    puls      pc,u      restore and return

NegateRelOp         ldd       4,s       get operator
                    cmpd      #95       compare threshold
                    ble       UseBaseBB at or below, base 0xBB
                    ldd       #195      base 0xC3
                    bra       SubtractOp compute reversed op

UseBaseBB           ldd       #187      base 0xBB
SubtractOp          subd      4,s       subtract operator from base
                    puls      pc,u      restore and return

ReverseOpDisp       cmpx      #90       operator 0x5A
                    beq       Op5AReverse reverse to 0x5B
                    cmpx      #91       operator 0x5B
                    beq       Op5BReverse reverse to 0x5A
                    bra       NegateRelOp compute reversed op

                    puls      pc,u      restore and return

AdjustOpSize        pshs      u         save the caller u register
                    ldd       #$FFC0    stack space needed
                    lbsr      stkcheck  check stack space
                    ldx       4,s       X = operator token
                    bra       OpSizeDisp dispatch on operator

SizeUnchanged       ldd       4,s       return operator size
                    puls      pc,u      restore and return

SizePlus2           ldd       4,s       get operator
                    addd      #2        add two
                    puls      pc,u      restore and return

SizeMinus2          ldd       4,s       get operator
                    addd      #$FFFE    subtract two
                    puls      pc,u      restore and return

OpSizeDisp          cmpx      #90       operator 0x5A
                    beq       SizeUnchanged size unchanged
                    cmpx      #91       operator 0x5B
                    lbeq      SizeUnchanged size unchanged
                    cmpx      #92       operator 0x5C
                    beq       SizePlus2 add two
                    cmpx      #93       operator 0x5D
                    lbeq      SizePlus2 add two
                    cmpx      #96       operator 0x60
                    lbeq      SizePlus2 add two
                    cmpx      #97       operator 0x61
                    lbeq      SizePlus2 add two
                    bra       SizeMinus2 default, subtract two

                    puls      pc,u      restore and return

IsZeroConst         pshs      u         save the caller u register
                    ldd       #$FFC0    stack space needed
                    lbsr      stkcheck  check stack space
                    ldu       4,s       U = node
                    ldd       6,u       node type
                    cmpd      #54       is integer constant
                    bne       RetFalse  no, return false
                    ldd       8,u       get constant value
                    bne       RetFalse  nonzero, return false
                    ldd       #1        return true
                    bra       StrToFpDone return result

RetFalse            clra                D = 0
                    clrb                clear low byte of result
StrToFpDone         puls      pc,u      restore U and return

BignumMul10AddDigit ldx       2,s       X = pointer to 7-byte accumulator
                    leas      -8,s       allocate 8-byte scratch
                    ldd       5,x       load low word of value
                    aslb                shift low byte left (times two)
                    rola                rotate carry into high byte
                    std       5,x       store doubled low word
                    std       5,s       save times-two copy on stack
                    ldd       3,x       next word up
                    rolb                continue shift with carry
                    rola                rotate high with carry
                    std       3,x       store doubled word
                    std       3,s       save times-two copy
                    ldd       1,x       load next word
                    rolb                shift with carry
                    rola                rotate high with carry
                    std       1,x       store doubled word
                    std       1,s       save times-two copy
                    lda       ,x        load top byte
                    rola                shift top with carry
                    sta       ,x        store doubled top byte
                    sta       ,s        save times-two copy top byte
                    asl       6,x       shift value left again (now times four)
                    rol       5,x       propagate carry up
                    rol       4,x       propagate carry up
                    rol       3,x       propagate carry up
                    rol       2,x       propagate carry up
                    rol       1,x       propagate carry up
                    rol       ,x        propagate carry into top
                    bcs       Mul10Overflow overflow means return error
                    asl       6,x       shift value left again (now times eight)
                    rol       5,x       propagate carry up
                    rol       4,x       propagate carry up
                    rol       3,x       propagate carry up
                    rol       2,x       propagate carry up
                    rol       1,x       propagate carry up
                    rol       ,x        propagate carry into top
                    bcs       Mul10Overflow overflow means return error
                    ldd       5,x       times-eight low word
                    addd      5,s       add times-two low word (gives times ten)
                    std       5,x       store combined low word
                    ldd       3,x       next word
                    adcb      4,s       add with carry
                    adca      3,s       add with carry
                    std       3,x       store word
                    ldd       1,x       next word
                    adcb      2,s       add with carry
                    adca      1,s       add with carry
                    std       1,x       store word
                    ldb       ,x        top byte
                    adcb      ,s        add top with carry
                    stb       ,x        store top byte
                    bcs       Mul10Overflow overflow means return error
                    ldb       13,s      get the digit argument
                    andb      #$0f      mask to a single digit
                    clra                clear high byte
                    addd      5,x       add digit to low word
                    std       5,x       store low word
                    ldd       #0        zero for carry propagation
                    adcb      4,x       propagate carry up
                    adca      3,x       propagate carry up
                    std       3,x       store word
                    ldd       #0        zero for carry propagation
                    adcb      2,x       propagate carry up
                    adca      1,x       propagate carry up
                    std       1,x       store word
                    lda       #0        zero for carry propagation
                    adca      ,x        carry into top byte
                    sta       ,x        store top byte
                    bcs       Mul10Overflow overflow means return error
                    leas      8,s        release scratch
                    clra                clear high byte of result
                    clrb                clear low byte (return zero success)
                    rts                 return to caller

Mul10Overflow       ldd       #1        return 1 to signal overflow
                    leas      8,s        release scratch
                    rts                 return to caller

PrintfToBuf         pshs      u         save caller U
                    leax      XStderrStruct,y   X = internal output buffer
                    stx       GlbOutPtr set output destination
                    ldd       #1        mode 1 (file style output)
                    std       GlbVar0076 store output mode
                    leax      6,s       X = address of first vararg
                    pshs      x         push the vararg pointer
                    ldd       6,s       D = format string pointer
                    bra       PrintfTail join common printf tail

fprintf             pshs      u         save caller U
                    ldd       4,s       D = FILE pointer
                    std       GlbOutPtr set output destination
                    ldd       #1        mode 1 (file style output)
                    std       GlbVar0076 store output mode
                    leax      8,s       X = vararg list address
                    pshs      x         push the vararg pointer
                    ldd       8,s       D = format string pointer
PrintfTail          pshs      d         push format string pointer
                    bsr       doprnt    run the formatter
                    leas      4,s        drop pushed args
                    puls      pc,u      restore U and return

Sprintf             pshs      u         save caller U
                    ldd       4,s       D = destination buffer
                    std       GlbOutPtr set output destination
                    ldd       #2        mode 2 (string output)
                    std       GlbVar0076 store output mode
                    leax      8,s       X = vararg list address
                    pshs      x         push the vararg pointer
                    ldd       8,s       D = format string pointer
                    pshs      d         push format string pointer
                    bsr       doprnt    run the formatter
                    leas      4,s        drop pushed args
                    clra                clear high byte
                    clrb                clear low byte
                    stb       [>GlbOutPtr,y] null-terminate the output string
                    puls      pc,u      restore U and return

doprnt              pshs      u         save caller U
                    ldu       4,s       U = format string pointer
                    leas      -11,s      allocate local variables
                    bra       FormatLoop enter the format loop

OutputLiteralChar   ldb       8,s       B = current character
                    lbeq      DoPrntDone null terminator ends formatting
                    ldb       8,s       reload the character
                    sex                 sign-extend to D
                    pshs      d         push the character
                    lbsr      PutChar   output the character
                    leas      2,s        drop the pushed char
FormatLoop          ldb       ,u+       get next format character
                    stb       8,s       save as current character
                    cmpb      #'%      is it a percent
                    bne       OutputLiteralChar no, print it literally
                    ldb       ,u+       get char after the percent
                    stb       8,s       save as current character
                    clra                clear high byte
                    clrb                clear low byte
                    std       2,s       precision = 0
                    std       6,s       width = 0
                    ldb       8,s       B = flag char
                    cmpb      #'-      is it a minus (left justify)
                    bne       NoLeftFlag no left-justify flag
                    ldd       #1        flag value 1
                    std       GlbVar0072 set left-justify flag
                    ldb       ,u+       consume flag, next char
                    stb       8,s       save as current character
                    bra       CheckZeroPad continue to pad selection

NoLeftFlag          clra                clear high byte
                    clrb                clear low byte
                    std       GlbVar0072 clear left-justify flag
CheckZeroPad        ldb       8,s       B = current char
                    cmpb      #'0      is it a zero
                    bne       SpacePad  no, use space padding
                    ldd       #48       pad char = zero
                    bra       StorePadChar store the pad char

SpacePad            ldd       #'        pad char = space
StorePadChar        std       GlbVar0074 store the pad character
                    bra       WidthScan enter the width scan

AccumWidthDigit     ldd       6,s       D = current width value
                    pshs      d         push width
                    ldd       #10       multiplier ten
                    lbsr      MulEntry  width times ten
                    pshs      d         push scaled width
                    ldb       10,s      B = digit character
                    sex                 sign-extend
                    addd      #$FFD0    subtract ASCII zero
                    addd      ,s++      add to width times ten
                    std       6,s       store new width
                    ldb       ,u+       next format character
                    stb       8,s       save as current character
WidthScan           ldb       8,s       B = current char
                    sex                 extend to table index
                    leax      CtypeTab,y X = character class table
                    leax      d,x       index by character
                    ldb       ,x        B = class code
                    cmpb      #107      is it a digit class
                    beq       AccumWidthDigit yes, accumulate width digit
                    ldb       8,s       B = current char
                    cmpb      #'.      is it a dot
                    bne       NoPrecision no precision follows
                    ldd       #1        flag value 1
                    std       4,s       set precision-present flag
                    bra       PrecisionScan enter precision scan

AccumPrecDigit      ldd       2,s       D = current precision value
                    pshs      d         push precision
                    ldd       #10       multiplier ten
                    lbsr      MulEntry  precision times ten
                    pshs      d         push scaled precision
                    ldb       10,s      B = digit character
                    sex                 sign-extend
                    addd      #$FFD0    subtract ASCII zero
                    addd      ,s++      add to precision times ten
                    std       2,s       store new precision
PrecisionScan       ldb       ,u+       next format character
                    stb       8,s       save as current character
                    ldb       8,s       B = current char
                    sex                 extend to table index
                    leax      CtypeTab,y X = character class table
                    leax      d,x       index by character
                    ldb       ,x        B = class code
                    cmpb      #107      is it a digit class
                    beq       AccumPrecDigit yes, accumulate precision digit
                    bra       GetConvChar done, get conversion char

NoPrecision         clra                clear high byte
                    clrb                clear low byte
                    std       4,s       clear precision-present flag
GetConvChar         ldb       8,s       B = conversion specifier
                    sex                 sign-extend
                    tfr       d,x       X = conversion char
                    lbra      DispatchConv dispatch the conversion

ConvDecimal         ldd       6,s       push width for field output
                    pshs      d         push it
                    ldx       19,s      X = vararg pointer
                    leax      2,x       advance past the int arg
                    stx       19,s      save vararg pointer
                    ldd       -2,x      D = the int argument
                    pshs      d         push value
                    lbsr      IntToDecStr convert int to decimal string
                    bra       NumFieldTail go output the number field

ConvHex             ldd       6,s       push width for field output
                    pshs      d         push it
                    ldx       19,s      X = vararg pointer
                    leax      2,x       advance past the int arg
                    stx       19,s      save vararg pointer
                    ldd       -2,x      D = the int argument
                    pshs      d         push value
                    lbsr      IntToHexStr convert int to hex string
NumFieldTail        std       ,s        save the result string pointer
                    lbra      OutputStrField output the number field

ConvChar            ldx       17,s      X = vararg pointer
                    leax      2,x       advance past the char arg
                    stx       17,s      save vararg pointer
                    ldd       -2,x      D = the char argument
                    lbra      OutputCharField output the single character

ConvString          ldx       17,s      X = vararg pointer
                    leax      2,x       advance past the string arg
                    stx       17,s      save vararg pointer
                    ldd       -2,x      D = the string pointer
                    std       9,s       save string pointer
                    ldd       4,s       precision present
                    beq       PrintFullStr none, print the full string
                    ldd       9,s       reload string pointer
                    std       4,s       reuse slot as scan pointer
                    bra       StrScanCount start precision-limited scan

StrScanLoop         ldb       [9,s]     B = current string byte
                    beq       PrintTruncStr null ends the scan
                    ldd       9,s       scan pointer
                    addd      #1        advance one byte
                    std       9,s       save scan pointer
StrScanCount        ldd       2,s       precision counter
                    addd      #$FFFF    decrement it
                    std       2,s       store counter
                    subd      #$FFFF    test the original value
                    bne       StrScanLoop nonzero means more allowed
PrintTruncStr       ldd       6,s       push width
                    pshs      d         push it
                    ldd       11,s      end scan pointer
                    subd      6,s       compute truncated length
                    pshs      d         push length
                    ldd       8,s       push string pointer
                    pshs      d         push it
                    lbsr      EmitCountedField output the truncated string field
                    leas      6,s        drop args
                    bra       ConvDone2 return to format loop

PrintFullStr        ldd       6,s       push width
                    pshs      d         push it
                    ldd       11,s      push string pointer
                    pshs      d         push it
OutputStrField      lbsr      OutputStrWithWidth output string padded to width
                    leas      4,s        drop args
ConvDone2           lbra      FormatLoop back to the format loop

ConvLiteral         ldb       8,s       B = literal conversion char
                    sex                 sign-extend
OutputCharField     pshs      d         push the character
                    lbsr      PutChar   output the character
                    leas      2,s        drop the pushed char
                    lbra      FormatLoop back to the format loop

DispatchConv        cmpx      #100      is conversion a d
                    lbeq      ConvDecimal decimal handler
                    cmpx      #120      is it an x
                    lbeq      ConvHex   hex handler
                    cmpx      #99       is it a c
                    lbeq      ConvChar  char handler
                    cmpx      #115      is it an s
                    lbeq      ConvString string handler
                    bra       ConvLiteral unknown, print literally

DoPrntDone          leas      11,s       release doprnt locals
                    puls      pc,u      restore U and return

IntToDecStr         pshs      u,d       save U and the value
