                    negb                negate low byte
                    sbca      #0        finish two's complement negate
                    std       6,s       store absolute value
                    bge       StoreSign negation succeeded, add sign
                    leax      IntMinStr,pcr X = the minus-32768 literal
                    pshs      x         push it
                    leax      XNumberBuffer,y   X = number buffer
                    pshs      x         push it
                    lbsr      StrCpy    copy literal into buffer
                    leas      4,s        drop args
                    lbra      FieldEmitDone return the buffer

StoreSign           ldd       #'-       minus sign character
                    ldx       ,s        buffer pointer
                    leax      1,x       advance
                    stx       ,s        save pointer
                    stb       -1,x      store the minus sign
ConvertDecDigits    ldd       6,s       reload value
                    pshs      d         push value
                    ldd       2,s       buffer pointer
                    pshs      d         push it
                    bsr       UtoaDecimal convert the decimal digits
                    leas      4,s        drop args
                    leax      XNumberBuffer,y   X = buffer start
                    tfr       x,d       D = buffer pointer
                    lbra      FieldEmitDone return the result

UtoaDecimal         pshs      u,y,x,d   save regs and allocate locals
                    ldu       10,s      U = output pointer
                    clra                clear high byte
                    clrb                clear low byte
                    std       2,s       nonzero-seen flag = 0
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        digit counter = 0
                    bra       MagnitudeLoop enter magnitude search

AdjustMagnitude     ldd       ,s        digit counter
                    addd      #1        increment it
                    std       ,s        store counter
                    ldd       12,s      value
                    subd      Pow10,y   subtract a power of ten
                    std       12,s      store value
MagnitudeLoop       ldd       12,s      value
                    blt       AdjustMagnitude still negative, keep adjusting
                    leax      Pow10,y   X = power-of-ten table
                    stx       4,s       save table pointer
                    bra       DecDigitLoop2 enter digit loop

CountDigit          ldd       ,s        digit counter
                    addd      #1        increment digit
                    std       ,s        store counter
DigitSubLoop        ldd       12,s      value
                    subd      [4,s]     subtract the current power
                    std       12,s      store value
                    bge       CountDigit still fits, count again
                    ldd       12,s      value went negative
                    addd      [4,s]     add the power back
                    std       12,s      store value
                    ldd       ,s        the digit value
                    beq       CheckLeadingZero zero digit
                    ldd       #1        flag value 1
                    std       2,s       mark a nonzero digit seen
CheckLeadingZero    ldd       2,s       nonzero-seen flag
                    beq       NextPower suppress leading zeros
                    ldd       ,s        the digit
                    addd      #48       convert to ASCII
                    stb       ,u+       store digit character
NextPower           clra                clear high byte
                    clrb                clear low byte
                    std       ,s        reset digit counter
                    ldd       4,s       table pointer
                    addd      #2        advance to next power
                    std       4,s       store pointer
DecDigitLoop2       ldd       4,s       table pointer
                    cmpd      GlbVar0001 reached end-of-table marker
                    bne       DigitSubLoop more digits to extract
                    ldd       12,s      remaining value is last digit
                    addd      #48       convert to ASCII
                    stb       ,u+       store last digit
                    clra                clear high byte
                    clrb                clear low byte
                    stb       ,u        null-terminate the string
                    ldd       10,s      return the output pointer
                    leas      6,s        release locals
                    puls      pc,u      restore U and return

IntToHexStr         pshs      u,x,d     save regs and value
                    leax      XNumberBuffer,y   X = number buffer
                    stx       2,s       save buffer pointer
                    leau      UScratchBuffer,y   U = scratch buffer end
HexNibbleLoop       ldd       8,s       the value
                    clra                clear high byte
                    andb      #$0f      isolate the low nibble
                    std       ,s        save nibble
                    pshs      d         push nibble copy
                    ldd       2,s       reload nibble value
                    cmpd      #9        is nibble above nine
                    ble       HexDigitBase2 no, use digit base
                    ldd       #'W       hex letter base (a minus ten)
