                    tfr       a,cc      restore condition codes
                    rts                 return

CopyToScratch32     ldd       ,x        load high word
                    std       ScratchType,y   store to scratch
                    ldd       2,x       load low word
                    leax      ScratchType,y   point X at scratch
                    std       2,x       store low word
                    rts                 return

                    use       lib/imul.asm
                    clr       DivideSignFlag,y   clear divide sign flag
                    leax      >UDivEntry,pcr point at unsigned divide routine
                    stx       DivideRoutinePointer,y   store divide routine pointer
                    bra       DivCheckZero go check divisor

SignedDivSetup      leax      >SDivEntry,pcr point at signed divide routine
                    stx       DivideRoutinePointer,y   store divide routine pointer
                    clr       DivideSignFlag,y   clear sign flag
                    tst       2,s       test dividend sign
                    bpl       DivCheckZero positive dividend
                    inc       DivideSignFlag,y   mark negative result
DivCheckZero        subd      #0        test divisor for zero
                    bne       DoDivide  nonzero, do divide
                    puls      x         pop return address
                    ldd       ,s++      discard operand
                    jmp       ,x        return

DoDivide            ldx       2,s       get dividend pointer
                    pshs      x         push argument
                    jsr       [DivideRoutinePointer,y] call selected divide routine
                    ldd       ,s        fetch result low
                    std       2,s       reposition it
                    tfr       x,d       result to D
                    tst       DivideSignFlag,y   negative result flag
                    beq       DivResult positive, keep as is
                    nega                negate result high
                    negb                negate result low
                    sbca      #0        finish negate
DivResult           std       ,s++      store result and return
                    rts                 return

                    use       lib/divide.asm

                    use       lib/shift.asm

SendSignal          std       Errno,y   stash signal value
                    pshs      y,b       save globals and signal
                    os9       F$ID      get current process id
                    puls      y,b       restore signal in B
                    os9       F$Send    send signal to self
                    rts                 return

GetStatCall         lda       5,s       A = path number
                    ldb       3,s       B = getstat function code
                    beq       GetStatCode0 code 0, size query
                    cmpb      #1        code 1
                    beq       GetStatDo do plain getstat
                    cmpb      #6        code 6
                    beq       GetStatDo do plain getstat
                    cmpb      #2        code 2
                    beq       GetStatXU getstat with U param
                    cmpb      #5        code 5
                    beq       GetStatXU getstat with U param
                    ldb       #208      E$UnkSvc unknown code
                    lbra      SyscallErr return error

                    use       lib/getstat.asm

GetStatCode0        ldx       6,s       X = size result buffer
GetStatDo           os9       I$GetStt  get status
                    lbra      SyscallRet return status

                    lda       5,s       A = path number
                    ldb       3,s       B = setstat function code
                    beq       SetStatSimple code 0, plain setstat
                    cmpb      #2        code 2
                    beq       SetStatXU setstat with U param
                    ldb       #208      E$UnkSvc unknown code
                    lbra      SyscallErr return error

SetStatSimple       ldx       6,s       X = parameter
                    os9       I$SetStt  set status
                    lbra      SyscallRet return status

                    use       lib/setstat.asm

                    use       lib/access.asm

                    use       lib/openpath.asm

                    use       lib/closepath.asm

                    ldx       2,s       X = pathname
                    ldb       5,s       B = attributes
                    os9       I$MakDir  make directory
                    lbra      SyscallRet return status

                    use       lib/createheadb.asm
                    use       lib/createtail.asm

                    use       lib/deletepath.asm

                    lda       3,s       A = path number
                    os9       I$Dup     duplicate path
                    lbcs      SyscallErr failed, return error
                    tfr       a,b       new path to B
                    clra                clear high byte
                    rts                 return new path number

                    use       lib/readpath.asm

                    use       lib/writepath.asm

                    use       lib/seek.asm
HighResultWord      equ       ScratchType this module's long-value high cell
LowResultWord       equ       ResultLowWord this module's long-value low cell

SbrkGrow            ldd       DBreakPointer,y   D = current break pointer
                    pshs      d         save it
                    ldd       4,s       D = requested size
                    cmpd      FreeBytes,y   compare to free bytes
                    bcs       SbrkAllocPool enough, allocate directly
                    addd      DBreakPointer,y   extend past current break
                    pshs      y         save global base
                    subd      ,s        adjust to memory size
                    os9       F$Mem     request more memory
                    tfr       y,d       new memory top into D
                    puls      y         restore global base
                    bcc       SbrkGrowOk got memory
                    ldd       #$FFFF    return failure
                    leas      2,s        drop saved break
                    rts                 return -1

SbrkGrowOk          std       DBreakPointer,y   update break pointer
                    addd      FreeBytes,y   add previous free count
                    subd      ,s        minus old break
                    std       FreeBytes,y   store new free count
SbrkAllocPool       leas      2,s        drop saved break
                    ldd       FreeBytes,y   D = free byte count
                    pshs      d         save it
                    subd      4,s       subtract requested size
                    std       FreeBytes,y   reduce free count
                    ldd       DBreakPointer,y   D = break pointer
                    subd      ,s++      minus free, drop saved
                    pshs      d         save allocation start
                    clra                zero fill value
                    ldx       ,s        X = allocation start
SbrkZeroLoop        sta       ,x+       zero a byte
                    cmpx      DBreakPointer,y   reached break
                    bcs       SbrkZeroLoop keep zeroing
                    puls      pc,d      return pointer

ArenaAlloc          ldd       2,s       D = requested increment
                    addd      ArenaTop,y   add to arena top
                    bcs       ArenaAllocFail overflow, fail
                    cmpd      ArenaLimit,y   compare to arena limit
                    bcc       ArenaAllocFail exceeds, fail
                    pshs      d         save new top
                    ldx       ArenaTop,y   X = old top
                    clra                zero fill value
ArenaZeroLoop       cmpx      ,s        reached new top
                    bcc       ArenaAllocOk done zeroing
                    sta       ,x+       zero a byte
                    bra       ArenaZeroLoop keep zeroing

ArenaAllocOk        ldd       ArenaTop,y   return old top pointer
                    puls      x         X = new top
                    stx       ArenaTop,y   update arena top
                    rts                 return old pointer

ArenaAllocFail      ldd       #$FFFF    return failure
                    rts                 return -1

GetProcId           pshs      y         save Y
                    os9       F$ID      get process id
                    puls      y         restore Y
                    bcc       GetProcIdOk success
                    lbcs      SyscallErr failed, return error
GetProcIdOk         tfr       a,b       process id into B
                    clra                clear high byte
                    rts                 return process id

GetUserId           pshs      y         save Y
                    os9       F$ID      get process ids
                    bcc       GetUserIdOk success
GetUserIdErr        puls      y         restore Y
                    lbra      SyscallErr return error

GetUserIdOk         tfr       y,d       user id into D
                    puls      pc,y      restore and return

                    pshs      y         save Y
                    bsr       GetUserId get current user id
                    std       -2,s      stash it below stack
                    beq       SetUserDo already superuser
                    ldb       #214      E$Permit not permitted
                    bra       GetUserIdErr return error

SetUserDo           ldy       4,s       Y = target user id
                    os9       F$SUser   set user id
                    bcc       SetUserOk success
                    cmpb      #208      E$UnkSvc unsupported
                    bne       GetUserIdErr other error
                    tfr       y,d       user id into D
                    ldy       >GlbVar004B load globals pointer
                    std       CacheUserId,y     cache user id in globals
SetUserOk           clra                success zero high
                    clrb                success zero low
                    puls      pc,y      restore and return

SetupIntercept      pshs      u         save U
                    tfr       y,u       U = global base
                    ldx       4,s       X = handler address
                    stx       HandlerPointer,y   save handler pointer
                    leax      >InterceptHandler,pcr X = intercept trampoline
                    os9       F$Icpt    install signal intercept
                    puls      u         restore U
                    lbra      SyscallRet return status

InterceptHandler    tfr       u,y       restore global base
                    clra                clear high byte
                    pshs      d         push signal argument
                    jsr       [HandlerPointer,y] call user signal handler
                    leas      2,s        drop argument
                    rti                 return from intercept

                    use       lib/syscallerr.asm

exit                lbsr      ExitFlush run exit hook
                    lbsr      FlushAllBufs flush and close open files
_exit               ldd       2,s       D = exit status
                    os9       F$Exit    terminate process
ExitFlush           rts                 return stub

